class HMGSpinnerOption(SpinnerOption):
    def __init__(self, **kwargs):
        super().__init__(**kwargs)
        self.background_normal = ''
        self.background_down = ''
        self.background_color = get_color_from_hex('#2C3E50')
        self.color = get_color_from_hex('#FFFFFF')
        self.font_size = kwargs.get('font_size', 14)
        self.bold = False
        self.size_hint_y = None
        self.height = 42


class HMGSpinner(Spinner):
    def __init__(self, **kwargs):
        kwargs.setdefault('background_normal', '')
        kwargs.setdefault('background_down', '')
        kwargs.setdefault('background_color', get_color_from_hex('#34495E'))
        kwargs.setdefault('color', get_color_from_hex('#FFFFFF'))
        kwargs.setdefault('font_size', 14)
        kwargs.setdefault('bold', False)
        super().__init__(**kwargs)
        self.option_cls = HMGSpinnerOption
        self._hmg_style_dropdown()

    def _hmg_style_dropdown(self):
        try:
            self.bind(is_open=self._hmg_dropdown_opened)
        except Exception:
            pass

    def _hmg_dropdown_opened(self, instance, is_open):
        if not is_open:
            return
        try:
            dropdown = getattr(self, '_dropdown', None)
            if dropdown is not None:
                dropdown.background_color = get_color_from_hex('#1F2937')
                dropdown.bar_width = 8
                for child in list(dropdown.container.children):
                    if isinstance(child, HMGSpinnerOption):
                        child.background_normal = ''
                        child.background_down = ''
                        child.background_color = get_color_from_hex('#2C3E50')
                        child.color = get_color_from_hex('#FFFFFF')
                        child.height = max(42, child.height)
        except Exception:
            pass


class HMGButton(Button):
    """Material 3-inspired filled button for the HMG mobile EMR."""
    M3_PRIMARY = get_color_from_hex('#6750A4')
    M3_ON_PRIMARY = get_color_from_hex('#FFFFFF')
    M3_PRIMARY_CONTAINER = get_color_from_hex('#EADDFF')
    M3_ON_PRIMARY_CONTAINER = get_color_from_hex('#21005D')
    M3_DISABLED = get_color_from_hex('#E6E1E5')
    M3_ON_DISABLED = get_color_from_hex('#79747E')

    def __init__(self, **kwargs):
        kwargs.setdefault('background_normal', '')
        kwargs.setdefault('background_down', '')
        kwargs.setdefault('background_disabled_normal', '')
        kwargs.setdefault('background_color', self.M3_PRIMARY)
        kwargs.setdefault('color', self.M3_ON_PRIMARY)
        kwargs.setdefault('font_size', 14)
        kwargs.setdefault('bold', False)
        super().__init__(**kwargs)
        with self.canvas.before:
            self._m3_color = Color(*self.background_color)
            self._m3_rect = RoundedRectangle(pos=self.pos, size=self.size,
                                              radius=[dp(20)])
        self.bind(pos=self._m3_update_shape, size=self._m3_update_shape,
                  background_color=self._m3_update_color,
                  state=self._m3_update_state, disabled=self._m3_update_state)
        self._m3_update_shape()
        self._m3_update_state()

    def _m3_update_shape(self, *args):
        self._m3_rect.pos = self.pos
        self._m3_rect.size = self.size
        self._m3_rect.radius = [dp(20)]

    def _m3_update_color(self, *args):
        if not self.disabled:
            self._m3_color.rgba = self.background_color

    def _m3_update_state(self, *args):
        if self.disabled:
            self._m3_color.rgba = self.M3_DISABLED
            self.color = self.M3_ON_DISABLED
        elif self.state == 'down':
            base = list(self.background_color)
            self._m3_color.rgba = tuple(max(0.0, c * 0.82) for c in base[:3]) + (base[3],)
            self.color = self.M3_ON_PRIMARY
        else:
            self._m3_color.rgba = self.background_color
            self.color = self.M3_ON_PRIMARY

Spinner = HMGSpinner
Button = HMGButton

