class LoginScreen(BoxLayout):
    def __init__(self, user_manager, on_login, **kwargs):
        super().__init__(orientation='vertical', padding=20, spacing=10, **kwargs)
        self.user_manager = user_manager
        self.on_login = on_login

        self.add_widget(Label(size_hint_y=0.2))
        self.add_widget(Label(text="HMG HOSPITAL EMR", font_size=28, bold=True,
                              color=get_color_from_hex('#1a5276'),
                              size_hint_y=None, height=50))
        self.add_widget(Label(text="Electronic Medical Records System", font_size=13,
                              color=get_color_from_hex('#7f8c8d'),
                              size_hint_y=None, height=24))
        self.add_widget(Label(size_hint_y=0.05))

        card = BoxLayout(orientation='vertical', spacing=10, padding=20,
                         size_hint=(0.9, None), size_hint_y=None, height=340)
        card.pos_hint = {"center_x": 0.5}
        card.add_widget(Label(text="Sign In", font_size=22, bold=True,
                              color=get_color_from_hex('#2c3e50'),
                              size_hint_y=None, height=34))
        card.add_widget(Label(text="Username", font_size=13, bold=True,
                              size_hint_y=None, height=20))
        self.username_input = TextInput(multiline=False, font_size=16,
                                        size_hint_y=None, height=42,
                                        hint_text="Enter username")
        card.add_widget(self.username_input)
        card.add_widget(Label(text="Password", font_size=13, bold=True,
                              size_hint_y=None, height=20))
        self.password_input = TextInput(multiline=False, font_size=16, password=True,
                                        size_hint_y=None, height=42,
                                        hint_text="Enter password",
                                        on_text_validate=self._attempt_login)
        card.add_widget(self.password_input)
        self.error_label = Label(text="", font_size=12,
                                 color=get_color_from_hex('#e74c3c'),
                                 size_hint_y=None, height=24)
        card.add_widget(self.error_label)
        btn_row = BoxLayout(size_hint_y=None, height=46, spacing=8)
        btn_row.add_widget(Button(text="LOGIN", font_size=16, bold=True,
                                  background_color=get_color_from_hex('#27ae60'),
                                  background_normal='',
                                  on_press=self._attempt_login))
        btn_row.add_widget(Button(text="EXIT", font_size=16, bold=True,
                                  background_color=get_color_from_hex('#e74c3c'),
                                  background_normal='',
                                  on_press=self._exit_app))
        card.add_widget(btn_row)
        card.add_widget(Label(text="Default: admin / admin123",
                              font_size=11, color=get_color_from_hex('#7f8c8d'),
                              size_hint_y=None, height=20))
        self.add_widget(card)
        self.add_widget(Label(size_hint_y=0.2))
        Clock.schedule_once(lambda dt: setattr(self.username_input, 'focus', True), 0.3)

    def _attempt_login(self, *args):
        username = self.username_input.text.strip()
        password = self.password_input.text
        self.error_label.text = ""
        if not username or not password:
            self.error_label.text = "Please enter both username and password."
            return
        user = self.user_manager.verify_login(username, password)
        if user is None:
            self.error_label.text = "Invalid username or password."
            self.password_input.text = ""
            return
        if callable(self.on_login):
            self.on_login(user)

    def _exit_app(self, *args):
        App.get_running_app().stop()


# ====================== AI MODELS ======================
class AIModels:
    OPENAI = ["gpt-4o-mini", "gpt-4o", "gpt-4-turbo", "gpt-3.5-turbo"]
    DEEPSEEK = ["deepseek-chat", "deepseek-coder"]

    @classmethod
    def get(cls, provider):
        return cls.OPENAI if provider == "OpenAI" else cls.DEEPSEEK

    @classmethod
    def default(cls, provider):
        return "gpt-4o-mini" if provider == "OpenAI" else "deepseek-chat"


class AIAPIManager:
    def __init__(self):
        self.provider = "OpenAI"
        self.api_key = ""
        self.model = "gpt-4o-mini"
        self.enabled = False
        self.load()

    def load(self):
        try:
            if os.path.exists("ai_settings.json"):
                with open("ai_settings.json") as f:
                    s = json.load(f)
                    self.provider = s.get("provider", "OpenAI")
                    self.api_key = s.get("api_key", "")
                    self.model = s.get("model", "gpt-4o-mini")
                    self.enabled = bool(self.api_key and len(self.api_key) > 10)
        except Exception as e:
            print(f"AI settings load error: {e}")

    def save(self, provider, api_key, model):
        self.provider = provider
        self.api_key = api_key.strip()
        self.model = model
        self.enabled = bool(self.api_key and len(self.api_key) > 10)
        try:
            with open("ai_settings.json", "w") as f:
                json.dump({"provider": provider, "api_key": self.api_key,
                           "model": model}, f, indent=2)
        except Exception as e:
            print(f"AI settings save error: {e}")

    def call(self, sp, up, mt=2000):
        if not self.enabled or not REQUESTS_AVAILABLE:
            return False, "API not available"
        try:
            url = "https://api.openai.com/v1/chat/completions"
            if self.provider == "DeepSeek":
                url = "https://api.deepseek.com/v1/chat/completions"
            headers = {"Authorization": f"Bearer {self.api_key}",
                       "Content-Type": "application/json"}
            payload = {"model": self.model,
                       "messages": [{"role": "system", "content": sp},
                                    {"role": "user", "content": up}],
                       "max_tokens": mt}
            r = requests.post(url, headers=headers, json=payload, timeout=90)
            if r.status_code == 200:
                return True, r.json()['choices'][0]['message']['content']
            return False, f"Error {r.status_code}"
        except Exception as e:
            return False, str(e)


class QRCodeGenerator:
    @staticmethod
    def generate(data):
        if not QRCODE_AVAILABLE:
            return None
        try:
            qr = qrcode.QRCode(version=1, box_size=8, border=3)
            qr.add_data(data)
            qr.make(fit=True)
            img = qr.make_image(fill_color="black", back_color="white")
            buff = BytesIO()
            img.save(buff, format="PNG")
            return base64.b64encode(buff.getvalue()).decode()
        except Exception:
            return None


class CameraHelper:
    @staticmethod
    def available():
        try:
            CoreCamera(index=0)
            return True
        except Exception:
            return False


class PaymentTracker:
    def __init__(self):
        self.payments = []
        try:
            if os.path.exists("payments.json"):
                with open("payments.json") as f:
                    self.payments = json.load(f)
        except Exception:
            pass

    def save(self):
        try:
            with open("payments.json", "w") as f:
                json.dump(self.payments, f, indent=2, default=str)
        except Exception:
            pass

    def add(self, pid, bid, amt, method="Cash"):
        p = {"id": f"PAY{datetime.now().strftime('%Y%m%d%H%M%S')}",
             "patient_id": pid, "bill_id": bid, "amount": amt,
             "method": method,
             "ts": datetime.now().strftime("%Y-%m-%d %H:%M:%S")}
        self.payments.append(p)
        self.save()
        return p

    def get_for(self, pid):
        return [p for p in self.payments if p.get("patient_id") == pid]

    def total_for(self, pid):
        return sum(p.get("amount", 0) for p in self.get_for(pid))

    def remove_for_patient(self, pid):
        self.payments = [p for p in self.payments if p.get("patient_id") != pid]
        self.save()


class ChatSystem:
    def __init__(self):
        self.msgs = []
        self.rooms = {"General": []}
        try:
            if os.path.exists("chat.json"):
                with open("chat.json") as f:
                    d = json.load(f)
                    self.msgs = d.get("msgs", [])
                    self.rooms = d.get("rooms", {"General": []})
        except Exception:
            pass

    def save(self):
        try:
            with open("chat.json", "w") as f:
                json.dump({"msgs": self.msgs, "rooms": self.rooms}, f, indent=2)
        except Exception:
            pass

    def send(self, user, room, msg, image=None):
        if room not in self.rooms:
            self.rooms[room] = []
        m = {"user": user, "room": room, "msg": msg,
             "ts": datetime.now().strftime("%Y-%m-%d %H:%M:%S"),
             "image": image}
        self.msgs.append(m)
        self.rooms[room].append(m)
        self.save()
        return m

    def get(self, room):
        return self.rooms.get(room, [])[-50:]

    def remove_for_patient(self, patient_name):
        self.msgs = [m for m in self.msgs if m.get("user") != patient_name]
        for room in self.rooms:
            self.rooms[room] = [m for m in self.rooms[room]
                                if m.get("user") != patient_name]
        self.save()


class TaskManager:
    STATUSES = ["Pending", "In Progress", "Completed", "Waiting",
                "On Hold", "Cancelled"]

    def __init__(self):
        self.tasks = []
        self.load()

    def load(self):
        try:
            if os.path.exists("tasks.json"):
                with open("tasks.json") as f:
                    self.tasks = json.load(f)
        except Exception as e:
            print(f"Tasks load error: {e}")

    def save(self):
        try:
            with open("tasks.json", "w") as f:
                json.dump(self.tasks, f, indent=2, default=str)
        except Exception as e:
            print(f"Tasks save error: {e}")

    def create_task(self, patient_id, patient_name, assigned_to, task_type,
                    description, order_items=None, priority="Normal",
                    department=None):
        task = {"id": f"TASK{datetime.now().strftime('%Y%m%d%H%M%S%f')}",
                "patient_id": patient_id, "patient_name": patient_name,
                "assigned_to": assigned_to, "task_type": task_type,
                "description": description, "order_items": order_items or [],
                "status": "Pending", "priority": priority,
                "department": department,
                "created_at": datetime.now().strftime("%Y-%m-%d %H:%M:%S"),
                "updated_at": datetime.now().strftime("%Y-%m-%d %H:%M:%S"),
                "completed_at": None, "assigned_to_name": "", "notes": ""}
        self.tasks.append(task)
        self.save()
        return task

    def update_status(self, task_id, status, notes=""):
        for task in self.tasks:
            if task.get("id") == task_id:
                task["status"] = status
                task["updated_at"] = datetime.now().strftime("%Y-%m-%d %H:%M:%S")
                if status == "Completed":
                    task["completed_at"] = datetime.now().strftime("%Y-%m-%d %H:%M:%S")
                if notes:
                    task["notes"] = notes
                self.save()
                return task
        return None

    def get_tasks_for_patient(self, patient_id):
        return [t for t in self.tasks if t.get("patient_id") == patient_id]

    def get_pending_tasks(self):
        return [t for t in self.tasks
                if t.get("status") in ["Pending", "In Progress", "Waiting", "On Hold"]]

    def auto_assign_from_emr(self, emr_record, patient):
        tasks = []

        def ensure_list(value):
            if isinstance(value, list):
                return value
            if isinstance(value, str):
                if ',' in value:
                    return [x.strip() for x in value.split(',') if x.strip()]
                if value.strip():
                    return [value.strip()]
                return []
            return []

        for test in ensure_list(emr_record.get("lab_orders", "")):
            if test and test.strip():
                tasks.append(self.create_task(
                    patient_id=patient.get("id"),
                    patient_name=patient.get("name"),
                    assigned_to="Lab Scientist", task_type="Laboratory",
                    description=f"Lab test: {test}", order_items=[test],
                    department="Laboratory"))
        for study in ensure_list(emr_record.get("radiology_orders", "")):
            if study and study.strip():
                tasks.append(self.create_task(
                    patient_id=patient.get("id"),
                    patient_name=patient.get("name"),
                    assigned_to="Radiologist", task_type="Radiology",
                    description=f"Radiology: {study}", order_items=[study],
                    department="Radiology"))
        for drug in (ensure_list(emr_record.get("medications")) +
                     ensure_list(emr_record.get("prescribed_drugs"))):
            if drug and drug.strip():
                tasks.append(self.create_task(
                    patient_id=patient.get("id"),
                    patient_name=patient.get("name"),
                    assigned_to="Pharmacy", task_type="Pharmacy",
                    description=f"Dispense: {drug}", order_items=[drug],
                    department="Pharmacy"))
        nursing = ensure_list(emr_record.get("nursing_orders"))
        if nursing and any(nursing):
            txt = "\n".join(nursing) if isinstance(nursing, list) else str(nursing)
            tasks.append(self.create_task(
                patient_id=patient.get("id"),
                patient_name=patient.get("name"),
                assigned_to="Nurse", task_type="Nursing",
                description=f"Nursing care: {txt}",
                order_items=nursing if isinstance(nursing, list) else [txt],
                department="Nursing"))
        self.save()
        return tasks
# ====================== ECG ANALYZER ======================
class ECGAnalyzer:
    SP = """You are an expert cardiologist. Generate a comprehensive 12-lead ECG report following this structure:

1. PATIENT DEMOGRAPHICS (Name, ID, Age, Sex)
2. TECHNICAL QUALITY (Calibration, Paper speed, Quality)
3. HEART RATE (Ventricular, Atrial, Method, Interpretation)
4. RHYTHM (Regularity, Diagnosis, Supporting features)
5. CARDIAC AXIS (QRS axis, Degree)
6. P WAVE ANALYSIS
7. PR INTERVAL
8. QRS COMPLEX
9. R WAVE PROGRESSION
10. PATHOLOGICAL Q WAVES
11. ST SEGMENT
12. T WAVE
13. QT INTERVAL
14. U WAVES
15. ECTOPIC ACTIVITY
16. ARRHYTHMIAS
17. ISCHEMIC CHANGES
18. HYPERTROPHY
19. ELECTROLYTE PATTERN
20. DRUG EFFECTS
21. COMPARISON WITH PREVIOUS ECG
22. FINAL IMPRESSION
23. RECOMMENDATIONS

Output a JSON summary with keys: rate, rhythm, axis, pr_interval, qrs_duration, qt_qtc, findings (list), interpretation, urgency, recommendations.
"""

    def __init__(self, ai):
        self.ai = ai

    def analyze(self, pt, ecg_data=None, previous_ecg=None):
        ctx = (f"Patient: {pt.get('name','')} | ID: {pt.get('id','')} | "
               f"Age: {pt.get('age','')} | Sex: {pt.get('gender','')}\n")
        ctx += f"Height: {pt.get('height','N/A')} | Weight: {pt.get('weight','N/A')}\n"
        ctx += f"Symptoms: {pt.get('symptoms','None')}\n"
        ctx += f"BP: {pt.get('bp','N/A')} | HR: {pt.get('pulse','N/A')}\n"
        ctx += f"Reason: {pt.get('ecg_reason','Routine')}\n"
        if ecg_data:
            ctx += f"ECG Data:\n{ecg_data[:2000]}\n"
        if previous_ecg:
            ctx += f"Previous ECG: {previous_ecg}\n"

        if self.ai.enabled:
            s, r = self.ai.call(self.SP, ctx, mt=4000)
            if s:
                sd = {}
                try:
                    m = re.search(r'\{[\s\S]*\}', r)
                    if m:
                        sd = json.loads(m.group())
                except Exception:
                    pass
                return {"analysis": r, "structured": sd, "ai_used": True}

        rid = f"ECG-{datetime.now().strftime('%Y%m%d%H%M%S')}"
        analysis = self._generate_fallback_report(pt, rid)
        sd = {"rate": "72 bpm", "rhythm": "Sinus rhythm, regular",
              "axis": "Normal (+30°)", "pr_interval": "160 ms",
              "qrs_duration": "90 ms", "qt_qtc": "400/420 ms",
              "findings": ["Normal ECG"], "interpretation": "Normal ECG",
              "urgency": "Routine", "recommendations": ["Continue management"]}
        return {"analysis": analysis, "structured": sd, "ai_used": False,
                "report_id": rid}

    def _generate_fallback_report(self, pt, rid):
        return f"""
COMPREHENSIVE 12-LEAD ECG REPORT
Report ID: {rid}
Patient Information
Name: {pt.get('name','N/A')}
Hospital No.: {pt.get('id','N/A')}
Age/Sex: {pt.get('age','N/A')} / {pt.get('gender','N/A')}
Date & Time of ECG: {datetime.now().strftime('%Y-%m-%d %H:%M')}
Clinical Indication: {pt.get('ecg_reason','Routine')}

Technical Quality
Calibration: 10 mm/mV | Paper Speed: 25 mm/sec | Quality: Good

ECG ANALYSIS
1. Heart Rate: Ventricular 72 bpm | Atrial 72 bpm | Method: 300 | Normal
2. Rhythm: Regular | Normal Sinus Rhythm
3. Cardiac Axis: Normal | +30°
4. P Wave: Present, normal morphology
5. PR Interval: 160 ms (Normal 120–200 ms)
6. QRS Complex: 90 ms | Narrow | Normal voltage
7. R Wave Progression: Normal
8. Pathological Q Waves: No
9. ST Segment: No elevation | No depression
10. T Wave: Normal upright
11. QT Interval: 400 ms | QTc 420 ms | Bazett | Normal
12. U Waves: No
13. Ectopic Activity: None
14. Arrhythmias: None
15. Ischemic Changes: None
16. Hypertrophy: None
17. Electrolyte Pattern: No changes
18. Drug Effects: None
19. Comparison: Not available

Final Impression
Normal sinus rhythm at 72 bpm.
Normal cardiac axis.
PR 160 ms | QRS 90 ms | QTc 420 ms.
Normal R-wave progression.
No pathological Q waves, no ST changes, normal T waves.
No chamber hypertrophy or conduction defect.
Overall: Normal ECG.

Recommendations
Correlate with clinical findings.
Consider serial ECGs if clinically indicated.
"""


class ECGReportGenerator:
    @staticmethod
    def generate(result, pt):
        rid = result.get("report_id",
                          f"ECG-{datetime.now().strftime('%Y%m%d%H%M%S')}")
        qr = QRCodeGenerator.generate(f"HMG|ECG|{rid}|{pt.get('name','')}")
        return result.get("analysis", "No report generated."), rid, qr


# ====================== CLINICAL AI ASSISTANT ======================
class ModularAIClinicalAssistant:
    SP = """You are an AI clinical clerk integrated with the HMG Hospital EMR.
Your ONLY job is to gather the information required to fill the EMR clerking
form, then emit it as JSON with the exact keys listed below.

Conduct the interview ONE SHORT QUESTION AT A TIME, in this order, skipping
sections already covered:

  1. cc   — Chief Complaint (in the patient's own words)
  2. hpi  — History of Presenting Illness (onset, character, radiation,
            associated symptoms, timing, aggravating/relieving factors, severity)
  3. pmh  — Past Medical History
  4. psh  — Past Surgical History
  5. dh   — Drug History / current medications (name, dose, frequency)
  6. all  — Allergies
  7. fh   — Family History
  8. sh   — Social History (occupation, smoking, alcohol, marital status)
  9. ros  — Review of Systems (brief per-system screen)
 10. vitals — bp, temp, pulse, spo2, rr, wt, ht, bmi, avpu (skip if unknown)
 11. exam  — gen, cvs, resp, abd, cns (ask only if findings are volunteered)
 12. dx   — Diagnosis / impression / differential
 13. tx   — Treatment plan
 14. lab_orders / radiology_orders — investigations to order (as lists)
 15. prescribed_drugs — list of {name, dose, frequency, duration}
 16. nursing_orders — list of nursing tasks
 17. fu / follow_up — follow-up plan and interval

RULES:
- Ask ONE question per turn. Keep each under 25 words.
- Do NOT offer a diagnosis until you have at least cc + hpi + pmh + exam.
- After roughly 8–15 exchanges, output your FINAL answer as a single fenced
  JSON block with the exact keys below, ending with the token
  [DIAGNOSIS_READY] on its own line.
- NEVER omit a key. Use "Not documented" or [] where data was not obtained.
- The JSON must parse. Do not write prose outside it in the final message.

Output schema (every key is REQUIRED):
{
  "cc": "", "hpi": "", "pmh": "", "psh": "", "dh": "", "all": "",
  "fh": "", "sh": "", "ros": "",
  "gen": "", "cvs": "", "resp": "", "abd": "", "cns": "",
  "bp": "", "temp": "", "pulse": "", "spo2": "", "rr": "",
  "wt": "", "ht": "", "bmi": "", "avpu": "Alert",
  "dx": "", "tx": "", "fu": "",
  "lab_orders": [], "radiology_orders": [], "prescribed_drugs": [],
  "nursing_orders": [], "follow_up": "", "urgency": "Routine",
  "_text": "Full formatted clerking narrative for the EMR preview."
}
"""

    def __init__(self, ai):
        self.ai = ai
        self.conv = []
        self.emr = None
        self.done = False
        self.idx = 0
        self.turn_count = 0
        self.pctx = {}
        self.fb = [
            "What brings you in today? (Chief complaint)",
            "When did it start, and how has it changed?",
            "Where exactly is the problem, and does it move?",
            "How severe is it on a scale of 1 to 10?",
            "Anything else associated — fever, weight loss, night sweats?",
            "Any past medical conditions (diabetes, hypertension, asthma)?",
            "Any past surgeries or hospital admissions?",
            "What medications are you on currently?",
            "Any drug, food or other allergies?",
            "Any family history of similar illness?",
            "Do you smoke or drink? What is your occupation?",
            "Any bowel, bladder, or sleep changes?",
            "Any cough, chest pain, or breathlessness?",
            "Any headaches, dizziness, or weakness?",
            "Any other concerns you want documented?",
        ]

    def start(self, name="", age="", gender=""):
        self.conv = []
        self.emr = None
        self.done = False
        self.idx = 0
        self.turn_count = 0
        self.pctx = {"name": name, "age": age, "gender": gender}
        g = (f"Hello{f' {name}' if name else ''}, I'm your clinical AI. "
             f"What brings you to the hospital today?")
        self.conv.append({"role": "assistant", "content": g})
        return g

    def process(self, msg):
        self.conv.append({"role": "user", "content": msg})
        self.turn_count += 1
        if self.turn_count >= 20:
            self.done = True
            self.emr = self._sum()
            summary = self.emr["_text"]
            self.conv.append({"role": "assistant", "content": summary})
            return summary
        if self.ai.enabled:
            ctx = (f"Patient: {self.pctx.get('name','')}, "
                   f"{self.pctx.get('age','')}yo\n\nConversation:\n")
            for m in self.conv[-12:]:
                role = "Dr" if m['role'] == 'assistant' else "Pt"
                ctx += f"{role}: {m['content']}\n"
            ctx += "\nNext: ask question OR provide [DIAGNOSIS_READY]."
            s, r = self.ai.call(self.SP, ctx, mt=1500)
            if s:
                self.conv.append({"role": "assistant", "content": r})
                if "[DIAGNOSIS_READY]" in r:
                    self.done = True
                    self.emr = self._extract(r)
                return r
            return self._fb()
        return self._fb()

    def _fb(self):
        if self.idx < len(self.fb):
            q = self.fb[self.idx]
            self.idx += 1
            self.conv.append({"role": "assistant", "content": q})
            return q
        self.done = True
        s = self._sum()
        self.emr = s
        self.conv.append({"role": "assistant", "content": s["_text"]})
        return s["_text"]

    def _extract(self, r):
        """Parse the AI's fenced JSON. Backfill missing EMR keys from _sum()."""
        parsed = None
        try:
            m = re.search(r'```json\s*([\s\S]*?)\s*```', r)
            if m:
                parsed = json.loads(m.group(1))
            else:
                m = re.search(r'\{[\s\S]*\}', r)
                if m:
                    parsed = json.loads(m.group())
        except Exception:
            parsed = None

        base = self._sum()
        if not isinstance(parsed, dict):
            return base

        for k, v in base.items():
            if k not in parsed or parsed[k] in (None, "", []):
                parsed[k] = v

        for k in ("lab_orders", "radiology_orders",
                  "prescribed_drugs", "nursing_orders"):
            val = parsed.get(k, [])
            if isinstance(val, str):
                val = [x.strip() for x in val.split(",") if x.strip()] or []
            parsed[k] = val

        return parsed

    def _sum(self):
        """Fallback when AI is off — pack the conversation into EMR-shaped keys."""
        user_msgs = [m["content"] for m in self.conv if m["role"] == "user"]
        blob = " ".join(user_msgs).strip()
        return {
            "cc":   blob[:200] or "Not documented",
            "hpi":  blob[:500] or "Not documented",
            "pmh":  "Not documented",
            "psh":  "Not documented",
            "dh":   "Not documented",
            "all":  "None known",
            "fh":   "Not documented",
            "sh":   "Not documented",
            "ros":  "Not documented",
            "gen":  "Not documented",
            "cvs":  "Not documented",
            "resp": "Not documented",
            "abd":  "Not documented",
            "cns":  "Not documented",
            "bp": "", "temp": "", "pulse": "", "spo2": "", "rr": "",
            "wt": "", "ht": "", "bmi": "", "avpu": "Alert",
            "dx":   "Further evaluation needed",
            "tx":   "Symptomatic management; review after investigation",
            "fu":   "Review in 2 weeks",
            "lab_orders":       ["Full Blood Count (FBC)", "Urinalysis"],
            "radiology_orders": [],
            "prescribed_drugs": [],
            "nursing_orders":   ["Vital signs monitoring"],
            "follow_up":        "Review in 2 weeks",
            "urgency":          "Routine",
            "_text": "[DIAGNOSIS_READY]\nStructured clerking summary "
                     "prepared from available information.",
        }

    def get_emr(self):
        return self.emr

    def re_analyze(self):
        if not self.ai.enabled or not self.conv:
            return None
        ctx = (f"Patient: {self.pctx.get('name','')}, "
               f"{self.pctx.get('age','')}yo\n\nConversation:\n")
        for m in self.conv[-20:]:
            role = "Dr" if m['role'] == 'assistant' else "Pt"
            ctx += f"{role}: {m['content']}\n"
        ctx += "\nProvide comprehensive re-assessment with [DIAGNOSIS_READY]."
        s, r = self.ai.call(self.SP, ctx, mt=1500)
        if s:
            self.done = True
            self.emr = self._extract(r)
            return r
        return None
# ====================== PATHOLOGY AI ======================
class AIPathologyExtractor:
    SP = ("You are an expert clinical pathologist. Analyze patient data and "
          "provide Pathology Summary, Organ System Assessment, Abnormality Flags, "
          "Risk Stratification, ML Features, Personalized Management, Follow-up.")

    def __init__(self, ai):
        self.ai = ai

    def extract(self, pd, emr, labs, rx):
        ctx = (f"PATIENT: {pd.get('name','')} | {pd.get('age','')}yr | "
               f"{pd.get('gender','')}\n")
        for e in emr[-5:]:
            ctx += f"- [{e.get('ts','')}] {e.get('cc','')}\n"
        completed = [t for t in labs if t.get('status') == 'Completed']
        if completed:
            for lab in completed[-15:]:
                ctx += f"- {lab.get('test_name','')}: {lab.get('result','')}\n"
        ctx += f"\nMEDICATIONS: {len(rx)} prescriptions\n"
        if self.ai.enabled:
            s, r = self.ai.call(self.SP, ctx, mt=2000)
            if s:
                sd = {}
                try:
                    m = re.search(r'\{[\s\S]*\}', r)
                    if m:
                        sd = json.loads(m.group())
                except Exception:
                    pass
                return {"analysis": r, "structured": sd, "ai_used": True}
        ac = sum(1 for lab in completed
                 if any(w in str(lab.get('result', '')).lower()
                        for w in ['positive', 'abnormal', 'high', 'low']))
        risk = min(ac + len(rx) // 3, 10)
        rl = "High" if risk >= 7 else "Medium" if risk >= 4 else "Low"
        return {"analysis": f"Pathology Analysis\nAbnormal: {ac}\nRisk: {rl}",
                "structured": {"risk_score": risk, "risk_level": rl,
                               "ml_features": {"abnormal_lab_count": ac}},
                "ai_used": False}


