        opps = ["Referral programs", "Affiliate programs", "Loyalty programs",
                "Premium services", "Subscription models", "Upselling",
                "Cross-selling", "Bundles", "Digital products", "Training",
                "Licensing", "Franchising", "Partnerships", "Corporate sales",
                "Government contracts", "International expansion"]
        analysis = {o: {
            "revenue_potential": "High" if o in ["Subscription models", "Partnerships"] else "Medium",
            "profit_potential": "High" if o in ["Digital products", "Licensing"] else "Medium",
            "cost": "Low" if o in ["Referral programs", "Affiliate programs"] else "Medium",
            "roi": "High" if o in ["Subscription models", "Digital products"] else "Medium"
        } for o in opps}
        self.revenue_engine = {
            "opportunities": analysis,
            "ranked": sorted(analysis.items(),
                             key=lambda x: (x[1]['roi'] == "High",
                                            x[1]['revenue_potential'] == "High"),
                             reverse=True)}
