# ====================== MAIN APP ======================
class HMGBillingApp(App):
    DEFAULT_DELETE_PASSCODE = "1234"
    CONFIG_FILE = "config.json"

    # ---------- Build ----------
    def build(self):
        self.title = "HMG Hospital EMR v13.4.1"

        if platform == 'android':
            try:
                Window.softinput_mode = 'below_target'
            except Exception:
                pass
        else:
            Window.size = (1400, 900)
            try:
                Window.minimum_width = 900
                Window.minimum_height = 600
            except Exception:
                pass

        self.facility = FacilityConfig()
        try:
            self.facility.FILE = os.path.join(
                self._get_reports_dir(), FacilityConfig.FILE)
            self.facility.load()
        except Exception as _fac_init_error:
            print(f"[HMG] facility config init: {_fac_init_error}")
        self.user_manager = UserManager()
        self.audit = AuditLog()
        self.ai = AIAPIManager()
        self.clinical_ai = ModularAIClinicalAssistant(self.ai)
        self.ecg_ai = ECGAnalyzer(self.ai)
        self.pathology_ai = AIPathologyExtractor(self.ai)
        self.pt_tracker = PaymentTracker()
        self.chat_sys = ChatSystem()
        self.lis_manager = LISManager(self)
        self.bos = AIBOS(self.ai)
        self.task_manager = TaskManager()

        self.current_user = None
        self.root_container = BoxLayout(orientation='vertical')
        self.main_root = None

        self.login_screen = LoginScreen(self.user_manager,
                                         on_login=self._on_login_success)
        self.root_container.add_widget(self.login_screen)
        return self.root_container

    # ---------- Login / Logout ----------
    def _on_login_success(self, user):
        try:
            if not hasattr(self, "facility"):
                self.facility = FacilityConfig()
            self.facility.FILE = os.path.join(
                self._get_reports_dir(), FacilityConfig.FILE)
            self.facility.load()
        except Exception as _fac_login_error:
            print(f"[HMG] facility login reload: {_fac_login_error}")
        self.current_user = user
        self.audit.log(username=user.get("username"), action="LOGIN",
                       details=f"Role: {user.get('role')}")
        self.root_container.clear_widgets()
        self._build_main_app()
        if user.get("must_change_password"):
            Clock.schedule_once(lambda dt: self._popup(
                "Security Warning",
                "You are using a default or reset password.\n\n"
                "Go to Settings → SECURITY → CHANGE MY PASSWORD."), 0.5)

    def _logout(self, instance=None):
        if self.current_user:
            self.audit.log(username=self.current_user.get("username"),
                           action="LOGOUT")
        self.save_all()
        self.current_user = None
        self.root_container.clear_widgets()
        self.cp = None
        self.bill_items = []
        self.emr_drug_list = []
        self.clinical_ai = ModularAIClinicalAssistant(self.ai)
        self.login_screen = LoginScreen(self.user_manager,
                                         on_login=self._on_login_success)
        self.root_container.add_widget(self.login_screen)

    def _build_main_app(self):
        self.patients = []
        self.emr_records = []
        self.lab_tests = []
        self.radiology = []
        self.prescriptions = []
        self.bills = []
        self.bill_items = []
        self.ecg_reports = []
        self.pathology_data = []
        self.followups = []
        self.patient_summaries = {}
        self.consent_forms = []
        self.referral_notes = []
        self.daily_notes = []
        self.patient_snapshots = []
        self.procedures_db = []
        self.lab_results = []
        self.tasks = self.task_manager.tasks
        self.emr_drug_list = []
        self.admissions = []
        self.saved_lab_reports = []
        self.appointments = []
        self.nursing_notes = []
        self.transfers = []
        self.delete_attempts = {}

        self.drugs = self._init_drugs()
        self.procedures = self._init_procs()
        self.investigations = self._init_invs()
        self._ensure_panel_tests_in_catalog()
        self.charges = self._init_charges()
        self.depts = list(self._fac("default_departments", [
            "General Medicine", "Pediatrics", "Obstetrics",
            "Surgery", "Cardiology", "Emergency"]))

        self.cp = None
        self.sel_drug_idx = None
        self.sel_inv_idx = None
        self.cur_ecg_img = None
        self.cur_ecg_report = None
        self.cur_upload = None
        self.ai_patient_id = None
        self._admission_id_map = {}

        self._load_config()
        self.load_all()

        self.main_root = BoxLayout(orientation='vertical')
        self._header()
        self.tp = CustomTabbedPanel()
        self.main_root.add_widget(self.tp)

        # M3 tab-strip styling: active tab is vivid; inactive tabs remain
        # readable against the light surface on Android and desktop.
        def _style_tabs(*_):
            try:
                theme = _m3_theme(self) if callable(globals().get('_m3_theme')) else 'light'
                for tab in self.tp.tab_list:
                    active = (self.tp.current_tab is tab)
                    tab.background_normal = ''
                    tab.background_down = ''
                    tab.background_color = _m3(
                        'primary' if active else 'surface_container_high', theme)
                    tab.color = _m3(
                        'on_primary' if active else 'on_surface_variant', theme)
                    tab.bold = active
                    tab.font_size = 14
            except Exception as _tab_e:
                print(f'[HMG] tab styling: {_tab_e}')

        self.tp.bind(current_tab=lambda *_: _style_tabs())
        Clock.schedule_once(_style_tabs, 0.15)

        # FAST STARTUP: build only the high-value landing tabs synchronously so
        # the first frame can appear immediately. The remaining modules are
        # constructed in small UI-thread batches; this avoids a long blank
        # startup/frozen frame on Android while preserving the original tab
        # order and all existing module implementations.
        self._dashboard()
        self._analytics_tab()
        self._register()
        self._clinical_ai_tab()

        self.root_container.add_widget(self.main_root)

        _hmg_remaining_tabs = [
            self._emr,
            self._task_management_tab,
            self._ecg_tab,
            self._liver_span_tab,
            self._pathology_tab,
            self._lis_tab,
            self._billing,
            self._payment,
            self._pharmacy,
            self._drug_mgmt,
            self._inv_mgmt,
            self._lab,
            self._rad,
            self._upload_tab,
            self._settings,
            self._chat_tab,
            self._clinical_summary_tab,
            self._vitals_timeline_tab,
            self._consent_form_tab,
            self._referral_note_tab,
            self._saved_items_tab,
            self._daily_notes_tab,
            self._ai_analysis_tab,
            self._ai_bos_tab,
            self._snapshot_tab,
            self._procedures_tab,
            self._enhanced_lab_tab,
            self._pharmacy_dispense_tab,
            self._admissions_tab,
            self._transfer_tab,
            self._appointments_tab,
            self._nursing_notes_tab,
            self._medical_report_tab,
            self._user_management_tab,
            self._audit_log_tab,
        ]

        self._hmg_tabs_loading = True
        self._hmg_tabs_remaining = list(_hmg_remaining_tabs)
        self._hmg_tabs_batch_size = 4

        def _hmg_build_tab_batch(_dt):
            try:
                batch = self._hmg_tabs_remaining[:self._hmg_tabs_batch_size]
                del self._hmg_tabs_remaining[:self._hmg_tabs_batch_size]
                for _builder in batch:
                    try:
                        _builder()
                    except Exception as _tab_e:
                        print(f'[HMG FAST LOAD] tab build failed: {_tab_e}')
                if self._hmg_tabs_remaining:
                    Clock.schedule_once(_hmg_build_tab_batch, 0.01)
                else:
                    self._hmg_tabs_loading = False
                    print('[HMG FAST LOAD] all tabs constructed')
                    try:
                        self._contrast_fixed_tab_strip()
                    except Exception:
                        pass
            except Exception as _e:
                self._hmg_tabs_loading = False
                print(f'[HMG FAST LOAD] batch scheduler failed: {_e}')

        Clock.schedule_once(_hmg_build_tab_batch, 0.02)
        Clock.schedule_once(lambda dt: self._apply_m3_theme(), 0.1)
        Clock.schedule_once(lambda dt: self._refresh_dash(), 0.5)

    # ---------- Material 3 visual system ----------
    def _apply_m3_theme(self):
        """Apply Material 3 surface, typography and input tokens without changing EMR logic."""
        Window.clearcolor = get_color_from_hex('#FFFBFE')
        surface = get_color_from_hex('#FFFBFE')
        surface_variant = get_color_from_hex('#E7E0EC')
        on_surface = get_color_from_hex('#1D1B20')
        outline = get_color_from_hex('#79747E')

        def walk(widget):
            if isinstance(widget, TextInput):
                widget.background_normal = ''
                widget.background_active = ''
                widget.background_color = surface
                widget.foreground_color = on_surface
                widget.cursor_color = get_color_from_hex('#6750A4')
                widget.padding = [dp(14), dp(10), dp(14), dp(10)]
                widget.border = [dp(1), dp(1), dp(1), dp(1)]
                widget.radius = [dp(12)] if hasattr(widget, 'radius') else getattr(widget, 'radius', None)
            elif isinstance(widget, HMGSpinner):
                widget.background_color = get_color_from_hex('#E7E0EC')
                widget.color = on_surface
            elif isinstance(widget, Label):
                if widget.color == [1, 1, 1, 1] or widget.color is None:
                    widget.color = on_surface
            for child in widget.children:
                walk(child)

        if self.main_root:
            walk(self.main_root)
        if self.main_root:
            self.main_root.canvas.before.clear()
            with self.main_root.canvas.before:
                Color(*surface)
                RoundedRectangle(pos=self.main_root.pos, size=self.main_root.size, radius=[dp(0)])

    # ---------- Config / Delete Passcode ----------
    def _load_config(self):
        if not os.path.exists(self.CONFIG_FILE):
            default = {"delete_passcode_hash":
                       self._hash_passcode(self.DEFAULT_DELETE_PASSCODE)}
            try:
                with open(self.CONFIG_FILE, "w", encoding="utf-8") as f:
                    json.dump(default, f, indent=2)
            except Exception as e:
                print(f"Config write error: {e}")
            return default
        try:
            with open(self.CONFIG_FILE, "r", encoding="utf-8") as f:
                cfg = json.load(f)
            if "delete_passcode_hash" not in cfg:
                cfg["delete_passcode_hash"] = self._hash_passcode(
                    self.DEFAULT_DELETE_PASSCODE)
                with open(self.CONFIG_FILE, "w", encoding="utf-8") as f:
                    json.dump(cfg, f, indent=2)
            return cfg
        except Exception as e:
            print(f"Config read error: {e}")
            return {"delete_passcode_hash":
                    self._hash_passcode(self.DEFAULT_DELETE_PASSCODE)}

    def _save_config(self, cfg):
        try:
            with open(self.CONFIG_FILE, "w", encoding="utf-8") as f:
                json.dump(cfg, f, indent=2)
            return True
        except Exception as e:
            print(f"Config save error: {e}")
            return False

    @staticmethod
    def _hash_passcode(passcode):
        return hashlib.sha256(str(passcode).encode("utf-8")).hexdigest()

    def _verify_delete_passcode(self, entered):
        if not entered:
            return False
        cfg = self._load_config()
        stored = cfg.get("delete_passcode_hash", "")
        return stored != "" and self._hash_passcode(entered.strip()) == stored

    def _set_delete_passcode(self, new_passcode):
        new_passcode = str(new_passcode).strip()
        if len(new_passcode) < 4:
            return False, "Passcode must be at least 4 characters."
        cfg = self._load_config()
        cfg["delete_passcode_hash"] = self._hash_passcode(new_passcode)
        if self._save_config(cfg):
            return True, "Delete passcode updated successfully."
        return False, "Could not save config file."

    # ---------- JSON Data Layer ----------
    def _save_json(self, filename, data, max_backups=3):
        try:
            if os.path.exists(filename):
                for i in range(max_backups - 1, 0, -1):
                    src = f"{filename}.bak{i - 1}" if i > 1 else filename
                    dst = f"{filename}.bak{i}"
                    if os.path.exists(src):
                        shutil.copy2(src, dst)
                shutil.copy2(filename, f"{filename}.bak0")
            fd, temp_path = tempfile.mkstemp(dir=os.path.dirname(filename) or '.',
                                              prefix='tmp_', suffix='.json')
            with os.fdopen(fd, 'w', encoding='utf-8') as f:
                json.dump(data, f, indent=2, default=str, ensure_ascii=False)
            os.replace(temp_path, filename)
        except Exception as e:
            print(f"Error saving {filename}: {e}")
            if os.path.exists(f"{filename}.bak0"):
                shutil.copy2(f"{filename}.bak0", filename)

