    def _export_to_pdf(self, text, prefix, title):
        try:
            dir_path = self._get_reports_dir()
            fn = os.path.join(dir_path,
                              f"{prefix}_{datetime.now().strftime('%Y%m%d_%H%M%S')}")
            patient = self._patient_identity_for_report()
            image_path = self._render_professional_report_image(
                text, prefix, title, patient=patient)
            if PDF_AVAILABLE:
                try:
                    class PDF(FPDF):
                        def header(self):
                            self.set_font('Arial', 'B', 12)
                            self.cell(0, 10, 'HMG Hospital Ltd', 0, 1, 'C')
                            self.ln(5)
                        def footer(self):
                            self.set_y(-15)
                            self.set_font('Arial', 'I', 8)
                            self.cell(0, 10, f'Page {self.page_no()}', 0, 0, 'C')
                    pdf = PDF()
                    pdf.add_page()
                    pdf.set_font('Arial', 'B', 16)
                    pdf.cell(0, 10, self._sanitize_text(title), ln=True, align='C')
                    pdf.ln(5)
                    pdf.set_font('Arial', '', 10)
                    if patient.get('name'):
                        pdf.cell(0, 6, self._sanitize_text(
                            f"Patient: {patient.get('name')} | ID: {patient.get('id','')} | Age: {patient.get('age','')} | Sex: {patient.get('gender','')}"),
                            ln=True)
                    pdf.cell(0, 6,
                             f"Generated: {datetime.now().strftime('%Y-%m-%d %H:%M:%S')}",
                             ln=True)
                    pdf.cell(0, 6,
                             "Reported by: Dr. Precious Belema Ibiabuo, Medical Director",
                             ln=True)
                    pdf.ln(5)
                    for line in text.split('\n'):
                        safe_line = self._sanitize_text(line)
                        if not safe_line.strip():
                            pdf.ln(2)
                            continue
                        pdf.set_font('Arial', '', 11)
                        pdf.multi_cell(0, 6, safe_line.strip()[:100])
                    pdf_fn = f"{fn}.pdf"
                    pdf.output(pdf_fn)
                    self._open_file(image_path or pdf_fn)
                    msg = f"Professional report saved:\n{os.path.basename(pdf_fn)}"
                    if image_path:
                        msg += f"\n\nImage report:\n{os.path.basename(image_path)}"
                    self._popup("Export Success", msg)
                    self.audit_log("EXPORT_REPORT",
                                   f"{title} → {pdf_fn}", patient.get('id', ''))
                    return True, pdf_fn
                except Exception as e:
                    print('PDF export error:', e)
            if image_path:
                self._open_file(image_path)
                self._popup("Export Success", f"Image report saved:\n{image_path}")
                return True, image_path
            return False, None
        except Exception as e:
            self._popup("Export Error", str(e))
            return False, None

    def _open_file(self, filepath):
        if not os.path.exists(filepath):
            self._popup("Error", "File does not exist.")
            return
        if platform == 'android':
            try:
                from jnius import autoclass
                PythonActivity = autoclass('org.kivy.android.PythonActivity')
                Intent = autoclass('android.content.Intent')
                File = autoclass('java.io.File')
                Uri = autoclass('android.net.Uri')
                activity = PythonActivity.mActivity
                mime_type, _ = mimetypes.guess_type(filepath)
                if mime_type is None:
                    mime_type = "*/*"
                file = File(filepath)
                uri = Uri.fromFile(file)
                intent = Intent(Intent.ACTION_VIEW)
                intent.setDataAndType(uri, mime_type)
                intent.addFlags(Intent.FLAG_ACTIVITY_NEW_TASK)
                intent.addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION)
                activity.startActivity(intent)
            except Exception:
                pass
        else:
            try:
                if sys.platform == 'win32':
                    os.startfile(filepath)
                elif sys.platform == 'darwin':
                    subprocess.Popen(['open', filepath])
                else:
                    subprocess.Popen(['xdg-open', filepath])
            except Exception:
                pass

    # ========== v13.4.1: robust Android file opener ==========
    def _open_file_with_fallback(self, filepath):
        if not filepath or not os.path.exists(filepath):
            print(f"open_file: missing file {filepath}")
            return False
        try:
            if os.path.getsize(filepath) < 100:
                print(f"open_file: file too small to be valid: {filepath}")
                return False
        except Exception:
            pass

        if platform != 'android':
            try:
                if sys.platform == 'win32':
                    os.startfile(filepath)
                elif sys.platform == 'darwin':
                    subprocess.Popen(['open', filepath])
                else:
                    subprocess.Popen(['xdg-open', filepath])
                return True
            except Exception as e:
                print(f"desktop open error: {e}")
                return False

        try:
            from jnius import autoclass

            PythonActivity = autoclass('org.kivy.android.PythonActivity')
            Intent = autoclass('android.content.Intent')
            File = autoclass('java.io.File')
            Uri = autoclass('android.net.Uri')
            StrictMode = autoclass('android.os.StrictMode')

            try:
                StrictMode.disableDeathOnFileUriExposure()
            except Exception:
                pass

            activity = PythonActivity.mActivity
            if activity is None:
                print("open_file: no Android activity")
                return False

            mime_type, _ = mimetypes.guess_type(filepath)
            if not mime_type:
                low = filepath.lower()
                if low.endswith(".pdf"):
                    mime_type = "application/pdf"
                elif low.endswith(".png"):
                    mime_type = "image/png"
                elif low.endswith(".jpg") or low.endswith(".jpeg"):
                    mime_type = "image/jpeg"
                else:
                    mime_type = "*/*"

            uri = None
            try:
                FileProvider = autoclass(
                    'androidx.core.content.FileProvider')
                authority = f"{activity.getPackageName()}.fileprovider"
                uri = FileProvider.getUriForFile(
                    activity, authority, File(filepath))
            except Exception as e:
                print(f"open_file: FileProvider unavailable ({e}); "
                      f"falling back to Uri.fromFile")

            if uri is None:
                try:
                    uri = Uri.fromFile(File(filepath))
                except Exception as e:
                    print(f"open_file: Uri.fromFile failed: {e}")
                    return False

            try:
                intent = Intent(Intent.ACTION_VIEW)
                intent.setDataAndType(uri, mime_type)
                intent.addFlags(Intent.FLAG_ACTIVITY_NEW_TASK)
                intent.addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION)
                activity.startActivity(intent)
                return True
            except Exception as e:
                print(f"open_file: ACTION_VIEW failed: {e}")

            try:
                view_intent = Intent(Intent.ACTION_VIEW)
                view_intent.setDataAndType(uri, mime_type)
                view_intent.addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION)
                chooser = Intent.createChooser(view_intent, "Open with")
                chooser.addFlags(Intent.FLAG_ACTIVITY_NEW_TASK)
                activity.startActivity(chooser)
                return True
            except Exception as e:
                print(f"open_file: chooser failed: {e}")

            try:
                cachedir = activity.getFilesDir().getAbsolutePath()
                os.makedirs(cachedir, exist_ok=True)
                dst = os.path.join(cachedir, os.path.basename(filepath))
                shutil.copy2(filepath, dst)
                return self._open_file_with_fallback(dst)
            except Exception as e:
                print(f"open_file: private-dir retry failed: {e}")
                return False

        except Exception as e:
            print(f"open_file: outer error: {e}")
            return False

    # ========== v13.4.1: robust Android share ==========
    def _share_file(self, filepath):
        if not filepath or not os.path.exists(filepath):
            self._popup("Share Error", f"File not found:\n{filepath}")
            return

        if platform != 'android':
            try:
                if sys.platform == 'win32':
                    subprocess.Popen(['explorer', '/select,', filepath])
                elif sys.platform == 'darwin':
                    subprocess.Popen(['open', '-R', filepath])
                else:
                    subprocess.Popen(['xdg-open', os.path.dirname(filepath)])
                self._popup("File Location", os.path.dirname(filepath))
            except Exception as e:
                self._popup("Share Error", str(e))
            return

        try:
            from jnius import autoclass
            PythonActivity = autoclass('org.kivy.android.PythonActivity')
            Intent = autoclass('android.content.Intent')
            File = autoclass('java.io.File')
            Uri = autoclass('android.net.Uri')
            StrictMode = autoclass('android.os.StrictMode')

            try:
                StrictMode.disableDeathOnFileUriExposure()
            except Exception:
                pass

            activity = PythonActivity.mActivity
            if activity is None:
                self._popup("Share Error", "Android activity not available.")
                return

            mime_type, _ = mimetypes.guess_type(filepath)
            if not mime_type:
                low = filepath.lower()
                if low.endswith(".pdf"):
                    mime_type = "application/pdf"
                elif low.endswith(".png"):
                    mime_type = "image/png"
                else:
                    mime_type = "*/*"

            uri = None
            try:
                FileProvider = autoclass(
                    'androidx.core.content.FileProvider')
                authority = f"{activity.getPackageName()}.fileprovider"
                uri = FileProvider.getUriForFile(
                    activity, authority, File(filepath))
            except Exception as e:
                print(f"share: FileProvider unavailable ({e})")

            if uri is None:
                try:
                    cachedir = activity.getFilesDir().getAbsolutePath()
                    os.makedirs(cachedir, exist_ok=True)
                    dst = os.path.join(cachedir,
                                        os.path.basename(filepath))
                    if os.path.abspath(dst) != os.path.abspath(filepath):
                        shutil.copy2(filepath, dst)
                        filepath = dst
                    uri = Uri.fromFile(File(filepath))
                except Exception as e:
                    print(f"share: Uri.fromFile failed: {e}")
                    self._popup("Share Error",
                                f"Could not prepare file for sharing.\n{e}")
                    return

            intent = Intent(Intent.ACTION_SEND)
            intent.setType(mime_type)
            intent.putExtra(Intent.EXTRA_STREAM, uri)
            intent.putExtra(Intent.EXTRA_SUBJECT,
                             os.path.basename(filepath))
            intent.addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION)
            intent.addFlags(Intent.FLAG_ACTIVITY_NEW_TASK)

            chooser = Intent.createChooser(intent, "Share Report")
            chooser.addFlags(Intent.FLAG_ACTIVITY_NEW_TASK)
            activity.startActivity(chooser)
        except Exception as e:
            print(f"share error: {e}")
            self._popup("Share Error", str(e))

    # ========== v13.4.1: copy to public Download ==========
    def _save_to_public_downloads(self, filepath):
        if not filepath or not os.path.exists(filepath):
            self._popup("Save Error", "File not found.")
            return
        targets = [
            "/sdcard/Download/HMG_Reports",
            "/storage/emulated/0/Download/HMG_Reports",
        ]
        saved = None
        for t in targets:
            try:
                os.makedirs(t, exist_ok=True)
                dst = os.path.join(t, os.path.basename(filepath))
                shutil.copy2(filepath, dst)
                saved = dst
                break
            except Exception:
                continue
        if saved:
            self._popup("Saved to Downloads",
                        f"Copy written to:\n{saved}\n\n"
                        "You can open it with any file manager.")
            self.audit_log("SAVE_TO_DOWNLOADS", saved)
        else:
            self._popup("Save Error",
                        "Could not write to /sdcard/Download.\n\n"
                        "Use SHARE instead.")

