        row1.add_widget(Label(
            text="HMG EMR",
            font_size=15, bold=True,
            color=get_color_from_hex('#1a5276'),
            size_hint_x=0.28))

        lab_running = sum(1 for s in self.lis_manager.servers.values()
                          if s.get("running"))
        self.lis_lbl = Label(
            text=f"LIS: {lab_running}",
            font_size=11, size_hint_x=0.1,
            color=get_color_from_hex('#27ae60'))
