        ai_text = f"AI: {self.ai.provider}" if self.ai.enabled else "AI: Off"
        self.ai_lbl = Label(text=ai_text, font_size=11, size_hint_x=0.14)
        row1.add_widget(self.ai_lbl)

        uname = self._current_username()
