# ---------- Clinical AI ----------
def _clinical_ai_tab(self):
    tab = TabbedPanelItem(text="Clinical AI")
    main = BoxLayout(orientation='horizontal', padding=6, spacing=6)
    left = BoxLayout(orientation='vertical', size_hint_x=0.5, spacing=4)
    left.add_widget(Label(text="AI CLINICAL ASSISTANT", font_size=20,
                          bold=True, size_hint_y=None, height=32,
                          color=get_color_from_hex('#e67e22')))
    ai_status = BoxLayout(size_hint_y=None, height=30, spacing=5)
    self.ai_status_label = Label(
        text="AI Status: " + ("✅ Connected" if self.ai.enabled else "⚠️ Offline"),
        font_size=13, bold=True,
        color=get_color_from_hex('#27ae60') if self.ai.enabled
        else get_color_from_hex('#e74c3c'))
    ai_status.add_widget(self.ai_status_label)
    ai_status.add_widget(Button(text="Test AI", font_size=12, size_hint_x=0.15,
                                 on_press=self._test_ai_connection,
                                 background_color=get_color_from_hex('#2980b9'),
                                 background_normal=''))
    left.add_widget(ai_status)
    self.ca_ctx = Label(text="No patient selected", font_size=13,
                        size_hint_y=None, height=20,
                        color=get_color_from_hex('#7f8c8d'))
    left.add_widget(self.ca_ctx)

    chat_scroll = ScrollView(size_hint_y=0.6, bar_width=10,
                              scroll_type=['bars', 'content'])
    self.ca_chat = TextInput(multiline=True, readonly=True, font_size=12,
                              background_color=get_color_from_hex('#f8f9fa'),
                              size_hint_y=None)
    self.ca_chat.bind(minimum_height=self.ca_chat.setter('height'))
    chat_scroll.add_widget(self.ca_chat)
    left.add_widget(chat_scroll)

    inp = BoxLayout(size_hint_y=None, height=45, spacing=4)
    self.ca_input = TextInput(size_hint_x=0.6, font_size=15,
                               size_hint_y=None, height=45,
                               hint_text="Type response...",
                               on_text_validate=self._send_ca)
    inp.add_widget(self.ca_input)
    inp.add_widget(Button(text="📷", font_size=16, bold=True, size_hint_x=0.08,
                          on_press=self._ca_camera,
                          background_color=get_color_from_hex('#2980b9'),
                          background_normal=''))
    inp.add_widget(Button(text="SEND", font_size=16, bold=True, size_hint_x=0.25,
                          on_press=self._send_ca,
                          background_color=get_color_from_hex('#27ae60'),
                          background_normal=''))
    left.add_widget(inp)

    ctrl = BoxLayout(size_hint_y=None, height=40, spacing=4)
    for txt, cb, col in [
        ("START", self._start_ca, '#27ae60'),
        ("RESET", self._reset_ca, '#f39c12'),
        ("RE-ANALYZE", self._re_analyze_ca, '#e67e22'),
        ("ASSESSMENT", self._show_assessment, '#c0392b'),
        ("POPULATE EMR", self._populate_emr, '#8e44ad'),
        ("SCHEDULE", self._schedule_followup, '#16a085'),
        ("AUTO-ASSIGN TASKS", self._auto_assign_tasks_from_ai, '#2c3e50')]:
        ctrl.add_widget(Button(text=txt, font_size=14, bold=True,
                                on_press=cb, background_normal='',
                                background_color=get_color_from_hex(col)))
    left.add_widget(ctrl)

    right = BoxLayout(orientation='vertical', size_hint_x=0.5, spacing=3)
    right.add_widget(Label(text="ASSESSMENT", font_size=16, bold=True,
                           size_hint_y=None, height=25,
                           color=get_color_from_hex('#2c3e50')))
    assess_scroll = ScrollView(size_hint_y=0.3, bar_width=10, scroll_type=['bars'])
    self.ca_diag = TextInput(multiline=True, readonly=True, font_size=11,
                              background_color=get_color_from_hex('#fef9e7'),
                              size_hint_y=None)
    self.ca_diag.bind(minimum_height=self.ca_diag.setter('height'))
    assess_scroll.add_widget(self.ca_diag)
    right.add_widget(assess_scroll)
    right.add_widget(Label(text="EMR PREVIEW", font_size=16, bold=True,
                           size_hint_y=None, height=25,
                           color=get_color_from_hex('#2c3e50')))
    emr_scroll = ScrollView(size_hint_y=0.5, bar_width=10, scroll_type=['bars'])
    self.ca_emr = TextInput(multiline=True, readonly=True, font_size=11,
                             background_color=get_color_from_hex('#eaf2f8'),
                             size_hint_y=None)
    self.ca_emr.bind(minimum_height=self.ca_emr.setter('height'))
    emr_scroll.add_widget(self.ca_emr)
    right.add_widget(emr_scroll)
    act = BoxLayout(size_hint_y=None, height=40, spacing=4)
    act.add_widget(Button(text="SAVE TO EMR", font_size=14, bold=True,
                          on_press=self._save_ca_emr,
                          background_color=get_color_from_hex('#27ae60'),
                          background_normal=''))
    act.add_widget(Button(text="ADD TO BILL", font_size=14,
                          on_press=self._add_ca_bill,
                          background_color=get_color_from_hex('#2980b9'),
                          background_normal=''))
    right.add_widget(act)
    main.add_widget(left)
    main.add_widget(right)
    tab.add_widget(main)
    self.tp.add_widget(tab)

def _test_ai_connection(self, instance):
    if not self.ai.enabled:
        self._popup("AI Status", "AI is not enabled. Set API key in Settings.")
        return
    self.ai_status_label.text = "AI Status: Testing..."

    def run_test():
        ok, resp = self.ai.call("You are a helpful assistant.",
                                 "Reply with 'OK' if you can read this.", mt=10)
        if ok:
            Clock.schedule_once(lambda dt: setattr(
                self.ai_status_label, 'text', "AI Status: ✅ Connected"), 0)
            self._popup("AI Test", "AI is working correctly!")
        else:
            Clock.schedule_once(lambda dt: setattr(
                self.ai_status_label, 'text',
                f"AI Status: ❌ Failed: {resp[:50]}"), 0)
            self._popup("AI Test", f"AI test failed:\n{resp}")
    threading.Thread(target=run_test, daemon=True).start()

def _ca_camera(self, instance):
    if not CameraHelper.available():
        self._popup("Camera", "Camera not available")
        return
    content = BoxLayout(orientation='vertical', spacing=4, padding=4)
    cam = Camera(play=True, resolution=(640, 480))
    content.add_widget(cam)
    btns = BoxLayout(size_hint_y=None, height=40, spacing=5)
    pp = Popup(title="Capture Photo", content=content, size_hint=(0.85, 0.85))

    def capture(inst):
        if cam.texture:
            fn = f"chat_capture_{datetime.now().strftime('%Y%m%d_%H%M%S')}.png"
            cam.texture.save(fn)
            pp.dismiss()
            self.ca_chat.text += f"\n[Image captured: {fn}]\n"
            self._popup("Photo Captured", f"Image saved as: {fn}")
            self.log_activity(f"Chat photo captured: {fn}")
            if self.cp:
                self.chat_sys.send(self.cp.get('name', 'User'), "General",
                                    f"[Photo] {fn}", image=fn)
    btns.add_widget(Button(text="📸 CAPTURE", font_size=16, bold=True,
                           on_press=capture,
                           background_color=get_color_from_hex('#27ae60'),
                           background_normal=''))
    btns.add_widget(Button(text="CANCEL", font_size=16,
                           on_press=pp.dismiss, background_normal=''))
    content.add_widget(btns)
    pp.open()

def _send_ca(self, instance):
    msg = self.ca_input.text.strip()
    if not msg:
        return
    self.ai_patient_id = self.cp.get("id") if self.cp else None
    self.ca_chat.text += f"Patient: {msg}\n\nAssistant: Analyzing...\n"
    self.ca_input.text = ""
    threading.Thread(target=self._process_ca, args=(msg,), daemon=True).start()

def _process_ca(self, msg):
    r = self.clinical_ai.process(msg)
    pid_at_start = self.ai_patient_id
    Clock.schedule_once(lambda dt: self._update_ca(r, pid_at_start)
                        if r else self._update_ca("Could not process.",
                                                   pid_at_start), 0)

def _update_ca(self, response, expected_pid=None):
    current_pid = self.cp.get("id") if self.cp else None
    if expected_pid and expected_pid != current_pid:
        self.ca_chat.text += "\n[Warning: Response discarded — patient changed]\n"
        return
    lines = [l for l in self.ca_chat.text.split('\n') if 'Analyzing...' not in l]
    self.ca_chat.text = '\n'.join(lines) + '\nAssistant: ' + response + '\n\n'
    self.ca_chat.scroll_y = 0
    if self.clinical_ai.done:
        emr = self.clinical_ai.get_emr()
        if emr:
            self.ca_diag.text = "Differential:\n" + "\n".join(
                [f"  {i+1}. {d}" for i, d in
                 enumerate(emr.get("dx") and [emr.get("dx")] or
                            [emr.get("interpretation", "See assessment")])])
            self.ca_emr.text = "EMR DATA:\n" + "\n".join(
                [f"{k}: {v}" for k, v in emr.items() if k != "_text"])
            self.ca_chat.text += ("\n" + "=" * 50 +
                                   "\nINTERVIEW COMPLETE\n" + "=" * 50 + "\n")
            if self.cp:
                pid = self.cp.get("id")
                self.patient_summaries[pid] = self._format_summary(emr)
                self.save_all()
                self._refresh_clinical_summary()

# FIX 11: _format_summary uses EMR-shaped keys
def _format_summary(self, emr):
    lines = ["AI CLERKING SUMMARY",
             f"Chief Complaint: {emr.get('cc', 'N/A')}",
             f"HPI: {emr.get('hpi', 'N/A')}",
             f"PMH: {emr.get('pmh', 'N/A')}",
             f"PSH: {emr.get('psh', 'N/A')}",
             f"Drugs: {emr.get('dh', 'N/A')}",
             f"Allergies: {emr.get('all', 'N/A')}",
             f"Family Hx: {emr.get('fh', 'N/A')}",
             f"Social Hx: {emr.get('sh', 'N/A')}",
             f"ROS: {emr.get('ros', 'N/A')}",
             "",
             f"Exam: GEN {emr.get('gen', 'N/A')} | "
             f"CVS {emr.get('cvs', 'N/A')} | "
             f"RESP {emr.get('resp', 'N/A')} | "
             f"ABD {emr.get('abd', 'N/A')} | "
             f"CNS {emr.get('cns', 'N/A')}",
             "",
             f"Impression: {emr.get('dx', 'N/A')}",
             f"Treatment: {emr.get('tx', 'N/A')}",
             f"Follow-up: {emr.get('fu', emr.get('follow_up', 'N/A'))}",
             f"Urgency: {emr.get('urgency', 'Routine')}"]
    return "\n".join(lines)

def _show_assessment(self, instance):
    if not self.clinical_ai.done or not self.clinical_ai.emr:
        if self.ai.enabled:
            self._generate_assessment_ai()
        else:
            self._popup("Assessment", "Complete interview or enable AI.")
        return
    emr = self.clinical_ai.emr
    text = "Clinical Assessment\n" + "=" * 50 + "\n"
    text += f"Chief Complaint: {emr.get('cc','N/A')}\n"
    text += "Differential Diagnoses:\n"
    for i, d in enumerate(emr.get('differential_diagnosis', [])):
        text += f"  {i+1}. {d}\n"
    text += f"Diagnosis / Impression: {emr.get('dx','N/A')}\n"
    text += (f"Investigations: "
             f"{', '.join(emr.get('lab_orders', []))}\n")
    text += f"Treatment: {emr.get('tx','N/A')}\n"
    text += f"Urgency: {emr.get('urgency','Routine')}\n"
    text += f"Follow-up: {emr.get('fu', emr.get('follow_up','N/A'))}\n"
    self._text_popup("Clinical Assessment", text)

def _generate_assessment_ai(self):
    if not self.ai.enabled or not self.cp:
        self._popup("AI Error", "AI not enabled or no patient selected.")
        return
    conv_text = "\n".join(
        f"{'Doctor' if m['role']=='assistant' else 'Patient'}: {m['content']}"
        for m in self.clinical_ai.conv)
    prompt = (f"Generate a comprehensive SOAP assessment:\n\n{conv_text}\n\n"
              f"Provide Subjective, Objective, Assessment, Plan.")

    def run():
        ok, resp = self.ai.call(
            "You are a senior clinician providing SOAP assessment.",
            prompt, mt=1500)
        if ok:
            Clock.schedule_once(
                lambda dt: self._text_popup("AI Assessment", resp), 0)
        else:
            Clock.schedule_once(lambda dt: self._popup("Error", resp), 0)
    threading.Thread(target=run, daemon=True).start()

def _start_ca(self, instance):
    if self.cp:
        name = self.cp.get('name', '')
        pid = self.cp.get('id', '')
        age = str(self.cp.get('age', ''))
        gender = self.cp.get('gender', '')
        self.ca_ctx.text = f"Patient: {name} ({pid}) | {age}yr | {gender}"
        opening = self.clinical_ai.start(name, age, gender)
    else:
        self.ca_ctx.text = "No patient selected"
        opening = self.clinical_ai.start("", "", "")
    self.ca_chat.text = ("=" * 50 + "\nAI CLINICAL ASSISTANT\n" +
                          "=" * 50 + "\n\nAssistant: " + opening + "\n\n")
    if not self.ai.enabled:
        self.ca_chat.text += "(Structured mode)\n\n"
    self.ca_input.text = ""
    self.ca_input.focus = True
    if hasattr(self, 'cl_summary'):
        self.cl_summary.text = ""

def _re_analyze_ca(self, instance):
    if not self.clinical_ai.conv:
        self._popup("No Data", "Start interview first.")
        return
    self.ca_chat.text += "\nRe-analyzing...\n"
    threading.Thread(
        target=lambda: Clock.schedule_once(
            lambda dt: self._update_ca(
                self.clinical_ai.re_analyze() or "Re-analysis failed."), 0),
        daemon=True).start()

# FIX 9: _populate_emr writes every EMR field
def _populate_emr(self, instance):
    emr = self.clinical_ai.get_emr()
    if not emr:
        self._popup("No Data", "Complete the interview first.")
        return
    self._switch("EMR")
    if not hasattr(self, 'ew'):
        return

    direct = {
        "cc": "cc", "hpi": "hpi", "pmh": "pmh", "psh": "psh",
        "dh": "dh", "all": "all", "fh": "fh", "sh": "sh",
        "ros": "ros", "gen": "gen", "cvs": "cvs", "resp": "resp",
        "abd": "abd", "cns": "cns", "dx": "dx", "tx": "tx",
        "fu": "fu",
    }
    for emr_key, ew_key in direct.items():
        if ew_key not in self.ew:
            continue
        val = emr.get(emr_key, "")
        if val in (None, ""):
            continue
        try:
            self.ew[ew_key].text = str(val)
        except Exception:
            pass

    for vk in ("bp", "temp", "pulse", "spo2", "rr", "wt", "ht",
               "bmi", "avpu"):
        v = emr.get(vk, "")
        if v and vk in self.ew:
            try:
                self.ew[vk].text = str(v)
            except Exception:
                pass

    def _join_list(items):
        out = []
        for it in items or []:
            if isinstance(it, dict):
                parts = [it.get("name", ""), it.get("dose", ""),
                         it.get("frequency", ""), it.get("duration", "")]
                out.append(" ".join(p for p in parts if p))
            else:
                out.append(str(it))
        return "\n".join(out)

    if "lab_orders" in self.ew:
        self.ew["lab_orders"].text = _join_list(emr.get("lab_orders"))
    if "radiology_orders" in self.ew:
        self.ew["radiology_orders"].text = _join_list(
            emr.get("radiology_orders"))
    if "prescribed_drugs" in self.ew:
        self.ew["prescribed_drugs"].text = _join_list(
            emr.get("prescribed_drugs"))
    if "nursing_orders" in self.ew:
        self.ew["nursing_orders"].text = _join_list(
            emr.get("nursing_orders"))

    if "notes" in self.ew:
        notes_parts = []
        if emr.get("urgency"):
            notes_parts.append(f"Urgency: {emr['urgency']}")
        if emr.get("follow_up"):
            notes_parts.append(f"Follow-up: {emr['follow_up']}")
        self.ew["notes"].text = "\n".join(notes_parts)

    structured = []
    for d in emr.get("prescribed_drugs", []) or []:
        if isinstance(d, dict):
            structured.append({
                "name": d.get("name", ""),
                "qty_per_day": 1, "days": 1, "total": 1,
                "stock_checked": 0,
            })
    if structured:
        self.emr_drug_list = structured
        self._refresh_drug_display()

    self._popup(
        "EMR Populated",
        "All clerking fields have been written into the EMR form.\n"
        "Review, adjust if needed, then tap SAVE EMR.")

# FIX 10: _save_ca_emr writes the complete EMR record
def _save_ca_emr(self, instance):
    if not self.cp:
        self._popup("Error", "Select a patient first.")
        return
    emr = self.clinical_ai.get_emr()
    if not emr:
        self._popup("Error", "Complete the AI interview first.")
        return
    pid = self.cp.get("id")
    name = self.cp.get("name")
    if not pid:
        return
    record = {
        "emr_id": f"EMR-CA-{datetime.now().strftime('%Y%m%d%H%M%S')}",
        "patient_id": pid, "patient_name": name,
        "dept": "General Medicine",
        "ts": datetime.now().strftime("%Y-%m-%d %H:%M:%S"),
        "admission_id": None,
        "source": "AI_CLERKING",
    }
    for k in ("cc", "hpi", "pmh", "psh", "dh", "all", "fh", "sh", "ros"):
        record[k] = str(emr.get(k, "") or "")
    for k in ("gen", "cvs", "resp", "abd", "cns"):
        record[k] = str(emr.get(k, "") or "")
    for k in ("bp", "temp", "pulse", "spo2", "rr",
              "wt", "ht", "bmi", "avpu"):
        record[k] = str(emr.get(k, "") or ("Alert" if k == "avpu" else ""))
    record["dx"] = str(emr.get("dx", "") or "")
    record["tx"] = str(emr.get("tx", "") or "")
    record["fu"] = str(emr.get("fu", "") or emr.get("follow_up", "") or "")

    def _join(items):
        out = []
        for it in items or []:
            if isinstance(it, dict):
                parts = [it.get("name", ""), it.get("dose", ""),
                         it.get("frequency", ""), it.get("duration", "")]
                out.append(" ".join(p for p in parts if p))
            else:
                out.append(str(it))
        return "\n".join(out)

    record["lab_orders"]       = _join(emr.get("lab_orders"))
    record["radiology_orders"] = _join(emr.get("radiology_orders"))
    record["prescribed_drugs"] = _join(emr.get("prescribed_drugs"))
    record["nursing_orders"]   = _join(emr.get("nursing_orders"))

    notes_parts = []
    if emr.get("urgency"):
        notes_parts.append(f"Urgency: {emr['urgency']}")
    if emr.get("follow_up"):
        notes_parts.append(f"Follow-up: {emr['follow_up']}")
    record["notes"] = "\n".join(notes_parts)

    structured = []
    for d in emr.get("prescribed_drugs", []) or []:
        if isinstance(d, dict) and d.get("name"):
            structured.append({
                "name": d["name"],
                "qty_per_day": 1, "days": 1, "total": 1,
                "stock_checked": 0,
            })
    record["_structured_drugs"] = structured

    self.emr_records.append(record)
    self.save_all()

    try:
        self._auto_assign_tasks_from_emr(record)
    except Exception as e:
        print(f"[AI EMR] auto-task failed: {e}")
    try:
        self._auto_bill_from_emr_record(record)
    except Exception as e:
        print(f"[AI EMR] auto-bill failed: {e}")

    self._popup("Saved",
                f"EMR record saved from AI clerking.\n"
                f"ID: {record['emr_id']}")
    self.audit_log("SAVE_AI_EMR",
                   f"EMR ID {record['emr_id']} from AI clerking", pid)

def _add_ca_bill(self, instance):
    if not self.cp:
        return
    self._switch("Billing")
    self.bill_pid.text = self.cp.get("id", "")
    self.bill_name.text = self.cp.get("name", "")
    self.bill_items.append({"name": "AI Consultation", "cat": "Charges",
                             "qty": 1, "price": 7500, "total": 7500})
    self._refresh_bill()

def _reset_ca(self, instance):
    self.clinical_ai = ModularAIClinicalAssistant(self.ai)
    self.ca_chat.text = ""
    self.ca_diag.text = ""
    self.ca_emr.text = ""
    self.ca_input.text = ""
    if hasattr(self, 'cl_summary'):
        self.cl_summary.text = ""

def _schedule_followup(self, instance):
    if not self.cp:
        self._popup("Error", "Select a patient first!")
        return
    c = BoxLayout(orientation='vertical', spacing=6, padding=8)
    c.add_widget(Label(text="Date (YYYY-MM-DD):", font_size=15, bold=True))
    date_inp = TextInput(text=datetime.now().strftime("%Y-%m-%d"),
                          font_size=15, size_hint_y=None, height=40)
    c.add_widget(date_inp)
    c.add_widget(Label(text="Description:", font_size=15, bold=True))
    desc_inp = TextInput(font_size=15, size_hint_y=None, height=40,
                          hint_text="e.g., Review lab results")
    c.add_widget(desc_inp)
    btns = BoxLayout(size_hint_y=None, height=40, spacing=5)
    pp = Popup(title="Schedule Follow-up", content=c, size_hint=(0.6, 0.4))

    def save_fu(inst):
        date_str = date_inp.text.strip()
        desc = desc_inp.text.strip()
        if not date_str or not desc:
            self._popup("Error", "Both fields required.")
            return
        try:
            datetime.strptime(date_str, "%Y-%m-%d")
        except Exception:
            self._popup("Error", "Invalid date format.")
            return
        self.followups.append({"patient_id": self.cp.get("id"),
                                "date": date_str, "description": desc})
        self.save_all()
        self._refresh_timeline()
        pp.dismiss()
        self._popup("Scheduled", f"Follow-up on {date_str}")
        if self.cp:
            self.task_manager.create_task(
                patient_id=self.cp.get("id"),
                patient_name=self.cp.get("name"),
                assigned_to="Doctor", task_type="Follow-up",
                description=f"Follow-up: {desc} on {date_str}",
                department="Medical")
            self._refresh_tasks()

    btns.add_widget(Button(text="SAVE", font_size=16, bold=True,
                           on_press=save_fu,
                           background_color=get_color_from_hex('#27ae60'),
                           background_normal=''))
