def _on_elab_test_change(self, spinner, test_name):
    self._build_elab_dynamic_row(test_name)

def _build_elab_dynamic_row(self, test_name):
    panel = next(
        (k for k in PANEL_DEFINITIONS
         if k.lower() == str(test_name or '').lower()),
        None)

    swap = getattr(self, 'elab_swap', None)
    if swap is None:
        return
    swap.clear_widgets()
    self.elab_panel_rows = []

    if panel:
        try:
            self.elab_reference.text = "See components below"
        except Exception:
            pass
        header = BoxLayout(size_hint_y=None, height=22, spacing=3)
        for txt, sx in [("Component", .24), ("Result", .27),
                        ("Unit", .20), ("Reference", .29)]:
            header.add_widget(Label(
                text=txt, size_hint_x=sx, font_size=10, bold=True,
                color=get_color_from_hex('#6B7B85')))
        swap.add_widget(header)

        for cname, du, alts, ref in PANEL_DEFINITIONS[panel]:
            row = BoxLayout(size_hint_y=None, height=42, spacing=3)
            row.add_widget(Label(text=cname, size_hint_x=.24, font_size=11))
            ri = TextInput(multiline=False, font_size=12,
                           size_hint_x=.27, size_hint_y=None, height=38)
            row.add_widget(ri)
            options = list(alts) if alts else [du or "—"]
            initial = du if du in options else options[0]
            sp = Spinner(text=initial, values=options, font_size=11,
                         size_hint_x=.20, size_hint_y=None, height=38)
            row.add_widget(sp)
            rr = TextInput(text=ref, multiline=False, font_size=10,
                           size_hint_x=.29, size_hint_y=None, height=38)
            row.add_widget(rr)
            swap.add_widget(row)
            self.elab_panel_rows.append({
                'component': cname,
                'result':    ri,
                'unit':      sp,
                'reference': rr,
                'default_unit': du,
            })
        Clock.schedule_once(
            lambda dt: setattr(swap, 'height', swap.minimum_height), 0)
        return

    if getattr(self, 'elab_single_row', None) is not None:
        try:
            if self.elab_single_row.parent is not None:
                self.elab_single_row.parent.remove_widget(
                    self.elab_single_row)
        except Exception:
            pass
        swap.add_widget(self.elab_single_row)

    test = next((i for i in self.investigations
                 if str(i.get('name', '')).lower() == str(test_name).lower()),
                None)

    ref = (test or {}).get('reference', '')
    try:
        self.elab_reference.text = ref if ref else ""
    except Exception:
        pass

    self.elab_result_container.clear_widgets()
    self.elab_unit_container.clear_widgets()

    rt    = (test or {}).get('result_type', 'text')
    units = (test or {}).get('allowed_units', [])
    du    = (test or {}).get('default_unit', '')

    if rt == 'numeric':
        w = TextInput(multiline=False, font_size=15, input_filter='float',
                      input_type='number', size_hint_y=None, height=42,
                      hint_text="e.g., 98")
    elif rt == 'qualitative':
        opts = (test or {}).get('qualitative_options', []) or \
               ["Negative", "Positive"]
        w = Spinner(text=opts[0], values=opts,
                    size_hint_y=None, height=42)
    else:
        w = TextInput(multiline=False, font_size=15,
                      size_hint_y=None, height=42,
                      hint_text="Enter result")
    self.elab_result_container.add_widget(w)

    if units:
        display_units = [u for u in units if u] or ["—"]
        initial = du if du in display_units else display_units[0]
        u = Spinner(text=initial, values=display_units,
                    size_hint_y=None, height=42)
    else:
        u = TextInput(multiline=False, font_size=15,
                      size_hint_y=None, height=42, hint_text="Unit")
    self.elab_unit_container.add_widget(u)

    self.elab_result_widget = w
    self.elab_unit_widget   = u
    self.elab_result        = w
    self.elab_unit          = u

    Clock.schedule_once(
        lambda dt: setattr(swap, 'height', swap.minimum_height), 0)

def _add_enhanced_lab(self, instance):
    if not getattr(self, 'elab_pid', None) or not self.elab_pid.text or \
            self.elab_test.text == 'Select':
        self._popup('Error', 'Select patient and test.')
        return
    panel = next((k for k in PANEL_DEFINITIONS
                  if k.lower() == self.elab_test.text.lower()), None)
    if panel:
        added = []
        for row in getattr(self, 'elab_panel_rows', []):
            result = row['result'].text.strip()
            if not result:
                continue
            entry = {
                'id': f"ELAB{datetime.now().strftime('%Y%m%d%H%M%S%f')}",
                'patient_id': self.elab_pid.text,
                'patient_name': self.elab_name.text,
                'test_name': row['component'],
                'result': result,
                'unit': row['unit'].text,
                'reference': row['reference'].text,
                'date': datetime.now().strftime("%Y-%m-%d %H:%M:%S"),
                'status': 'Completed',
                'panel': panel,
                'component': row['component'],
            }
            self.lab_results.append(entry)
            added.append(entry)
        if not added:
            self._popup('Error', 'Enter at least one panel result.')
            return
        self.save_all()
        self._refresh_elab()
        self._popup('Added', f'{len(added)} {panel} component(s) added.')
        return

    try:
        result = str(self.elab_result_widget.text).strip()
    except Exception:
        result = ''
    if not result:
        self._popup('Error', 'Enter a result value.')
        return
    test = next((i for i in self.investigations
                 if i.get('name') == self.elab_test.text), None)
    if test and test.get('result_type') == 'numeric':
        try:
            float(result)
        except ValueError:
            self._popup('Invalid Result',
                        f"'{self.elab_test.text}' requires a numeric "
                        f"result.\nYou entered: {result}")
            return
    unit = str(getattr(self.elab_unit_widget, 'text', '')).strip()
    entry = {
        'id': f"ELAB{datetime.now().strftime('%Y%m%d%H%M%S%f')}",
        'patient_id': self.elab_pid.text,
        'patient_name': self.elab_name.text,
        'test_name': self.elab_test.text,
        'result': result,
        'unit': unit,
        'reference': self.elab_reference.text,
        'date': datetime.now().strftime("%Y-%m-%d %H:%M:%S"),
        'status': 'Completed'
    }
    self.lab_results.append(entry)
    self.save_all()
    self._refresh_elab()
    try:
        self.elab_result_widget.text = ''
    except Exception:
        pass
    self._popup('Added', f"{entry['test_name']}: {result} {unit}")

def _refresh_elab(self):
    if not hasattr(self, 'elab_results'):
        return
    self.elab_results.clear_widgets()
    if not self.elab_pid.text:
        self.elab_results.add_widget(Label(
            text="Select a patient to view lab results.",
            font_size=13, size_hint_y=None, height=30))
        return
    pid = self.elab_pid.text
    results = [r for r in self.lab_results if r.get("patient_id") == pid]
    if not results:
        self.elab_results.add_widget(Label(
            text="No lab results for this patient.",
            font_size=13, size_hint_y=None, height=30))
        return
    for r in sorted(results, key=lambda x: x.get('date', ''), reverse=True):
        row = BoxLayout(size_hint_y=None, height=30, spacing=3)
        row.add_widget(Label(text=r.get('test_name', ''), font_size=13,
                              size_hint_x=0.3))
        row.add_widget(Label(text=f"{r.get('result', '')} {r.get('unit', '')}",
                              font_size=13, size_hint_x=0.2, bold=True,
                              color=get_color_from_hex('#2980b9')))
        row.add_widget(Label(text=r.get('date', '')[:16], font_size=11,
                              size_hint_x=0.25))
        btn_del = Button(text="X", font_size=11, size_hint_x=0.05,
                          size_hint_y=None, height=25,
                          background_color=get_color_from_hex('#e74c3c'),
                          background_normal='')
        btn_del.lab_id = r.get('id')
        btn_del.bind(on_press=lambda x: self._delete_enhanced_lab(x.lab_id))
        row.add_widget(btn_del)
        self.elab_results.add_widget(row)

def _delete_enhanced_lab(self, lab_id):
    self.lab_results = [r for r in self.lab_results
                        if r.get('id') != lab_id]
    self.save_all()
    self._refresh_elab()

def _view_all_lab_results(self, instance):
    if not self.elab_pid.text:
        self._popup("Error", "No patient selected.")
        return
    pid = self.elab_pid.text
    results = [r for r in self.lab_results if r.get("patient_id") == pid]
    if not results:
        self._popup("Lab Results", "None found.")
        return
    text = f"LAB RESULTS FOR {self.elab_name.text}\n" + "=" * 50 + "\n\n"
    for r in results:
        text += (f"{r.get('test_name','')}: {r.get('result','')} "
                 f"{r.get('unit','')}\n"
                 f"Date: {r.get('date','')}\n" + "-" * 30 + "\n")
    self._text_popup("Lab Results", text)

def _export_enhanced_lab(self, instance):
    if not self.elab_pid.text:
        self._popup("Error", "No patient selected.")
        return
    pid = self.elab_pid.text
    results = [r for r in self.lab_results if r.get("patient_id") == pid]
    if not results:
        self._popup("Error", "No results to export.")
        return
    text = (f"HMG HOSPITAL - LABORATORY RESULTS\n"
            f"Patient: {self.elab_name.text} (ID: {self.elab_pid.text})\n"
            f"Generated: {datetime.now().strftime('%Y-%m-%d %H:%M:%S')}\n" +
            "=" * 60 + "\n\n")
    for r in results:
        text += (f"Test: {r.get('test_name','')}\n"
                 f"Result: {r.get('result','')} {r.get('unit','')}\n"
                 f"Date: {r.get('date','')}\n" + "-" * 40 + "\n")
    ok, path = self._export_to_pdf(text, "Lab_Results",
                                    "Laboratory Results")
    if path and os.path.exists(path):
        self._open_file_with_fallback(path)

def _clear_enhanced_lab(self, instance):
    if not self._require_role("Administrator", "Doctor", "Lab Scientist"):
        return
    if not self.elab_pid.text:
        return
    pid = self.elab_pid.text
    self.lab_results = [r for r in self.lab_results
                        if r.get("patient_id") != pid]
    self.save_all()
    self._refresh_elab()
    self._popup("Deleted", "All lab results cleared.")
    self.audit_log("DELETE_ENHANCED_LAB", f"Patient {pid}", pid)

# ========== v13.4.1: PDF-first comprehensive report ==========
def _generate_comprehensive_lab_report(self, instance):
    """Build a real vector PDF (ReportLab platypus) for the comprehensive
    lab report. PNG is generated as a secondary artefact only if Pillow
    is available. Does NOT wrap a PNG into a PDF page.
    """
    if not self.elab_pid.text:
        self._popup("Error", "Select a patient first.")
        return

    pid = self.elab_pid.text.strip()
    name = self.elab_name.text.strip() or "Unnamed Patient"
    results = self._get_patient_lab_results(pid)
    if not results:
        self._popup("Error",
                    "No laboratory tests or results found for this patient.")
        return

    patient = next((p for p in self.patients if p.get("id") == pid), None)
    now = datetime.now()
    report_id = f"HMG-LAB-{now.strftime('%Y%m%d%H%M%S')}"
    dir_path = self._get_reports_dir()

    pdf_fn = os.path.join(dir_path,
                           f"Comprehensive_Lab_Report_{report_id}.pdf")
    png_fn = os.path.join(dir_path,
                           f"Comprehensive_Lab_Report_{report_id}.png")

    pdf_ok = False
    png_ok = False

    if REPORTLAB_AVAILABLE:
        try:
            self._render_lab_pdf_native(results, patient, pid, name,
                                         report_id, pdf_fn)
            pdf_ok = (os.path.exists(pdf_fn)
                      and os.path.getsize(pdf_fn) > 500)
            if not pdf_ok:
                sz = (os.path.getsize(pdf_fn)
                      if os.path.exists(pdf_fn) else 0)
                print(f"PDF produced but suspiciously small ({sz} bytes)")
        except Exception as e:
            import traceback
            print("Native PDF error:", traceback.format_exc())
            self._popup("PDF Generation Error",
                        f"ReportLab could not build the PDF:\n{e}\n\n"
                        "Falling back to PNG (if Pillow is installed).")
            pdf_ok = False
    else:
        print("ReportLab is not installed. Skipping PDF generation.")

    if PIL_AVAILABLE:
        try:
            self._render_lab_png_native(results, patient, pid, name,
                                         report_id, png_fn)
            png_ok = (os.path.exists(png_fn)
                      and os.path.getsize(png_fn) > 500)
        except Exception as e:
            print(f"PNG render error: {e}")
            png_ok = False

    if not pdf_ok and not png_ok:
        self._popup(
            "Report Error",
            "Could not generate any report format.\n\n"
            f"ReportLab installed: {REPORTLAB_AVAILABLE}\n"
            f"Pillow installed: {PIL_AVAILABLE}\n\n"
            "Install in Pydroid 3 with:\n"
            "  pip install reportlab pillow")
        return

    primary_file = pdf_fn if pdf_ok else png_fn

    self.saved_lab_reports.append({
        "id": report_id,
        "patient_id": pid,
        "patient_name": name,
        "date": now.strftime("%Y-%m-%d %H:%M:%S"),
        "file_path": primary_file,
        "pdf_path": pdf_fn if pdf_ok else "",
        "image_path": png_fn if png_ok else "",
        "result_count": len(results),
        "format": "PDF" if pdf_ok else "PNG",
    })
    self.save_all()
    self._refresh_saved_reports_list()

    opened = self._open_file_with_fallback(primary_file)
    if opened:
        self._popup(
            "Report Generated",
            f"{'PDF' if pdf_ok else 'Image'} report saved and opened:\n"
            f"{os.path.basename(primary_file)}\n\n"
            f"{len(results)} laboratory item(s) included.")
    else:
        self._popup(
            "Report Saved",
            f"File saved to:\n{primary_file}\n\n"
            "Auto-open failed on this device.\n"
            "Tap OPEN in SAVED REPORTS, or SHARE to send,\n"
            "or SAVE to copy it into Download/HMG_Reports.")

    self.audit_log("GENERATE_LAB_REPORT", report_id, pid)

# ========== v13.4.1: native vector PDF builder ==========
def _render_lab_pdf_native(self, results, patient, pid, name,
                            report_id, out_path):
    """Draw a real PDF (not a wrapped image) with ReportLab platypus."""
    from reportlab.lib.pagesizes import A4
    from reportlab.lib.units import mm
    from reportlab.lib import colors
    from reportlab.lib.styles import ParagraphStyle
    from reportlab.platypus import (SimpleDocTemplate, Paragraph,
                                     Spacer, Table, TableStyle,
                                     Image as RLImage)
    from reportlab.lib.enums import TA_CENTER, TA_LEFT

    now = datetime.now()
    generated = now.strftime("%d/%m/%Y %H:%M")

    NAVY = colors.HexColor(self._fac("navy","#123B72"))
    BLUE = colors.HexColor(self._fac("accent","#1E6AA8"))
    LIGHT = colors.HexColor("#EAF5FC")
    PALE = colors.HexColor("#F5FAFE")
    LINE = colors.HexColor("#B9D5E8")
    DARK = colors.HexColor("#17202A")
    MUTED = colors.HexColor("#536878")
    GREEN = colors.HexColor("#16803A")
    RED = colors.HexColor("#B3261E")
    AMBER = colors.HexColor("#B26A00")

    def sty(size=9, bold=False, align=TA_LEFT, color=DARK,
             leading=None, space_after=2, name="p"):
        return ParagraphStyle(
            name,
            fontName="Helvetica-Bold" if bold else "Helvetica",
            fontSize=size,
            leading=leading or (size + 2),
            alignment=align,
            textColor=color,
            spaceAfter=space_after)

    doc = SimpleDocTemplate(
        out_path, pagesize=A4,
        leftMargin=15 * mm, rightMargin=15 * mm,
        topMargin=12 * mm, bottomMargin=12 * mm,
        title=f"Comprehensive Laboratory Report {report_id}",
        author="HMG Hospital Ltd")

    story = []

    story.append(Paragraph(self._fac("facility_name","HMG HOSPITAL LTD"),
                            sty(18, True, TA_CENTER, NAVY,
                                 leading=22, space_after=0,
                                 name="h1")))
    story.append(Paragraph(
        self._fac("address_line","Obazi Gate, Abonnema, Akulga, Rivers State"),
        sty(9, False, TA_CENTER, MUTED, name="addr")))
    story.append(Paragraph(
        self._fac("tagline","...Quality Care, Healthier Tomorrow"),
        sty(9, False, TA_CENTER, BLUE, name="tag")))
    story.append(Spacer(1, 4 * mm))

    title_tbl = Table(
        [[Paragraph("COMPREHENSIVE LABORATORY REPORT",
                     sty(13, True, TA_CENTER, colors.white,
                         name="rtitle"))]],
        colWidths=[doc.width])
    title_tbl.setStyle(TableStyle([
        ("BACKGROUND", (0, 0), (-1, -1), NAVY),
        ("TOPPADDING", (0, 0), (-1, -1), 8),
        ("BOTTOMPADDING", (0, 0), (-1, -1), 8),
    ]))
    story.append(title_tbl)
    story.append(Spacer(1, 4 * mm))

    age = (patient or {}).get("age", "N/A")
    sex = (patient or {}).get("gender",
                                (patient or {}).get("sex", "N/A"))
    dob = (patient or {}).get("dob", "N/A")

    left_rows = [
        ("Patient Name:", name),
        ("Age:", str(age)),
        ("Sex:", str(sex)),
        ("Patient ID:", pid),
        ("Date of Collection:", generated),
    ]
    right_rows = [
        ("Report ID:", report_id),
        ("Date Reported:", generated),
        ("DOB:", str(dob)),
        ("Sample:", "Laboratory specimen"),
        ("Reporter:", self._fac("signatory_name","Dr. Precious Belema Ibiabuo")),
    ]

    combined_rows = []
    for i in range(max(len(left_rows), len(right_rows))):
        lk, lv = left_rows[i] if i < len(left_rows) else ("", "")
        rk, rv = right_rows[i] if i < len(right_rows) else ("", "")
        combined_rows.append([
            Paragraph(lk, sty(9, True, TA_LEFT, NAVY, name="lbl")),
            Paragraph(lv, sty(9, False, TA_LEFT, DARK, name="val")),
            Paragraph(rk, sty(9, True, TA_LEFT, NAVY, name="lbl2")),
            Paragraph(rv, sty(9, False, TA_LEFT, DARK, name="val2")),
        ])

    info_tbl = Table(
        combined_rows,
        colWidths=[doc.width * 0.19, doc.width * 0.31,
                   doc.width * 0.19, doc.width * 0.31])
    info_tbl.setStyle(TableStyle([
        ("BACKGROUND", (0, 0), (-1, -1), PALE),
        ("BOX", (0, 0), (-1, -1), 1, LINE),
        ("INNERGRID", (0, 0), (-1, -1), 0.25, LINE),
        ("VALIGN", (0, 0), (-1, -1), "MIDDLE"),
        ("TOPPADDING", (0, 0), (-1, -1), 4),
        ("BOTTOMPADDING", (0, 0), (-1, -1), 4),
        ("LEFTPADDING", (0, 0), (-1, -1), 6),
        ("RIGHTPADDING", (0, 0), (-1, -1), 6),
    ]))
    story.append(info_tbl)
    story.append(Spacer(1, 4 * mm))

    headers = ["S/N", "TEST", "RESULT", "UNIT",
               "REFERENCE RANGE", "STATUS"]
    table_data = [[Paragraph(f"<b>{h}</b>",
                              sty(9, True, TA_CENTER, colors.white,
                                  name=f"th{i}"))
                   for i, h in enumerate(headers)]]

    for idx, r in enumerate(results, start=1):
        test_name = str(r.get("test_name", ""))
        result = str(r.get("result", ""))
        unit = str(r.get("unit", ""))
        reference = str(r.get("reference",
                               r.get("reference_range", ""))) or "—"
        status = str(r.get("status", "Completed"))
        sl = status.lower()
        if sl in ("abnormal", "high", "low", "critical"):
            s_color = RED
        elif "pending" in sl or "ordered" in sl:
            s_color = AMBER
        else:
            s_color = GREEN

        table_data.append([
            Paragraph(str(idx),
                       sty(9, False, TA_CENTER, DARK, name=f"sn{idx}")),
            Paragraph(test_name,
                       sty(9, False, TA_LEFT, DARK, name=f"tn{idx}")),
            Paragraph(result,
                       sty(9, False, TA_LEFT, DARK, name=f"rs{idx}")),
            Paragraph(unit,
                       sty(9, False, TA_CENTER, DARK, name=f"un{idx}")),
            Paragraph(reference,
                       sty(8, False, TA_LEFT, MUTED, name=f"rf{idx}")),
            Paragraph(status,
                       sty(9, True, TA_CENTER, s_color, name=f"st{idx}")),
        ])

    results_tbl = Table(
        table_data,
        colWidths=[doc.width * 0.06, doc.width * 0.30,
                   doc.width * 0.14, doc.width * 0.10,
                   doc.width * 0.28, doc.width * 0.12],
        repeatRows=1)
    results_tbl.setStyle(TableStyle([
        ("BACKGROUND", (0, 0), (-1, 0), NAVY),
        ("GRID", (0, 0), (-1, -1), 0.4, LINE),
        ("VALIGN", (0, 0), (-1, -1), "MIDDLE"),
        ("TOPPADDING", (0, 0), (-1, -1), 5),
        ("BOTTOMPADDING", (0, 0), (-1, -1), 5),
        ("LEFTPADDING", (0, 0), (-1, -1), 5),
        ("RIGHTPADDING", (0, 0), (-1, -1), 5),
        ("ROWBACKGROUNDS", (0, 1), (-1, -1),
         [colors.white, colors.HexColor("#FAFCFE")]),
    ]))
    story.append(results_tbl)
    story.append(Spacer(1, 4 * mm))

    interp = ("Laboratory findings are documented as entered in the "
              "EMR. Clinical correlation and review by the responsible "
              "clinician are advised.")
    interp_tbl = Table(
        [[Paragraph("<b>INTERPRETATION / COMMENTS</b>",
                     sty(10, True, TA_LEFT, NAVY, name="ih"))],
         [Paragraph(interp,
                     sty(9, False, TA_LEFT, DARK, name="ib"))]],
        colWidths=[doc.width])
    interp_tbl.setStyle(TableStyle([
        ("BACKGROUND", (0, 0), (-1, -1), LIGHT),
        ("BOX", (0, 0), (-1, -1), 0.6, LINE),
        ("TOPPADDING", (0, 0), (-1, -1), 6),
        ("BOTTOMPADDING", (0, 0), (-1, -1), 6),
        ("LEFTPADDING", (0, 0), (-1, -1), 8),
        ("RIGHTPADDING", (0, 0), (-1, -1), 8),
    ]))
    story.append(interp_tbl)
    story.append(Spacer(1, 8 * mm))

    sig_lines = [
        Paragraph("<b>REPORTED BY</b>",
                   sty(9, True, TA_LEFT, MUTED, name="rby")),
        Paragraph(self._fac("signatory_name","Dr. Precious Belema Ibiabuo"),
                   sty(11, True, TA_LEFT, NAVY, name="rnm")),
        Paragraph(self._fac("signatory_quals","B.Sc., MBBS, M.Sc., MLT, FWACS (Primary)"),
                   sty(8.5, False, TA_LEFT, DARK, name="rq1")),
        Paragraph(self._fac("signatory_role","Medical Director, HMG Hospital Ltd"),
                   sty(8.5, False, TA_LEFT, DARK, name="rq2")),
        Paragraph(f"Electronically signed: {generated}",
                   sty(8, False, TA_LEFT, MUTED, name="rsg")),
    ]
    sig_stack = [[p] for p in sig_lines]
    sig_tbl = Table(sig_stack, colWidths=[doc.width * 0.62])
    sig_tbl.setStyle(TableStyle([
        ("LEFTPADDING", (0, 0), (-1, -1), 0),
        ("RIGHTPADDING", (0, 0), (-1, -1), 0),
        ("TOPPADDING", (0, 0), (-1, -1), 1),
        ("BOTTOMPADDING", (0, 0), (-1, -1), 1),
    ]))

    tmp_qr = None
    qr_cell = Paragraph("", sty(8, name="qre"))
    try:
        qr_b64 = QRCodeGenerator.generate(
            f"HMG|LAB|{report_id}|{pid}|{name}")
        if qr_b64 and PIL_AVAILABLE:
            qr_img = PILImage.open(
                BytesIO(base64.b64decode(qr_b64))).convert("RGB")
            tmp_qr = os.path.join(self._get_reports_dir(),
                                   f".qr_{report_id}.png")
            qr_img.save(tmp_qr)
            qr_cell = RLImage(tmp_qr, width=30 * mm, height=30 * mm)
    except Exception as e:
        print(f"QR embed failed: {e}")

    footer_tbl = Table(
        [[sig_tbl, qr_cell]],
        colWidths=[doc.width * 0.68, doc.width * 0.32])
    footer_tbl.setStyle(TableStyle([
        ("VALIGN", (0, 0), (-1, -1), "TOP"),
        ("LEFTPADDING", (0, 0), (-1, -1), 0),
        ("RIGHTPADDING", (0, 0), (-1, -1), 0),
    ]))
    story.append(footer_tbl)
    story.append(Spacer(1, 6 * mm))
    story.append(Paragraph(
        "HMG Hospital Ltd  |  Medical Records & Diagnostic Services",
        sty(8, False, TA_CENTER, MUTED, name="foot")))

    doc.build(story)

    try:
        if tmp_qr and os.path.exists(tmp_qr):
            os.remove(tmp_qr)
    except Exception:
        pass

# ========== v13.4.1: PNG (secondary artefact) ==========
def _hmg_render_lab_png_native(self, results, patient, pid, name,
                                report_id, out_path):
    from PIL import ImageDraw, ImageFont

    W, H = 1654, 2339
    img = PILImage.new('RGB', (W, H), 'white')
    d = ImageDraw.Draw(img)

    navy    = '#123B72'
    blue    = '#1E6AA8'
    pale    = '#F5FAFE'
    light   = '#EAF5FC'
    line    = '#B9D5E8'
    linealt = '#EDF3F8'
    dark    = '#17202A'
    muted   = '#536878'
    green   = '#16803A'
    red     = '#B3261E'
    amber   = '#B26A00'

    def F(sz, b=False):
        for p in (('/system/fonts/Roboto-Bold.ttf',
                   '/usr/share/fonts/truetype/dejavu/DejaVuSans-Bold.ttf')
                  if b else
                  ('/system/fonts/Roboto-Regular.ttf',
                   '/usr/share/fonts/truetype/dejavu/DejaVuSans.ttf')):
            if os.path.exists(p):
                try:
                    return ImageFont.truetype(p, sz)
                except Exception:
                    pass
        return ImageFont.load_default()

    f8   = F(22)
    f10  = F(27)
    f12  = F(31)
    f14b = F(38, True)
    f18b = F(52, True)
    f_res = F(32, True)
    f_bold = F(28, True)

    def safe(s):
        if s is None:
            return ''
        s = str(s)
        for k, v in (('×', 'x'), ('·', '.'), ('•', '-'),
                     ('–', '-'), ('—', '-'),
                     ('’', "'"), ('‘', "'"),
                     ('“', '"'), ('”', '"'),
                     ('⁹', '^9'), ('¹', '^1'), ('²', '^2'), ('³', '^3'),
                     ('⁴', '^4'), ('⁵', '^5'), ('⁶', '^6'), ('⁷', '^7'),
                     ('⁸', '^8'),
                     ('µ', 'u'), ('μ', 'u'),
                     ('\u200b', ''), ('■', ' '), ('▪', ' '),
                     ('\r', ' '), ('\t', ' '), ('\n', ' ')):
            s = s.replace(k, v)
        return s.strip()

    def fit_txt(value, font, maxw, ellipsis='…'):
        s = safe(value)
        if d.textlength(s, font=font) <= maxw:
            return s
        while s and d.textlength(s + ellipsis, font=font) > maxw:
            s = s[:-1]
        return s + ellipsis

    def t(x, y, v, f=f10, c=dark, a=None):
        d.text((x, y), str(v), font=f, fill=c, anchor=a)

    logo = getattr(self, 'rpt_logo_path', None)
    sig  = getattr(self, 'rpt_signature_path', None)

    # ---------------- Header ----------------
    logo_size = 170
    if logo and os.path.exists(logo):
        li = PILImage.open(logo).convert('RGBA')
        li.thumbnail((logo_size, logo_size))
        img.paste(li, (45, 35), li)
    else:
        cx = 45 + logo_size // 2
        cy = 35 + logo_size // 2
        d.ellipse((cx - logo_size // 2, cy - logo_size // 2,
                   cx + logo_size // 2, cy + logo_size // 2),
                  fill='#2FA84F')
        bw = int(logo_size * 0.18)
        d.rectangle((cx - bw // 2, cy - int(logo_size * 0.32),
                     cx + bw // 2, cy + int(logo_size * 0.32)),
                    fill='white')
        d.rectangle((cx - int(logo_size * 0.32), cy - bw // 2,
                     cx + int(logo_size * 0.32), cy + bw // 2),
                    fill='white')

    hx = 45 + logo_size + 35

    t(hx, 45, self._fac("facility_name","HMG HOSPITAL LTD"), f18b, navy)
    t(hx, 105, self._fac("address_line","Obazi Gate, Abonnema, Akulga, Rivers State"), f10, muted)
    t(hx, 140, self._fac("tagline","...Quality Care, Healthier Tomorrow"), f8, blue)
    d.line((40, 240, W - 40, 240), fill=navy, width=4)

    d.rounded_rectangle((40, 265, W - 40, 340), 12, fill=navy)
    t(W // 2, 303, 'COMPREHENSIVE LABORATORY REPORT', f14b, 'white', 'mm')

    # ---------------- Patient info strip ----------------
    t(55, 375, f'PATIENT: {safe(name)}', f12, dark)
    t(W - 55, 375, f'REPORT ID: {safe(report_id)}', f12, dark, 'ra')
    t(55, 410, f'ID: {safe(pid)}', f10, muted)
    t(W - 55, 410, datetime.now().strftime('%d/%m/%Y %H:%M'),
      f10, muted, 'ra')
    t(55, 445, f'AGE / SEX: {safe(patient.get("age","N/A"))} / '
               f'{safe(patient.get("gender","N/A"))}', f10, muted)

    # ---------------- Table ----------------
    table_top  = 490
    header_h   = 54
    row_h      = 46
    footer_top = 2010
    gap        = 18
    interp_h   = 150

    # S/N  TEST   RESULT (widest)   UNIT  REFERENCE  STATUS
    cols = [40, 90, 505, 1055, 1140, 1345, W - 40]
    heads = ['S/N', 'TEST', 'RESULT', 'UNIT',
             'REFERENCE RANGE', 'STATUS']

    d.rectangle((40, table_top, W - 40, table_top + header_h), fill=navy)
    for i, h in enumerate(heads):
        t((cols[i] + cols[i + 1]) // 2, table_top + header_h // 2,
          h, f10, 'white', 'mm')

    max_rows = max(0, (footer_top - gap - interp_h - gap -
                       (table_top + header_h)) // row_h)
    shown = results[:max_rows]
    row_y = table_top + header_h

    for idx, r in enumerate(shown, 1):
        if idx % 2 == 0:
            d.rectangle((40, row_y, W - 40, row_y + row_h),
                        fill=linealt)
        d.rectangle((40, row_y, W - 40, row_y + row_h),
                    outline=line, width=1)
        for x in cols[1:-1]:
            d.line((x, row_y, x, row_y + row_h), fill=line, width=1)

        test_name = safe(r.get('test_name', ''))
        result    = safe(r.get('result', ''))
        unit      = safe(r.get('unit', ''))
        reference = safe(r.get('reference',
                              r.get('reference_range', ''))) or '—'
        status    = safe(r.get('status', 'Completed'))
        sl = status.lower()
        if sl in ('abnormal', 'high', 'low', 'critical'):
            sc = red
        elif 'pending' in sl or 'ordered' in sl:
            sc = amber
        else:
            sc = green

        cy = row_y + row_h // 2

        t((cols[0] + cols[1]) // 2, cy, idx, f8, muted, 'mm')

        t(cols[1] + 12, cy,
          fit_txt(test_name, f_bold, (cols[2] - cols[1]) - 20),
          f_bold, dark, 'lm')

        t((cols[2] + cols[3]) // 2, cy,
          fit_txt(result, f_res, (cols[3] - cols[2]) - 24),
          f_res, blue, 'mm')

        t((cols[3] + cols[4]) // 2, cy,
          fit_txt(unit, f8, (cols[4] - cols[3]) - 12),
          f8, muted, 'mm')

        t(cols[4] + 12, cy,
          fit_txt(reference, f8, (cols[5] - cols[4]) - 20),
          f8, muted, 'lm')

        pill_w = 200
        pill_h = 34
        cx_pill = (cols[5] + cols[6]) // 2
        pill_x = cx_pill - pill_w // 2
        pill_y = cy - pill_h // 2
        d.rounded_rectangle((pill_x, pill_y,
                             pill_x + pill_w, pill_y + pill_h),
                            radius=pill_h // 2, outline=sc, width=2)
        t(cx_pill, cy, fit_txt(status, f8, pill_w - 16),
          f8, sc, 'mm')

        row_y += row_h

    if len(results) > len(shown):
        t(55, row_y + 8,
          f'… {len(results) - len(shown)} more laboratory item(s) not '
          f'shown — see the PDF version for the full list.',
          f8, muted)

    # ---------------- Interpretation ----------------
    interp_top = row_y + gap
    d.rounded_rectangle((40, interp_top, W - 40, interp_top + interp_h),
                        12, fill=light, outline=line, width=2)
    t(60, interp_top + 25, 'INTERPRETATION / COMMENTS', f14b, navy)
    t(60, interp_top + 72,
      'Laboratory findings are documented as entered in the EMR.',
      f10, dark)
    t(60, interp_top + 105,
      'Clinical correlation and review by the responsible clinician are advised.',
      f10, dark)

    # ---------------- Footer ----------------
    if sig and os.path.exists(sig):
        si = PILImage.open(sig).convert('RGBA')
        si.thumbnail((520, 170))
        img.paste(si, (55, footer_top + 55), si)

    t(55, footer_top + 25, 'REPORTED BY', f10, muted)
    t(55, footer_top + 205, self._fac("signatory_name","Dr. Precious Belema Ibiabuo"), f14b, navy)
    t(55, footer_top + 240,
      self._fac("signatory_quals","B.Sc., MBBS, M.Sc., MLT, FWACS (Primary)") + ' • ' +
      self._fac("signatory_role","Medical Director, HMG Hospital Ltd"), f8, dark)

    try:
        b = QRCodeGenerator.generate(
            f'HMG|LAB|{report_id}|{pid}|{name}')
        q = PILImage.open(BytesIO(base64.b64decode(b))).convert('RGB')
        q = q.resize((180, 180))
        qx = W - 240
        qy = footer_top + 70
        d.rectangle((qx - 8, qy - 8, qx + 188, qy + 188),
                    outline=navy, width=2)
        img.paste(q, (qx, qy))
        t(qx + 90, qy - 22, 'SCAN TO VERIFY', f8, navy, 'ms')
    except Exception as e:
        print(f'QR PNG failed: {e}')

    strip = H - 70
    d.rectangle((0, strip, W, H), fill=navy)
    t(40, strip + 35,
      f'HMG Hospital Ltd • Laboratory Report • '
      f'{datetime.now().strftime("%d/%m/%Y")}',
      f8, 'white', 'lm')
    t(W - 40, strip + 35, 'SCAN TO VERIFY', f8, 'white', 'rm')

    img.save(out_path, 'PNG', optimize=True)

# ========== v13.4.1: saved reports list with SAVE button ==========
def _refresh_saved_reports_list(self):
    if not hasattr(self, 'saved_reports_list'):
        return
    self.saved_reports_list.clear_widgets()

    if not self.elab_pid.text:
        self.saved_reports_list.add_widget(Label(
            text="Select a patient to view saved reports.",
            font_size=13, size_hint_y=None, height=30,
            color=get_color_from_hex('#7f8c8d')))
        return

    pid = self.elab_pid.text
    reports = [r for r in self.saved_lab_reports
               if r.get("patient_id") == pid]
    if not reports:
        self.saved_reports_list.add_widget(Label(
            text="No saved reports for this patient.",
            font_size=13, size_hint_y=None, height=30,
            color=get_color_from_hex('#7f8c8d')))
        return

    for r in sorted(reports, key=lambda x: x.get('date', ''),
                    reverse=True):
        row = BoxLayout(size_hint_y=None, height=36, spacing=3)

        fpath = r.get('file_path', '')
        pdf_path = r.get('pdf_path', '')
        img_path = r.get('image_path', '')

        row.add_widget(Label(
            text=(f"{r.get('id', '')} | "
                  f"{r.get('date', '')[:16]} | "
                  f"{r.get('result_count', 0)} results "
                  f"[{r.get('format', 'PNG')}]"),
            font_size=11, size_hint_x=0.42,
            shorten=True, shorten_from='right'))

        btn_open = Button(text="OPEN", font_size=11, size_hint_x=0.13,
                          size_hint_y=None, height=30,
                          background_color=get_color_from_hex('#2980b9'),
                          background_normal='')
        btn_open.file_path = fpath
        btn_open.bind(on_press=lambda x: self._open_saved_report(
            x.file_path))
        row.add_widget(btn_open)

        btn_share = Button(text="SHARE", font_size=11, size_hint_x=0.13,
                           size_hint_y=None, height=30,
                           background_color=get_color_from_hex('#8e44ad'),
                           background_normal='')
        btn_share.file_path = fpath
        btn_share.bind(on_press=lambda x: self._share_file(x.file_path))
        row.add_widget(btn_share)

        btn_pdf = Button(text="PDF", font_size=11, size_hint_x=0.10,
                         size_hint_y=None, height=30,
                         background_color=get_color_from_hex('#16a085'),
                         background_normal='')
        btn_pdf.pdf_path = pdf_path
        btn_pdf.bind(on_press=lambda x: self._open_saved_report(
            x.pdf_path))
        row.add_widget(btn_pdf)

        btn_save = Button(text="SAVE", font_size=11, size_hint_x=0.12,
                          size_hint_y=None, height=30,
                          background_color=get_color_from_hex('#f39c12'),
                          background_normal='')
        btn_save.file_path = fpath
        btn_save.bind(on_press=lambda x: self._save_to_public_downloads(
            x.file_path))
        row.add_widget(btn_save)

        btn_del = Button(text="X", font_size=11, size_hint_x=0.08,
                         size_hint_y=None, height=30,
                         background_color=get_color_from_hex('#e74c3c'),
                         background_normal='')
        btn_del.report_id = r.get('id')
        btn_del.bind(on_press=lambda x: self._delete_saved_report(
            x.report_id))
        row.add_widget(btn_del)

        self.saved_reports_list.add_widget(row)

def _open_saved_report(self, filepath):
    if not filepath or not os.path.exists(filepath):
        self._popup("Error",
                    f"File not found:\n{filepath or '(no path)'}")
        return
    if not self._open_file_with_fallback(filepath):
        self._popup("Cannot Auto-Open",
                    f"Unable to launch a viewer.\n\nFile:\n{filepath}\n\n"
                    f"Try the SHARE button instead, or SAVE to copy it "
                    f"into Download/HMG_Reports.")

def _delete_saved_report(self, report_id):
    self.saved_lab_reports = [r for r in self.saved_lab_reports
                               if r.get('id') != report_id]
    self.save_all()
    self._refresh_saved_reports_list()
    self._popup("Deleted", "Report removed.")

    # ---------- Radiology ----------
    def _rad(self):
        tab = TabbedPanelItem(text="Radiology")
        s = ScrollView()
        l = BoxLayout(orientation='vertical', padding=5, spacing=3, size_hint_y=None)
        l.bind(minimum_height=l.setter('height'))
        bar = BoxLayout(size_hint_y=None, height=40, spacing=4)
        bar.add_widget(Label(text="ID:", font_size=15, bold=True, size_hint_x=0.05))
        self.rad_pid = TextInput(size_hint_x=0.15, readonly=True, font_size=15,
                                  size_hint_y=None, height=40)
        bar.add_widget(self.rad_pid)
        bar.add_widget(Label(text="Name:", font_size=15, bold=True, size_hint_x=0.07))
        self.rad_name = TextInput(size_hint_x=0.35, readonly=True, font_size=15,
                                   size_hint_y=None, height=40)
        bar.add_widget(self.rad_name)
        l.add_widget(bar)
        order = BoxLayout(size_hint_y=None, height=40, spacing=4)
        order.add_widget(Label(text="Study:", font_size=15, bold=True,
                                size_hint_x=0.06))
        self.rad_study = Spinner(
            text="Select",
            values=["X-Ray Chest", "X-Ray Abdomen", "CT Scan", "MRI",
                    "Ultrasound", "Mammogram", "DEXA Scan", "Fluoroscopy"],
            size_hint_x=0.3, size_hint_y=None, height=40)
        order.add_widget(self.rad_study)
        order.add_widget(Button(text="ORDER", font_size=15, bold=True,
                                 size_hint_x=0.15, on_press=self._order_rad,
                                 background_color=get_color_from_hex('#2980b9'),
                                 background_normal=''))
        order.add_widget(Button(text="VIEW", font_size=15, bold=True,
                                 size_hint_x=0.15, on_press=self._view_rad,
                                 background_color=get_color_from_hex('#16a085'),
                                 background_normal=''))
        order.add_widget(Button(text="DELETE", font_size=15, bold=True,
                                 size_hint_x=0.1, on_press=self._delete_rad,
                                 background_color=get_color_from_hex('#e74c3c'),
                                 background_normal=''))
        l.add_widget(order)
        self.rad_list = BoxLayout(orientation='vertical',
                                   size_hint_y=None, spacing=1)
        self.rad_list.bind(minimum_height=self.rad_list.setter('height'))
        l.add_widget(self.rad_list)
        s.add_widget(l)
        tab.add_widget(s)
        self.tp.add_widget(tab)
        self._refresh_rad()

    def _order_rad(self, instance):
        if not self.rad_pid.text or self.rad_study.text == "Select":
            self._popup("Error", "Select patient and study.")
            return
        self.radiology.append({
            "rad_id": f"RAD{datetime.now().strftime('%Y%m%d%H%M%S%f')}",
            "patient_id": self.rad_pid.text,
            "patient_name": self.rad_name.text,
            "study": self.rad_study.text, "status": "Ordered", "report": "",
            "date": datetime.now().strftime("%Y-%m-%d %H:%M"),
            "completed": ""})
        self.save_all()
        self._refresh_rad()
        self._popup("Ordered", f"{self.rad_study.text} ordered.")
        self.audit_log("ORDER_RAD", self.rad_study.text, self.rad_pid.text)
        if self.cp:
            self.task_manager.create_task(
                patient_id=self.cp.get("id"),
                patient_name=self.cp.get("name"),
                assigned_to="Radiologist",
                task_type="Radiology",
                description=f"Radiology study: {self.rad_study.text}",
                order_items=[self.rad_study.text],
                department="Radiology")
            self._refresh_tasks()

    def _refresh_rad(self):
        if not hasattr(self, 'rad_list'):
            return
        self.rad_list.clear_widgets()
        if not self.rad_pid.text:
            return
        pid = self.rad_pid.text
        studies = [r for r in self.radiology if r.get("patient_id") == pid]
        if not studies:
            self.rad_list.add_widget(Label(text="No radiology studies.",
                                            font_size=13,
                                            size_hint_y=None, height=30))
            return
        for r in studies:
            row = BoxLayout(size_hint_y=None, height=35, spacing=3)
            row.add_widget(Label(text=f"{r.get('study','')} - "
                                       f"{r.get('status','')}",
                                  font_size=13, size_hint_x=0.5))
            if r.get("status") == "Ordered":
                btn = Button(text="ENTER REPORT", font_size=12,
                              size_hint_x=0.25, size_hint_y=None, height=30,
                              background_color=get_color_from_hex('#27ae60'),
                              background_normal='')
                btn.rad = r
                btn.bind(on_press=self._enter_rad_report)
                row.add_widget(btn)
            elif r.get("status") == "Completed":
                btn = Button(text="VIEW REPORT", font_size=12,
                              size_hint_x=0.25, size_hint_y=None, height=30,
                              background_color=get_color_from_hex('#2980b9'),
                              background_normal='')
                btn.rad = r
                btn.bind(on_press=lambda x: self._text_popup(
                    "Radiology Report", x.rad.get('report', 'No report')))
                row.add_widget(btn)
                img_btn = Button(text="IMAGE REPORT", font_size=12,
                                 size_hint_x=0.18,
                                 size_hint_y=None, height=30,
                                 background_color=get_color_from_hex('#8e44ad'),
                                 background_normal='')
                img_btn.rad = r
                img_btn.bind(on_press=self._export_radiology_image)
                row.add_widget(img_btn)
            row.add_widget(Button(text="X", font_size=12, size_hint_x=0.1,
                                   size_hint_y=None, height=30,
                                   background_color=get_color_from_hex('#e74c3c'),
                                   background_normal='',
                                   on_press=lambda x, rid=r.get('rad_id'):
                                   self._remove_rad(rid)))
            self.rad_list.add_widget(row)

    def _enter_rad_report(self, instance):
        rad = instance.rad
        content = BoxLayout(orientation='vertical', spacing=5, padding=8)
        content.add_widget(Label(text=f"Report for {rad.get('study')}",
                                  font_size=16, bold=True,
                                  size_hint_y=None, height=30))
        content.add_widget(Label(text="Findings:", font_size=14, bold=True,
                                  size_hint_y=None, height=22))
        report_inp = TextInput(font_size=14, size_hint_y=None, height=120,
                                multiline=True)
        content.add_widget(report_inp)
        content.add_widget(Label(text="Impression:", font_size=14, bold=True,
                                  size_hint_y=None, height=22))
        imp_inp = TextInput(font_size=14, size_hint_y=None, height=80,
                             multiline=True)
        content.add_widget(imp_inp)
        btn_box = BoxLayout(size_hint_y=None, height=40, spacing=5)
        pp = Popup(title="Enter Report", content=content, size_hint=(0.7, 0.7))

        def save(inst):
            rad["report"] = (f"Findings:\n{report_inp.text}\n\n"
                             f"Impression:\n{imp_inp.text}")
            rad["status"] = "Completed"
            rad["completed"] = datetime.now().strftime("%Y-%m-%d %H:%M:%S")
            self.save_all()
            self._refresh_rad()
            for task in self.tasks:
                if (task.get("patient_id") == rad.get("patient_id") and
                        "Radiology" in task.get("task_type") and
                        task.get("status") != "Completed"):
                    if rad.get("study") in task.get("description", ""):
                        self.task_manager.update_status(
                            task.get("id"), "Completed", "Report completed")
                        break
            self._refresh_tasks()
            pp.dismiss()
            self._popup("Saved", "Radiology report completed.")
            self.audit_log("ENTER_RAD_REPORT", rad.get('study'),
                           rad.get("patient_id"))
        btn_box.add_widget(Button(text="SAVE", font_size=15, bold=True,
                                   on_press=save,
                                   background_color=get_color_from_hex('#27ae60'),
                                   background_normal=''))
        btn_box.add_widget(Button(text="CANCEL", font_size=15,
                                   on_press=pp.dismiss,
                                   background_color=get_color_from_hex('#e74c3c'),
                                   background_normal=''))
        content.add_widget(btn_box)
        pp.open()

    def _export_radiology_image(self, instance):
        rad = getattr(instance, 'rad', None) or {}
        pid = str(rad.get('patient_id', '')).strip()
        if not pid:
            self._popup('Error', 'Patient identity is missing.')
            return
        patient = self._patient_identity_for_report(pid)
        report = (f"Study: {rad.get('study','')}\n"
                  f"Status: {rad.get('status','')}\n"
                  f"Date: {rad.get('date', rad.get('completed',''))}\n\n"
                  f"{rad.get('report','No radiology report entered.')}")
        path = self._render_professional_report_image(
            report, 'Radiology_Report', 'Radiology Report', patient=patient,
            report_id=rad.get('rad_id') or None)
        if path:
            self._open_file(path)
            self._popup('Report Generated',
                        f'Professional image report saved:\n{path}')
            self.audit_log('EXPORT_RADIOLOGY_IMAGE', path, pid)

    def _remove_rad(self, rad_id):
        self.radiology = [r for r in self.radiology
                          if r.get("rad_id") != rad_id]
        self.save_all()
        self._refresh_rad()

    def _view_rad(self, instance):
        if not self.rad_pid.text:
            self._popup("Error", "No patient selected.")
            return
        pid = self.rad_pid.text
        studies = [r for r in self.radiology if r.get("patient_id") == pid]
        if not studies:
            self._popup("Radiology", "None found.")
            return
        text = f"RADIOLOGY STUDIES FOR {self.rad_name.text}\n" + "=" * 50 + "\n\n"
        for r in studies:
            text += (f"Study: {r.get('study','')}\n"
                     f"Status: {r.get('status','')}\n"
                     f"Date: {r.get('date','')}\n")
            if r.get("report"):
                text += f"\nReport:\n{r.get('report','')}\n"
            text += "-" * 30 + "\n"
        self._text_popup("Radiology Studies", text)

    def _delete_rad(self, instance):
        if not self._require_role("Administrator", "Doctor", "Radiologist"):
            return
        if not self.rad_pid.text:
            return
        pid = self.rad_pid.text
        self.radiology = [r for r in self.radiology
                          if r.get("patient_id") != pid]
        self.save_all()
        self._refresh_rad()
        self._popup("Deleted", "All radiology studies deleted.")
        self.audit_log("DELETE_RAD_ALL", f"Patient {pid}", pid)

    # ---------- Upload ----------
    def _upload_tab(self):
        tab = TabbedPanelItem(text="Upload/Results")
        s = ScrollView()
        l = BoxLayout(orientation='vertical', padding=5, spacing=3,
                      size_hint_y=None)
        l.bind(minimum_height=l.setter('height'))
        bar = BoxLayout(size_hint_y=None, height=40, spacing=4)
        bar.add_widget(Label(text="ID:", font_size=15, bold=True,
                              size_hint_x=0.05))
        self.up_pid = TextInput(size_hint_x=0.15, readonly=True, font_size=15,
                                 size_hint_y=None, height=40)
        bar.add_widget(self.up_pid)
        bar.add_widget(Label(text="Name:", font_size=15, bold=True,
                              size_hint_x=0.07))
        self.up_name = TextInput(size_hint_x=0.35, readonly=True, font_size=15,
                                  size_hint_y=None, height=40)
        bar.add_widget(self.up_name)
        l.add_widget(bar)
        upload = BoxLayout(size_hint_y=None, height=40, spacing=4)
        upload.add_widget(Button(text="UPLOAD FILE", font_size=15, bold=True,
                                  size_hint_x=0.25, on_press=self._upload_file,
                                  background_color=get_color_from_hex('#2980b9'),
                                  background_normal=''))
        upload.add_widget(Button(text="VIEW RESULTS", font_size=15, bold=True,
                                  size_hint_x=0.25,
                                  on_press=self._view_uploaded_results,
                                  background_color=get_color_from_hex('#16a085'),
                                  background_normal=''))
        upload.add_widget(Button(text="DELETE", font_size=15, bold=True,
                                  size_hint_x=0.15,
                                  on_press=self._delete_uploaded,
                                  background_color=get_color_from_hex('#e74c3c'),
                                  background_normal=''))
        l.add_widget(upload)
        self.up_list = BoxLayout(orientation='vertical',
                                  size_hint_y=None, spacing=1)
        self.up_list.bind(minimum_height=self.up_list.setter('height'))
        l.add_widget(self.up_list)
        s.add_widget(l)
        tab.add_widget(s)
        self.tp.add_widget(tab)

    def _upload_file(self, instance):
        if not self.up_pid.text:
            self._popup("Error", "No patient selected.")
            return
        c = BoxLayout(orientation='vertical', spacing=4, padding=4)
        fc = FileChooserListView(path=os.getcwd())
        c.add_widget(fc)
        btns = BoxLayout(size_hint_y=None, height=42, spacing=5)
        pp = Popup(title="Upload File", content=c, size_hint=(0.9, 0.85))

        def select(inst):
            if fc.selection:
                src = fc.selection[0]
                dest_dir = os.path.join(self._get_reports_dir(),
                                         self.up_pid.text)
                os.makedirs(dest_dir, exist_ok=True)
                dest = os.path.join(dest_dir, os.path.basename(src))
                shutil.copy2(src, dest)
                self._popup("Uploaded", f"File saved to {dest}")
                self.audit_log("UPLOAD_FILE", os.path.basename(src),
                               self.up_pid.text)
                pp.dismiss()
                self._refresh_uploaded_results()
        btns.add_widget(Button(text="SELECT", font_size=16, bold=True,
                               on_press=select,
                               background_color=get_color_from_hex('#27ae60'),
                               background_normal=''))
        btns.add_widget(Button(text="CANCEL", font_size=16,
                               on_press=lambda x: pp.dismiss(),
                               background_normal=''))
        c.add_widget(btns)
        pp.open()

    def _refresh_uploaded_results(self):
        if not hasattr(self, 'up_list'):
            return
        self.up_list.clear_widgets()
        if not self.up_pid.text:
            self.up_list.add_widget(Label(
                text="Select a patient to view uploaded files.",
                font_size=13, size_hint_y=None, height=30))
            return
        pid = self.up_pid.text
        dir_path = os.path.join(self._get_reports_dir(), pid)
        if not os.path.exists(dir_path):
            self.up_list.add_widget(Label(text="No uploaded files.",
                                            font_size=13, size_hint_y=None,
                                            height=30))
            return
        files = os.listdir(dir_path)
        if not files:
            self.up_list.add_widget(Label(text="No files in patient directory.",
                                            font_size=13, size_hint_y=None,
                                            height=30))
            return
        for f in files:
            row = BoxLayout(size_hint_y=None, height=35, spacing=3)
            row.add_widget(Label(text=f, font_size=13, size_hint_x=0.8))
            btn = Button(text="VIEW", font_size=13, size_hint_x=0.2,
                          size_hint_y=None, height=30,
                          background_color=get_color_from_hex('#2980b9'),
                          background_normal='')
            btn.filepath = os.path.join(dir_path, f)
            btn.bind(on_press=lambda x: self._open_file(x.filepath))
            row.add_widget(btn)
            self.up_list.add_widget(row)

    def _view_uploaded_results(self, instance):
        self._refresh_uploaded_results()

    def _delete_uploaded(self, instance):
        if not self._require_role("Administrator", "Doctor"):
            return
        if not self.up_pid.text:
            return
        pid = self.up_pid.text
        dir_path = os.path.join(self._get_reports_dir(), pid)
        if not os.path.exists(dir_path):
            self._popup("Info", "No files to delete.")
            return
        shutil.rmtree(dir_path)
        self._refresh_uploaded_results()
        self._popup("Deleted", "All files deleted.")
        self.audit_log("DELETE_UPLOADED", f"Patient {pid}", pid)

