    def _run_full_analysis(self, instance):
        if not self.cp or not self.ai.enabled:
            self._popup("Error", "Select patient and enable AI.")
            return
        pid = self.cp.get("id")
        emrs = [r for r in self.emr_records if r.get("patient_id") == pid]
        labs = [t for t in self.lab_tests if t.get("patient_id") == pid
                and t.get("status") == "Completed"]
        rx = [p for p in self.prescriptions if p.get("patient_id") == pid]
        self.ai_stats_emr.text = f"EMR: {len(emrs)}"
        self.ai_stats_lab.text = f"Lab: {len(labs)}"
        self.ai_stats_rx.text = f"Rx: {len(rx)}"
        prompt = (f"Patient: {self.cp.get('name', '')} (ID: {pid})\n"
                  f"Age: {self.cp.get('age', 0)}\n"
                  f"EMR: {len(emrs)}, Lab: {len(labs)}, Rx: {len(rx)}\n"
                  f"Provide comprehensive clinical analysis.")
        self.ai_analysis_output.text = "Generating..."

        def run():
            ok, resp = self.ai.call("You are a senior clinician.",
                                     prompt, mt=2000)
            Clock.schedule_once(lambda dt: setattr(
                self.ai_analysis_output, 'text', resp), 0)
        threading.Thread(target=run, daemon=True).start()

    def _run_clinical_summary_ai(self, instance):
        if not self.cp or not self.ai.enabled:
            self._popup("Error", "Select patient and enable AI.")
            return
        prompt = (f"Patient: {self.cp.get('name', '')}, "
                  f"Age: {self.cp.get('age', 0)}\n"
                  f"Generate a concise clinical summary.")
        self.ai_analysis_output.text = "Generating..."

        def run():
            ok, resp = self.ai.call("You are a clinician.", prompt, mt=1000)
            Clock.schedule_once(lambda dt: setattr(
                self.ai_analysis_output, 'text', resp), 0)
        threading.Thread(target=run, daemon=True).start()

