    def _refresh_vitals_timeline(self):
        if not hasattr(self, 'vitals_list'):
            return
        self.vitals_list.clear_widgets()
        if not self.cp:
            self.vitals_list.add_widget(Label(
                text="Select a patient.", font_size=14,
                size_hint_y=None, height=30))
            self.news_label.text = "NEWS2: --"
            self.qsofa_label.text = "qSOFA: --"
            return
        pid = self.cp.get("id")
        records = [r for r in self.emr_records if r.get("patient_id") == pid]
        for dn in self.daily_notes:
            if dn.get("patient_id") == pid:
                records.append({
                    "ts": dn.get("date", "") + " 08:00",
                    "bp": dn.get("vitals", {}).get("bp", ""),
                    "pulse": dn.get("vitals", {}).get("pulse", ""),
                    "rr": dn.get("vitals", {}).get("rr", ""),
                    "spo2": dn.get("vitals", {}).get("spo2", ""),
                    "temp": dn.get("vitals", {}).get("temp", ""),
                    "avpu": dn.get("vitals", {}).get("avpu", "Alert")})
        records.sort(key=lambda x: x.get("ts", ""))
        if not records:
            self.vitals_list.add_widget(Label(text="No records found.",
                                                font_size=14,
                                                size_hint_y=None, height=30))
            return
        latest = records[-1]
        bp = latest.get("bp", "")
        pulse = latest.get("pulse", "")
        rr = latest.get("rr", "")
        spo2 = latest.get("spo2", "")
        temp = latest.get("temp", "")
        avpu = latest.get("avpu", "Alert")
        news = self.compute_news(bp, pulse, rr, spo2, temp, avpu)
        qsofa = self.compute_qsofa(bp, rr, avpu)
        news_color = ("#27ae60" if news <= 4
                      else "#f39c12" if news <= 6 else "#e74c3c")
        self.news_label.text = f"NEWS2: {news}"
        self.news_label.color = get_color_from_hex(news_color)
        self.qsofa_label.text = (f"qSOFA: {qsofa}" +
                                  (" (Sepsis risk)" if qsofa >= 2 else ""))
        for r in records:
            row = BoxLayout(size_hint_y=None, height=28, spacing=2)
            row.add_widget(Label(text=r.get("ts", "N/A")[:16], font_size=12,
                                  size_hint_x=0.15))
            row.add_widget(Label(text=r.get("bp", "-"), font_size=12,
                                  size_hint_x=0.1))
            row.add_widget(Label(text=r.get("pulse", "-"), font_size=12,
                                  size_hint_x=0.08))
            row.add_widget(Label(text=r.get("spo2", "-"), font_size=12,
                                  size_hint_x=0.08))
            row.add_widget(Label(text=r.get("rr", "-"), font_size=12,
                                  size_hint_x=0.08))
            row.add_widget(Label(text=r.get("temp", "-"), font_size=12,
                                  size_hint_x=0.08))
            row.add_widget(Label(text=r.get("avpu", "Alert"), font_size=12,
                                  size_hint_x=0.1))
            self.vitals_list.add_widget(row)

    @staticmethod
    def compute_news(bp, pulse, rr, spo2, temp, avpu="Alert"):
        score = 0
        sbp = None
        if bp and '/' in bp:
            try:
                sbp = int(bp.split('/')[0])
            except Exception:
                pass
        if sbp:
            if sbp <= 90 or sbp >= 220:
                score += 3
            elif sbp <= 100:
                score += 2
            elif sbp <= 110:
                score += 1
        try:
            hr = int(pulse)
        except Exception:
            hr = 0
        if hr > 0:
            if hr <= 40 or hr >= 131:
                score += 3
            elif hr <= 50 or hr >= 111:
                score += 2
            elif hr > 90:
                score += 1
        try:
            rv = int(rr)
        except Exception:
            rv = 0
        if rv > 0:
            if rv <= 8 or rv >= 25:
                score += 3
            elif rv <= 11 or rv >= 21:
                score += 1
        try:
            sv = int(spo2)
        except Exception:
            sv = 0
        if sv > 0:
            if sv <= 91:
                score += 3
            elif sv <= 93:
                score += 2
            elif sv <= 95:
                score += 1
        try:
            tv = float(temp)
        except Exception:
            tv = 0
        if tv > 0:
            if tv <= 35.0:
                score += 3
            elif tv >= 39.1:
                score += 2
            elif tv >= 38.1:
                score += 1
        if avpu != "Alert":
            score += 3
        return score

    @staticmethod
    def compute_qsofa(bp, rr, avpu="Alert"):
        score = 0
        sbp = None
        if bp and '/' in bp:
            try:
                sbp = int(bp.split('/')[0])
            except Exception:
                pass
        if sbp and sbp <= 100:
            score += 1
        try:
            rv = int(rr)
        except Exception:
            rv = 0
        if rv >= 22:
            score += 1
        if avpu != "Alert":
            score += 1
        return score

