        self.nurse_list = BoxLayout(orientation='vertical',
                                     size_hint_y=None, spacing=1)
        self.nurse_list.bind(minimum_height=self.nurse_list.setter('height'))
        l.add_widget(self.nurse_list)
        s.add_widget(l)
