    def _refresh_transfer_list(self):
        if not hasattr(self, 'transfer_list'):
            return
        self.transfer_list.clear_widgets()
        if (not getattr(self, 'transfer_pid', None) or
                not self.transfer_pid.text):
            self.transfer_list.add_widget(Label(
                text="Select a patient to view transfer records.",
                font_size=13, size_hint_y=None, height=30))
            return
        pid = self.transfer_pid.text
        items = [t for t in self.transfers if t.get("patient_id") == pid]
        items.sort(key=lambda x: x.get("date", ""), reverse=True)
        if not items:
            self.transfer_list.add_widget(Label(
                text="No transfer records for this patient.",
                font_size=13, size_hint_y=None, height=30))
            return

        for t in items:
            status_color = {
                "Pending":   "#f39c12",
                "Accepted":  "#2980b9",
                "Completed": "#27ae60",
                "Cancelled": "#e74c3c",
            }.get(t.get("status", "Pending"), "#7f8c8d")

            row = BoxLayout(size_hint_y=None, height=34, spacing=3)
            row.add_widget(Label(
                text=f"{t.get('date','')} {t.get('time','')}",
                font_size=11, size_hint_x=0.18))
            row.add_widget(Label(
                text=f"{t.get('from_dept','')} → {t.get('to_dept','')}",
                font_size=11, size_hint_x=0.26, bold=True,
                shorten=True, shorten_from='center'))
            row.add_widget(Label(
                text=str(t.get('reason', ''))[:22],
                font_size=11, size_hint_x=0.16,
                shorten=True, shorten_from='right'))
            row.add_widget(Label(
                text=t.get("status", "Pending"),
                font_size=11, size_hint_x=0.1, bold=True,
                color=get_color_from_hex(status_color)))

            sp = Spinner(
                text=t.get("status", "Pending"),
                values=["Pending", "Accepted", "Completed", "Cancelled"],
                size_hint_x=0.14, size_hint_y=None, height=30)
            sp.transfer_id = t.get("id")
            sp.bind(text=lambda s, tid=t.get("id"):
                    self._update_transfer_status(tid, s.text))
            row.add_widget(sp)

            bv = Button(text="View", font_size=11, size_hint_x=0.08,
                        size_hint_y=None, height=28,
                        background_color=get_color_from_hex('#2980b9'),
                        background_normal='')
            bv.transfer = t
            bv.bind(on_press=lambda x: self._view_transfer_detail(x.transfer))
            row.add_widget(bv)

            bd = Button(text="X", font_size=11, size_hint_x=0.08,
                        size_hint_y=None, height=28,
                        background_color=get_color_from_hex('#e74c3c'),
                        background_normal='')
            bd.transfer_id = t.get("id")
            bd.bind(on_press=lambda x: self._delete_transfer(x.transfer_id))
            row.add_widget(bd)

            self.transfer_list.add_widget(row)

    def _add_transfer(self, instance):
        if not self.transfer_pid.text:
            self._popup("Error", "Select a patient first.")
            return
        if self.transfer_from.text == self.transfer_to.text:
            self._popup("Error",
                        "From and To departments must be different.")
            return
        date = self.transfer_date.text.strip()
        if not date:
            self._popup("Error", "Transfer date is required.")
            return
        try:
            datetime.strptime(date, "%Y-%m-%d")
        except Exception:
            self._popup("Error", "Invalid date (use YYYY-MM-DD).")
            return
        reason = self.transfer_reason.text.strip()
        if not reason:
            self._popup("Error", "Please provide a reason for the transfer.")
            return

        transfer = {
            "id": f"TRF{datetime.now().strftime('%Y%m%d%H%M%S%f')}",
            "patient_id": self.transfer_pid.text,
            "patient_name": self.transfer_name.text,
            "from_dept": self.transfer_from.text,
            "to_dept": self.transfer_to.text,
            "date": date,
            "time": datetime.now().strftime("%H:%M"),
            "urgency": self.transfer_urgency.text,
            "reason": reason,
            "receiving_doctor": self.transfer_doctor.text.strip(),
            "summary": self.transfer_summary.text.strip(),
            "status": "Pending",
            "initiated_by": self._current_username(),
            "created": datetime.now().strftime("%Y-%m-%d %H:%M:%S"),
        }
        self.transfers.append(transfer)
        self.save_all()
        self._refresh_transfer_list()

        self.transfer_reason.text = ""
        self.transfer_summary.text = ""

        self.task_manager.create_task(
            patient_id=self.transfer_pid.text,
            patient_name=self.transfer_name.text,
            assigned_to=self.transfer_to.text,
            task_type="Transfer",
            description=(f"Accept transfer from {self.transfer_from.text} "
                         f"({self.transfer_urgency.text}): {reason[:60]}"),
            department=self.transfer_to.text,
            priority=("High" if self.transfer_urgency.text
                      in ("Urgent", "Emergency") else "Normal"))
        self._refresh_tasks()

        self._popup("Transfer Initiated",
                    f"{self.transfer_from.text}  →  {self.transfer_to.text}\n"
                    f"Urgency: {self.transfer_urgency.text}")
        self.audit_log("INITIATE_TRANSFER",
                       f"{self.transfer_from.text} → {self.transfer_to.text}",
                       self.transfer_pid.text)

    def _update_transfer_status(self, transfer_id, new_status):
        for t in self.transfers:
            if t.get("id") == transfer_id:
                t["status"] = new_status
                t["updated"] = datetime.now().strftime("%Y-%m-%d %H:%M:%S")
                if new_status == "Completed":
                    t["completed"] = datetime.now().strftime(
                        "%Y-%m-%d %H:%M:%S")
                self.save_all()
                self._refresh_transfer_list()
                self.audit_log("UPDATE_TRANSFER",
                               f"{transfer_id} → {new_status}",
                               t.get("patient_id", ""))
                return

    def _view_transfer_detail(self, transfer):
        text = (f"TRANSFER DETAIL\n{'=' * 55}\n\n"
                f"Transfer ID: {transfer.get('id', '')}\n"
                f"Patient: {transfer.get('patient_name', '')} "
                f"(ID: {transfer.get('patient_id', '')})\n"
                f"Date: {transfer.get('date', '')} "
                f"{transfer.get('time', '')}\n"
                f"From: {transfer.get('from_dept', '')}\n"
                f"To: {transfer.get('to_dept', '')}\n"
                f"Urgency: {transfer.get('urgency', 'Routine')}\n"
                f"Receiving Doctor: "
                f"{transfer.get('receiving_doctor', 'N/A')}\n"
                f"Status: {transfer.get('status', 'Pending')}\n"
                f"Initiated By: {transfer.get('initiated_by', '')}\n"
                f"Created: {transfer.get('created', '')}\n\n"
                f"REASON:\n{transfer.get('reason', '')}\n\n"
                f"CLINICAL SUMMARY:\n{transfer.get('summary', '')}\n")
        self._text_popup("Transfer Detail", text)

    def _delete_transfer(self, transfer_id):
        if not self._require_role("Administrator", "Doctor"):
            return
        self.transfers = [t for t in self.transfers
                          if t.get("id") != transfer_id]
        self.save_all()
        self._refresh_transfer_list()
        self._popup("Deleted", "Transfer record removed.")
        self.audit_log("DELETE_TRANSFER", transfer_id)

    def _autofill_transfer_from_emr(self, instance):
        if not self.cp:
            self._popup("Error", "Select a patient first.")
            return
        pid = self.cp.get("id")
        emrs = [r for r in self.emr_records if r.get("patient_id") == pid]
        if not emrs:
            self._popup("Info", "No EMR records for this patient.")
            return
        latest = emrs[-1]

        if latest.get("dept"):
            self.transfer_from.text = latest.get("dept")

        lines = []
        if latest.get("cc"):
            lines.append(f"Chief Complaint: {latest.get('cc')}")
        if latest.get("dx"):
            lines.append(f"Diagnosis: {latest.get('dx')}")
        if latest.get("tx"):
            lines.append(f"Treatment: {latest.get('tx')}")

        vitals = []
        for k, lb in [("bp", "BP"), ("pulse", "Pulse"), ("temp", "Temp"),
                      ("spo2", "SpO2"), ("rr", "RR"),
                      ("avpu", "AVPU")]:
            if latest.get(k):
                vitals.append(f"{lb}: {latest.get(k)}")
        if vitals:
            lines.append("Vitals — " + " | ".join(vitals))

        if latest.get("all"):
            lines.append(f"Allergies: {latest.get('all')}")

        structured = latest.get("_structured_drugs") or []
        if structured:
            drugs = ", ".join(d.get("name", "")
                              for d in structured if d.get("name"))
            if drugs:
                lines.append(f"Medications: {drugs}")

        self.transfer_summary.text = ("\n".join(lines)
                                      or "No clinical data available.")
        self._popup("Auto-Filled",
                    "Handover summary populated from latest EMR record.")

    def _print_transfer(self, instance):
        if not self.transfer_pid.text:
            self._popup("Error", "No patient selected.")
            return
        pid = self.transfer_pid.text
        items = [t for t in self.transfers if t.get("patient_id") == pid]
        if not items:
            self._popup("Error", "No transfer records to export.")
            return
        text = (f"HMG HOSPITAL - TRANSFER RECORD\n"
                f"Patient: {self.transfer_name.text} (ID: {pid})\n"
                f"Generated: {datetime.now().strftime('%Y-%m-%d %H:%M:%S')}\n"
                + "=" * 60 + "\n\n")
        for t in sorted(items, key=lambda x: x.get("date", ""),
                        reverse=True):
            text += (f"Transfer ID: {t.get('id', '')}\n"
                     f"Date: {t.get('date', '')} {t.get('time', '')}\n"
                     f"From: {t.get('from_dept', '')}  →  "
                     f"To: {t.get('to_dept', '')}\n"
                     f"Urgency: {t.get('urgency', 'Routine')}\n"
                     f"Receiving Doctor: "
                     f"{t.get('receiving_doctor', 'N/A')}\n"
                     f"Status: {t.get('status', 'Pending')}\n"
                     f"Reason: {t.get('reason', '')}\n"
                     f"Summary:\n{t.get('summary', '')}\n"
                     + "-" * 50 + "\n\n")
        self._export_to_pdf(text, "Transfer_Record",
                            "Patient Transfer Record")

