    def _clear_medical_report_form(self):
        for w in [self.rpt_facility_name, self.rpt_facility_address,
                   self.rpt_facility_contact, self.rpt_ref_number,
                   self.rpt_patient_name, self.rpt_patient_id,
                   self.rpt_patient_age, self.rpt_patient_sex,
                   self.rpt_conditions, self.rpt_narrative,
                   self.rpt_recommendations, self.rpt_doctor_name,
                   self.rpt_doctor_qual, self.rpt_doctor_role]:
            w.text = ""
        self.rpt_report_date.text = datetime.now().strftime("%d %B %Y")
        self.rpt_logo_path = None
        self.rpt_signature_path = None
        self.rpt_logo_label.text = "(none attached)"
        self.rpt_sig_label.text = "(none attached)"

    def _pick_image_for_report(self, target):
        menu = BoxLayout(orientation='vertical', spacing=8, padding=12)
        menu.add_widget(Label(
            text=f"Attach {'Logo' if target == 'logo' else 'Signature'}",
            font_size=16, bold=True, size_hint_y=None, height=30))
        pp = Popup(title="Choose Image Source", content=menu,
                   size_hint=(0.55, 0.42), auto_dismiss=True)

        def choose_file(inst):
            pp.dismiss()
            self._pick_image_from_file(target)

        def take_photo(inst):
            pp.dismiss()
            self._take_photo_for_report(target)

        cam_avail = CameraHelper.available()
        pb = Button(
            text="📷  Take Photo" if cam_avail
            else "📷  Take Photo (unavailable)",
            font_size=15, bold=True, size_hint_y=None, height=48,
            background_color=get_color_from_hex('#2980b9'),
            background_normal='', disabled=not cam_avail)
        pb.bind(on_press=take_photo)
        menu.add_widget(pb)
        fb = Button(text="📁  Choose File", font_size=15, bold=True,
                     size_hint_y=None, height=48,
                     background_color=get_color_from_hex('#27ae60'),
                     background_normal='')
        fb.bind(on_press=choose_file)
        menu.add_widget(fb)
        cb = Button(text="Cancel", font_size=14, size_hint_y=None, height=40,
                     background_color=get_color_from_hex('#e74c3c'),
                     background_normal='')
        cb.bind(on_press=lambda *_: pp.dismiss())
        menu.add_widget(cb)
        pp.open()

    def _pick_image_from_file(self, target):
        content = BoxLayout(orientation='vertical', spacing=4, padding=4)
        fc = FileChooserListView(path=os.path.expanduser("~"),
                                  filters=["*.png", "*.jpg", "*.jpeg"])
        content.add_widget(fc)
        btns = BoxLayout(size_hint_y=None, height=42, spacing=5)
        pp = Popup(
            title=f"Choose {'Logo' if target == 'logo' else 'Signature'}",
            content=content, size_hint=(0.9, 0.85))

        def select(inst):
            if fc.selection:
                self._set_report_image(target, fc.selection[0])
            pp.dismiss()
        btns.add_widget(Button(text="SELECT", font_size=15, bold=True,
                                on_press=select,
                                background_color=get_color_from_hex('#27ae60'),
                                background_normal=''))
        btns.add_widget(Button(text="CANCEL", font_size=15,
                                on_press=pp.dismiss, background_normal=''))
        content.add_widget(btns)
        pp.open()

    def _take_photo_for_report(self, target):
        if not CameraHelper.available():
            self._popup("Camera", "Camera not available.")
            return
        try:
            cam = Camera(play=True, resolution=(800, 600))
        except Exception as e:
            self._popup("Camera Error", str(e))
            return
        content = BoxLayout(orientation='vertical', spacing=4, padding=4)
        content.add_widget(cam)
        btns = BoxLayout(size_hint_y=None, height=44, spacing=5)
        pp = Popup(
            title=f"Take {'Logo' if target == 'logo' else 'Signature'} Photo",
            content=content, size_hint=(0.9, 0.85))

        def capture(inst):
            if not cam.texture:
                self._popup("Camera", "Not ready.")
                return
            try:
                os.makedirs(OUTPUT_DIR, exist_ok=True)
                fn = os.path.join(
                    OUTPUT_DIR,
                    f"rpt_{target}_{datetime.now().strftime('%Y%m%d_%H%M%S')}.png")
                cam.texture.save(fn)
                try:
                    cam.play = False
                except Exception:
                    pass
                self._set_report_image(target, fn)
                pp.dismiss()
                self._popup("Photo Saved",
                            f"Saved as {os.path.basename(fn)}")
            except Exception as e:
                self._popup("Save Error", str(e))

        def cancel(inst):
            try:
                cam.play = False
            except Exception:
                pass
            pp.dismiss()
        btns.add_widget(Button(text="📸 CAPTURE", font_size=16, bold=True,
                                on_press=capture,
                                background_color=get_color_from_hex('#27ae60'),
                                background_normal=''))
        btns.add_widget(Button(text="CANCEL", font_size=16, on_press=cancel,
                                background_color=get_color_from_hex('#e74c3c'),
                                background_normal=''))
        content.add_widget(btns)
        pp.open()

    def _set_report_image(self, target, path):
        if not path or not os.path.exists(path):
            self._popup("Error", f"File not found: {path}")
            return
        if target == "logo":
            self.rpt_logo_path = path
            self.rpt_logo_label.text = os.path.basename(path)
        else:
            self.rpt_signature_path = path
            self.rpt_sig_label.text = os.path.basename(path)
        self.log_activity(f"Report {target} attached: {path}")

    def _generate_medical_report_pdf(self, instance):
        if not REPORTLAB_AVAILABLE:
            self._popup("Error", "ReportLab is not installed.")
            return
        if (not self.rpt_patient_name.text.strip() or
                not self.rpt_doctor_name.text.strip()):
            self._popup("Error", "Fill at least patient and doctor name.")
            return
        os.makedirs(OUTPUT_DIR, exist_ok=True)
        safe_name = "".join(c for c in self.rpt_patient_name.text
                             if c.isalnum() or c in " _-").strip().replace(" ", "_") or "report"
        out_path = os.path.join(
            OUTPUT_DIR,
            f"{safe_name}_report_{datetime.now().strftime('%Y%m%d_%H%M%S')}.pdf")
        try:
            c = pdf_canvas.Canvas(out_path, pagesize=A4)
            width, height = A4
            margin = 22 * mm
            content_width = width - 2 * margin
            bottom_limit = margin + 14 * mm
            page_num = [1]
            state = {"y": height - margin}
            ACCENT = (0.14, 0.42, 0.38)
            MUTED = (0.35, 0.35, 0.35)
            BS, BL = 10.5, 15
            FR, FB, FI = "Helvetica", "Helvetica-Bold", "Helvetica-Oblique"

            def draw_footer():
                c.setFont(FR, 8)
                c.setFillColorRGB(*MUTED)
                c.drawString(margin, margin - 6 * mm,
                             self.rpt_facility_name.text.strip())
                c.drawRightString(width - margin, margin - 6 * mm,
                                   f"Page {page_num[0]}")
                c.setFillColorRGB(0, 0, 0)

            def draw_cont():
                c.setFont(FI, 8.5)
                c.setFillColorRGB(*MUTED)
                header = (f"{self.rpt_facility_name.text.strip()} — "
                          f"Medical Report (cont'd)").strip(" —")
                c.drawString(margin, state["y"], header)
                c.setFillColorRGB(0, 0, 0)
                state["y"] -= 10 * mm

            def new_page():
                draw_footer()
                c.showPage()
                page_num[0] += 1
                state["y"] = height - margin
                draw_cont()

            def ensure(n):
                if state["y"] - n < bottom_limit:
                    new_page()

            def heading(text, size=11.5):
                ensure(4 * mm + size + 3 * mm)
                state["y"] -= 4 * mm
                c.setFont(FB, size)
                c.setFillColorRGB(*ACCENT)
                c.drawString(margin, state["y"], text.upper())
                c.setFillColorRGB(0, 0, 0)
                state["y"] -= 3
                c.setStrokeColorRGB(*ACCENT)
                c.setLineWidth(0.6)
                c.line(margin, state["y"], margin + 26 * mm, state["y"])
                c.setStrokeColorRGB(0, 0, 0)
                state["y"] -= 3 * mm

            def ln(text, size=None, bold=False, italic=False,
                   gap=None, color=None):
                size = size or BS
                gap = gap or BL
                ensure(gap)
                font = FB if bold else (FI if italic else FR)
                c.setFont(font, size)
                if color:
                    c.setFillColorRGB(*color)
                c.drawString(margin, state["y"], text)
                if color:
                    c.setFillColorRGB(0, 0, 0)
                state["y"] -= gap

            def wrap(text, size, maxw, font=None):
                font = font or FR
                words = text.split()
                out, cur = [], ""
                for w in words:
                    trial = (cur + " " + w).strip()
                    if c.stringWidth(trial, font, size) > maxw and cur:
                        out.append(cur)
                        cur = w
                    else:
                        cur = trial
                if cur:
                    out.append(cur)
                return out

            def para(text, size=None, gap=None, indent=0, prefix=""):
                size = size or BS
                gap = gap or BL
                maxw = content_width - indent
                pw = c.stringWidth(prefix, FR, size) if prefix else 0
                wrapped = wrap(text, size,
                                maxw - pw if prefix else maxw)
                for i, wl in enumerate(wrapped):
                    ensure(gap)
                    c.setFont(FR, size)
                    if i == 0 and prefix:
                        c.setFont(FB, size)
                        c.drawString(margin, state["y"], prefix)
                        c.setFont(FR, size)
                        c.drawString(margin + pw, state["y"], wl)
                    else:
                        c.drawString(margin + indent, state["y"], wl)
                    state["y"] -= gap

            ht = state["y"]
            if self.rpt_logo_path and os.path.exists(self.rpt_logo_path):
                try:
                    img = ImageReader(self.rpt_logo_path)
                    c.drawImage(img, margin, ht - 20 * mm,
                                width=20 * mm, height=20 * mm,
                                preserveAspectRatio=True, mask="auto")
                except Exception:
                    pass
                hx = margin + 25 * mm
            else:
                hx = margin
            c.setFont(FB, 19)
            c.setFillColorRGB(*ACCENT)
            c.drawString(hx, ht - 7 * mm,
                         self.rpt_facility_name.text.strip() or "[Facility name]")
            c.setFillColorRGB(0, 0, 0)
            c.setFont(FR, 8.5)
            c.setFillColorRGB(*MUTED)
            addr = (self.rpt_facility_address.text or "").strip().split("\n")
            ay = ht - 12.5 * mm
            for al in addr[:2]:
                if al.strip():
                    c.drawString(hx, ay, al.strip())
                    ay -= 4 * mm
            if self.rpt_facility_contact.text.strip():
                c.drawString(hx, ay, self.rpt_facility_contact.text.strip())
            c.setFillColorRGB(0, 0, 0)
            state["y"] = ht - 24 * mm
            c.setStrokeColorRGB(*ACCENT)
            c.setLineWidth(1.4)
            c.line(margin, state["y"], width - margin, state["y"])
            c.setLineWidth(0.5)
            c.setStrokeColorRGB(*MUTED)
            c.line(margin, state["y"] - 1.2 * mm,
                   width - margin, state["y"] - 1.2 * mm)
            c.setStrokeColorRGB(0, 0, 0)
            state["y"] -= 9 * mm
            c.setFont(FR, 9.5)
            c.setFillColorRGB(*MUTED)
            c.drawString(margin, state["y"],
                         f"Ref: {self.rpt_ref_number.text.strip() or '—'}")
            c.drawRightString(width - margin, state["y"],
                              f"Date: {self.rpt_report_date.text.strip()}")
            c.setFillColorRGB(0, 0, 0)
            state["y"] -= 10 * mm
            c.setFont(FB, 14.5)
            c.drawCentredString(width / 2, state["y"], "MEDICAL REPORT")
            state["y"] -= 2.5 * mm
            c.setLineWidth(0.8)
            tw = c.stringWidth("MEDICAL REPORT", FB, 14.5)
            c.line(width / 2 - tw / 2, state["y"],
                   width / 2 + tw / 2, state["y"])
            state["y"] -= 9 * mm
            ln(f"RE:  {self.rpt_patient_name.text.strip()}",
               size=12, bold=True, gap=16)
            details = []
            if self.rpt_patient_age.text.strip():
                details.append(f"Age: {self.rpt_patient_age.text.strip()}")
            if self.rpt_patient_sex.text.strip():
                details.append(f"Sex: {self.rpt_patient_sex.text.strip()}")
            if self.rpt_patient_id.text.strip():
                details.append(f"ID: {self.rpt_patient_id.text.strip()}")
            if details:
                ln("   |   ".join(details), size=9.5, color=MUTED, gap=13)
            state["y"] -= 3 * mm
            ln("To Whom It May Concern,", gap=15)
            state["y"] -= 2 * mm
            if self.rpt_conditions.text.strip():
                heading("Diagnosis / Conditions")
                para(self.rpt_conditions.text.strip())
                state["y"] -= 2 * mm
            if self.rpt_narrative.text.strip():
                heading("Clinical Summary")
                for p in self.rpt_narrative.text.strip().split("\n"):
                    if p.strip():
                        para(p.strip())
                        state["y"] -= 1.5 * mm
                state["y"] -= 1 * mm
            if self.rpt_recommendations.text.strip():
                heading("Recommendations")
                items = [r.strip() for r in
                         self.rpt_recommendations.text.strip().split("\n")
                         if r.strip()]
                for i, item in enumerate(items, start=1):
                    para(item, indent=6 * mm, prefix=f"{i}.  ")
                    state["y"] -= 1.5 * mm
                state["y"] -= 2 * mm
            ensure(38 * mm)
            state["y"] -= 4 * mm
            ln("Yours faithfully,", gap=15)
            if self.rpt_signature_path and os.path.exists(self.rpt_signature_path):
                try:
                    img = ImageReader(self.rpt_signature_path)
                    sh = 14 * mm
                    c.drawImage(img, margin, state["y"] - sh,
                                width=42 * mm, height=sh,
                                preserveAspectRatio=True, mask="auto",
                                anchor="sw")
                except Exception:
                    pass
                state["y"] -= (14 * mm + 3 * mm)
            else:
                state["y"] -= 10 * mm
            c.setLineWidth(0.5)
            c.line(margin, state["y"], margin + 55 * mm, state["y"])
            state["y"] -= 5.5 * mm
            ln(self.rpt_doctor_name.text.strip() or "[Doctor name]",
               size=11, bold=True, gap=14)
            if self.rpt_doctor_qual.text.strip():
                ln(self.rpt_doctor_qual.text.strip(), size=9.5,
                   color=MUTED, gap=12.5)
            if self.rpt_doctor_role.text.strip():
                ln(self.rpt_doctor_role.text.strip(), size=9.5,
                   color=MUTED, gap=12.5)
            if self.rpt_facility_name.text.strip():
                ln(self.rpt_facility_name.text.strip(), size=9.5,
                   color=MUTED, gap=12.5)
            draw_footer()
            c.save()

            medical_text = (
                f"Diagnosis / Conditions: {self.rpt_conditions.text.strip()}\n"
                f"Clinical Summary: {self.rpt_narrative.text.strip()}\n"
                f"Recommendations: {self.rpt_recommendations.text.strip()}")
            patient = self._patient_identity_for_report()
            image_path = self._render_professional_report_image(
                medical_text, 'Medical_Report', 'Medical Report',
                patient=patient,
                report_id=f"HMG-MED-{datetime.now().strftime('%Y%m%d%H%M%S')}")
            self._popup("Report Generated",
                        f"Saved to {out_path}" +
                        (f"\nImage report: {image_path}" if image_path else ""))
            self.audit_log("GENERATE_REPORT", out_path)
            try:
                self._open_file(out_path)
            except Exception:
                pass
        except Exception as e:
            self._popup("Report Error", str(e))

    # ---------- User Management ----------
    def _user_management_tab(self):
        tab = TabbedPanelItem(text="Users")
        s = ScrollView()
        l = BoxLayout(orientation='vertical', padding=6, spacing=4,
                      size_hint_y=None)
        l.bind(minimum_height=l.setter('height'))
        l.add_widget(Label(text="USER MANAGEMENT", font_size=20, bold=True,
                           size_hint_y=None, height=32,
                           color=get_color_from_hex('#8e44ad')))
        l.add_widget(Label(text="Administrator access only", font_size=12,
                           size_hint_y=None, height=20,
                           color=get_color_from_hex('#7f8c8d')))
        form = GridLayout(cols=2, size_hint_y=None, height=180, spacing=4)
        form.add_widget(Label(text="Username:", font_size=14, bold=True))
        self.um_username = TextInput(font_size=14, size_hint_y=None, height=36)
        form.add_widget(self.um_username)
        form.add_widget(Label(text="Full Name:", font_size=14, bold=True))
        self.um_fullname = TextInput(font_size=14, size_hint_y=None, height=36)
        form.add_widget(self.um_fullname)
        form.add_widget(Label(text="Password:", font_size=14, bold=True))
        self.um_password = TextInput(font_size=14, password=True,
                                       size_hint_y=None, height=36)
        form.add_widget(self.um_password)
        form.add_widget(Label(text="Role:", font_size=14, bold=True))
        self.um_role = Spinner(text="Doctor", values=UserManager.ROLES,
                                size_hint_y=None, height=36)
        form.add_widget(self.um_role)
        l.add_widget(form)
        btn_row = BoxLayout(size_hint_y=None, height=42, spacing=5)
        btn_row.add_widget(Button(text="CREATE USER", font_size=15, bold=True,
                                   on_press=self._create_new_user,
                                   background_color=get_color_from_hex('#27ae60'),
                                   background_normal=''))
        btn_row.add_widget(Button(text="RESET PASSWORD", font_size=15,
                                   bold=True,
                                   on_press=self._admin_reset_password,
                                   background_color=get_color_from_hex('#2980b9'),
                                   background_normal=''))
        btn_row.add_widget(Button(text="DELETE USER", font_size=15, bold=True,
                                   on_press=self._delete_user,
                                   background_color=get_color_from_hex('#e74c3c'),
                                   background_normal=''))
        btn_row.add_widget(Button(text="REFRESH", font_size=15, bold=True,
                                   on_press=lambda x: self._refresh_user_list(),
                                   background_color=get_color_from_hex('#16a085'),
                                   background_normal=''))
        l.add_widget(btn_row)
        l.add_widget(Label(text="USER LIST", font_size=16, bold=True,
                           size_hint_y=None, height=24,
                           color=get_color_from_hex('#2c3e50')))
        self.user_list = BoxLayout(orientation='vertical',
                                    size_hint_y=None, spacing=1)
        self.user_list.bind(minimum_height=self.user_list.setter('height'))
        l.add_widget(self.user_list)
        s.add_widget(l)
        tab.add_widget(s)
        self.tp.add_widget(tab)
        self._refresh_user_list()

    def _refresh_user_list(self):
        if not hasattr(self, 'user_list'):
            return
        self.user_list.clear_widgets()
        for u in self.user_manager.users:
            row = BoxLayout(size_hint_y=None, height=32, spacing=3)
            row.add_widget(Label(text=u.get("username", ""), font_size=13,
                                  size_hint_x=0.22))
            row.add_widget(Label(text=u.get("full_name", ""), font_size=13,
                                  size_hint_x=0.28))
            row.add_widget(Label(text=u.get("role", ""), font_size=13,
                                  size_hint_x=0.2, bold=True,
                                  color=get_color_from_hex('#8e44ad')))
            row.add_widget(Label(text=u.get("last_login", "")[:16],
                                  font_size=11, size_hint_x=0.25))
            self.user_list.add_widget(row)

    def _create_new_user(self, instance):
        if not self._require_role("Administrator"):
            return
        ok, msg = self.user_manager.create_user(
            self.um_username.text.strip(), self.um_fullname.text.strip(),
            self.um_password.text, self.um_role.text)
        self._popup("Create User", msg)
        if ok:
            self.audit_log("CREATE_USER",
                           f"{self.um_username.text} ({self.um_role.text})")
            self.um_username.text = ""
            self.um_fullname.text = ""
            self.um_password.text = ""
            self._refresh_user_list()

    def _admin_reset_password(self, instance):
        if not self._require_role("Administrator"):
            return
        username = self.um_username.text.strip()
        if not username:
            self._popup("Error", "Enter username to reset.")
            return
        if len(self.um_password.text) < 4:
            self._popup("Error", "Enter new password (min 4 chars).")
            return
        ok, msg = self.user_manager.admin_reset_password(
            username, self.um_password.text)
        self._popup("Reset Password", msg)
        if ok:
            self.audit_log("ADMIN_RESET_PASSWORD", username)
            self.um_password.text = ""
            self._refresh_user_list()

    def _delete_user(self, instance):
        if not self._require_role("Administrator"):
            return
        username = self.um_username.text.strip()
        if not username:
            self._popup("Error", "Enter username to delete.")
            return
        if username == self._current_username():
            self._popup("Error", "Cannot delete your own account.")
            return
        ok, msg = self.user_manager.delete_user(username)
        self._popup("Delete User", msg)
        if ok:
            self.audit_log("DELETE_USER", username)
            self._refresh_user_list()

    # ---------- Audit Log ----------
    def _audit_log_tab(self):
        tab = TabbedPanelItem(text="Audit Log")
        s = ScrollView()
        l = BoxLayout(orientation='vertical', padding=6, spacing=4,
                      size_hint_y=None)
        l.bind(minimum_height=l.setter('height'))
        l.add_widget(Label(text="AUDIT LOG", font_size=20, bold=True,
                           size_hint_y=None, height=32,
                           color=get_color_from_hex('#c0392b')))
        l.add_widget(Label(text="Administrator access only", font_size=12,
                           size_hint_y=None, height=20,
                           color=get_color_from_hex('#7f8c8d')))
        row = BoxLayout(size_hint_y=None, height=40, spacing=4)
        row.add_widget(Label(text="Filter user:", font_size=13, bold=True,
                              size_hint_x=0.12))
        self.audit_user_filter = TextInput(font_size=13, size_hint_x=0.3,
                                            size_hint_y=None, height=36)
        row.add_widget(self.audit_user_filter)
        row.add_widget(Button(text="APPLY", font_size=13, bold=True,
                               size_hint_x=0.15,
                               on_press=lambda x: self._refresh_audit_log(
                                   self.audit_user_filter.text.strip()),
                               background_color=get_color_from_hex('#2980b9'),
                               background_normal=''))
        row.add_widget(Button(text="SHOW ALL", font_size=13, bold=True,
                               size_hint_x=0.15,
                               on_press=lambda x: (setattr(
                                   self.audit_user_filter, 'text', ''),
                                   self._refresh_audit_log()),
                               background_color=get_color_from_hex('#16a085'),
                               background_normal=''))
        row.add_widget(Button(text="EXPORT", font_size=13, bold=True,
                               size_hint_x=0.15,
                               on_press=self._export_audit_log,
                               background_color=get_color_from_hex('#8e44ad'),
                               background_normal=''))
        l.add_widget(row)
        self.audit_display = TextInput(multiline=True, readonly=True,
                                        font_size=12,
                                        background_color=get_color_from_hex('#f8f9fa'),
                                        size_hint_y=None, height=500)
        l.add_widget(self.audit_display)
        s.add_widget(l)
        tab.add_widget(s)
        self.tp.add_widget(tab)
        self._refresh_audit_log()

    def _refresh_audit_log(self, username_filter=""):
        if not hasattr(self, 'audit_display'):
            return
        entries = (self.audit.filter_by_user(username_filter)
                   if username_filter else self.audit.get_recent(300))
        lines = [f"AUDIT LOG — {len(entries)} "
                 f"entr{'y' if len(entries) == 1 else 'ies'}",
                 "=" * 80]
        for e in entries:
            lines.append(f"[{e.get('ts', '')}] "
                         f"{e.get('username', 'system'):<20} "
                         f"{e.get('action', ''):<28} "
                         f"{e.get('details', '')[:60]}")
        self.audit_display.text = "\n".join(lines)

    def _export_audit_log(self, instance):
        if not self._require_role("Administrator"):
            return
        text = "AUDIT LOG EXPORT\n" + "=" * 80 + "\n\n"
        for e in self.audit.entries:
            text += (f"[{e.get('ts', '')}] "
                     f"{e.get('username', 'system'):<20} "
                     f"{e.get('action', ''):<28} "
                     f"{e.get('details', '')}\n")
        self._export_to_pdf(text, "Audit_Log", "Audit Log Export")

    # ---------- Utilities ----------
    def _popup(self, title, msg):
        content = BoxLayout(orientation='vertical', spacing=10, padding=10)
        content.add_widget(Label(text=msg, font_size=15))
        btn = Button(text="OK", font_size=16, bold=True,
                     size_hint_y=None, height=44,
                     background_color=get_color_from_hex('#2980b9'),
                     background_normal='')
        sz = (0.92, 0.42) if platform == 'android' else (0.6, 0.3)
        pp = Popup(title=title, content=content, size_hint=sz)
        btn.bind(on_press=pp.dismiss)
        content.add_widget(btn)
        pp.open()

    def _text_popup(self, title, text):
        content = BoxLayout(orientation='vertical', spacing=5, padding=8)
        sv = ScrollView()
        ti = TextInput(text=text, readonly=True, font_size=13, size_hint_y=None,
                       background_color=get_color_from_hex('#fafafa'))
        ti.bind(minimum_height=ti.setter('height'))
        sv.add_widget(ti)
        content.add_widget(sv)
        btn = Button(text="CLOSE", font_size=16, bold=True,
                     size_hint_y=None, height=44,
                     background_color=get_color_from_hex('#2980b9'),
                     background_normal='')
        sz = (0.95, 0.85) if platform == 'android' else (0.85, 0.75)
        pp = Popup(title=title, content=content, size_hint=sz)
        btn.bind(on_press=pp.dismiss)
        content.add_widget(btn)
        pp.open()

    def _switch(self, tab_text):
        for tab in self.tp.tab_list:
            if tab.text == tab_text:
                self.tp.switch_to(tab)
                return
        self._popup("Tab", f"'{tab_text}' not found.")

    def on_stop(self):
        try:
            self.save_all()
        except Exception:
            pass
        try:
            self.lis_manager.save_configs()
        except Exception:
            pass
        try:
            if self.current_user:
                self.audit.log(username=self.current_user.get("username"),
                               action="APP_CLOSE")
        except Exception:
            pass



