def _ensure_panel_tests_in_catalog(self):
    invs = getattr(self, "investigations", None)
    if invs is None:
        self.investigations = []
        invs = self.investigations
    existing = {str(x.get("name", "")).strip().lower() for x in invs
                if isinstance(x, dict)}
    for panel in PANEL_DEFINITIONS:
        if panel.lower() not in existing:
            invs.append({
                "name": panel, "price": 0, "dept": "Laboratory",
                "cat": "Panel", "result_type": "panel",
                "allowed_units": [], "default_unit": "",
                "reference": "See individual parameters",
                "panel": panel,
            })
    try:
        if hasattr(self, "elab_test"):
            self.elab_test.values = [i.get("name", "") for i in invs]
    except Exception:
        pass


def _hmg_get_patient_lab_results(self, patient_id):
    pid = str(patient_id or '').strip()
    combined, seen = [], set()
    blocked = (
        'x-ray', 'xray', 'ecg', 'electrocard', 'echo', 'scan', 'mri',
        ' ct ', 'ct scan', 'computed tomography', 'ultrasound', 'sonograph',
        'mammogram', 'mammography', 'fluoroscopy', 'dexa', 'doppler', 'pet ',
        'radiolog', 'angiograph', 'cardiology', 'imaging', 'echocardi',
    )
    def is_lab_name(name):
        low = f" {str(name or '').strip().lower()} "
        if any(k in low for k in blocked):
            return False
        # Explicit catalog department lookup has precedence over name guesses.
        for inv in getattr(self, 'investigations', []):
            if str(inv.get('name', '')).strip().lower() == str(name or '').strip().lower():
                dept = str(inv.get('dept', '')).strip().lower()
                if dept in {'radiology', 'cardiology', 'imaging'}:
                    return False
                break
        return True
    def add_row(row, source):
        name = str(row.get('test_name', '')).strip()
        if not name or not is_lab_name(name):
            return
        row = dict(row)
        row['source'] = source
        key = (name.lower(), str(row.get('result', '')).strip(),
               str(row.get('date', '')).strip(),
               str(row.get('status', '')).strip().lower())
        if key not in seen:
            combined.append(row); seen.add(key)
    for t in getattr(self, 'lab_tests', []):
        if str(t.get('patient_id', '')).strip() != pid: continue
        st = str(t.get('status', '')).strip() or 'Pending'
        done = st.lower() == 'completed'
        add_row({'id': t.get('test_id',''), 'patient_id': pid,
                 'patient_name': t.get('patient_name',''),
                 'test_name': t.get('test_name',''),
                 'result': t.get('result','') if done else '—',
                 'unit': t.get('unit',''), 'reference': t.get('reference',''),
                 'date': t.get('date_completed') or t.get('date_ordered',''),
                 'status': 'Completed' if done else 'Ordered — Result Pending',
                 'category':'Laboratory'}, 'Lab Orders')
    for r in getattr(self, 'lab_results', []):
        if str(r.get('patient_id','')).strip() != pid: continue
        row = dict(r); row.setdefault('status','Completed')
        row.setdefault('reference', r.get('reference', r.get('reference_range','')))
        row.setdefault('category','Laboratory')
        add_row(row, 'Enhanced Lab')
    def clean(raw):
        nm = str(raw or '').strip()
        nm = re.sub(r'^\s*lab(?:oratory)?\s*[:.\-]?\s*', '', nm, flags=re.I)
        nm = re.sub(r'^\s*\d+\s*[.)\-:]\s*', '', nm)
        return nm.strip()
    def add_items(items, when):
        for item in items or []:
            nm = clean(item.get('name',''))
            if not nm or not is_lab_name(nm): continue
            cat = str(item.get('cat','')).lower()
            low = nm.lower()
            lab_terms = ('fbc','full blood count','cbc','urinalysis','lipid',
                         'lft','liver function','renal function','urea',
                         'creatinine','electrolyte','glucose','h.pylori',
                         'malaria','blood film','d-dimer','thyroid','albumin',
                         'bilirubin','troponin','ck-mb','bnp','haemoglobin','hemoglobin')
            if not (low.startswith(('lab:', 'lab.', 'lab ', 'laboratory')) or
                    'laboratory' in cat or cat == 'investigations' or
                    any(x in low for x in lab_terms)):
                continue
            add_row({'id':'','patient_id':pid,
                     'patient_name':getattr(getattr(self,'elab_name',None),'text',''),
                     'test_name':nm,'result':'—','unit':'','reference':'',
                     'date':when or '','status':'Ordered — Result Pending',
                     'category':'Laboratory'}, 'Saved Items')
    if getattr(getattr(self,'bill_pid',None),'text','').strip() == pid:
        add_items(getattr(self,'bill_items',[]), datetime.now().strftime('%Y-%m-%d %H:%M:%S'))
    for bill in getattr(self,'bills',[]):
        if str(bill.get('patient',{}).get('id','')).strip() == pid:
            add_items(bill.get('items',[]), bill.get('ts',''))
    combined.sort(key=lambda x: str(x.get('date','')), reverse=True)
    return combined


def _hmg_share_file(self, filepath):
    if not filepath or not os.path.exists(filepath):
        self._popup("Share Error", f"File not found:\n{filepath}"); return
    if platform != 'android':
        try:
            if sys.platform == 'win32': subprocess.Popen(['explorer','/select,',filepath])
            elif sys.platform == 'darwin': subprocess.Popen(['open','-R',filepath])
            else: subprocess.Popen(['xdg-open',os.path.dirname(filepath)])
        except Exception as e: self._popup("Share Error", str(e))
        return
    try:
        from jnius import autoclass
        PythonActivity=autoclass('org.kivy.android.PythonActivity'); Intent=autoclass('android.content.Intent')
        File=autoclass('java.io.File'); Uri=autoclass('android.net.Uri')
        ClipData=autoclass('android.content.ClipData')
        activity=PythonActivity.mActivity
        mime,_=mimetypes.guess_type(filepath)
        low=filepath.lower()
        mime = mime or ('application/pdf' if low.endswith('.pdf') else 'image/png' if low.endswith('.png') else 'image/jpeg' if low.endswith(('.jpg','.jpeg')) else '*/*')
        uri=None
        try:
            FP=autoclass('androidx.core.content.FileProvider')
            uri=FP.getUriForFile(activity, f"{activity.getPackageName()}.fileprovider", File(filepath))
        except Exception as e: print(f"share: FileProvider unavailable: {e}")
        if uri is None:
            dst=os.path.join(activity.getFilesDir().getAbsolutePath(), os.path.basename(filepath))
            if os.path.abspath(dst)!=os.path.abspath(filepath): shutil.copy2(filepath,dst)
            uri=Uri.fromFile(File(dst))
        intent=Intent(Intent.ACTION_SEND); intent.setType(mime)
        intent.putExtra(Intent.EXTRA_STREAM,uri); intent.putExtra(Intent.EXTRA_SUBJECT,os.path.basename(filepath))
        # Critical for Android 10+ chooser grant propagation.
        intent.setClipData(ClipData.newRawUri(os.path.basename(filepath), uri))
        intent.addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION | Intent.FLAG_ACTIVITY_NEW_TASK)
        chooser=Intent.createChooser(intent,"Share Report")
        chooser.addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION | Intent.FLAG_ACTIVITY_NEW_TASK)
        activity.startActivity(chooser)
    except Exception as e:
        print(f"share error: {e}"); self._popup("Share Error", str(e))


def _hmg_elab_test(self, name):
    return next((i for i in getattr(self,'investigations',[]) if str(i.get('name','')).lower()==str(name).lower()), None)


