    self.elab_single_row.add_widget(
        Label(text="Unit:", font_size=15, bold=True, size_hint_x=.06))
    self.elab_unit_container = BoxLayout(size_hint_x=.28,
                                          size_hint_y=None, height=42)
    self.elab_single_row.add_widget(self.elab_unit_container)
    self.elab_single_row.add_widget(
        Button(text="ADD", font_size=15, bold=True, size_hint_x=.14,
               on_press=self._add_enhanced_lab,
               background_color=get_color_from_hex('#27ae60'),
               background_normal=''))

    # Default content of the swap container is the single-test row.
    self.elab_swap.add_widget(self.elab_single_row)

    # --- Results list ---
