# -------------------- bootstrap recovery of swallowed nested functions ------
def _hmg_bootstrap_recover_swallowed_methods():
    harvested={}
    class _HMGMock:
        saved_lab_reports=[]
        def __getattr__(self,name):
            return (lambda *a,**k: None)
    mock=_HMGMock()
    def profiler(frame,event,arg):
        if event=='return' and frame.f_code.co_name=='_delete_saved_report':
            for k,v in frame.f_locals.items():
                if callable(v): harvested.setdefault(k,v)
    old=sys.getprofile(); sys.setprofile(profiler)
    try:
        try: HMGBillingApp._delete_saved_report(mock,'__HMG_BOOTSTRAP__')
        except Exception as e: print(f'[HMG bootstrap] recovery execution: {e}')
    finally: sys.setprofile(old)
    for n,fn in harvested.items():
        if not hasattr(HMGBillingApp,n): setattr(HMGBillingApp,n,fn)
    for n in ('compute_news','compute_qsofa'):
        fn=harvested.get(n) or globals().get(n)
        if callable(fn): setattr(HMGBillingApp,n,staticmethod(fn))
    # Explicitly bind the targeted replacements and new ECG/panel methods.
    explicit={
        '_get_patient_lab_results':_hmg_get_patient_lab_results,
        '_share_file':_hmg_share_file,
        '_enhanced_lab_tab':_hmg_enhanced_lab_tab,
        '_build_elab_dynamic_row':_hmg_build_elab_dynamic_row,
        '_add_enhanced_lab':_hmg_add_enhanced_lab,
        '_ensure_panel_tests_in_catalog':_ensure_panel_tests_in_catalog,
        '_render_lab_pdf_native':_hmg_render_lab_pdf_native,
        '_render_lab_png_native':_hmg_render_lab_png_native,
        '_print_ecg':_hmg_print_ecg,
        '_hmg_print_ecg':_hmg_print_ecg,
        '_ecg_tab':_hmg_ecg_tab,
        '_save_ecg':_hmg_save_ecg,
        '_render_ecg_pdf_native':_hmg_render_ecg_pdf_native,
        '_render_ecg_png_native':_hmg_render_ecg_png_native,
        '_view_saved_ecg':_view_saved_ecg,
        '_load_ecg_report':_load_ecg_report,
        '_load_and_print_ecg':_load_and_print_ecg,
        '_delete_ecg_report':_delete_ecg_report,
    }
    for n,fn in explicit.items(): setattr(HMGBillingApp,n,fn)
    required=['_pharmacy','_drug_mgmt','_inv_mgmt','_rad','_upload_tab','_settings','_chat_tab','_snapshot_tab','_procedures_tab','_vitals_timeline_tab','_consent_form_tab','_referral_note_tab','_saved_items_tab','_daily_notes_tab','_ai_analysis_tab','_ai_bos_tab','_transfer_tab','_appointments_tab','_nursing_notes_tab','_medical_report_tab','_user_management_tab','_audit_log_tab','_popup','_text_popup','_switch','on_stop','compute_news','compute_qsofa']
    required += [n for n in dir(HMGBillingApp) if n.startswith('_refresh_')]
    missing=[]
    for n in required:
        if not callable(getattr(HMGBillingApp,n,None)):
            missing.append(n); print(f'[HMG bootstrap] missing method: {n}')
    if missing: print('[HMG bootstrap] missing names:', ', '.join(sorted(set(missing))))
    else: print('[HMG bootstrap] OK')

_hmg_bootstrap_recover_swallowed_methods()
# ============================================================================
# HMG panel-injection guard
# ----------------------------------------------------------------------------
# load_all() replaces self.investigations with whatever is in invs.json.
# "Full Lipid Profile", "Liver Function Test (LFT)" and "Renal Function
# Test (RFT)" live only in PANEL_DEFINITIONS (never in _init_invs), so
# they get wiped by load_all() and never reach the Enhanced Lab spinner.
# This patch re-injects them after every load_all(), and refreshes the
# spinner's values if the tab already exists.
# ============================================================================
def _hmg_patch_load_all_for_panels():
    try:
        _orig = HMGBillingApp.load_all

        def _patched_load_all(self, *a, **kw):
            _orig(self, *a, **kw)
            try:
                self._ensure_panel_tests_in_catalog()
            except Exception as e:
                print(f"[HMG] panel re-inject after load_all failed: {e}")

        HMGBillingApp.load_all = _patched_load_all
        print("[HMG] load_all patched — panel tests will re-inject on every load.")
    except Exception as e:
        print(f"[HMG] load_all patch failed: {e}")


_hmg_patch_load_all_for_panels()


# Belt-and-braces: also refresh the spinner once the main UI has settled,
# in case _enhanced_lab_tab was built before the last load_all() finished.
def _hmg_refresh_elab_spinner_later(self, dt=None):
    """Safely refresh the enhanced-lab spinner after login/UI construction."""
    try:
        spinner = getattr(self, 'elab_test', None)
        investigations = getattr(self, 'investigations', None)
        if spinner is not None and isinstance(investigations, list):
            spinner.values = [str(i.get('name', '')) for i in investigations
                              if isinstance(i, dict) and i.get('name')]
    except Exception as e:
        print(f"[HMG] spinner refresh failed: {e}")


try:
    _orig_on_login = HMGBillingApp._on_login_success

    def _patched_on_login(self, user):
        _orig_on_login(self, user)
        Clock.schedule_once(
            lambda dt: _hmg_refresh_elab_spinner_later(self), 1.0)

    HMGBillingApp._on_login_success = _patched_on_login
except Exception as e:
    print(f"[HMG] login-hook patch failed: {e}")
   
