# ============================================================================
# HMG — final method binding
# ----------------------------------------------------------------------------
# Because the class body of HMGBillingApp ends after _dashboard, every
# self-taking function defined at module scope must be explicitly attached
# as a method. This loops over the module globals and binds them all.
# ============================================================================
import inspect as _inspect

_bind_count = 0
for _name, _obj in list(globals().items()):
    if (callable(_obj)
            and _name.startswith('_')
            and not _name.startswith('__')
            and not hasattr(HMGBillingApp, _name)):
        try:
            _params = list(_inspect.signature(_obj).parameters)
            if _params and _params[0] == 'self':
                setattr(HMGBillingApp, _name, _obj)
                _bind_count += 1
        except Exception:
            pass

print(f"[HMG] final binding — attached {_bind_count} methods to HMGBillingApp")

# HMG recovery: the EMR/dependent methods were swallowed as nested functions
# inside _schedule_followup. Recover only self-taking methods that are still
# absent from HMGBillingApp, preserving any existing top-level replacements.
def _hmg_recover_schedule_methods():
    try:
        import ast as _ast
        with open(__file__, "r", encoding="utf-8") as _f:
            _tree = _ast.parse(_f.read(), filename=__file__)
        _schedule = next((n for n in _tree.body
                          if isinstance(n, _ast.FunctionDef)
                          and n.name == "_schedule_followup"), None)
        if _schedule is None:
            return
        _ns = globals()
        _recovered = 0
        for _node in _schedule.body:
            if not isinstance(_node, _ast.FunctionDef):
                continue
            _args = _node.args.args
            if not _args or _args[0].arg != "self" or not _node.name.startswith("_"):
                continue
            if callable(getattr(HMGBillingApp, _node.name, None)):
                continue
            _mod = _ast.Module(body=[_node], type_ignores=[])
            _ast.fix_missing_locations(_mod)
            exec(compile(_mod, __file__, "exec"), _ns, _ns)
            _fn = _ns.get(_node.name)
            if callable(_fn):
                setattr(HMGBillingApp, _node.name, _fn)
                _recovered += 1
        print(f"[HMG] recovered {_recovered} swallowed EMR methods")
    except Exception as _e:
        print(f"[HMG] nested-method recovery failed: {_e}")

_hmg_recover_schedule_methods()




# ============================================================================
# HMG FINAL RUNTIME EMR BINDING
# ============================================================================
try:
    import ast as _hmg_ast
    _hmg_source = open(__file__, "r", encoding="utf-8").read()
    _hmg_tree = _hmg_ast.parse(_hmg_source, filename=__file__)
    _hmg_schedule = next((n for n in _hmg_tree.body
        if isinstance(n, _hmg_ast.FunctionDef) and n.name == "_schedule_followup"), None)
    if _hmg_schedule is not None:
        for _hmg_node in _hmg_schedule.body:
            if (isinstance(_hmg_node, _hmg_ast.FunctionDef)
                    and _hmg_node.name.startswith("_")
                    and _hmg_node.args.args
                    and _hmg_node.args.args[0].arg == "self"):
                try:
                    _hmg_mod = _hmg_ast.Module(body=[_hmg_node], type_ignores=[])
                    _hmg_ast.fix_missing_locations(_hmg_mod)
                    exec(compile(_hmg_mod, __file__, "exec"), globals(), globals())
                    _hmg_fn = globals().get(_hmg_node.name)
                    if callable(_hmg_fn):
                        setattr(HMGBillingApp, _hmg_node.name, _hmg_fn)
                except Exception as _hmg_inner:
                    print(f"[HMG] recovery skipped {_hmg_node.name}: {_hmg_inner}")

    if callable(globals().get("_emr")):
        HMGBillingApp._emr = globals()["_emr"]

    for _hmg_name in (
        "_on_dept_change", "_build_dept_fields", "_add_fields_to_section",
        "_recalc_dept_fields_height", "_build_common_fields",
        "_clear_drug_list", "_add_drug_row", "_save_emr", "_clear_emr",
        "_view_emr_history", "_view_emr_detail",
    ):
        _hmg_fn = globals().get(_hmg_name)
        if callable(_hmg_fn):
            setattr(HMGBillingApp, _hmg_name, _hmg_fn)

    if not callable(getattr(HMGBillingApp, "_emr", None)):
        raise RuntimeError("HMG final repair failed: HMGBillingApp._emr unavailable")
    print("[HMG] FINAL EMR binding OK — _emr and callbacks attached")
except Exception as _hmg_final_error:
    print(f"[HMG] FINAL EMR binding ERROR: {_hmg_final_error}")
    raise


# ============================================================================
# HMG EMR DRUG-ROW COMPATIBILITY HELPER
# The current _refresh_drug_display builds rows inline.  Older EMR patches
# may still expect _add_drug_row, so provide a compatible helper without
# changing the existing display logic.
# ============================================================================
def _add_drug_row(self, drug, index=None):
    """Add one prescription row to self.drug_display.

    Kept compatible with the current EMR drug record format.  If *drug* is
    omitted, the optional index selects a record from self.emr_drug_list.
    Returns the created row, or None when the display/record is unavailable.
    """
    try:
        if not hasattr(self, "drug_display"):
            return None
        if drug is None and index is not None:
            if 0 <= int(index) < len(getattr(self, "emr_drug_list", [])):
                drug = self.emr_drug_list[int(index)]
        if not isinstance(drug, dict):
            return None

        row = BoxLayout(size_hint_y=None, height=30, spacing=3)
        row.add_widget(Label(text=str(drug.get("name", "")), font_size=12,
                             size_hint_x=0.3))
        row.add_widget(Label(text=f"Total: {drug.get('total', 0)}",
                             font_size=12, size_hint_x=0.15, bold=True,
                             color=get_color_from_hex('#2980b9')))
        row.add_widget(Label(text=f"Days: {drug.get('days', 0)}",
                             font_size=12, size_hint_x=0.1))
        if drug.get('stock_checked', 0) < drug.get('total', 0):
            row.add_widget(Label(text="⚠️ Low Stock", font_size=11,
                                 size_hint_x=0.12,
                                 color=get_color_from_hex('#e74c3c')))

        btn_remove = Button(text="X", font_size=11, size_hint_x=0.08,
                            size_hint_y=None, height=25,
                            background_color=get_color_from_hex('#e74c3c'),
                            background_normal='')
        if index is None:
            try:
                index = self.emr_drug_list.index(drug)
            except (ValueError, AttributeError):
                index = -1
        btn_remove.idx = index
        if hasattr(self, '_remove_drug_from_emr'):
            btn_remove.bind(on_press=self._remove_drug_from_emr)
        row.add_widget(btn_remove)
        self.drug_display.add_widget(row)
        return row
    except Exception:
        return None


# ============================================================================
# HMG INTENSIVE EMR REPAIR — EXPLICIT NESTED-METHOD EXTRACTION
# ============================================================================
# The EMR methods were originally nested directly inside _schedule_followup.
# Generic global binding is insufficient when the nested methods are not yet
# module globals. Extract every direct self-method from the original AST and
# bind it explicitly to HMGBillingApp. This block is deliberately placed
# immediately before application startup.
try:
    import ast as _HMG_AST_INTENSIVE
    with open(__file__, "r", encoding="utf-8") as _HMG_F:
        _HMG_TREE_INTENSIVE = _HMG_AST_INTENSIVE.parse(
            _HMG_F.read(), filename=__file__
        )

    _HMG_SCHED_INTENSIVE = next(
        (n for n in _HMG_TREE_INTENSIVE.body
         if isinstance(n, _HMG_AST_INTENSIVE.FunctionDef)
         and n.name == "_schedule_followup"),
        None
    )

    _HMG_RECOVERED_NAMES = []
    if _HMG_SCHED_INTENSIVE is not None:
        for _HMG_NODE in _HMG_SCHED_INTENSIVE.body:
            if not (
                isinstance(_HMG_NODE, _HMG_AST_INTENSIVE.FunctionDef)
                and _HMG_NODE.args.args
                and _HMG_NODE.args.args[0].arg == "self"
                and _HMG_NODE.name.startswith("_")
            ):
                continue

            _HMG_MOD = _HMG_AST_INTENSIVE.Module(
                body=[_HMG_NODE], type_ignores=[]
            )
            _HMG_AST_INTENSIVE.fix_missing_locations(_HMG_MOD)

            _HMG_LOCAL_NS = {}
            exec(
                compile(_HMG_MOD, __file__, "exec"),
                globals(),
                _HMG_LOCAL_NS
            )
            _HMG_FN = _HMG_LOCAL_NS.get(_HMG_NODE.name)

            if callable(_HMG_FN):
                globals()[_HMG_NODE.name] = _HMG_FN
                setattr(HMGBillingApp, _HMG_NODE.name, _HMG_FN)
                _HMG_RECOVERED_NAMES.append(_HMG_NODE.name)

    # Explicitly guarantee the critical EMR chain.
    _HMG_CRITICAL_EMR = (
        "_emr",
        "_on_dept_change",
        "_build_dept_fields",
        "_add_fields_to_section",
        "_recalc_dept_fields_height",
        "_build_common_fields",
        "_on_drug_search_change",
        "_on_dispense_drug_search_change",
        "_on_pharm_drug_search_change",
        "_add_drug_to_emr",
        "_refresh_drug_display",
        "_remove_drug_from_emr",
        "_refresh_admission_spinner",
        "_clear_drug_list",
        "_add_drug_row",
        "_clear_emr",
        "_save_emr",
        "_view_emr_history",
        "_view_emr_detail",
    )

    # If a critical function was extracted, force-bind it even if a previous
    # patch installed another object with the same name.
    for _HMG_NAME in _HMG_CRITICAL_EMR:
        _HMG_FN = globals().get(_HMG_NAME)
        if callable(_HMG_FN):
            setattr(HMGBillingApp, _HMG_NAME, _HMG_FN)

    _HMG_MISSING = [
        _HMG_NAME for _HMG_NAME in _HMG_CRITICAL_EMR
        if not callable(getattr(HMGBillingApp, _HMG_NAME, None))
    ]

    if _HMG_MISSING:
        raise RuntimeError(
            "HMG intensive EMR repair failed; missing methods: "
            + ", ".join(_HMG_MISSING)
        )

    print(
        "[HMG INTENSIVE REPAIR] OK — "
        + str(len(_HMG_RECOVERED_NAMES))
        + " nested methods recovered; "
        + "critical EMR chain verified"
    )

except Exception as _HMG_INTENSIVE_ERROR:
    print("[HMG INTENSIVE REPAIR] FAILED:", _HMG_INTENSIVE_ERROR)
    raise



