class FacilityConfig:
    FILE = "facility_config.json"
    DEFAULTS = {
        "facility_name": "HMG HOSPITAL LTD",
        "short_name": "HMG",
        "address_line": "Obazi Gate, Abonnema, Akuku-Toru L.G.A., Rivers State.",
        "tagline": "...Quality Care, Healthier Tomorrow",
        "footer_strip": "Medical Records & Diagnostic Services",
        "currency": "₦",
        "primary_color": "#6750A4",
        "primary_container": "#EADDFF",
        "on_primary": "#FFFFFF",
        "on_primary_container": "#21005D",
        "navy": "#123B72",
        "accent": "#1E6AA8",
        "logo_path": "",
        "signature_path": "",
        "signatory_name": "Dr. Precious Belema Ibiabuo",
        "signatory_quals": "B.Sc., MBBS, M.Sc., MLT, FWACS (Primary)",
        "signatory_role": "Medical Director, HMG Hospital Ltd",
        "report_prefix": "HMG",
        "default_departments": [
            "General Medicine", "Pediatrics", "Obstetrics",
            "Surgery", "Cardiology", "Emergency"
        ],
    }

    def __init__(self):
        self.data = dict(self.DEFAULTS)
        self.load()

    def load(self):
        try:
            if os.path.exists(self.FILE):
                with open(self.FILE, "r", encoding="utf-8") as f:
                    saved = json.load(f)
                if isinstance(saved, dict):
                    self.data.update(saved)
        except Exception as e:
            print(f"[HMG] Facility config load error: {e}")

    def save(self):
        try:
            parent = os.path.dirname(self.FILE)
            if parent:
                os.makedirs(parent, exist_ok=True)
            with open(self.FILE, "w", encoding="utf-8") as f:
                json.dump(self.data, f, indent=2, ensure_ascii=False, default=str)
            return True
        except Exception as e:
            print(f"[HMG] Facility config save error: {e}")
            return False

    def get(self, key, fallback=None):
        return self.data.get(key, fallback)

    def set(self, key, value):
        self.data[key] = value

    def reset(self):
        self.data = dict(self.DEFAULTS)
        return self.save()

    def color(self, key):
        try:
            return get_color_from_hex(str(self.get(key, "#6750A4")))
        except Exception:
            return get_color_from_hex("#6750A4")


class AnalyticsEngine:
    """Pure read-only analytics over the live HMGBillingApp data collections."""

    def __init__(self, app):
        self.app = app

    @staticmethod
    def _dt(value):
        if isinstance(value, datetime):
            return value
        if value is None:
            return None
        s = str(value).strip()
        if not s:
            return None
        for fmt in ("%Y-%m-%d %H:%M:%S", "%Y-%m-%d %H:%M",
                    "%Y-%m-%d", "%d/%m/%Y %H:%M:%S", "%d/%m/%Y"):
            try:
                return datetime.strptime(s[:19], fmt)
            except Exception:
                pass
        try:
            return datetime.fromisoformat(s.replace("Z", "+00:00")).replace(tzinfo=None)
        except Exception:
            return None

    @classmethod
    def _date(cls, value):
        d = cls._dt(value)
        return d.date() if d else None

    @staticmethod
    def _num(value):
        try:
            if value is None or value == "":
                return 0.0
            return float(str(value).replace(",", "").replace("₦", "").strip())
        except Exception:
            return 0.0

    @staticmethod
    def _label_date(d):
        return d.strftime("%Y-%m-%d")

    @staticmethod
    def _period_bounds(period, anchor):
        a = anchor.date() if isinstance(anchor, datetime) else anchor
        if period == "daily":
            return a, a, a.strftime("%Y-%m-%d")
        if period == "weekly":
            start = a - timedelta(days=a.weekday())
            end = start + timedelta(days=6)
            return start, end, f"{start.isocalendar().year}-W{start.isocalendar().week:02d}"
        if period == "monthly":
            start = a.replace(day=1)
            if start.month == 12:
                nxt = start.replace(year=start.year + 1, month=1, day=1)
            else:
                nxt = start.replace(month=start.month + 1, day=1)
            return start, nxt - timedelta(days=1), start.strftime("%Y-%m")
        start = a.replace(month=1, day=1)
        return start, start.replace(year=start.year + 1) - timedelta(days=1), start.strftime("%Y")

    def _rows(self, name):
        v = getattr(self.app, name, [])
        return v if isinstance(v, list) else []

    def _in(self, value, start, end):
        d = self._date(value)
        return bool(d and start <= d <= end)

    def _deaths(self, start, end):
        deaths = []
        words = re.compile(r"\b(expired|died|deceased|death|mortuary)\b", re.I)
        for a in self._rows("admissions"):
            dd = a.get("discharge_date")
            notes = f"{a.get('notes','')} {a.get('diagnosis','')}"
            if dd and self._in(dd, start, end) and words.search(str(notes)):
                deaths.append(a)
        for t in self._rows("tasks"):
            if str(t.get("task_type", "")).strip().lower() == "mortality":
                stamp = t.get("created_at") or t.get("updated_at") or t.get("completed_at")
                if self._in(stamp, start, end):
                    deaths.append(t)
        return deaths

    def _bucket_start(self, d, bucket):
        if bucket == "hour":
            return d.replace(minute=0, second=0, microsecond=0)
        if bucket == "week":
            return d - timedelta(days=d.weekday())
        if bucket == "month":
            return d.replace(day=1)
        if bucket == "year":
            return d.replace(month=1, day=1)
        return d

    def _bucket_label(self, d, bucket):
        if bucket == "hour":
            return d.strftime("%m-%d %Hh")
        if bucket == "week":
            iso = d.isocalendar()
            return f"{iso.year}-W{iso.week:02d}"
        if bucket == "month":
            return d.strftime("%Y-%m")
        if bucket == "year":
            return d.strftime("%Y")
        return d.strftime("%Y-%m-%d")

    def range_series(self, metric, start_date, end_date, bucket="day"):
        try:
            start = start_date.date() if isinstance(start_date, datetime) else start_date
            end = end_date.date() if isinstance(end_date, datetime) else end_date
            if start > end:
                start, end = end, start
            counts = {}
            if metric in ("registrations", "admissions", "discharges", "transfers",
                          "lab_orders", "rad_orders", "ecg", "deaths"):
                source = {
                    "registrations": "patients", "admissions": "admissions",
                    "discharges": "admissions", "transfers": "transfers",
                    "lab_orders": "lab_tests", "rad_orders": "radiology",
                    "ecg": "ecg_reports"
                }.get(metric)
                for r in self._rows(source) if source else []:
                    stamp = (r.get("date") if metric == "registrations" else
                             r.get("admission_date") if metric == "admissions" else
                             r.get("discharge_date") if metric == "discharges" else
                             r.get("date") if metric == "transfers" else
                             r.get("date_ordered") if metric == "lab_orders" else
                             r.get("date") if metric == "rad_orders" else
                             r.get("ts"))
                    if metric == "transfers":
                        stamp = r.get("date") or r.get("created")
                    if self._in(stamp, start, end):
                        d = self._dt(stamp) if bucket == "hour" else self._date(stamp)
                        if d is None:
                            continue
                        b = self._bucket_start(d, bucket)
                        counts[b] = counts.get(b, 0) + 1
                if metric == "deaths":
                    for r in self._deaths(start, end):
                        stamp = r.get("discharge_date") or r.get("created_at") or r.get("ts")
                        d = self._date(stamp)
                        if d:
                            b = self._bucket_start(d, bucket)
                            counts[b] = counts.get(b, 0) + 1
            elif metric in ("billing", "payments"):
                source = self._rows("bills") if metric == "billing" else getattr(
                    getattr(self.app, "pt_tracker", None), "payments", []) or []
                for r in source:
                    stamp = r.get("ts") or r.get("created")
                    if self._in(stamp, start, end):
                        d = self._dt(stamp) if bucket == "hour" else self._date(stamp)
                        if d is None:
                            continue
                        b = self._bucket_start(d, bucket)
                        val = self._num(r.get("total", 0) if metric == "billing"
                                        else r.get("amount", 0))
                        counts[b] = counts.get(b, 0.0) + val
            out = []
            if bucket == "hour":
                cur = datetime.combine(start, datetime.min.time())
                stop = datetime.combine(end, datetime.max.time()).replace(minute=0, second=0, microsecond=0)
                while cur <= stop:
                    out.append((self._bucket_label(cur, bucket), counts.get(cur, 0)))
                    cur += timedelta(hours=1)
                return out
            cur = datetime.combine(start, datetime.min.time())
            stop = datetime.combine(end, datetime.min.time())
            while cur <= stop:
                d = cur.date()
                b = self._bucket_start(d, bucket)
                out.append((self._bucket_label(b, bucket), counts.get(b, 0)))
                if bucket == "week":
                    cur += timedelta(days=7)
                elif bucket == "month":
                    cur = cur.replace(day=1)
                    if cur.month == 12:
                        cur = cur.replace(year=cur.year + 1, month=1)
                    else:
                        cur = cur.replace(month=cur.month + 1)
                elif bucket == "year":
                    cur = cur.replace(year=cur.year + 1, month=1, day=1)
                else:
                    cur += timedelta(days=1)
            return out
        except Exception:
            import traceback
            traceback.print_exc()
            return []

    def snapshot(self, period="daily", anchor=None):
        empty = {
            "period": period, "label": "", "start": "", "end": "",
            "registrations": 0, "admissions": 0, "discharges": 0,
            "transfers_out": 0, "transfers_in": 0,
            "billed_total": 0.0, "paid_total": 0.0, "outstanding": 0.0,
            "prescriptions": 0, "lab_orders": 0, "rad_orders": 0,
            "ecg_reports": 0, "deaths": 0, "top_diagnoses": [],
            "top_departments": [], "payment_methods": {},
            "daily_series": {}
        }
        try:
            anchor = anchor or datetime.now()
            start, end, label = self._period_bounds(period, anchor)
            out = dict(empty)
            out.update({"period": period, "label": label,
                        "start": start.isoformat(), "end": end.isoformat()})

            patients = self._rows("patients")
            admissions = self._rows("admissions")
            transfers = self._rows("transfers")
            bills = self._rows("bills")
            payments = getattr(getattr(self.app, "pt_tracker", None), "payments", []) or []
            prescriptions = self._rows("prescriptions")
            labs = self._rows("lab_tests")
            rad = self._rows("radiology")
            ecg = self._rows("ecg_reports")

            out["registrations"] = sum(1 for r in patients if self._in(r.get("date"), start, end))
            out["admissions"] = sum(1 for r in admissions if self._in(r.get("admission_date"), start, end))
            out["discharges"] = sum(1 for r in admissions if self._in(r.get("discharge_date"), start, end))
            out["transfers_out"] = sum(1 for r in transfers if self._in(r.get("date") or r.get("created"), start, end))
            out["transfers_in"] = sum(1 for r in transfers if self._in(r.get("date") or r.get("created"), start, end))
            out["billed_total"] = sum(self._num(r.get("total")) for r in bills
                                      if self._in(r.get("ts") or r.get("created"), start, end))
            out["paid_total"] = sum(self._num(r.get("amount")) for r in payments
                                    if self._in(r.get("ts"), start, end))
            out["outstanding"] = max(0.0, out["billed_total"] - out["paid_total"])
            out["prescriptions"] = sum(1 for r in prescriptions if self._in(r.get("ts"), start, end))
            out["lab_orders"] = sum(1 for r in labs if self._in(r.get("date_ordered"), start, end))
            out["rad_orders"] = sum(1 for r in rad if self._in(r.get("date"), start, end))
            out["ecg_reports"] = sum(1 for r in ecg if self._in(r.get("ts"), start, end))
            out["deaths"] = len(self._deaths(start, end))

            dx = {}
            deps = {}
            for r in admissions:
                if self._in(r.get("admission_date"), start, end):
                    d = str(r.get("diagnosis", "") or "").strip()
                    dep = str(r.get("department", "") or "").strip()
                    if d:
                        dx[d] = dx.get(d, 0) + 1
                    if dep:
                        deps[dep] = deps.get(dep, 0) + 1
            for r in self._rows("emr_records"):
                if self._in(r.get("ts"), start, end):
                    d = str(r.get("dx") or r.get("diagnosis") or "").strip()
                    dep = str(r.get("dept") or "").strip()
                    if d:
                        dx[d] = dx.get(d, 0) + 1
                    if dep:
                        deps[dep] = deps.get(dep, 0) + 1
            out["top_diagnoses"] = sorted(dx.items(), key=lambda x: (-x[1], x[0]))[:10]
            out["top_departments"] = sorted(deps.items(), key=lambda x: (-x[1], x[0]))[:8]

            pm = {}
            for r in payments:
                if self._in(r.get("ts"), start, end):
                    method = str(r.get("method") or "Other").strip() or "Other"
                    pm[method] = pm.get(method, 0.0) + self._num(r.get("amount"))
            out["payment_methods"] = pm

            if period != "daily":
                out["daily_series"] = {
                    "registrations": self.range_series("registrations", start, end, "day"),
                    "admissions": self.range_series("admissions", start, end, "day"),
                    "discharges": self.range_series("discharges", start, end, "day"),
                    "billing": self.range_series("payments", start, end, "day"),
                    "deaths": self.range_series("deaths", start, end, "day"),
                }
            return out
        except Exception:
            import traceback
            traceback.print_exc()
            return empty

    def summary_table(self, start_date, end_date):
        try:
            start = start_date.date() if isinstance(start_date, datetime) else start_date
            end = end_date.date() if isinstance(end_date, datetime) else end_date
            days = (end - start).days + 1
            bucket = "day" if days <= 31 else "week" if days <= 180 else "month" if days <= 730 else "year"
            labels = self.range_series("registrations", start, end, bucket)
            rows = []
            for label, _ in labels:
                # derive bucket range from label and query all metrics against the same span
                vals = {}
                metrics = ["registrations", "admissions", "discharges", "deaths",
                           "billing", "payments", "transfers"]
                for m in metrics:
                    series = self.range_series(m, start, end, bucket)
                    vals[m] = dict(series).get(label, 0)
                billed = float(vals["billing"] or 0)
                paid = float(vals["payments"] or 0)
                rows.append({
                    "period": label, "registrations": vals["registrations"],
                    "admissions": vals["admissions"], "discharges": vals["discharges"],
                    "deaths": vals["deaths"], "billed": billed, "paid": paid,
                    "outstanding": max(0.0, billed - paid),
                    "transfers": vals["transfers"]
                })
            return rows
        except Exception:
            import traceback
            traceback.print_exc()
            return []


class M3BarChart(BoxLayout):
    def __init__(self, title="", height=dp(220), **kwargs):
        kwargs.setdefault("orientation", "vertical")
        kwargs.setdefault("size_hint_y", None)
        kwargs.setdefault("height", height)
        super().__init__(**kwargs)
        self.title = title
        self.series = []
        self.value_fmt = "{:,.0f}"
        self.bar_color = None
        self.on_bar_tap = None
        self.padding = (dp(6), dp(4), dp(6), dp(4))
        self.bind(pos=self._redraw, size=self._redraw)
        Clock.schedule_once(lambda dt: self._redraw(), 0)

    def set_data(self, series, value_fmt="{:,.0f}", bar_color=None, on_bar_tap=None):
        try:
            self.series = list(series or [])
            self.value_fmt = value_fmt
            self.bar_color = bar_color
            if on_bar_tap is not None:
                self.on_bar_tap = on_bar_tap
            self._redraw()
        except Exception as e:
            print(f"M3BarChart set_data: {e}")

    def _redraw(self, *args):
        try:
            self.canvas.before.clear()
            with self.canvas.before:
                Color(*get_color_from_hex("#FFFBFE"))
                RoundedRectangle(pos=self.pos, size=self.size, radius=[dp(16)])
                Color(*get_color_from_hex("#79747E"))
                Line(rounded_rectangle=(self.x, self.y, self.width, self.height, dp(16)), width=dp(1))
            n = len(self.series)
            if not n or self.width <= dp(20) or self.height <= dp(40):
                return
            left, right, bottom, top = self.x+dp(42), self.right-dp(10), self.y+dp(30), self.top-dp(32)
            maxv = max([float(v or 0) for _, v in self.series] + [1])
            plot_h = max(dp(10), top-bottom)
            # grid
            with self.canvas.after:
                self.canvas.after.clear()
            with self.canvas.after:
                for i in range(6):
                    gy = bottom + plot_h * i / 5.0
                    Color(*get_color_from_hex("#E7E0EC"))
                    Line(points=[left, gy, right, gy], width=dp(1))
                Color(*get_color_from_hex(self.bar_color or "#6750A4"))
                gap = dp(5)
                bw = max(dp(4), (right-left-gap*(n+1))/max(n,1))
                hi = max(range(n), key=lambda i: float(self.series[i][1] or 0))
                for i, (lab, val) in enumerate(self.series):
                    val = float(val or 0)
                    bh = plot_h * val / maxv if maxv else 0
                    bx = left + gap + i*(bw+gap)
                    by = bottom
                    if isinstance(self.bar_color, (list, tuple)):
                        _bc = self.bar_color[i % len(self.bar_color)]
                    else:
                        _bc = self.bar_color or "#6750A4"
                    Color(*get_color_from_hex("#21005D" if i == hi else _bc))
                    RoundedRectangle(pos=(bx, by), size=(bw, max(dp(1), bh)),
                                     radius=[dp(16), dp(16), dp(2), dp(2)])
            # compact labels
            self._labels = []
            for child in list(self.children):
                self.remove_widget(child)
            title_lbl = Label(text=self.title, font_size=13, bold=True,
                              color=get_color_from_hex("#1D1B20"),
                              size_hint=(1, None), height=dp(22),
                              pos=(self.x, self.top-dp(26)))
            self.add_widget(title_lbl)
            top_lbl = Label(text=self.value_fmt.format(maxv), font_size=9,
                            color=get_color_from_hex("#79747E"),
                            size_hint=(None,None), size=(dp(45),dp(16)),
                            pos=(self.x+dp(2), self.top-dp(45)))
            self.add_widget(top_lbl)
            if n:
                for i,(lab,val) in enumerate(self.series):
                    x = left + gap + i*(bw+gap) + bw/2
                    text = str(lab)
                    if len(text) > 8:
                        text = text[:7] + "…"
                    lbl = Label(text=text, font_size=8,
                                color=get_color_from_hex("#79747E"),
                                size_hint=(None,None), size=(max(dp(32),bw+dp(8)),dp(20)),
                                pos=(x-(max(dp(32),bw+dp(8))/2), self.y+dp(5)))
                    self.add_widget(lbl)
        except Exception as e:
            print(f"M3BarChart redraw: {e}")

    def on_touch_down(self, touch):
        if not self.collide_point(*touch.pos) or not self.series:
            return super().on_touch_down(touch)
        try:
            left, right = self.x+dp(42), self.right-dp(10)
            n = len(self.series)
            gap = dp(5)
            bw = max(dp(4), (right-left-gap*(n+1))/max(n,1))
            for i,(lab,val) in enumerate(self.series):
                bx = left + gap + i*(bw+gap)
                if bx <= touch.x <= bx+bw:
                    if callable(self.on_bar_tap):
                        self.on_bar_tap(i, lab, val)
                    return True
        except Exception:
            pass
        return super().on_touch_down(touch)


class M3LineChart(M3BarChart):
    def set_data(self, series, value_fmt="{:,.0f}", bar_color=None, on_bar_tap=None):
        self.series = list(series or [])
        self.value_fmt = value_fmt
        self.bar_color = bar_color
        if on_bar_tap is not None:
            self.on_bar_tap = on_bar_tap
        self._redraw_line()

    def _redraw_line(self):
        try:
            self.canvas.before.clear()
            self.canvas.after.clear()
            with self.canvas.before:
                Color(*get_color_from_hex("#FFFBFE"))
                RoundedRectangle(pos=self.pos, size=self.size, radius=[dp(16)])
                Color(*get_color_from_hex("#79747E"))
                Line(rounded_rectangle=(self.x,self.y,self.width,self.height,dp(16)), width=dp(1))
            n = len(self.series)
            if not n:
                return
            left, right, bottom, top = self.x+dp(42), self.right-dp(10), self.y+dp(30), self.top-dp(32)
            maxv = max([float(v or 0) for _,v in self.series] + [1])
            plot_h = max(dp(10), top-bottom)
            pts=[]
            for i,(_,v) in enumerate(self.series):
                x = left + (right-left)*(i/(n-1) if n>1 else .5)
                y = bottom + plot_h*float(v or 0)/maxv
                pts.extend([x,y])
            with self.canvas.after:
                for i in range(6):
                    gy=bottom+plot_h*i/5
                    Color(*get_color_from_hex("#E7E0EC"))
                    Line(points=[left,gy,right,gy],width=dp(1))
                Color(*get_color_from_hex("#6750A4"))
                Line(points=pts, width=dp(2), joint="round")
                if n:
                    Color(0.403,0.314,0.643,0.15)
                    fill_pts=pts+[right,bottom,left,bottom]
                    Line(points=fill_pts, close=True, width=dp(1))
            for child in list(self.children):
                self.remove_widget(child)
            self.add_widget(Label(text=self.title,font_size=13,bold=True,
                                  color=get_color_from_hex("#1D1B20"),
                                  size_hint=(1,None),height=dp(22),
                                  pos=(self.x,self.top-dp(26))))
            for i,(lab,val) in enumerate(self.series):
                if i not in (0,n-1) and n>8:
                    continue
                text=str(lab)
                if len(text)>8: text=text[:7]+"…"
                x=left+(right-left)*(i/(n-1) if n>1 else .5)
                self.add_widget(Label(text=text,font_size=8,
                                      color=get_color_from_hex("#79747E"),
                                      size_hint=(None,None),size=(dp(52),dp(18)),
                                      pos=(x-dp(26),self.y+dp(4))))
        except Exception as e:
            print(f"M3LineChart redraw: {e}")

    def _redraw(self,*args):
        self._redraw_line()


class M3DonutChart(M3BarChart):
    PALETTE = ["#6750A4","#7D5260","#386A20","#7A5900","#00696D","#8C4A60","#565992"]
    def set_data(self, series, center_label=""):
        self.series=list(series or [])
        self.center_label=center_label
        self._redraw_donut()
    def _redraw_donut(self):
        try:
            self.canvas.before.clear()
            self.canvas.after.clear()
            with self.canvas.before:
                Color(*get_color_from_hex("#FFFBFE"))
                RoundedRectangle(pos=self.pos,size=self.size,radius=[dp(16)])
                Color(*get_color_from_hex("#79747E"))
                Line(rounded_rectangle=(self.x,self.y,self.width,self.height,dp(16)),width=dp(1))
            total=sum(max(0,float(v or 0)) for _,v in self.series)
            cx=self.center_x; cy=self.center_y-dp(5)
            r=min(self.width,self.height)*.28
            start=0
            with self.canvas.after:
                if total:
                    for i,(lab,val) in enumerate(self.series):
                        frac=max(0,float(val or 0))/total
                        Color(*get_color_from_hex(self.PALETTE[i%len(self.PALETTE)]))
                        Line(circle=(cx,cy,r,start,start+360*frac),width=dp(28))
                        start += 360*frac
            for child in list(self.children): self.remove_widget(child)
            self.add_widget(Label(text=self.title,font_size=13,bold=True,
                                  color=get_color_from_hex("#1D1B20"),
                                  size_hint=(1,None),height=dp(22),
                                  pos=(self.x,self.top-dp(26))))
            self.add_widget(Label(text=str(self.center_label),font_size=16,bold=True,
                                  color=get_color_from_hex("#21005D"),
                                  size_hint=(None,None),size=(dp(100),dp(28)),
                                  pos=(cx-dp(50),cy-dp(14))))
            if self.series:
                legend="  ".join(f"{str(k)[:10]}: {float(v):,.0f}" for k,v in self.series[:4])
                self.add_widget(Label(text=legend,font_size=8,
                                      color=get_color_from_hex("#79747E"),
                                      size_hint=(1,None),height=dp(22),
                                      pos=(self.x,self.y+dp(4))))
        except Exception as e:
            print(f"M3DonutChart redraw: {e}")


def _fac(self, key, fallback=""):
    try:
        return self.facility.get(key, fallback)
    except Exception:
        return fallback


def _currency(self):
    return self._fac("currency", "₦")


def _analytics_anchor_shift(self, direction):
    try:
        p = getattr(self, "_analytics_period", "daily")
        a = getattr(self, "_analytics_anchor", datetime.now())
        if p == "daily":
            a += timedelta(days=direction)
        elif p == "weekly":
            a += timedelta(days=7*direction)
        elif p == "monthly":
            m = a.month - 1 + direction
            y = a.year + m // 12
            m = m % 12 + 1
            a = a.replace(year=y, month=m, day=min(a.day, 28))
        else:
            a = a.replace(year=a.year + direction)
        self._analytics_anchor = a
        self._analytics_render()
    except Exception as e:
        print(f"Analytics anchor: {e}")


def _analytics_set_period(self, period):
    self._analytics_period = period
    self._analytics_anchor = datetime.now()
    self._analytics_render()


def _analytics_render(self):
    try:
        total_records = sum(len(getattr(self, n, []) or [])
                           for n in ("patients","admissions","transfers","bills",
                                     "prescriptions","lab_tests","radiology",
                                     "ecg_reports","emr_records","tasks"))
        if total_records > 500 and not getattr(self, "_analytics_busy", False):
            self._analytics_busy = True
            period = getattr(self, "_analytics_period", "daily")
            anchor = getattr(self, "_analytics_anchor", datetime.now())
            def worker():
                try:
                    snap = AnalyticsEngine(self).snapshot(period, anchor)
                    start = datetime.fromisoformat(snap["start"])
                    end = datetime.fromisoformat(snap["end"])
                    rows = AnalyticsEngine(self).summary_table(start.date(), end.date())
                    Clock.schedule_once(lambda dt: self._analytics_apply_result(snap, rows), 0)
                except Exception as e:
                    print(f"Analytics worker: {e}")
                    Clock.schedule_once(lambda dt: self._analytics_apply_result({}, []), 0)
            threading.Thread(target=worker, daemon=True).start()
            return
        snap = AnalyticsEngine(self).snapshot(
            getattr(self, "_analytics_period", "daily"),
            getattr(self, "_analytics_anchor", datetime.now()))
        start = datetime.fromisoformat(snap["start"])
        end = datetime.fromisoformat(snap["end"])
        rows = AnalyticsEngine(self).summary_table(start.date(), end.date())
        self._analytics_apply_result(snap, rows)
        return
    except Exception as e:
        print(f"Analytics render: {e}")
        return


def _analytics_apply_result(self, snap, rows):
    try:
        if not snap:
            self._analytics_busy = False
            return
        self._analytics_busy = False
        self._analytics_snapshot = snap
        if hasattr(self, "an_period_label"):
            self.an_period_label.text = snap["label"]
        elif hasattr(self, "_contrast_analytics_period_label"):
            self._contrast_analytics_period_label.text = snap["label"]
        for key, attr in {
            "registrations":"an_reg","admissions":"an_adm","discharges":"an_dis",
            "deaths":"an_deaths","billed_total":"an_billed","paid_total":"an_paid",
            "outstanding":"an_outstanding"
        }.items():
            if hasattr(self, attr):
                val=snap.get(key,0)
                getattr(self,attr).text = (
                    f"{self._currency()}{val:,.0f}" if key.endswith("total") else str(val))
        if hasattr(self,"an_transfers"):
            self.an_transfers.text=str(snap.get("transfers_in",0)+snap.get("transfers_out",0))
        if hasattr(self,"an_volume_chart"):
            if self._analytics_period == "daily":
                vol = [("Reg", snap.get("registrations",0)),
                       ("Adm", snap.get("admissions",0)),
                       ("Disch", snap.get("discharges",0))]
                self.an_volume_chart.set_data(vol,
                    bar_color=["#6750A4","#7D5260","#386A20"])
            else:
                ds = snap.get("daily_series", {})
                regs = dict(ds.get("registrations", []))
                adms = dict(ds.get("admissions", []))
                dis = dict(ds.get("discharges", []))
                labels = list(dict(ds.get("registrations", [])).keys())
                vol = []
                for lab in labels:
                    short = str(lab)[-5:]
                    vol.extend([(f"R{short}", regs.get(lab,0)),
                                (f"A{short}", adms.get(lab,0)),
                                (f"D{short}", dis.get(lab,0))])
                self.an_volume_chart.set_data(vol,
                    bar_color=["#6750A4","#7D5260","#386A20"])
        if hasattr(self,"an_payment_chart"):
            self.an_payment_chart.set_data(
                list(snap.get("payment_methods",{}).items()),
                center_label=f"{self._currency()}{snap.get('paid_total',0):,.0f}")
        if hasattr(self,"an_dx_chart"):
            self.an_dx_chart.set_data(snap.get("top_diagnoses",[]))
        if hasattr(self,"an_dept_chart"):
            self.an_dept_chart.set_data(snap.get("top_departments",[]))
        start=datetime.fromisoformat(snap["start"]); end=datetime.fromisoformat(snap["end"])
        bucket={"daily":"hour","weekly":"day","monthly":"day","yearly":"month"}.get(
            self._analytics_period,"day")
        metric=getattr(self,"an_metric_spinner",None)
        metric_name=(metric.text if metric else "Registrations")
        metric_map={
            "Registrations":"registrations","Admissions":"admissions","Discharges":"discharges",
            "Transfers":"transfers","Billing":"billing","Payments":"payments",
            "Lab Orders":"lab_orders","Radiology":"rad_orders","ECG":"ecg","Deaths":"deaths"}
        series=AnalyticsEngine(self).range_series(metric_map.get(metric_name,"registrations"),
                                                   start,end,bucket)
        if hasattr(self,"an_series_chart"):
            self.an_series_chart.set_data(series)
        if hasattr(self,"an_summary_grid"):
            self.an_summary_grid.clear_widgets()
            headers=["Period","Reg","Adm","Disch","Deaths","Billed","Paid","Outstanding","Transfers"]
            for h in headers:
                self.an_summary_grid.add_widget(Label(text=h,bold=True,font_size=10,
                    color=get_color_from_hex("#21005D"),size_hint_y=None,height=dp(26)))
            for row in rows:
                for k in ["period","registrations","admissions","discharges","deaths",
                          "billed","paid","outstanding","transfers"]:
                    v=row.get(k,0)
                    if k in ("billed","paid","outstanding"):
                        v=f"{self._currency()}{float(v):,.0f}"
                    self.an_summary_grid.add_widget(Label(text=str(v),font_size=9,
                        color=get_color_from_hex("#1D1B20"),size_hint_y=None,height=dp(24)))
    except Exception as e:
        print(f"Analytics render: {e}")


