def _export_analytics_csv(self, instance=None):
    try:
        snap=getattr(self,"_analytics_snapshot",None) or AnalyticsEngine(self).snapshot(
            getattr(self,"_analytics_period","daily"),getattr(self,"_analytics_anchor",datetime.now()))
        start=datetime.fromisoformat(snap["start"]); end=datetime.fromisoformat(snap["end"])
        rows=AnalyticsEngine(self).summary_table(start.date(),end.date())
        out=os.path.join(self._get_reports_dir(),
                         f"{self._fac('report_prefix','HMG')}_analytics_{snap['period']}_{snap['label'].replace('/','-')}.csv")
        with open(out,"w",newline="",encoding="utf-8") as f:
            w=csv.writer(f); w.writerow(["Period","Reg","Adm","Disch","Deaths","Billed","Paid","Outstanding","Transfers"])
            for r in rows: w.writerow([r["period"],r["registrations"],r["admissions"],r["discharges"],
                                       r["deaths"],r["billed"],r["paid"],r["outstanding"],r["transfers"]])
        self.audit_log("EXPORT_ANALYTICS_CSV",os.path.basename(out))
        self._popup("Analytics CSV",f"Saved:\n{out}")
        return out
    except Exception as e:
        self._popup("Analytics CSV Error",str(e)); return None


def _chart_to_png(self, kind, series, title, path, w_px=1200, h_px=500):
    if not PIL_AVAILABLE: return False
    try:
        from PIL import ImageFont
        im=PILImage.new("RGB",(w_px,h_px),"#FFFBFE"); d=ImageDraw.Draw(im)
        navy=self._fac("navy","#123B72"); primary=self._fac("primary_color","#6750A4")
        d.rounded_rectangle((10,10,w_px-10,h_px-10),radius=24,fill="#FFFBFE",outline="#79747E",width=2)
        d.text((35,25),str(title),fill="#1D1B20")
        vals=[float(v or 0) for _,v in series] or [0]
        mx=max(vals+[1]); left,right,top,bottom=90,w_px-35,85,h_px-70
        for i in range(6):
            y=bottom-(bottom-top)*i/5
            d.line((left,y,right,y),fill="#E7E0EC",width=1)
        if kind=="line":
            pts=[]
            for i,(_,v) in enumerate(series):
                x=left+(right-left)*(i/(len(series)-1) if len(series)>1 else .5)
                y=bottom-(bottom-top)*float(v or 0)/mx; pts.append((x,y))
            if len(pts)>1: d.line(pts,fill=primary,width=6,joint="curve")
        else:
            n=max(1,len(series)); bw=max(4,(right-left)/(n*1.35))
            for i,(_,v) in enumerate(series):
                x=left+(right-left)*(i+.5)/n; y=bottom-(bottom-top)*float(v or 0)/mx
                d.rounded_rectangle((x-bw/2,y,x+bw/2,bottom),radius=10,fill=("#B3261E" if kind=="deaths" else primary))
        for i,(lab,val) in enumerate(series):
            if len(series)>12 and i%max(1,len(series)//12): continue
            x=left+(right-left)*(i/(len(series)-1) if len(series)>1 else .5)
            d.text((x,bottom+8),str(lab)[:10],fill="#79747E",anchor="ma")
        im.save(path); return True
    except Exception as e:
        print(f"chart_to_png: {e}"); return False


def _render_analytics_pdf_native(self, snap, summary_rows, charts, period_label, out_path):
    try:
        from reportlab.lib import colors
        from reportlab.platypus import SimpleDocTemplate, Paragraph, Spacer, Table, TableStyle, Image as RLImage
        from reportlab.lib.styles import getSampleStyleSheet, ParagraphStyle
        from reportlab.lib.enums import TA_CENTER
        doc=SimpleDocTemplate(out_path,pagesize=A4,leftMargin=10*mm,rightMargin=10*mm,
                              topMargin=10*mm,bottomMargin=15*mm)
        styles=getSampleStyleSheet()
        navy=colors.HexColor(self._fac("navy","#123B72"))
        primary=colors.HexColor(self._fac("primary_color","#6750A4"))
        story=[]
        logo=self._fac("logo_path","")
        head=[[Paragraph(f"<b>{self._fac('facility_name')}</b><br/>{self._fac('address_line')}<br/>{self._fac('tagline')}",
                         styles["Normal"]),
               Paragraph(f"<b>Period:</b> {period_label}<br/><b>Generated:</b> {datetime.now():%Y-%m-%d %H:%M:%S}",
                         styles["Normal"])]]
        ht=Table(head,colWidths=[125*mm,55*mm]); ht.setStyle(TableStyle([
            ("BACKGROUND",(0,0),(-1,-1),navy),("TEXTCOLOR",(0,0),(-1,-1),colors.white),
            ("VALIGN",(0,0),(-1,-1),"MIDDLE"),("BOX",(0,0),(-1,-1),0.5,navy)]))
        story += [ht,Spacer(1,4*mm),
                  Table([[Paragraph("<b>ANALYTICS & PERFORMANCE REPORT</b>",ParagraphStyle("t",fontSize=14,textColor=colors.white,alignment=TA_CENTER))]],
                        colWidths=[180*mm],style=TableStyle([("BACKGROUND",(0,0),(-1,-1),navy),("BOX",(0,0),(-1,-1),0,navy)])),
                  Spacer(1,4*mm)]
        kpis=[("Registrations",snap["registrations"]),("Admissions",snap["admissions"]),
              ("Discharges",snap["discharges"]),("Deaths",snap["deaths"]),
              ("Billed",f"{self._currency()}{snap['billed_total']:,.0f}"),("Paid",f"{self._currency()}{snap['paid_total']:,.0f}"),
              ("Outstanding",f"{self._currency()}{snap['outstanding']:,.0f}"),
              ("Transfers",snap["transfers_in"]+snap["transfers_out"])]
        kd=[]
        for i in range(0,8,2):
            kd.append([Paragraph(f"<b>{kpis[i][0]}</b><br/><font size=16>{kpis[i][1]}</font>",styles["Normal"]),
                       Paragraph(f"<b>{kpis[i+1][0]}</b><br/><font size=16>{kpis[i+1][1]}</font>",styles["Normal"])])
        kt=Table(kd,colWidths=[90*mm,90*mm])
        kt.setStyle(TableStyle([("GRID",(0,0),(-1,-1),0.5,colors.HexColor("#79747E")),
                                ("BACKGROUND",(0,0),(-1,-1),colors.HexColor("#FFFBFE")),
                                ("ROWBACKGROUNDS",(0,0),(-1,-1),[colors.HexColor("#FFFBFE"),colors.HexColor("#F5F0FA")]),
                                ("VALIGN",(0,0),(-1,-1),"MIDDLE"),("LEFTPADDING",(0,0),(-1,-1),6),("TOPPADDING",(0,0),(-1,-1),7)]))
        story += [kt,Spacer(1,5*mm),Paragraph("<b>TREND ANALYSIS</b>",styles["Heading2"])]
        for pth in charts:
            if pth and os.path.exists(pth):
                try: story += [RLImage(pth,width=180*mm,height=75*mm),Spacer(1,3*mm)]
                except Exception: pass
        story += [Paragraph("<b>TOP DIAGNOSES</b>",styles["Heading2"])]
        story += [Table([["Diagnosis","Count"]]+[[str(a),b] for a,b in snap.get("top_diagnoses",[])],
                        colWidths=[145*mm,35*mm],repeatRows=1,
                        style=TableStyle([("BACKGROUND",(0,0),(-1,0),primary),("TEXTCOLOR",(0,0),(-1,0),colors.white),
                                          ("GRID",(0,0),(-1,-1),0.4,colors.HexColor("#79747E"))]))]
        story += [Spacer(1,3*mm),Paragraph("<b>DEPARTMENT LOAD</b>",styles["Heading2"])]
        dep_rows=[["Department","Admissions","Discharges","Transfers out"]]
        for dep,cnt in snap.get("top_departments",[]): dep_rows.append([str(dep),cnt,"",""])
        story += [Table(dep_rows,colWidths=[90*mm,30*mm,30*mm,30*mm],repeatRows=1,
                        style=TableStyle([("BACKGROUND",(0,0),(-1,0),primary),("TEXTCOLOR",(0,0),(-1,0),colors.white),
                                          ("GRID",(0,0),(-1,-1),0.4,colors.HexColor("#79747E"))]))]
        story += [Spacer(1,3*mm),Paragraph("<b>PAYMENT MIX</b>",styles["Heading2"])]
        pm=[["Method","Amount","%"]]; total=snap.get("paid_total",0) or 0
        for m,v in snap.get("payment_methods",{}).items(): pm.append([m,f"{self._currency()}{v:,.2f}",f"{100*v/total:.1f}%" if total else "0%"])
        story += [Table(pm,colWidths=[80*mm,55*mm,45*mm],repeatRows=1,
                        style=TableStyle([("BACKGROUND",(0,0),(-1,0),primary),("TEXTCOLOR",(0,0),(-1,0),colors.white),
                                          ("GRID",(0,0),(-1,-1),0.4,colors.HexColor("#79747E"))]))]
        story += [Spacer(1,4*mm),Paragraph("<b>BUCKET SUMMARY</b>",styles["Heading2"])]
        hdr=["Period","Reg","Adm","Disch","Deaths","Billed","Paid","Outstanding","Transfers"]
        data=[hdr]+[[r.get(k,"") for k in ["period","registrations","admissions","discharges","deaths","billed","paid","outstanding","transfers"]] for r in summary_rows]
        story += [Table(data,repeatRows=1,colWidths=[30*mm,16*mm,16*mm,18*mm,18*mm,22*mm,22*mm,24*mm,22*mm],
                        style=TableStyle([("BACKGROUND",(0,0),(-1,0),navy),("TEXTCOLOR",(0,0),(-1,0),colors.white),
                                          ("ROWBACKGROUNDS",(0,1),(-1,-1),[colors.white,colors.HexColor("#F5F0FA")]),
                                          ("GRID",(0,0),(-1,-1),0.3,colors.HexColor("#79747E")),
                                          ("FONTSIZE",(0,0),(-1,-1),7)]))]
        story += [Spacer(1,5*mm),Paragraph(f"<b>{self._fac('signatory_name')}</b><br/>{self._fac('signatory_quals')}<br/>{self._fac('signatory_role')}",styles["Normal"])]
        def footer(c, d):
            c.saveState(); c.setFillColor(navy); c.rect(0,0,A4[0],8*mm,fill=1,stroke=0)
            c.setFillColor(colors.white); c.setFont("Helvetica",7)
            c.drawString(10*mm,3*mm,f"{self._fac('facility_name')} • Analytics Report • {datetime.now():%Y-%m-%d}")
            c.drawRightString(A4[0]-10*mm,"SCAN TO VERIFY"); c.restoreState()
        doc.build(story,onFirstPage=footer,onLaterPages=footer)
        return True
    except Exception as e:
        print(f"Analytics PDF error: {e}")
        return False


def _export_analytics_pdf(self, instance=None):
    try:
        snap=getattr(self,"_analytics_snapshot",None) or AnalyticsEngine(self).snapshot(
            getattr(self,"_analytics_period","daily"),getattr(self,"_analytics_anchor",datetime.now()))
        start=datetime.fromisoformat(snap["start"]); end=datetime.fromisoformat(snap["end"])
        rows=AnalyticsEngine(self).summary_table(start.date(),end.date())
        rd=self._get_reports_dir(); charts=[]
        specs=[
            ("bar",AnalyticsEngine(self).range_series("registrations",start,end,"day"),"Volume trend"),
            ("line",AnalyticsEngine(self).range_series("payments",start,end,"day"),"Revenue trend"),
            ("deaths",AnalyticsEngine(self).range_series("deaths",start,end,"day"),"Deaths trend")]
        for i,(kind,series,title) in enumerate(specs):
            path=os.path.join(rd,f".analytics_chart_{i}_{secrets.token_hex(4)}.png")
            try:
                if self._chart_to_png(kind,series,title,path): charts.append(path)
            except Exception as e: print(f"analytics chart skipped: {e}")
        out=os.path.join(rd,f"{self._fac('report_prefix','HMG')}_analytics_{snap['period']}_{snap['label'].replace('/','-')}.pdf")
        ok=self._render_analytics_pdf_native(snap,rows,charts,snap["label"],out)
        for c in charts:
            try: os.remove(c)
            except Exception: pass
        if ok:
            self.audit_log("EXPORT_ANALYTICS_PDF",os.path.basename(out))
            self._open_file_with_fallback(out)
            self._analytics_last_pdf=out
            self._popup("Analytics PDF",f"Saved:\n{out}")
            return out
    except Exception as e:
        self._popup("Analytics PDF Error",str(e))
    return None


def _share_analytics_pdf(self, instance=None):
    try:
        path=getattr(self,"_analytics_last_pdf",None)
        if not path or not os.path.exists(path):
            path=self._export_analytics_pdf()
        if path: self._share_file(path)
    except Exception as e:
        self._popup("Share Error",str(e))


def _analytics_dashboard_block(self):
    box=BoxLayout(orientation="vertical",size_hint_y=None,spacing=dp(5))
    box.add_widget(Label(text="TODAY AT A GLANCE",font_size=15,bold=True,
                         color=get_color_from_hex("#6750A4"),size_hint_y=None,height=dp(26)))
    grid=GridLayout(cols=4,size_hint_y=None,height=dp(78),spacing=dp(5))
    def mini(caption,attr):
        b=BoxLayout(orientation="vertical",padding=dp(5),size_hint_y=None,height=dp(72))
        with b.canvas.before:
            Color(*get_color_from_hex("#FFFBFE")); b.rr=RoundedRectangle(pos=b.pos,size=b.size,radius=[dp(16)])
            Color(*get_color_from_hex("#79747E")); b.ol=Line(rounded_rectangle=(b.x,b.y,b.width,b.height,dp(16)),width=dp(1))
        b.bind(pos=lambda w,*a: (setattr(w.rr,"pos",w.pos),
                                  setattr(w.rr,"size",w.size),
                                  setattr(w.ol,"rounded_rectangle",
                                          (w.x,w.y,w.width,w.height,dp(16)))))
        b.bind(size=lambda w,*a: (setattr(w.rr,"pos",w.pos),
                                  setattr(w.rr,"size",w.size),
                                  setattr(w.ol,"rounded_rectangle",
                                          (w.x,w.y,w.width,w.height,dp(16)))))
        val=Label(text="0",font_size=18,bold=True,color=get_color_from_hex("#1D1B20"))
        setattr(self,attr,val); b.add_widget(val); b.add_widget(Label(text=caption,font_size=9,color=get_color_from_hex("#79747E")))
        return b
    grid.add_widget(mini("Today's registrations","dash_an_reg"))
    grid.add_widget(mini("Today's admissions","dash_an_adm"))
    grid.add_widget(mini("Today's revenue (paid)","dash_an_rev"))
    grid.add_widget(mini("Pending tasks","dash_an_tasks"))
    box.add_widget(grid)
    self.dash_an_chart=M3BarChart(title="Last 7 days — revenue",height=dp(140))
    box.add_widget(self.dash_an_chart)
    box.add_widget(HMGButton(text="OPEN FULL ANALYTICS →",
                             on_press=lambda *_:self._switch("Analytics"),
                             size_hint_y=None,height=dp(42)))
    return box


def _dashboard_with_analytics(self):
    try:
        _orig_dashboard(self)
        # Locate the existing Dashboard vertical layout and insert before ACTIVITY.
        tab=next((x for x in self.tp.tab_list if getattr(x,"text","")=="Dashboard"),None)
        if not tab: return
        sc=tab.content
        root=sc.children[0] if getattr(sc,"children",[]) else None
        if root is None: return
        block=self._analytics_dashboard_block()
        idx=len(root.children)
        for i,w in enumerate(root.children):
            if isinstance(w,Label) and str(w.text).strip()=="ACTIVITY":
                idx=i
                break
        root.add_widget(block,index=idx)
        self._refresh_dash_analytics()
    except Exception as e:
        print(f"Dashboard analytics build: {e}")


def _refresh_dash_analytics(self,*args,**kwargs):
    try:
        if hasattr(self,'dash_an_reg'):
            total_records = sum(len(getattr(self,n,[]) or []) for n in (
                "patients","admissions","transfers","bills","prescriptions",
                "lab_tests","radiology","ecg_reports","emr_records","tasks"))
            if total_records > 500 and not getattr(self,"_dash_an_busy",False):
                self._dash_an_busy=True
                def worker():
                    try:
                        snap=AnalyticsEngine(self).snapshot("daily")
                        end=datetime.now(); start=end-timedelta(days=6)
                        series=AnalyticsEngine(self).range_series("payments",start,end,"day")
                        Clock.schedule_once(lambda dt:self._apply_dash_an_result(snap,series),0)
                    except Exception as e:
                        print(f"Dashboard analytics worker: {e}")
                        Clock.schedule_once(lambda dt:setattr(self,"_dash_an_busy",False),0)
                threading.Thread(target=worker,daemon=True).start()
                return
            snap=AnalyticsEngine(self).snapshot('daily')
            self._apply_dash_an_result(snap, AnalyticsEngine(self).range_series(
                'payments',datetime.now()-timedelta(days=6),datetime.now(),'day'))
    except Exception as e:
        print(f"Dashboard analytics refresh: {e}")


def _apply_dash_an_result(self,snap,series):
    try:
        self._dash_an_busy=False
        if hasattr(self,'dash_an_reg'):
            self.dash_an_reg.text=str(snap['registrations'])
            self.dash_an_adm.text=str(snap['admissions'])
            self.dash_an_rev.text=f"{self._currency()}{snap['paid_total']:,.0f}"
            try:
                self.dash_an_tasks.text=str(len(self.task_manager.get_pending_tasks()))
            except Exception:
                self.dash_an_tasks.text=str(len([t for t in getattr(self,'tasks',[]) if t.get('status') in ('Pending','In Progress','Waiting','On Hold')]))
            self.dash_an_chart.set_data(series)
    except Exception as e:
        print(f"Dashboard analytics refresh: {e}")


def _facility_refresh(self):
    try:
        self.title=f"{self._fac('short_name','HMG')} EMR v13.4.1"
        primary=self._fac("primary_color","#6750A4")
        pc=self._fac("primary_container","#EADDFF")
        op=self._fac("on_primary","#FFFFFF")
        opc=self._fac("on_primary_container","#21005D")
        HMGButton.M3_PRIMARY=get_color_from_hex(primary)
        HMGButton.M3_PRIMARY_CONTAINER=get_color_from_hex(pc)
        HMGButton.M3_ON_PRIMARY=get_color_from_hex(op)
        HMGButton.M3_ON_PRIMARY_CONTAINER=get_color_from_hex(opc)
        def walk(w):
            if isinstance(w,Label):
                if str(w.text) in ("HMG HOSPITAL LTD","HMG Hospital Ltd","HMG EMR",
                                   "HMG Hospital Ltd | Medical Records & Diagnostic Services",
                                   "HMG HOSPITAL EMR"):
                    if "EMR" in str(w.text): w.text=f"{self._fac('short_name','HMG')} EMR"
                    else: w.text=self._fac("facility_name","HMG HOSPITAL LTD")
            for ch in getattr(w,"children",[]): walk(ch)
        if getattr(self,"root_container",None): walk(self.root_container)
    except Exception as e: print(f"Facility branding refresh: {e}")


def _facility_apply_theme(self):
    try:
        HMGButton.M3_PRIMARY=get_color_from_hex(self._fac("primary_color","#6750A4"))
        HMGButton.M3_PRIMARY_CONTAINER=get_color_from_hex(self._fac("primary_container","#EADDFF"))
        HMGButton.M3_ON_PRIMARY=get_color_from_hex(self._fac("on_primary","#FFFFFF"))
        HMGButton.M3_ON_PRIMARY_CONTAINER=get_color_from_hex(self._fac("on_primary_container","#21005D"))
    except Exception: pass
    _orig_apply_m3(self)
    self._refresh_facility_branding()


def _facility_settings(self):
    _orig_settings(self)
    try:
        tab=next((x for x in self.tp.tab_list if getattr(x,"text","")=="Settings"),None)
        if not tab: return
        root=tab.content.children[0] if getattr(tab.content,"children",[]) else None
        if root is None or getattr(self,"_facility_settings_added",False): return
        sec=CollapsibleSection("FACILITY & BRANDING",start_open=True)
        fields=[
            ("facility_name","Facility name"),("short_name","Short name"),("address_line","Address"),
            ("tagline","Tagline"),("footer_strip","Footer strip"),("currency","Currency"),
            ("signatory_name","Signatory name"),("signatory_quals","Signatory qualifications"),
            ("signatory_role","Signatory role"),("report_prefix","Report prefix"),
            ("default_departments","Default departments (comma-separated)")]
        self.facility_inputs={}
        for key,cap in fields:
            sec.body.add_widget(Label(text=cap,font_size=11,bold=True,size_hint_y=None,height=dp(20)))
            inp=TextInput(text=str(self._fac(key,"")),multiline=False,size_hint_y=None,height=dp(38))
            self.facility_inputs[key]=inp; sec.body.add_widget(inp)
        for key,cap in [("primary_color","Primary color"),("navy","Navy color")]:
            sec.body.add_widget(Label(text=cap,font_size=11,bold=True,size_hint_y=None,height=dp(20)))
            inp=TextInput(text=str(self._fac(key,"")),multiline=False,size_hint_y=None,height=dp(38))
            self.facility_inputs[key]=inp; sec.body.add_widget(inp)
        sec.body.add_widget(Label(text="Logo / Signature",font_size=11,bold=True,size_hint_y=None,height=dp(22)))
        imgrow=BoxLayout(size_hint_y=None,height=dp(42),spacing=dp(5))
        imgrow.add_widget(HMGButton(text="ATTACH LOGO",on_press=lambda *_:self._facility_pick_image("logo")))
        imgrow.add_widget(HMGButton(text="ATTACH SIGNATURE",on_press=lambda *_:self._facility_pick_image("signature")))
        sec.body.add_widget(imgrow)
        br=BoxLayout(size_hint_y=None,height=dp(44),spacing=dp(5))
        br.add_widget(HMGButton(text="SAVE FACILITY",on_press=self._save_facility_settings))
        br.add_widget(HMGButton(text="RESET TO DEFAULTS",on_press=self._reset_facility_settings))
        br.add_widget(HMGButton(text="PREVIEW REPORT HEADER",on_press=self._preview_facility_header))
        sec.body.add_widget(br)
        # Insert immediately above AI SETTINGS.
        root.add_widget(sec,index=max(0,len(root.children)-1))
        self._facility_settings_added=True
    except Exception as e: print(f"Facility settings build: {e}")


def _facility_pick_image(self,target):
    content=BoxLayout(orientation="vertical",spacing=dp(5),padding=dp(5))
    fc=FileChooserListView(path=self._get_reports_dir(),filters=["*.png","*.jpg","*.jpeg"])
    content.add_widget(fc)
    pp=Popup(title=f"Choose {'Logo' if target=='logo' else 'Signature'}",content=content,size_hint=(.9,.85))
    row=BoxLayout(size_hint_y=None,height=dp(42),spacing=dp(5))
    def choose(*_):
        if fc.selection:
            self.facility.set("logo_path" if target=="logo" else "signature_path",fc.selection[0])
            self._refresh_facility_branding(); pp.dismiss()
    row.add_widget(HMGButton(text="SELECT",on_press=choose))
    row.add_widget(HMGButton(text="CANCEL",on_press=pp.dismiss))
    content.add_widget(row);pp.open()


def _save_facility_settings(self,instance=None):
    try:
        for k,w in getattr(self,"facility_inputs",{}).items():
            if k == "default_departments":
                self.facility.set(k, [x.strip() for x in w.text.split(",") if x.strip()])
            else:
                self.facility.set(k,w.text.strip())
        self.facility.FILE=os.path.join(self._get_reports_dir(),FacilityConfig.FILE)
        self.facility.save(); self._apply_m3_theme(); self._refresh_facility_branding()
        self.audit_log("SAVE_FACILITY_CONFIG",self._fac("facility_name"))
        self._popup("Facility","Facility branding saved.")
    except Exception as e: self._popup("Facility Save Error",str(e))


def _reset_facility_settings(self,instance=None):
    try:
        self.facility.reset(); self.facility.FILE=os.path.join(self._get_reports_dir(),FacilityConfig.FILE)
        self.facility.load()
        for k,w in getattr(self,"facility_inputs",{}).items():
            v=self._fac(k,"")
            w.text=", ".join(v) if k == "default_departments" and isinstance(v,list) else str(v)
        self._apply_m3_theme(); self._refresh_facility_branding()
    except Exception as e: self._popup("Facility Reset Error",str(e))


def _preview_facility_header(self,instance=None):
    try:
        out=os.path.join(self._get_reports_dir(),"facility_preview.pdf")
        c=pdf_canvas.Canvas(out,pagesize=A4); W,H=A4
        navy=self._fac("navy","#123B72"); primary=self._fac("primary_color","#6750A4")
        c.setFillColor(get_color_from_hex(navy)); c.rect(0,H-55*mm,W,55*mm,fill=1,stroke=0)
        c.setFillColorRGB(1,1,1); c.setFont("Helvetica-Bold",18); c.drawString(15*mm,H-18*mm,self._fac("facility_name"))
        c.setFont("Helvetica",9); c.drawString(15*mm,H-26*mm,self._fac("address_line"))
        c.drawString(15*mm,H-32*mm,self._fac("tagline"))
        c.setFillColor(get_color_from_hex(primary)); c.rect(0,12*mm,W,12*mm,fill=1,stroke=0)
        c.setFillColorRGB(1,1,1); c.setFont("Helvetica",8); c.drawString(10*mm,16*mm,self._fac("footer_strip"))
        c.save(); self._open_file_with_fallback(out)
    except Exception as e: self._popup("Preview Error",str(e))


# Bind extension methods before application startup.
try:
    _orig_dashboard = HMGBillingApp._dashboard
    _orig_settings = HMGBillingApp._settings
    _orig_apply_m3 = HMGBillingApp._apply_m3_theme
    HMGBillingApp._dashboard = _dashboard_with_analytics
    HMGBillingApp._settings = _facility_settings
    HMGBillingApp._apply_m3_theme = _facility_apply_theme
    for _n in [
        "_fac","_currency","_analytics_tab","_analytics_render","_analytics_apply_result",
        "_analytics_dashboard_block","_analytics_set_period",
        "_analytics_anchor_shift","_export_analytics_pdf","_export_analytics_csv",
        "_share_analytics_pdf","_render_analytics_pdf_native","_chart_to_png",
        "_refresh_dash_analytics","_refresh_facility_branding","_save_facility_settings",
        "_reset_facility_settings","_preview_facility_header","_facility_pick_image"]:
        _fn=globals().get(_n)
        if callable(_fn): setattr(HMGBillingApp,_n,_fn)
    # Preserve original refresh logic and add analytics after it.
    _orig_refresh_dash=getattr(HMGBillingApp,"_refresh_dash",None)
    if callable(_orig_refresh_dash):
        def _refresh_dash_ext(self,*args,**kwargs):
            try: _orig_refresh_dash(self,*args,**kwargs)
            except Exception as e: print(f"[HMG] base dashboard refresh: {e}")
            self._refresh_dash_analytics(*args,**kwargs)
        HMGBillingApp._refresh_dash=_refresh_dash_ext
        globals()["_refresh_dash"]=_refresh_dash_ext
except Exception as _hmg_ext_bind_error:
    print(f"[HMG extension] binding error: {_hmg_ext_bind_error}")



