class M3Tokens:
    LIGHT = {
        "primary": "#6750A4", "on_primary": "#FFFFFF",
        "primary_container": "#EADDFF", "on_primary_container": "#21005D",
        "secondary": "#625B71", "on_secondary": "#FFFFFF",
        "secondary_container": "#E8DEF8", "on_secondary_container": "#1D192B",
        "tertiary": "#7D5260", "error": "#B3261E", "on_error": "#FFFFFF",
        "error_container": "#F9DEDC", "on_error_container": "#410E0B",
        "surface": "#FFFBFE", "surface_dim": "#DED8E1",
        "surface_container_lowest": "#FFFFFF", "surface_container_low": "#F7F2FA",
        "surface_container": "#F3EDF7", "surface_container_high": "#ECE6F0",
        "surface_container_highest": "#E6E0E9", "on_surface": "#1D1B20",
        "on_surface_variant": "#49454F", "outline": "#79747E",
        "outline_variant": "#CAC4D0", "scrim": "#000000",
        # Harmonised analytics chart colours.
        "chart_green": "#386A20", "chart_gold": "#7A5900", "chart_teal": "#00696D",
        "chart_rose": "#7D5260", "chart_purple": "#565992", "chart_magenta": "#8E4585",
        "chart_rose2": "#8C4A60",
    }
    DARK = {
        "primary": "#D0BCFF", "on_primary": "#381E72",
        "primary_container": "#4F378B", "on_primary_container": "#EADDFF",
        "secondary": "#CCC2DC", "on_secondary": "#332D41",
        "secondary_container": "#4A4458", "on_secondary_container": "#E8DEF8",
        "tertiary": "#EFB8C8", "error": "#F2B8B5", "on_error": "#601410",
        "error_container": "#8C1D18", "on_error_container": "#F9DEDC",
        "surface": "#1C1B1F", "surface_dim": "#141218",
        "surface_container_lowest": "#0F0D13", "surface_container_low": "#211F26",
        "surface_container": "#2B2930", "surface_container_high": "#36343B",
        "surface_container_highest": "#47464F", "on_surface": "#E6E1E5",
        "on_surface_variant": "#CAC4D0", "outline": "#938F99",
        "outline_variant": "#49454F", "scrim": "#000000",
        "chart_green": "#8FD17F", "chart_gold": "#E7C66A", "chart_teal": "#7DD6D8",
        "chart_rose": "#EFB8C8", "chart_purple": "#BFC1FF", "chart_magenta": "#E6B8E1",
        "chart_rose2": "#F0A9BE",
    }

    @classmethod
    def get(cls, role, theme="light"):
        table = cls.DARK if str(theme).lower() == "dark" else cls.LIGHT
        return table.get(role, table["on_surface"])


def _m3_theme(self):
    try:
        return "dark" if str(self.facility.get("theme", "light")).lower() == "dark" else "light"
    except Exception:
        return "light"


def _m3(role, theme="light"):
    return get_color_from_hex(M3Tokens.get(role, theme))


# Glimpse-style expressive glyphs: Unicode glyphs keep the UI dependency-free and Android-safe.
M3_GLYPHS = {
    # Expressive period glyphs: these are intentionally reserved for the period selector.
    "daily": "◉",
    "weekly": "▦",
    "monthly": "▤",
    "yearly": "▥",
    "back": "◀",
    "forward": "▶",
    "analytics": "▥",
    "report": "▤",
}

def _analytics_surface(self, widget, role="surface_container_low", radius=16):
    theme = _m3_theme(self)
    try:
        widget.canvas.before.clear()
        with widget.canvas.before:
            Color(*_m3(role, theme))
            widget._m3_bg = RoundedRectangle(pos=widget.pos, size=widget.size, radius=[dp(radius)])
            Color(*_m3("outline_variant", theme))
            widget._m3_border = Line(rounded_rectangle=(widget.x, widget.y, widget.width, widget.height, dp(radius)), width=dp(1))
        widget.bind(pos=lambda w,*a:(setattr(w._m3_bg,"pos",w.pos), setattr(w._m3_border,"rounded_rectangle",(w.x,w.y,w.width,w.height,dp(radius)))))
        widget.bind(size=lambda w,*a:(setattr(w._m3_bg,"size",w.size), setattr(w._m3_border,"rounded_rectangle",(w.x,w.y,w.width,w.height,dp(radius)))))
    except Exception:
        pass

def _fmt_count(n):
    try:
        if n is None or n == "":
            return "0"
        return f"{int(round(float(str(n).replace(',', '').strip()))):,}"
    except Exception:
        return "0"


def _fmt_pct(x):
    try:
        return f"{float(x or 0) * 100:.1f}%"
    except Exception:
        return "0.0%"


def _fmt_money(amount, currency="₦", compact=False):
    try:
        v = float(str(amount).replace(",", "").replace("₦", "").strip())
    except Exception:
        v = 0.0
    if not math.isfinite(v):
        v = 0.0
    sign = "−" if v < 0 else ""
    a = abs(v)
    cur = str(currency or "₦")
    if compact and a >= 1_000_000:
        value = a / 1_000_000.0
        text = f"{value:.2f}".rstrip("0").rstrip(".") + "M"
        return f"{sign}{cur}{text}"
    if compact and a >= 1_000:
        value = a / 1_000.0
        text = f"{value:.1f}".rstrip("0").rstrip(".") + "k"
        return f"{sign}{cur}{text}"
    return f"{sign}{cur}{a:,.0f}"


def _hmg_fmt_count(self, n):
    return _fmt_count(n)


def _hmg_fmt_pct(self, x):
    return _fmt_pct(x)


def _hmg_fmt_money(self, amount, compact=False):
    return _fmt_money(amount, self._currency() if hasattr(self, "_currency") else "₦", compact)


@classmethod
def _hmg_button_refresh_theme(cls, tokens=None):
    tokens = tokens or M3Tokens
    theme = "light"
    try:
        if hasattr(App.get_running_app(), "facility"):
            theme = "dark" if str(App.get_running_app().facility.get("theme", "light")).lower() == "dark" else "light"
    except Exception:
        pass
    cls.M3_PRIMARY = get_color_from_hex(tokens.get("primary", theme))
    cls.M3_ON_PRIMARY = get_color_from_hex(tokens.get("on_primary", theme))
    cls.M3_PRIMARY_CONTAINER = get_color_from_hex(tokens.get("primary_container", theme))
    cls.M3_ON_PRIMARY_CONTAINER = get_color_from_hex(tokens.get("on_primary_container", theme))
    cls.M3_DISABLED = get_color_from_hex(tokens.get("surface_container_high", theme))
    cls.M3_ON_DISABLED = get_color_from_hex(tokens.get("on_surface_variant", theme))


# ---------------------------------------------------------------------------
# Replacement M3 chart widgets
# ---------------------------------------------------------------------------
class M3BarChart(BoxLayout):
    SERIES_PALETTE = ["chart_purple", "chart_green", "chart_gold", "chart_teal", "chart_rose"]

    def __init__(self, title="", height=dp(240), **kwargs):
        kwargs.setdefault("orientation", "vertical")
        kwargs.setdefault("size_hint_y", None)
        kwargs.setdefault("height", max(dp(180), height))
        super().__init__(**kwargs)
        self.title = title
        self.series = []
        self.value_fmt = "count"
        self.bar_color = None
        self.on_bar_tap = None
        self._labels = []
        self._theme = "light"
        self.padding = (dp(12), dp(8), dp(12), dp(10))
        self.bind(pos=self._redraw, size=self._redraw)
        Clock.schedule_once(lambda dt: self._redraw(), 0)

    def _theme_now(self):
        try:
            app = App.get_running_app()
            return "dark" if str(app.facility.get("theme", "light")).lower() == "dark" else "light"
        except Exception:
            return "light"

    def _is_money(self):
        return self.value_fmt in ("money", "currency", "payments", "billing")

    def _format(self, value, compact=False):
        if self._is_money():
            try:
                app = App.get_running_app()
                return _fmt_money(value, app._currency(), compact)
            except Exception:
                return _fmt_money(value, "₦", compact)
        return _fmt_count(value)

    def set_data(self, series, value_fmt="count", bar_color=None, on_bar_tap=None):
        try:
            self.series = [(str(a), float(b or 0)) for a, b in (series or [])]
            self.value_fmt = value_fmt
            if value_fmt == "count" and any(k in str(self.title).lower() for k in ("revenue", "payment", "billing")):
                self.value_fmt = "money"
            self.bar_color = bar_color
            if on_bar_tap is not None:
                self.on_bar_tap = on_bar_tap
            Clock.schedule_once(lambda dt: self._redraw(), 0)
        except Exception as e:
            print(f"M3BarChart set_data: {e}")

    def _clear_labels(self):
        for child in list(self.children):
            self.remove_widget(child)

    def _draw_surface(self):
        theme = self._theme_now()
        self.canvas.before.clear()
        with self.canvas.before:
            Color(*_m3("surface_container_low", theme))
            RoundedRectangle(pos=self.pos, size=self.size, radius=[dp(16)])
            Color(*_m3("outline_variant", theme))
            Line(rounded_rectangle=(self.x, self.y, self.width, self.height, dp(16)), width=dp(1))

    def _axis_labels(self, left, right, bottom, top, maxv):
        theme = self._theme_now()
        for i in range(5):
            v = maxv * i / 4.0
            y = bottom + (top - bottom) * i / 4.0
            text = self._format(v, compact=self._is_money())
            self.add_widget(Label(text=text, font_size=11, color=_m3("on_surface_variant", theme),
                                  size_hint=(None, None), size=(dp(70), dp(20)),
                                  pos=(self.x + dp(2), y - dp(10)), halign="right", valign="middle"))

    def _redraw(self, *args):
        try:
            self._theme = self._theme_now()
            self._clear_labels()
            self._draw_surface()
            self.canvas.after.clear()
            theme = self._theme
            self.add_widget(Label(text="▥  "+self.title, font_size=16, bold=True,
                                  color=_m3("on_surface", theme), size_hint=(1, None), height=dp(26),
                                  halign="left", valign="middle"))
            n = len(self.series)
            left, right = self.x + dp(78), self.right - dp(12)
            bottom, top = self.y + dp(42), self.top - dp(42)
            if right <= left or top <= bottom:
                return
            maxv = max([v for _, v in self.series] + [1.0])
            if maxv <= 0:
                maxv = 1.0
            # Grid-only plot: no boxed axis spines.
            with self.canvas.after:
                for i in range(5):
                    gy = bottom + (top - bottom) * i / 4.0
                    Color(*_m3("outline_variant", theme)[:3], 0.40)
                    Line(points=[left, gy, right, gy], width=dp(1))
            self._axis_labels(left, right, bottom, top, maxv)
            if not n or all(v <= 0 for _, v in self.series):
                self.add_widget(Label(text="No data for this period", font_size=14,
                                      color=_m3("on_surface_variant", theme), size_hint=(1, None),
                                      height=dp(28), pos=(self.x, self.y + self.height * .45)))
                return
            gap = max(dp(4), min(dp(10), (right-left) / max(n*10, 1)))
            bw = max(dp(8), (right-left-gap*(n+1)) / max(n, 1))
            hi = max(range(n), key=lambda i: self.series[i][1])
            palette = self.bar_color if isinstance(self.bar_color, (list, tuple)) else None
            for i, (lab, val) in enumerate(self.series):
                bx = left + gap + i * (bw + gap)
                bh = (top-bottom) * max(0, val) / maxv
                by = bottom
                role = palette[i % len(palette)] if palette else self.SERIES_PALETTE[i % len(self.SERIES_PALETTE)]
                if isinstance(role, str) and role.startswith("#"):
                    # Only for legacy caller data; analytics itself uses token roles.
                    fill = get_color_from_hex(role)
                else:
                    fill = _m3(role, theme)
                if i == hi:
                    fill = _m3("primary_container", theme)
                    text_color = _m3("primary", theme)
                else:
                    text_color = _m3("on_primary", theme)
                with self.canvas.after:
                    Color(*fill)
                    RoundedRectangle(pos=(bx, by), size=(bw, max(dp(1), bh)),
                                     radius=[dp(8), dp(8), dp(2), dp(2)])
                    Color(*_m3("outline", theme))
                    Line(rounded_rectangle=(bx, by, bw, max(dp(1), bh), dp(8)), width=dp(1))
                if bh >= dp(20):
                    label_y = by + bh + dp(1)
                    self.add_widget(Label(text=self._format(val, compact=self._is_money()), font_size=11,
                                          color=_m3("on_surface", theme), size_hint=(None, None),
                                          size=(max(dp(44), bw+dp(12)), dp(18)),
                                          pos=(bx - dp(6), label_y), halign="center"))
                    if bh > dp(48):
                        self.add_widget(Label(text=self._format(val, compact=self._is_money()), font_size=11,
                                              color=text_color, size_hint=(None, None),
                                              size=(max(dp(44), bw+dp(12)), dp(18)),
                                              pos=(bx-dp(6), by+bh/2-dp(9)), halign="center"))
                shown = str(lab)
                if len(self.series) > 12:
                    step = max(1, math.ceil(len(self.series)/6))
                    if i % step:
                        shown = ""
                elif len(self.series) > 6:
                    shown = shown[:10] + ("…" if len(shown) > 10 else "")
                else:
                    shown = shown[:14] + ("…" if len(shown) > 14 else "")
                if shown:
                    self.add_widget(Label(text=shown, font_size=11, color=_m3("on_surface_variant", theme),
                                          size_hint=(None, None), size=(max(dp(44), bw+dp(8)), dp(22)),
                                          pos=(bx-dp(4), self.y+dp(10)), halign="center"))
            # Multi-series legend is explicit and never relies on colour alone.
            if palette and len(palette) > 1:
                legend = BoxLayout(size_hint=(1, None), height=dp(28), spacing=dp(10))
                for i, role in enumerate(palette[:5]):
                    sw = Label(text="■", font_size=12, color=(_m3(role, theme) if not str(role).startswith("#") else get_color_from_hex(role)),
                               size_hint=(None, None), size=(dp(16), dp(20)))
                    legend.add_widget(sw)
                    legend.add_widget(Label(text=["Registrations","Admissions","Discharges","Transfers","Other"][i],
                                             font_size=11, color=_m3("on_surface_variant", theme),
                                             size_hint_x=None, width=dp(82)))
                self.add_widget(legend)
        except Exception as e:
            print(f"M3BarChart redraw: {e}")

    def on_touch_down(self, touch):
        if not self.collide_point(*touch.pos) or not self.series:
            return super().on_touch_down(touch)
        try:
            if callable(self.on_bar_tap):
                self.on_bar_tap(0, self.series[0][0], self.series[0][1])
                return True
        except Exception:
            pass
        return super().on_touch_down(touch)


class M3LineChart(M3BarChart):
    def set_data(self, series, value_fmt="count", bar_color=None, on_bar_tap=None):
        try:
            self.series = [(str(a), float(b or 0)) for a, b in (series or [])]
            self.value_fmt = value_fmt
            self.bar_color = bar_color
            if on_bar_tap is not None:
                self.on_bar_tap = on_bar_tap
            Clock.schedule_once(lambda dt: self._redraw_line(), 0)
        except Exception as e:
            print(f"M3LineChart set_data: {e}")

    def _redraw(self, *args):
        self._redraw_line()

    def _redraw_line(self):
        try:
            self._theme = self._theme_now()
            self._clear_labels()
            self._draw_surface()
            self.canvas.after.clear()
            theme = self._theme
            self.add_widget(Label(text=self.title, font_size=16, bold=True, color=_m3("on_surface", theme),
                                  size_hint=(1,None), height=dp(26), halign="left"))
            n=len(self.series)
            left,right=self.x+dp(78),self.right-dp(12)
            bottom,top=self.y+dp(42),self.top-dp(42)
            maxv=max([v for _,v in self.series]+[1.0])
            if maxv<=0: maxv=1.0
            with self.canvas.after:
                for i in range(5):
                    gy=bottom+(top-bottom)*i/4
                    Color(*_m3("outline_variant",theme)[:3],0.40)
                    Line(points=[left,gy,right,gy],width=dp(1))
            self._axis_labels(left,right,bottom,top,maxv)
            if not n or all(v<=0 for _,v in self.series):
                self.add_widget(Label(text="No data for this period",font_size=14,color=_m3("on_surface_variant",theme),
                                      size_hint=(1,None),height=dp(28),pos=(self.x,self.y+self.height*.45)))
                return
            pts=[]
            for i,(_,v) in enumerate(self.series):
                x=left+(right-left)*(i/(n-1) if n>1 else .5)
                y=bottom+(top-bottom)*max(0,v)/maxv
                pts.extend([x,y])
            with self.canvas.after:
                # Primary area fill at 15% alpha, implemented with a triangle strip.
                if n > 1:
                    verts=[]
                    for i in range(n): verts += [pts[2*i], bottom, pts[2*i], pts[2*i+1]]
                    indices=[]
                    for i in range(n-1): indices += [2*i,2*i+1,2*i+2,2*i+1,2*i+3,2*i+2]
                    Color(*_m3("primary",theme)[:3],0.15)
                    Mesh(vertices=verts,indices=indices,mode="triangles")
                Color(*_m3("primary",theme))
                Line(points=pts,width=dp(2.5),joint="round")
                for i in range(n):
                    x,y=pts[2*i],pts[2*i+1]
                    Color(*_m3("primary",theme)); Ellipse(pos=(x-dp(4),y-dp(4)),size=(dp(8),dp(8)))
                    Color(*_m3("surface_container_low",theme)); Ellipse(pos=(x-dp(2.5),y-dp(2.5)),size=(dp(5),dp(5)))
            for i,(lab,val) in enumerate(self.series):
                shown=str(lab)
                if n>12 and i%max(1,math.ceil(n/6)): continue
                if n>6: shown=shown[:10]+("…" if len(shown)>10 else "")
                x=left+(right-left)*(i/(n-1) if n>1 else .5)
                self.add_widget(Label(text=shown,font_size=11,color=_m3("on_surface_variant",theme),
                                      size_hint=(None,None),size=(dp(62),dp(20)),pos=(x-dp(31),self.y+dp(10)),halign="center"))
        except Exception as e:
            print(f"M3LineChart redraw: {e}")


class M3DonutChart(M3BarChart):
    PALETTE = ["chart_purple","chart_rose","chart_green","chart_gold","chart_teal","chart_rose2","chart_purple","chart_magenta"]

    def set_data(self, series, center_label=""):
        try:
            self.series=[(str(a),float(b or 0)) for a,b in (series or [])]
            self.value_fmt="money"
            self.center_label=center_label
            Clock.schedule_once(lambda dt:self._redraw_donut(),0)
        except Exception as e:
            print(f"M3DonutChart set_data: {e}")

    def _redraw(self,*args): self._redraw_donut()

    def _redraw_donut(self):
        try:
            self._theme=self._theme_now(); self._clear_labels(); self.canvas.before.clear(); self.canvas.after.clear()
            theme=self._theme
            with self.canvas.before:
                Color(*_m3("surface_container_low",theme)); RoundedRectangle(pos=self.pos,size=self.size,radius=[dp(16)])
                Color(*_m3("outline_variant",theme)); Line(rounded_rectangle=(self.x,self.y,self.width,self.height,dp(16)),width=dp(1))
            self.add_widget(Label(text="▥  "+self.title,font_size=16,bold=True,color=_m3("on_surface",theme),size_hint=(1,None),height=dp(26)))
            total=sum(v for _,v in self.series)
            if total<=0:
                self.add_widget(Label(text="No data for this period",font_size=14,color=_m3("on_surface_variant",theme),size_hint=(1,None),height=dp(28)))
                return
            small=[]; main=[]
            for item in self.series:
                (small if item[1]/total < .03 else main).append(item)
            if small: main.append(("Other",sum(v for _,v in small)))
            cx=self.x+self.width*.30; cy=self.y+self.height*.48; r=min(dp(76),self.height*.30)
            angle=0
            with self.canvas.after:
                for i,(name,val) in enumerate(main):
                    sweep=360*val/total
                    Color(*_m3(self.PALETTE[i%len(self.PALETTE)],theme))
                    Ellipse(pos=(cx-r,cy-r),size=(2*r,2*r),angle_start=angle,angle_end=angle+sweep)
                    angle+=sweep
                # surface cut-out + separation stroke.
                Color(*_m3("surface_container_low",theme)); Ellipse(pos=(cx-r*.52,cy-r*.52),size=(1.04*r,1.04*r))
                Color(*_m3("surface_container_lowest",theme)); Line(circle=(cx,cy,r),width=dp(1))
            self.add_widget(Label(text=str(self.center_label or _fmt_money(total,"₦")),font_size=28,bold=False,color=_m3("on_surface",theme),
                                  size_hint=(None,None),size=(dp(150),dp(34)),pos=(cx-dp(75),cy-dp(8)),halign="center"))
            self.add_widget(Label(text=str(self.title or "PAYMENTS").upper(),font_size=12,bold=True,color=_m3("on_surface_variant",theme),
                                  size_hint=(None,None),size=(dp(150),dp(22)),pos=(cx-dp(75),cy-dp(34)),halign="center"))
            legend=BoxLayout(orientation="vertical",size_hint=(.55,1),spacing=dp(3),padding=(dp(4),dp(4)))
            for i,(name,val) in enumerate(main):
                row=BoxLayout(size_hint_y=None,height=dp(26),spacing=dp(5))
                row.add_widget(Label(text="■",font_size=13,color=_m3(self.PALETTE[i%len(self.PALETTE)],theme),size_hint=(None,None),size=(dp(16),dp(20))))
                nm=str(name); nm=nm[:18]+("…" if len(nm)>18 else "")
                row.add_widget(Label(text=nm,font_size=12,color=_m3("on_surface",theme),size_hint_x=.58,halign="left"))
                row.add_widget(Label(text=self._format(val),font_size=12,color=_m3("on_surface_variant",theme),size_hint_x=.42,halign="right"))
                legend.add_widget(row)
            if small:
                legend.add_widget(Label(text=f"Other: {_fmt_count(len(small))} small categories — tap donut to inspect",
                                        font_size=11,color=_m3("on_surface_variant",theme),size_hint_y=None,height=dp(28)))
            self.add_widget(legend)
        except Exception as e:
            print(f"M3DonutChart redraw: {e}")


# ---------------------------------------------------------------------------
# Analytics tab replacement
# ---------------------------------------------------------------------------
def _analytics_tab(self):
    tab=TabbedPanelItem(text="Analytics")
    s=ScrollView()
    self._analytics_period="daily"; self._analytics_anchor=datetime.now()
    theme=_m3_theme(self)
    l=BoxLayout(orientation="vertical",padding=dp(12),spacing=dp(12),size_hint_y=None)
    l.bind(minimum_height=l.setter("height"))
    # Visible page surface: separates the analytics canvas from the Android light background.
    with l.canvas.before:
        Color(*_m3("surface",theme))
        l._page_bg=RoundedRectangle(pos=l.pos,size=l.size,radius=[dp(18)])
    l.bind(pos=lambda w,*a:setattr(w._page_bg,"pos",w.pos))
    l.bind(size=lambda w,*a:setattr(w._page_bg,"size",w.size))

    # Segmented control: one selected pill, all other segments transparent.
    seg=BoxLayout(size_hint_y=None,height=dp(48),spacing=dp(2),padding=dp(2))
    with seg.canvas.before:
        Color(*_m3("surface_container_high",theme)); seg._rr=RoundedRectangle(pos=seg.pos,size=seg.size,radius=[dp(24)])
        Color(*_m3("outline",theme)); seg._ol=Line(rounded_rectangle=(seg.x,seg.y,seg.width,seg.height,dp(24)),width=dp(1))
    seg.bind(pos=lambda w,*a:(setattr(w._rr,"pos",w.pos),setattr(w._rr,"size",w.size),setattr(w._ol,"rounded_rectangle",(w.x,w.y,w.width,w.height,dp(24)))))
    seg.bind(size=lambda w,*a:(setattr(w._rr,"pos",w.pos),setattr(w._rr,"size",w.size),setattr(w._ol,"rounded_rectangle",(w.x,w.y,w.width,w.height,dp(24)))))
    self._analytics_segment_buttons={}
    for p,lab in [("daily","◉  DAILY"),("weekly","▦  WEEKLY"),("monthly","▤  MONTHLY"),("yearly","▥  YEARLY")]:
        b=HMGButton(text=lab,background_normal="",background_down="",background_color=_m3("secondary_container",theme) if p=="daily" else _m3("surface_container_high",theme),
                    color=_m3("on_secondary_container",theme) if p=="daily" else _m3("on_surface_variant",theme),
                    font_size=14,bold=(p=="daily"),size_hint_x=1,markup=False)
        b._segment_key=p; b._segment_selected=(p=="daily")
        b.bind(on_press=lambda x,p=p:self._analytics_segment_press(p,x))
        self._analytics_segment_buttons[p]=b; seg.add_widget(b)
    l.add_widget(seg)

    nav=BoxLayout(size_hint_y=None,height=dp(56),spacing=dp(8),padding=(dp(12),dp(8),dp(12),dp(8)))
    _analytics_surface(self, nav, "surface_container")
    for direction,glyph in [(-1,"◀"),(1,"▶")]:
        nav.add_widget(HMGButton(text=glyph,font_size=18,bold=True,background_color=_m3("primary_container",theme),color=_m3("on_primary_container",theme),
                                 size_hint=(None,None),size=(dp(40),dp(40)),on_press=lambda x,d=direction:self._analytics_anchor_shift(d)))
    self.an_period_label=Label(text="",font_size=16,bold=True,color=_m3("on_surface",theme),size_hint_x=1,text_size=(dp(120),None),halign="center")
    nav.add_widget(self.an_period_label)
    l.add_widget(nav)

    def card(caption,attr):
        b=BoxLayout(orientation="vertical",padding=dp(12),spacing=dp(8),size_hint_y=None,height=dp(96))
        b._default_bg="surface_container_low"; b._caption_role="on_surface_variant"; b._value_role="on_surface"
        with b.canvas.before:
            Color(*_m3("surface_container_low",theme)); b._rr=RoundedRectangle(pos=b.pos,size=b.size,radius=[dp(16)])
            Color(*_m3("outline_variant",theme)); b._ol=Line(rounded_rectangle=(b.x,b.y,b.width,b.height,dp(16)),width=dp(1))
        b.bind(pos=lambda w,*a:(setattr(w._rr,"pos",w.pos),setattr(w._rr,"size",w.size),setattr(w._ol,"rounded_rectangle",(w.x,w.y,w.width,w.height,dp(16)))))
        b.bind(size=lambda w,*a:(setattr(w._rr,"pos",w.pos),setattr(w._rr,"size",w.size),setattr(w._ol,"rounded_rectangle",(w.x,w.y,w.width,w.height,dp(16)))))
        val=Label(text="0",font_size=24,color=_m3("on_surface",theme),size_hint_y=None,height=dp(36),halign="right")
        cap=Label(text=caption.upper(),font_size=12,bold=True,color=_m3("on_surface_variant",theme),size_hint_y=None,height=dp(20),halign="right")
        setattr(self,attr,val); b._value_label=val
        b.add_widget(cap); b.add_widget(val)
        def conditional(*_):
            try:
                raw=float(str(val.text).replace(",","").replace("₦","").replace("−","-").strip() or 0)
            except Exception: raw=0
            special=(caption in ("Deaths","Outstanding") and ((raw>0) if caption=="Deaths" else raw>0.0001))
            bg="error_container" if special else "surface_container_low"; fg="on_error_container" if special else "on_surface"
            b._rr_color=_m3(bg,_m3_theme(self)); val.color=_m3(fg,_m3_theme(self)); cap.color=_m3("on_surface_variant",_m3_theme(self))
            b._rr_color and setattr(b._rr,"size",b.size)
            try:
                b.canvas.before.clear()
                with b.canvas.before:
                    Color(*_m3(bg,_m3_theme(self))); b._rr=RoundedRectangle(pos=b.pos,size=b.size,radius=[dp(16)])
                    Color(*_m3("outline_variant",_m3_theme(self))); b._ol=Line(rounded_rectangle=(b.x,b.y,b.width,b.height,dp(16)),width=dp(1))
            except Exception: pass
        val.bind(text=conditional); Clock.schedule_once(lambda dt:conditional(),0)
        return b

    for captions in [(("Registrations","an_reg"),("Admissions","an_adm")),(("Discharges","an_dis"),("Deaths","an_deaths")),
                     (("Billed","an_billed"),("Paid","an_paid")),(("Outstanding","an_outstanding"),("Transfers","an_transfers"))]:
        g=GridLayout(cols=2,size_hint_y=None,height=dp(96),spacing=dp(12))
        for c,a in captions:g.add_widget(card(c,a))
        l.add_widget(g)

    self.an_volume_chart=M3BarChart(title="Volume by period",height=dp(240)); l.add_widget(self.an_volume_chart)
    row=BoxLayout(orientation="vertical",size_hint_y=None,height=dp(720),spacing=dp(10))
    self.an_payment_chart=M3DonutChart(title="Payment mix",height=dp(230))
    self.an_dx_chart=M3BarChart(title="Top diagnoses",height=dp(230))
    self.an_dept_chart=M3BarChart(title="Top departments",height=dp(230))
    row.add_widget(self.an_payment_chart); row.add_widget(self.an_dx_chart); row.add_widget(self.an_dept_chart); l.add_widget(row)

    selector=BoxLayout(size_hint_y=None,height=dp(56),padding=(dp(16),0,dp(8),0),spacing=dp(8))
    with selector.canvas.before:
        Color(*_m3("surface_container_lowest",theme)); selector._rr=RoundedRectangle(pos=selector.pos,size=selector.size,radius=[dp(8)])
        Color(*_m3("outline",theme)); selector._ol=Line(rounded_rectangle=(selector.x,selector.y,selector.width,selector.height,dp(8)),width=dp(1))
    selector.bind(pos=lambda w,*a:(setattr(w._rr,"pos",w.pos),setattr(w._rr,"size",w.size),setattr(w._ol,"rounded_rectangle",(w.x,w.y,w.width,w.height,dp(8)))))
    selector.bind(size=lambda w,*a:(setattr(w._rr,"pos",w.pos),setattr(w._rr,"size",w.size),setattr(w._ol,"rounded_rectangle",(w.x,w.y,w.width,w.height,dp(8)))))
    selector.add_widget(Label(text="METRIC",font_size=14,bold=True,color=_m3("on_surface_variant",theme),size_hint_x=None,width=dp(80)))
    self.an_metric_spinner=HMGSpinner(text="Registrations",values=["Registrations","Admissions","Discharges","Transfers","Billing","Payments","Lab Orders","Radiology","ECG","Deaths"],
                                      size_hint_x=1,size_hint_y=None,height=dp(48),background_normal="",background_down="",background_color=_m3("surface_container_lowest",theme),color=_m3("on_surface",theme),font_size=14)
    self.an_metric_spinner.bind(text=lambda *_:self._analytics_render())
    self.an_metric_spinner.bind(is_open=lambda sp,opened:self._analytics_style_spinner_dropdown(sp,opened))
    selector.add_widget(self.an_metric_spinner); l.add_widget(selector)

    self.an_series_chart=M3LineChart(title="Selected metric",height=dp(240)); l.add_widget(self.an_series_chart)
    # Horizontal scroll prevents currency columns from being compressed below readable widths.
    hs=ScrollView(do_scroll_y=False,size_hint_y=None,height=dp(280),bar_width=dp(6))
    self.an_summary_grid=GridLayout(cols=9,size_hint=(None,None),width=dp(980),row_default_height=dp(40),row_force_default=True,spacing=0)
    self.an_summary_grid.bind(minimum_height=self.an_summary_grid.setter("height")); hs.add_widget(self.an_summary_grid); l.add_widget(hs)
    ex=BoxLayout(size_hint_y=None,height=dp(48),spacing=dp(8))
    ex.add_widget(HMGButton(text="EXPORT PDF ANALYSIS",on_press=self._export_analytics_pdf)); ex.add_widget(HMGButton(text="EXPORT CSV",on_press=self._export_analytics_csv)); ex.add_widget(HMGButton(text="SHARE PDF",on_press=self._share_analytics_pdf)); l.add_widget(ex)
    s.add_widget(l); tab.add_widget(s); self.tp.add_widget(tab)
    try:
        s.bar_color = _m3("outline_variant", theme)
    except Exception:
        pass
    Clock.schedule_once(lambda dt:self._analytics_render(),0.1)
    Clock.schedule_once(lambda dt:self._analytics_refresh_tab_strip(),0.15)


def _analytics_segment_press(self, period, button):
    current=getattr(self,"_analytics_period","daily")
    if current==period:
        return
    self._analytics_period=period
    theme=_m3_theme(self)
    for p,b in getattr(self,"_analytics_segment_buttons",{}).items():
        selected=(p==period); b._segment_selected=selected
        target=_m3("secondary_container",theme) if selected else (0,0,0,0)
        color=_m3("on_secondary_container",theme) if selected else _m3("on_surface_variant",theme)
        Animation(background_color=target,duration=.15).start(b)
        b.color=color; b.bold=selected
    self._analytics_anchor=datetime.now()
    self._analytics_render()


def _analytics_refresh_tab_strip(self):
    try:
        theme=_m3_theme(self)
        for tab in getattr(self.tp,"tab_list",[]):
            active=(tab is getattr(self.tp,"current_tab",None))
            tab.background_normal=""; tab.background_down=""
            tab.background_color=_m3("primary_container" if active else "surface_container_high",theme)
            tab.color=_m3("on_primary_container" if active else "on_surface_variant",theme)
            tab.font_size=14; tab.bold=active
        Clock.schedule_once(lambda dt:self._analytics_refresh_tab_strip(),.35)
    except Exception:
        pass


def _refresh_dash(self,*args,**kwargs):
    try:
        base=globals().get("_HMG_ANALYTICS_BASE_REFRESH_DASH")
        if callable(base): base(self,*args,**kwargs)
    except Exception as e: print(f"[HMG] base dashboard refresh: {e}")
    try: self._refresh_dash_analytics(*args,**kwargs)
    except Exception as e: print(f"[HMG] analytics dashboard refresh: {e}")


def _analytics_dashboard_block(self):
    theme=_m3_theme(self)
    box=BoxLayout(orientation="vertical",size_hint_y=None,spacing=dp(12),padding=(dp(4),dp(8)))
    box.add_widget(Label(text="TODAY AT A GLANCE",font_size=16,bold=True,color=_m3("primary",theme),size_hint_y=None,height=dp(28),halign="left"))
    grid=GridLayout(cols=2,size_hint_y=None,height=dp(200),spacing=dp(14),padding=(dp(2),dp(2)))
    def mini(caption,attr):
        b=BoxLayout(orientation="vertical",padding=dp(12),spacing=dp(7),size_hint_y=None,height=dp(92))
        with b.canvas.before:
            Color(*_m3("surface_container_low",theme)); b.rr=RoundedRectangle(pos=b.pos,size=b.size,radius=[dp(16)])
            Color(*_m3("outline_variant",theme)); b.ol=Line(rounded_rectangle=(b.x,b.y,b.width,b.height,dp(16)),width=dp(1))
        b.bind(pos=lambda w,*a:(setattr(w.rr,"pos",w.pos),setattr(w.rr,"size",w.size),setattr(w.ol,"rounded_rectangle",(w.x,w.y,w.width,w.height,dp(16)))))
        b.bind(size=lambda w,*a:(setattr(w.rr,"pos",w.pos),setattr(w.rr,"size",w.size),setattr(w.ol,"rounded_rectangle",(w.x,w.y,w.width,w.height,dp(16)))))
        val=Label(text="0",font_size=22,bold=False,color=_m3("on_surface",theme),size_hint_y=None,height=dp(36),halign="right",valign="middle")
        cap=Label(text=caption.upper(),font_size=12,bold=True,color=_m3("on_surface_variant",theme),size_hint_y=None,height=dp(20),halign="right")
        setattr(self,attr,val); b.add_widget(cap); b.add_widget(val); return b
    for c,a in [("Today's registrations","dash_an_reg"),("Today's admissions","dash_an_adm"),("Today's revenue (paid)","dash_an_rev"),("Pending tasks","dash_an_tasks")]: grid.add_widget(mini(c,a))
    box.add_widget(grid)
    self.dash_an_chart=M3LineChart(title="Last 7 days — revenue",height=dp(220)); box.add_widget(self.dash_an_chart)
    box.add_widget(HMGButton(text="OPEN FULL ANALYTICS",on_press=lambda *_:self._switch("Analytics"),size_hint_y=None,height=dp(48)))
    return box


# ---------------------------------------------------------------------------
# PDF replacement — same signature, same export path.
# ---------------------------------------------------------------------------
def _render_analytics_pdf_native(self,snap,summary_rows,charts,period_label,out_path):
    try:
        from reportlab.lib import colors
        from reportlab.platypus import SimpleDocTemplate,Paragraph,Spacer,Table,TableStyle,Image as RLImage
        from reportlab.lib.styles import getSampleStyleSheet,ParagraphStyle
        from reportlab.lib.enums import TA_CENTER,TA_RIGHT
        theme=_m3_theme(self)
        def hx(role): return colors.HexColor(M3Tokens.get(role,theme))
        doc=SimpleDocTemplate(out_path,pagesize=A4,leftMargin=10*mm,rightMargin=10*mm,topMargin=10*mm,bottomMargin=15*mm)
        styles=getSampleStyleSheet(); styles["Normal"].fontName="Helvetica"; styles["Normal"].fontSize=10.5; styles["Normal"].leading=14
        styles["Heading2"].fontName="Helvetica-Bold"
        styles["Heading2"].textColor=hx("primary"); styles["Heading2"].fontSize=13; styles["Heading2"].spaceBefore=7; styles["Heading2"].spaceAfter=5
        story=[]
        head=[[Paragraph(f"<b>{self._fac('facility_name')}</b><br/>{self._fac('address_line')}<br/>{self._fac('tagline')}",styles["Normal"]),
               Paragraph(f"<b>Period:</b> {period_label}<br/><b>Generated:</b> {datetime.now():%Y-%m-%d %H:%M:%S}",styles["Normal"])]]
        ht=Table(head,colWidths=[125*mm,55*mm]); ht.setStyle(TableStyle([("BACKGROUND",(0,0),(-1,-1),hx("primary")),("TEXTCOLOR",(0,0),(-1,-1),hx("on_primary")),("VALIGN",(0,0),(-1,-1),"MIDDLE"),("BOX",(0,0),(-1,-1),.5,hx("outline")),("LEFTPADDING",(0,0),(-1,-1),8),("TOPPADDING",(0,0),(-1,-1),7),("BOTTOMPADDING",(0,0),(-1,-1),7)]))
        story += [ht,Spacer(1,4*mm),Paragraph("<b>ANALYTICS &amp; PERFORMANCE REPORT</b>",ParagraphStyle("title_m3",fontName="Helvetica-Bold",fontSize=16,textColor=hx("on_primary"),alignment=TA_CENTER,backColor=hx("primary"),spaceAfter=4*mm))]
        kpis=[("Registrations",_fmt_count(snap.get("registrations",0))), ("Admissions",_fmt_count(snap.get("admissions",0))), ("Discharges",_fmt_count(snap.get("discharges",0))), ("Deaths",_fmt_count(snap.get("deaths",0))),
              ("Billed",self._fmt_money(snap.get("billed_total",0))), ("Paid",self._fmt_money(snap.get("paid_total",0))), ("Outstanding",self._fmt_money(snap.get("outstanding",0))), ("Transfers",_fmt_count((snap.get("transfers_in",0) or 0)+(snap.get("transfers_out",0) or 0)))]
        kd=[]
        for i in range(0,8,2): kd.append([Paragraph(f"<b>{kpis[i][0]}</b><br/><font size=16>{kpis[i][1]}</font>",styles["Normal"]),Paragraph(f"<b>{kpis[i+1][0]}</b><br/><font size=16>{kpis[i+1][1]}</font>",styles["Normal"])])
        kt=Table(kd,colWidths=[90*mm,90*mm]); kt.setStyle(TableStyle([("GRID",(0,0),(-1,-1),.5,hx("outline_variant")),("BACKGROUND",(0,0),(-1,-1),hx("surface_container_low")),("ROWBACKGROUNDS",(0,0),(-1,-1),[hx("surface_container_low"),hx("surface_container")]),("TEXTCOLOR",(0,0),(-1,-1),hx("on_surface")),("VALIGN",(0,0),(-1,-1),"MIDDLE"),("LEFTPADDING",(0,0),(-1,-1),8),("TOPPADDING",(0,0),(-1,-1),7)]))
        story += [kt,Spacer(1,5*mm),Paragraph("TREND ANALYSIS",styles["Heading2"])]
        for pth in charts:
            if pth and os.path.exists(pth):
                try: story += [RLImage(pth,width=180*mm,height=78*mm,kind="proportional"),Spacer(1,3*mm)]
                except Exception: pass
        story += [Paragraph("TOP DIAGNOSES",styles["Heading2"])]
        dx=[["Diagnosis","Count"]]+[[str(a),_fmt_count(b)] for a,b in snap.get("top_diagnoses",[])]
        story += [Table(dx,colWidths=[145*mm,35*mm],repeatRows=1,style=TableStyle([("BACKGROUND",(0,0),(-1,0),hx("primary")),("TEXTCOLOR",(0,0),(-1,0),hx("on_primary")),("TEXTCOLOR",(0,1),(-1,-1),hx("on_surface")),("ALIGN",(1,1),(1,-1),"RIGHT"),("ROWBACKGROUNDS",(0,1),(-1,-1),[hx("surface"),hx("surface_container_low")]),("LINEBELOW",(0,0),(-1,-1),.4,hx("outline_variant")),("LEFTPADDING",(0,0),(-1,-1),6),("RIGHTPADDING",(0,0),(-1,-1),6)]))]
        story += [Spacer(1,3*mm),Paragraph("PAYMENT MIX",styles["Heading2"])]
        total=float(snap.get("paid_total",0) or 0); pm=[["Method","Amount","%"]]
        for m,v in snap.get("payment_methods",{}).items(): pm.append([str(m),self._fmt_money(v),_fmt_pct(float(v)/total) if total else "0.0%"])
        story += [Table(pm,colWidths=[80*mm,55*mm,45*mm],repeatRows=1,style=TableStyle([("BACKGROUND",(0,0),(-1,0),hx("primary")),("TEXTCOLOR",(0,0),(-1,0),hx("on_primary")),("TEXTCOLOR",(0,1),(-1,-1),hx("on_surface")),("ALIGN",(1,1),(-1,-1),"RIGHT"),("ROWBACKGROUNDS",(0,1),(-1,-1),[hx("surface"),hx("surface_container_low")]),("LINEBELOW",(0,0),(-1,-1),.4,hx("outline_variant"))]))]
        story += [Spacer(1,4*mm),Paragraph("BUCKET SUMMARY",styles["Heading2"])]
        hdr=["Period","Reg","Adm","Disch","Deaths","Billed","Paid","Outstanding","Transfers"]
        data=[hdr]
        for r in summary_rows:
            data.append([str(r.get("period","")),_fmt_count(r.get("registrations")),_fmt_count(r.get("admissions")),_fmt_count(r.get("discharges")),_fmt_count(r.get("deaths")),self._fmt_money(r.get("billed")),self._fmt_money(r.get("paid")),self._fmt_money(r.get("outstanding")),_fmt_count(r.get("transfers"))])
        story += [Table(data,repeatRows=1,colWidths=[30*mm,16*mm,16*mm,18*mm,18*mm,22*mm,22*mm,24*mm,22*mm],style=TableStyle([("BACKGROUND",(0,0),(-1,0),hx("primary")),("TEXTCOLOR",(0,0),(-1,0),hx("on_primary")),("TEXTCOLOR",(0,1),(-1,-1),hx("on_surface_variant")),("ROWBACKGROUNDS",(0,1),(-1,-1),[hx("surface"),hx("surface_container_low")]),("ALIGN",(1,1),(-1,-1),"RIGHT"),("ALIGN",(0,1),(0,-1),"LEFT"),("LINEBELOW",(0,0),(-1,-1),.35,hx("outline_variant")),("FONTSIZE",(0,0),(-1,-1),9.5),("LEFTPADDING",(0,0),(-1,-1),5),("RIGHTPADDING",(0,0),(-1,-1),5)]))]
        story += [Spacer(1,5*mm),Paragraph(f"<b>{self._fac('signatory_name')}</b><br/>{self._fac('signatory_quals')}<br/>{self._fac('signatory_role')}",styles["Normal"])]
        def footer(c,d):
            c.saveState(); c.setFillColor(hx("primary")); c.rect(0,0,A4[0],8*mm,fill=1,stroke=0); c.setFillColor(hx("on_primary")); c.setFont("Helvetica-Bold",8); c.drawString(10*mm,3*mm,f"{self._fac('facility_name')} • Analytics Report • {datetime.now():%Y-%m-%d}"); c.restoreState()
        doc.build(story,onFirstPage=footer,onLaterPages=footer); return True
    except Exception as e:
        print(f"Analytics PDF error: {e}"); return False


def _analytics_style_spinner_dropdown(self, spinner, is_open):
    if not is_open:
        return
    try:
        theme=_m3_theme(self)
        spinner.background_color=_m3("surface_container_lowest",theme)
        spinner.color=_m3("on_surface",theme)
        dropdown=getattr(spinner,"_dropdown",None)
        if dropdown is not None:
            dropdown.background_color=_m3("surface_container_lowest",theme)
            for child in list(getattr(dropdown,"container",dropdown).children):
                if isinstance(child, HMGSpinnerOption):
                    child.background_color=_m3("surface_container",theme)
                    child.color=_m3("on_surface",theme)
    except Exception:
        pass


# High-resolution export chart renderer: avoids blurry analytics charts in WPS/Microsoft PDF viewers.
def _chart_to_png_hires(self, kind, series, title, path, w_px=2400, h_px=1200):
    """Render analytics export charts at high DPI with embedded TrueType text.
    This avoids the soft/small text that some Android PDF viewers show when a
    low-resolution PIL default font is scaled inside a PDF.
    """
    if not PIL_AVAILABLE:
        return False
    try:
        from PIL import ImageDraw, ImageFont
        theme = _m3_theme(self)
        bg = M3Tokens.get("surface_container_low", theme)
        fg = M3Tokens.get("on_surface", theme)
        sub = M3Tokens.get("on_surface_variant", theme)
        grid = M3Tokens.get("outline_variant", theme)
        primary = M3Tokens.get("primary", theme)
        border = M3Tokens.get("outline", theme)
        im = PILImage.new("RGB", (w_px, h_px), bg)
        d = ImageDraw.Draw(im)
        def font(size, bold=False):
            candidates = [
                "/system/fonts/Roboto-Bold.ttf" if bold else "/system/fonts/Roboto-Regular.ttf",
                "/usr/share/fonts/truetype/dejavu/DejaVuSans-Bold.ttf" if bold else "/usr/share/fonts/truetype/dejavu/DejaVuSans.ttf",
            ]
            for fp in candidates:
                try: return ImageFont.truetype(fp, size=size)
                except Exception: pass
            return ImageFont.load_default()
        f_title=font(54,True); f_axis=font(30,False); f_value=font(30,True); f_x=font(27,False)
        d.rounded_rectangle((18,18,w_px-18,h_px-18), radius=36, fill=bg, outline=border, width=3)
        d.text((65,48), str(title), fill=fg, font=f_title)
        vals=[float(v or 0) for _,v in (series or [])]
        if not vals:
            d.text((w_px//2,h_px//2), "No data for this period", fill=sub, font=f_title, anchor="mm")
            im.save(path, format="PNG", optimize=False, compress_level=1, dpi=(300,300)); return True
        mx=max(vals+[1.0]); left,right,top,bottom=210,w_px-80,170,h_px-180
        for i in range(5):
            y=bottom-(bottom-top)*i/4
            d.line((left,y,right,y), fill=grid, width=3)
            d.text((left-18,y), _fmt_money(mx*i/4,self._currency(),True) if getattr(self,"_chart_export_money",False) else _fmt_count(mx*i/4), fill=sub, font=f_axis, anchor="rm")
        if kind=="line":
            pts=[]
            for i,(_,v) in enumerate(series):
                x=left+(right-left)*(i/(len(series)-1) if len(series)>1 else .5)
                y=bottom-(bottom-top)*max(0,float(v))/mx; pts.append((int(x),int(y)))
            if len(pts)>1: d.line(pts,fill=primary,width=9,joint="curve")
            for x,y in pts:
                d.ellipse((x-10,y-10,x+10,y+10),fill=primary,outline=bg,width=4)
        else:
            n=max(1,len(series)); bw=max(18,(right-left)/(n*1.55))
            for i,(_,v) in enumerate(series):
                x=left+(right-left)*(i+.5)/n; y=bottom-(bottom-top)*max(0,float(v))/mx
                d.rounded_rectangle((x-bw/2,y,x+bw/2,bottom),radius=14,fill=primary,outline=border,width=2)
                if bottom-y >= 55:
                    label=_fmt_money(v,self._currency(),True) if getattr(self,"_chart_export_money",False) else _fmt_count(v)
                    d.text((x,y-12),label,fill=fg,font=f_value,anchor="ms")
        for i,(lab,val) in enumerate(series):
            if len(series)>12 and i%max(1,math.ceil(len(series)/6)): continue
            x=left+(right-left)*(i/(len(series)-1) if len(series)>1 else .5)
            d.text((x,bottom+35),str(lab)[:22],fill=sub,font=f_x,anchor="ma")
        im.save(path, format="PNG", optimize=False, compress_level=1, dpi=(300,300))
        return True
    except Exception as e:
        print(f"hires chart_to_png: {e}")
        return False

