# HMG ANALYTICS FINAL VISUAL/LEGIBILITY REPAIR
# Additive override block: preserves existing method names/signatures and data flow.

class M3AnalyticsCell(Label):
    def __init__(self, text="", role_bg="surface", role_fg="on_surface", theme="light", align="left", **kwargs):
        kwargs.setdefault("size_hint_y", None)
        kwargs.setdefault("height", dp(40))
        kwargs.setdefault("font_size", 12)
        kwargs.setdefault("color", _m3(role_fg, theme))
        kwargs.setdefault("text_size", (None, None))
        super().__init__(text=str(text), **kwargs)
        self.role_bg = role_bg
        self.role_fg = role_fg
        self._theme = theme
        self.halign = align
        self.valign = "middle"
        self.padding = (dp(8), 0)
        self._sync_text_size()
        with self.canvas.before:
            Color(*_m3(role_bg, theme))
            self._bg = Rectangle(pos=self.pos, size=self.size)
            Color(*_m3("outline_variant", theme))
            self._line = Line(points=[self.x, self.y, self.right, self.y], width=dp(1))
        self.bind(pos=self._sync_canvas, size=self._sync_canvas)

    def _sync_text_size(self, *args):
        self.text_size = (max(dp(10), self.width - dp(16)), self.height)

    def _sync_canvas(self, *args):
        self._bg.pos = self.pos
        self._bg.size = self.size
        self._line.points = [self.x, self.y, self.right, self.y]
        self._sync_text_size()

    def refresh(self, text, role_bg=None, role_fg=None, theme="light", align=None):
        self.text = str(text)
        if role_bg:
            self.role_bg = role_bg
        if role_fg:
            self.role_fg = role_fg
        self._theme = theme
        self.color = _m3(self.role_fg, theme)
        if align:
            self.halign = align
        self._bg.source = ""
        self.canvas.before.clear()
        with self.canvas.before:
            Color(*_m3(self.role_bg, theme))
            self._bg = Rectangle(pos=self.pos, size=self.size)
            Color(*_m3("outline_variant", theme))
            self._line = Line(points=[self.x, self.y, self.right, self.y], width=dp(1))
        self._sync_canvas()


def _hmg_analytics_button_state(self, *args):
    """Preserve HMGButton's normal behavior except for analytics buttons that
    explicitly supply their own M3 foreground/background pair."""
    try:
        original = globals().get("_HMG_ORIGINAL_BUTTON_STATE")
        if callable(original):
            original(self, *args)
    except Exception:
        pass
    if getattr(self, "_analytics_force_pair", False):
        try:
            down = self.state == "down"
            self.color = self._analytics_fg_down if down else self._analytics_fg
            self._m3_color.rgba = self._analytics_bg_down if down else self._analytics_bg
        except Exception:
            pass


if not globals().get("_HMG_ORIGINAL_BUTTON_STATE"):
    _HMG_ORIGINAL_BUTTON_STATE = HMGButton._m3_update_state
    # Kivy stores the bound method name in its weak-method observer.
    # Because this function lives at module scope, expose it on HMGButton
    # under the same name before replacing _m3_update_state.
    HMGButton._hmg_analytics_button_state = _hmg_analytics_button_state
    HMGButton._m3_update_state = _hmg_analytics_button_state


def _analytics_pair_button(button, bg_role, fg_role, pressed_bg_role=None, pressed_fg_role=None):
    theme = _m3_theme(App.get_running_app())
    button._analytics_force_pair = True
    button._analytics_bg = _m3(bg_role, theme)
    button._analytics_fg = _m3(fg_role, theme)
    button._analytics_bg_down = _m3(pressed_bg_role or bg_role, theme)
    button._analytics_fg_down = _m3(pressed_fg_role or fg_role, theme)
    button.background_color = button._analytics_bg
    button.color = button._analytics_fg
    return button


def _analytics_refresh_button_pairs(self):
    theme = _m3_theme(self)
    for b in getattr(self, "_analytics_segment_buttons", {}).values():
        selected = getattr(b, "_segment_selected", False)
        if selected:
            _analytics_pair_button(b, "primary", "on_primary",
                                    "primary_container", "on_primary_container")
        else:
            _analytics_pair_button(b, "surface_container_high", "on_surface_variant",
                                    "surface_container_highest", "on_surface")
    for b in getattr(self, "_analytics_nav_buttons", []):
        _analytics_pair_button(b, "primary_container", "on_primary_container",
                                "primary", "on_primary")


def _analytics_segment_press_final(self, period, button):
    current = getattr(self, "_analytics_period", "daily")
    if current == period:
        return
    self._analytics_period = period
    for p, b in getattr(self, "_analytics_segment_buttons", {}).items():
        selected = (p == period)
        b._segment_selected = selected
        b.background_color = _m3("primary" if selected else "surface_container_high", _m3_theme(self))
        b.color = _m3("on_primary" if selected else "on_surface_variant", _m3_theme(self))
        b.bold = selected
    _analytics_refresh_button_pairs(self)
    self._analytics_anchor = datetime.now()
    self._analytics_render()


