        val = Label(text="0", font_size=24, color=_m3("on_surface", theme), size_hint_y=None, height=dp(38), halign="right", valign="middle")
        cap = Label(text=caption.upper(), font_size=12, bold=True, color=_m3("on_surface_variant", theme), size_hint_y=None, height=dp(22), halign="right", valign="middle")
        setattr(self, attr, val)
