    hs.bind(size=lambda w,*a:(setattr(w._bg,"size",w.size),setattr(w._ol,"rounded_rectangle",(w.x,w.y,w.width,w.height,dp(16)))))
    self.an_summary_grid = GridLayout(cols=9,size_hint=(None,None),width=dp(1000),spacing=0,row_default_height=dp(40),row_force_default=True)
