HMGBillingApp._refresh_dash = _refresh_dash_final
# Final tab-strip contrast guard. This runs after every tab switch so later
# Kivy/HMGButton theme refreshes cannot restore low-contrast grey tabs.
def _hmg_final_refresh_tab_strip(self, *args):
    try:
        theme = _m3_theme(self)
        for tab in getattr(self.tp, "tab_list", []):
            active = (tab is getattr(self.tp, "current_tab", None))
            tab.background_normal = ""
            tab.background_down = ""
            tab.background_color = _m3("primary" if active else "surface_container_high", theme)
            tab.color = _m3("on_primary" if active else "on_surface_variant", theme)
            tab.bold = active
            tab.font_size = 14
    except Exception as e:
        print(f"[HMG] final tab-strip refresh: {e}")

HMGBillingApp._analytics_refresh_tab_strip = _hmg_final_refresh_tab_strip



