def _build_analytics_text_contrast(self, snap):
    lines = [
        f"ANALYTICS REPORT — {snap.get('label', '')}", '=' * 60, '',
        'VOLUME',
        f"  Registrations : {_fmt_count(snap.get('registrations', 0))}",
        f"  Admissions    : {_fmt_count(snap.get('admissions', 0))}",
        f"  Discharges    : {_fmt_count(snap.get('discharges', 0))}",
        f"  Deaths        : {_fmt_count(snap.get('deaths', 0))}",
        f"  Transfers In  : {_fmt_count(snap.get('transfers_in', 0))}",
        f"  Transfers Out : {_fmt_count(snap.get('transfers_out', 0))}", '',
        'FINANCE',
        f"  Billed        : {_fmt_money(snap.get('billed_total', 0), self._currency())}",
        f"  Paid          : {_fmt_money(snap.get('paid_total', 0), self._currency())}",
        f"  Outstanding   : {_fmt_money(snap.get('outstanding', 0), self._currency())}",
        '', 'TOP DIAGNOSES', '-' * 40]
    for dx, cnt in (snap.get('top_diagnoses') or [])[:10]:
        lines.append(f"  {dx:<40} {cnt}")
    lines += ['', 'TOP DEPARTMENTS', '-' * 40]
    for dep, cnt in (snap.get('top_departments') or [])[:8]:
        lines.append(f"  {dep:<40} {cnt}")
    lines += ['', 'PAYMENT MIX', '-' * 40]
    for method, amount in (snap.get('payment_methods') or {}).items():
        lines.append(f"  {method:<40} {_fmt_money(amount, self._currency())}")
    return '\n'.join(lines)


def _share_latest_analytics_pdf(self, instance=None):
    path = getattr(self, '_analytics_last_pdf', None)
    try:
        if not path or not os.path.exists(path):
            # Existing export method opens/saves the current analytics PDF.
            path = self._export_analytics_pdf()
        if path and os.path.exists(path):
            self._share_file(path)
            return path
        self._popup('Share', 'No analytics PDF available. Tap EXPORT PDF first.')
    except Exception as e:
        self._popup('Share Error', str(e))
    return None


