# ============================================================================
# HMG KIVY 2.3.1 TAB STRIP SAFETY REPAIR
# Kivy expects every TabbedPanelItem parent strip to expose .tabbed_panel.
# Some dynamically injected tabs can otherwise retain a plain BoxLayout parent,
# which crashes on Android when the tab is released. Repair only that parent
# reference; do not replace the TabbedPanel or its tab contents.
# ============================================================================
def _hmg_repair_tabbed_panel_parents(self, *args):
    try:
        tp = getattr(self, 'tp', None)
        if tp is None:
            return
        repaired = 0
        for tab in list(getattr(tp, 'tab_list', []) or []):
            parent = getattr(tab, 'parent', None)
            if parent is not None and not hasattr(parent, 'tabbed_panel'):
                try:
                    parent.tabbed_panel = tp
                    repaired += 1
                except Exception:
                    pass
        if repaired:
            print(f'[HMG] repaired {repaired} tab parent references')
    except Exception as e:
        print(f'[HMG] tab parent repair: {e}')

HMGBillingApp._repair_tabbed_panel_parents = _hmg_repair_tabbed_panel_parents

# Explicit final tab strip restyling, using the same plain Kivy foreground pair.
def _contrast_fixed_tab_strip(self, *args):
    try:
        for tab in getattr(self.tp, 'tab_list', []):
            active = tab is getattr(self.tp, 'current_tab', None)
            tab.background_normal = ''
            tab.background_down = ''
            tab.background_color = M3Tokens.get('primary' if active else 'surface_container_high')
            tab.color = M3Tokens.get('on_primary' if active else 'on_surface_variant')
            tab.bold = active
            tab.font_size = 14
    except Exception as e:
        print(f'[HMG] final tab strip: {e}')

HMGBillingApp._contrast_fixed_tab_strip = _contrast_fixed_tab_strip
try:
    if hasattr(HMGBillingApp, '_build_main_app'):
        _old_build_main_app_contrast = HMGBillingApp._build_main_app
        def _build_main_app_contrast(self, *args, **kwargs):
            result = _old_build_main_app_contrast(self, *args, **kwargs)
            try:
                self.tp.bind(current_tab=lambda *_: (self._repair_tabbed_panel_parents(), self._contrast_fixed_tab_strip()))
                Clock.schedule_once(lambda *_: (self._repair_tabbed_panel_parents(), self._contrast_fixed_tab_strip()), 0.15)
                Clock.schedule_once(lambda *_: self._repair_tabbed_panel_parents(), 1.0)
            except Exception as _e:
                print(f'[HMG] tab strip bind: {_e}')
            return result
        HMGBillingApp._build_main_app = _build_main_app_contrast
except Exception as _e:
    print(f'[HMG] build hook: {_e}')


