def _set_analytics_period_contrast(self, period):
    """Final bridge to the real AnalyticsEngine period implementation."""
    try:
        period = str(period).lower().strip()
        if period not in ('daily', 'weekly', 'monthly', 'yearly'):
            period = 'monthly'
        self._analytics_period = period
        self._analytics_anchor = datetime.now()
        self._analytics_set_period(period)
        try:
            if hasattr(self, '_contrast_analytics_style_segments'):
                self._contrast_analytics_style_segments()
        except Exception:
            pass
    except Exception as e:
        print(f'[HMG ANALYTICS] period change: {e}')

HMGBillingApp._set_analytics_period_contrast = _set_analytics_period_contrast


def _hmg_emr_select_saved_patient(self, patient):
    """Select a patient using the application's existing patient-selection chain."""
    try:
        pid = patient.get('id', '')
        if pid and hasattr(self, '_sel_by_id'):
            self._sel_by_id(pid)
        elif pid:
            self.cp = patient
            if hasattr(self, 'emr_pid'):
                self.emr_pid.text = pid
            if hasattr(self, 'emr_name'):
                self.emr_name.text = patient.get('name', '')
    except Exception as e:
        print(f'[HMG EMR] patient selection: {e}')


def _hmg_emr_patient_picker(self):
    """Popup showing all patients currently loaded by the real EMR database."""
    content = BoxLayout(orientation='vertical', spacing=dp(6), padding=dp(8))

    search = TextInput(
        hint_text='Search saved patients by name, ID or phone',
        multiline=False, size_hint_y=None, height=dp(42), font_size=13)
    content.add_widget(search)

    sv = ScrollView(bar_width=dp(5))
    rows = BoxLayout(orientation='vertical', spacing=dp(5),
                     size_hint_y=None, padding=(0, dp(2)))
    rows.bind(minimum_height=rows.setter('height'))
    sv.add_widget(rows)
    content.add_widget(sv)

    close = _PlainKivyButton(
        text='CLOSE', size_hint_y=None, height=dp(42),
        background_normal='', background_down='',
        background_color=M3Tokens.get('secondary_container'),
        color=M3Tokens.get('on_secondary_container'))
    content.add_widget(close)

    pp = Popup(title='SELECT SAVED PATIENT', content=content,
               size_hint=(0.94, 0.88))

    def populate(*_):
        rows.clear_widgets()
        patients = list(getattr(self, 'patients', []) or [])
        q = search.text.strip().lower()
        matched = []
        for p in patients:
            hay = ' '.join(str(p.get(k, '')) for k in
                           ('id', 'name', 'phone', 'dob')).lower()
            if q and q not in hay:
                continue
            matched.append(p)

        if not matched:
            rows.add_widget(Label(
                text='No saved patients found.',
                size_hint_y=None, height=dp(42),
                color=M3Tokens.get('on_surface_variant')))
            return

        for p in matched:
            text = (
                f"👤 {p.get('name','Unknown')}   "
                f"{p.get('id','')}   "
                f"{p.get('age','')}y   "
                f"{p.get('gender','')}   "
                f"{p.get('phone','')}"
            )
            b = _PlainKivyButton(
                text=text, font_size=12, halign='left',
                valign='middle', size_hint_y=None, height=dp(54),
                background_normal='', background_down='',
                background_color=M3Tokens.get('surface_container_low'),
                color=M3Tokens.get('on_surface'))
            b.text_size = (None, None)
            b.bind(on_press=lambda _b, patient=p: (
                _hmg_emr_select_saved_patient(self, patient), pp.dismiss()))
            rows.add_widget(b)

    search.bind(text=populate)
    close.bind(on_press=pp.dismiss)
    populate()
    pp.open()


def _hmg_emr_refresh_patient_view(self):
    """Refresh patient list and immediately reflect the current selected patient."""
    try:
        patients = list(getattr(self, 'patients', []) or [])
        self._emr_patient_count_label.text = f'{len(patients)} SAVED PATIENTS'
        cp = getattr(self, 'cp', None)
        if cp:
            self._emr_patient_summary.text = (
                f"SELECTED: {cp.get('name','')}  •  {cp.get('id','')}  •  "
                f"{cp.get('age','')}y  •  {cp.get('gender','')}  •  "
                f"Blood: {cp.get('blood','Unknown')}"
            )
        else:
            self._emr_patient_summary.text = (
                'NO PATIENT SELECTED — choose from your saved patient records')
    except Exception as e:
        print(f'[HMG EMR] patient refresh: {e}')


def _hmg_complex_emr(self):
    """
    Enhanced EMR wrapper around the existing production EMR builder.
    It does not replace the application's record structures or clinical
    callbacks; it adds a richer patient workspace around them.
    """
    tab_capture = []
    original_add = self.tp.add_widget

    def capture(widget, *args, **kwargs):
        tab_capture.append(widget)

    self.tp.add_widget = capture
    try:
        original_emr = globals().get('_HMG_ORIGINAL_EMR_BUILDER')
        if callable(original_emr):
            original_emr(self)
    finally:
        self.tp.add_widget = original_add

    if not tab_capture:
        print('[HMG EMR] original EMR builder produced no tab')
        # Still expose a usable EMR tab.
        fallback = TabbedPanelItem(text='EMR')
        box = BoxLayout(orientation='vertical')
        box.add_widget(Label(text='EMR could not be constructed.'))
        fallback.add_widget(box)
        self.tp.add_widget(fallback)
        return

    old_tab = tab_capture[-1]
    old_content = list(old_tab.children)
    zoom_root = old_content[0] if old_content else old_tab

    # Preserve the original scrolling EMR exactly as its clinical content.
    self._emr_content_root = zoom_root
    self._emr_zoom_level = getattr(self, '_emr_zoom_level', 1.0)
    _contrast_fixed_zoom_snapshot(self, zoom_root)

    # Patient workspace.
    patient_card = BoxLayout(
        orientation='vertical', size_hint_y=None, height=dp(104),
        spacing=dp(4), padding=(dp(7), dp(5)))
    with patient_card.canvas.before:
        Color(*M3Tokens.get('surface_container'))
        pbg = RoundedRectangle(pos=patient_card.pos,
                               size=patient_card.size, radius=[dp(14)])
    patient_card.bind(
        pos=lambda *_: setattr(pbg, 'pos', patient_card.pos),
        size=lambda *_: setattr(pbg, 'size', patient_card.size))

    top = BoxLayout(size_hint_y=None, height=dp(42), spacing=dp(6))
    select_btn = _PlainKivyButton(
        text='👤  SELECT SAVED PATIENT', font_size=12, bold=True,
        size_hint_x=.43, background_normal='', background_down='',
        background_color=M3Tokens.get('primary'),
        color=M3Tokens.get('on_primary'))
    refresh_btn = _PlainKivyButton(
        text='↻  REFRESH', font_size=11,
        size_hint_x=.19, background_normal='', background_down='',
        background_color=M3Tokens.get('secondary_container'),
        color=M3Tokens.get('on_secondary_container'))
    history_btn = _PlainKivyButton(
        text='📜  HISTORY', font_size=11,
        size_hint_x=.19, background_normal='', background_down='',
        background_color=M3Tokens.get('secondary_container'),
        color=M3Tokens.get('on_secondary_container'))
    reg_btn = _PlainKivyButton(
        text='＋  REGISTER', font_size=11,
        size_hint_x=.19, background_normal='', background_down='',
        background_color=M3Tokens.get('primary_container'),
        color=M3Tokens.get('on_primary_container'))
    top.add_widget(select_btn)
    top.add_widget(refresh_btn)
    top.add_widget(history_btn)
    top.add_widget(reg_btn)
    patient_card.add_widget(top)

    self._emr_patient_summary = Label(
        text='NO PATIENT SELECTED — choose from your saved patient records',
        font_size=11, bold=True, halign='left', valign='middle',
        color=M3Tokens.get('on_surface'), size_hint_y=None, height=dp(27))
    self._emr_patient_summary.bind(
        size=lambda w, size: setattr(w, 'text_size', (size[0], None)))
    patient_card.add_widget(self._emr_patient_summary)

    self._emr_patient_count_label = Label(
        text=f'{len(getattr(self, "patients", []) or [])} SAVED PATIENTS',
        font_size=10, color=M3Tokens.get('on_surface_variant'),
        halign='left', size_hint_y=None, height=dp(18))
    patient_card.add_widget(self._emr_patient_count_label)

    select_btn.bind(on_press=lambda *_: _hmg_emr_patient_picker(self))
    refresh_btn.bind(on_press=lambda *_: (
        self._refresh_plist() if hasattr(self, '_refresh_plist') else None,
        _hmg_emr_refresh_patient_view(self)))
    history_btn.bind(on_press=lambda *a, **kw: (
        self._view_emr_history(*a, **kw) if hasattr(self, '_view_emr_history')
        else self._popup('EMR History', 'History function unavailable')))
    reg_btn.bind(on_press=lambda *_: self._switch('Registration'))

    # Zoom toolbar.
    zoom_bar = BoxLayout(
        size_hint_y=None, height=dp(44), spacing=dp(6),
        padding=(dp(4), dp(3)))
    btn_out = _PlainKivyButton(
        text='−', font_size=18, bold=True, size_hint=(None, None),
        size=(dp(44), dp(36)), background_normal='', background_down='',
        background_color=M3Tokens.get('secondary_container'),
        color=M3Tokens.get('on_secondary_container'))
    btn_in = _PlainKivyButton(
        text='+', font_size=18, bold=True, size_hint=(None, None),
        size=(dp(44), dp(36)), background_normal='', background_down='',
        background_color=M3Tokens.get('secondary_container'),
        color=M3Tokens.get('on_secondary_container'))
    zoom_label = _PlainKivyButton(
        text=f"{int(round(self._emr_zoom_level * 100))}%",
        font_size=13, size_hint=(None, None), size=(dp(64), dp(36)),
        background_normal='', background_down='',
        background_color=M3Tokens.get('surface_container_high'),
        color=M3Tokens.get('on_surface_variant'))
    zoom_bar.add_widget(btn_out)
    zoom_bar.add_widget(Label(text='ZOOM', font_size=11, bold=True,
                              color=M3Tokens.get('on_surface_variant')))
    zoom_bar.add_widget(btn_in)
    zoom_bar.add_widget(zoom_label)
    zoom_bar.add_widget(Widget())
    self._emr_zoom_label = zoom_label

    btn_out.bind(on_press=lambda *_: _contrast_fixed_zoom(self, -0.1))
    btn_in.bind(on_press=lambda *_: _contrast_fixed_zoom(self, 0.1))
    zoom_label.bind(on_press=lambda *_: _contrast_fixed_zoom_reset(self))

    outer = BoxLayout(orientation='vertical', spacing=dp(4), padding=dp(4))
    outer.add_widget(patient_card)
    outer.add_widget(zoom_bar)
    outer.add_widget(zoom_root)

    tab = TabbedPanelItem(text='EMR')
    tab.add_widget(outer)
    self.tp.add_widget(tab)

    # If a patient was selected before opening EMR, display it immediately.
    _hmg_emr_refresh_patient_view(self)
    _contrast_fixed_apply_zoom(self)


