    root.add_widget(Label(text='📜  RECENT ACTIVITY',
                          font_size=15, bold=True, size_hint_y=None,
                          height=dp(25), color=M3Tokens.get('on_surface')))
    self.act_log = TextInput(
        multiline=True, readonly=True, font_size=12,
        size_hint_y=None, height=dp(170), background_normal='',
        background_active='', background_color=M3Tokens.get('surface_container_low'),
        foreground_color=M3Tokens.get('on_surface'))
    root.add_widget(self.act_log)

    scroll.add_widget(root)
    tab.add_widget(scroll)
    self.tp.add_widget(tab)


