HMGBillingApp._hmg_emr_patient_picker = _hmg_emr_patient_picker
HMGBillingApp._hmg_emr_refresh_patient_view = _hmg_emr_refresh_patient_view

# Kivy 2.3.1: repair the actual strip immediately when a tab is added.
# This is earlier and stronger than a delayed Clock repair.
try:
    if not hasattr(CustomTabbedPanel, '_hmg_original_add_widget'):
        CustomTabbedPanel._hmg_original_add_widget = CustomTabbedPanel.add_widget
        def _hmg_ctp_add_widget(self, widget, *args, **kwargs):
            result = self._hmg_original_add_widget(widget, *args, **kwargs)
            try:
                if isinstance(widget, TabbedPanelItem):
                    parent = getattr(widget, 'parent', None)
                    if parent is not None:
                        try:
                            parent.tabbed_panel = self
                        except Exception:
                            pass
                elif isinstance(widget, Widget):
                    # No-op for normal content; retained to avoid touching
                    # Kivy's content-parent semantics.
                    pass
            except Exception as e:
                print(f'[HMG TAB] add_widget repair: {e}')
            return result
        CustomTabbedPanel.add_widget = _hmg_ctp_add_widget
except Exception as e:
    print(f'[HMG TAB] immediate repair setup: {e}')



# ============================================================================
# HMG PERSISTENCE + OFFLINE SYNC PATCH
# - All application JSON is stored in HMG_Reports, not cwd.
# - Public Download/HMG_Reports is preferred on Android when writable.
# - Existing cwd JSON is migrated on first run when the new copy is absent.
# - Manager singletons are redirected before/after login and their literal
#   filenames are replaced by small method wrappers.
# - Patient export/backup/share is available from the Dashboard.
# - Optional server sync supports retry queue + bearer authentication.
# ============================================================================

def _hmg_public_data_dir(self):
    """Return a persistent, user-findable HMG data directory."""
    candidates = []
    if platform == 'android':
        # Prefer a public Download folder so the user can locate/export data.
        candidates += [
            '/storage/emulated/0/Download/HMG_Reports',
            '/sdcard/Download/HMG_Reports',
        ]
        # App-external storage is the reliable fallback on newer Android when
        # direct public-storage writes are restricted.
        try:
            from jnius import autoclass
            PythonActivity = autoclass('org.kivy.android.PythonActivity')
            activity = PythonActivity.mActivity
            if activity is not None:
                ext = activity.getExternalFilesDir(None)
                if ext is not None:
                    candidates.append(os.path.join(
                        ext.getAbsolutePath(), 'HMG_Reports'))
                internal = activity.getFilesDir()
                if internal is not None:
                    candidates.append(os.path.join(
                        internal.getAbsolutePath(), 'HMG_Reports'))
        except Exception:
            pass
    candidates += [
        os.path.join(os.path.expanduser('~'), 'HMG_Reports'),
        os.path.join(os.getcwd(), 'HMG_Reports'),
    ]
    for d in candidates:
        try:
            os.makedirs(d, exist_ok=True)
            probe = os.path.join(d, '.hmg_write_probe')
            with open(probe, 'w', encoding='utf-8') as f:
                f.write('ok')
            os.remove(probe)
            return d
        except Exception:
            continue
    return os.path.join(os.getcwd(), 'HMG_Reports')


def _hmg_data_path_v2(self, filename):
    base = _hmg_public_data_dir(self)
    try:
        os.makedirs(base, exist_ok=True)
    except Exception:
        pass
    return os.path.join(base, filename)


_HMG_PERSIST_FILES = {
    'patients.json': 'patients', 'emr.json': 'emr_records',
    'lab.json': 'lab_tests', 'rad.json': 'radiology',
    'rx.json': 'prescriptions', 'bills.json': 'bills',
    'drugs.json': 'drugs', 'invs.json': 'investigations',
    'ecg.json': 'ecg_reports', 'pathology.json': 'pathology_data',
    'followups.json': 'followups', 'summaries.json': 'patient_summaries',
    'consent_forms.json': 'consent_forms',
    'referral_notes.json': 'referral_notes',
    'daily_notes.json': 'daily_notes', 'snapshots.json': 'patient_snapshots',
    'procedures_db.json': 'procedures_db',
    'lab_results.json': 'lab_results', 'tasks.json': 'tasks',
    'admissions.json': 'admissions',
    'saved_lab_reports.json': 'saved_lab_reports',
    'appointments.json': 'appointments', 'nursing_notes.json': 'nursing_notes',
    'transfers.json': 'transfers',
}


def _hmg_normalize_loaded(self, attr, data):
    # Preserve the production loader's drug/investigation compatibility rules.
    if attr == 'drugs' and isinstance(data, list):
        data = [{
            'name': d.get('name', ''), 'price': d.get('price', 0),
            'qty': d.get('qty', d.get('quantity', 0)),
            'min': d.get('min', d.get('min_stock', 20)),
            'cat': d.get('cat', d.get('category', '')),
            'mfr': d.get('mfr', d.get('manufacturer', '')),
            'exp': d.get('exp', ''), 'batch': d.get('batch', '')
        } for d in data if isinstance(d, dict)]
    elif attr == 'investigations' and isinstance(data, list):
        data = [{
            'name': inv.get('name', ''), 'price': inv.get('price', 0),
            'dept': inv.get('dept', inv.get('department', '')),
            'cat': inv.get('cat', inv.get('category', '')),
            'tat': inv.get('tat', ''), 'specimen': inv.get('specimen', ''),
            'ref': inv.get('ref', ''), 'unit': inv.get('unit', ''),
            'desc': inv.get('desc', ''),
            'result_type': inv.get('result_type', 'text'),
            'allowed_units': inv.get('allowed_units', []),
            'default_unit': inv.get('default_unit', ''),
            'qualitative_options': inv.get('qualitative_options', []),
            'reference': inv.get('reference', ''),
        } for inv in data if isinstance(inv, dict)]
    if attr == 'tasks' and hasattr(self, 'task_manager'):
        self.task_manager.tasks = data
    setattr(self, attr, data)


def _hmg_load_all_v2(self, *a, **kw):
    """Load persistent data from HMG_Reports, migrating legacy cwd files once."""
    base = self._hmg_data_path('patients.json').rsplit(os.sep, 1)[0]
    loaded = 0
    migrated = 0
    for fn, attr in _HMG_PERSIST_FILES.items():
        new_path = self._hmg_data_path(fn)
        old_path = os.path.join(os.getcwd(), fn)
        path = new_path if os.path.exists(new_path) else old_path
        if not os.path.exists(path):
            continue
        try:
            with open(path, 'r', encoding='utf-8') as f:
                data = json.load(f)
            _hmg_normalize_loaded(self, attr, data)
            loaded += 1
            if path == old_path and os.path.abspath(old_path) != os.path.abspath(new_path):
                try:
                    shutil.copy2(old_path, new_path)
                    migrated += 1
                except Exception as e:
                    print(f'[HMG] migration {fn}: {e}')
        except Exception as e:
            print(f'[HMG] load {fn}: {e}')
    print(f'[HMG] persistent load: {loaded} files; migrated {migrated}; dir={base}')
    # Keep task manager synchronized with the authoritative patient-app data.
    try:
        if hasattr(self, 'task_manager'):
            self.task_manager.tasks = self.tasks
    except Exception:
        pass


def _hmg_save_all_v2(self, *a, **kw):
    """Atomically save all core JSON to the persistent HMG_Reports directory."""
    data = {fn: getattr(self, attr, []) for fn, attr in _HMG_PERSIST_FILES.items()}
    ok = fail = 0
    for fn, value in data.items():
        try:
            path = self._hmg_data_path(fn)
            os.makedirs(os.path.dirname(path), exist_ok=True)
            self._save_json(path, value)
            if os.path.exists(path):
                ok += 1
            else:
                fail += 1
        except Exception as e:
            fail += 1
            print(f'[HMG] save {fn}: {e}')
    try:
        if hasattr(self, 'task_manager'):
            self.task_manager.tasks = self.tasks
    except Exception:
        pass
    print(f'[HMG] persistent save: {ok} ok, {fail} failed')
    # Queue the latest patient snapshot for optional server synchronization.
    try:
        self._queue_patient_sync()
    except Exception as e:
        print(f'[HMG SYNC] queue: {e}')
    return ok, fail


# Install the authoritative persistence methods.
HMGBillingApp._get_reports_dir = _hmg_public_data_dir
HMGBillingApp._hmg_data_path = _hmg_data_path_v2
HMGBillingApp.load_all = _hmg_load_all_v2
HMGBillingApp.save_all = _hmg_save_all_v2


def _hmg_manager_paths(self):
    """Redirect singleton managers to the same persistent directory."""
    base = self._get_reports_dir()
    try:
        os.makedirs(base, exist_ok=True)
    except Exception:
        pass

    def migrate(old, new):
        if os.path.exists(old) and not os.path.exists(new):
            try:
                shutil.copy2(old, new)
                print(f'[HMG] migrated manager file: {old} -> {new}')
            except Exception as e:
                print(f'[HMG] manager migration {old}: {e}')

    # Managers created during build have already loaded legacy files. Redirect
    # their future writes and copy legacy data if the new location is empty.
    if hasattr(self, 'user_manager'):
        old = getattr(self.user_manager, 'USERS_FILE', 'users.json')
        new = os.path.join(base, 'users.json')
        migrate(old, new)
        self.user_manager.USERS_FILE = new
    if hasattr(self, 'audit'):
        old = getattr(self.audit, 'LOG_FILE', 'audit.json')
        new = os.path.join(base, 'audit.json')
        migrate(old, new)
        self.audit.LOG_FILE = new
    if hasattr(self, 'task_manager'):
        task_old = 'tasks.json'
        task_new = os.path.join(base, 'tasks.json')
        migrate(task_old, task_new)
        self.task_manager._hmg_file = task_new
        # Move existing in-memory tasks into the authoritative app list.
        try:
            self.task_manager.tasks = self.tasks
        except Exception:
            pass
    if hasattr(self, 'pt_tracker'):
        pay_old = 'payments.json'
        pay_new = os.path.join(base, 'payments.json')
        migrate(pay_old, pay_new)
        self.pt_tracker._hmg_file = pay_new
    if hasattr(self, 'chat_sys'):
        chat_old = 'chat.json'
        chat_new = os.path.join(base, 'chat.json')
        migrate(chat_old, chat_new)
        self.chat_sys._hmg_file = chat_new
    if hasattr(self, 'ai'):
        ai_old = 'ai_settings.json'
        ai_new = os.path.join(base, 'ai_settings.json')
        migrate(ai_old, ai_new)
        self.ai._hmg_file = ai_new
    self._hmg_manager_paths_ready = True
    print(f'[HMG] manager data dir = {base}')

HMGBillingApp._hmg_manager_paths = _hmg_manager_paths


