def _hmg_configure_managers_after_build(self):
    """Run immediately after manager construction, before the login screen."""
    try:
        self._hmg_manager_paths()
        # Reload managers from their new paths after migration.
        if hasattr(self, 'user_manager'):
            self.user_manager.load()
            self.user_manager._ensure_default_admin()
        if hasattr(self, 'audit'):
            self.audit.load()
        if hasattr(self, 'task_manager'):
            self.task_manager._hmg_file = os.path.join(self._get_reports_dir(), 'tasks.json')
            self.task_manager.load()
        if hasattr(self, 'pt_tracker'):
            self.pt_tracker._hmg_file = os.path.join(self._get_reports_dir(), 'payments.json')
            self.pt_tracker.load = lambda: None
            path = self.pt_tracker._hmg_file
            if os.path.exists(path):
                with open(path, 'r', encoding='utf-8') as f:
                    self.pt_tracker.payments = json.load(f)
        if hasattr(self, 'chat_sys'):
            self.chat_sys._hmg_file = os.path.join(self._get_reports_dir(), 'chat.json')
            self.chat_sys.load = lambda: None
            _chat_load_persistent(self.chat_sys)
        if hasattr(self, 'ai'):
            self.ai._hmg_file = os.path.join(self._get_reports_dir(), 'ai_settings.json')
            self.ai.load()
    except Exception as e:
        print(f'[HMG] manager startup redirect: {e}')

# Wrap build once so manager files are redirected before the user logs in.
if not getattr(HMGBillingApp, '_hmg_build_persistence_patched', False):
    _hmg_original_build = HMGBillingApp.build
    def _hmg_build_with_persistence(self, *a, **kw):
        root = _hmg_original_build(self, *a, **kw)
        try:
            self._hmg_configure_managers_after_build()
        except Exception as e:
            print(f'[HMG] build persistence setup: {e}')
        return root
    HMGBillingApp.build = _hmg_build_with_persistence
    HMGBillingApp._hmg_build_persistence_patched = True

# Also make login safe: if a previous screen/build path recreated managers,
# redirect them again and reload the persistent core data.
if not getattr(HMGBillingApp, '_hmg_login_persistence_patched', False):
    _hmg_original_login = HMGBillingApp._on_login_success
    def _hmg_login_with_persistence(self, user):
        try:
            self._hmg_manager_paths()
            self.load_all()
        except Exception as e:
            print(f'[HMG] pre-login persistence load: {e}')
        _hmg_original_login(self, user)
        try:
            self._hmg_manager_paths()
            self.load_all()
        except Exception as e:
            print(f'[HMG] post-login persistence load: {e}')
    HMGBillingApp._on_login_success = _hmg_login_with_persistence
    HMGBillingApp._hmg_login_persistence_patched = True


# ---------------------------- Offline sync queue ----------------------------
def _hmg_sync_config_path(self):
    return self._hmg_data_path('sync_config.json')


def _hmg_sync_queue_path(self):
    return self._hmg_data_path('sync_queue.json')


def _hmg_load_sync_config(self):
    path = self._hmg_sync_config_path()
    try:
        if os.path.exists(path):
            with open(path, 'r', encoding='utf-8') as f:
                return json.load(f)
    except Exception as e:
        print(f'[HMG SYNC] config load: {e}')
    return {'endpoint': '', 'token': '', 'last_synced': '', 'last_error': ''}


def _hmg_save_sync_config(self, cfg):
    try:
        self._save_json(self._hmg_sync_config_path(), cfg)
    except Exception as e:
        print(f'[HMG SYNC] config save: {e}')


def _hmg_queue_patient_sync(self):
    """Queue a compact patient snapshot only when it has changed."""
    patients = getattr(self, 'patients', []) or []
    try:
        payload_text = json.dumps(patients, sort_keys=True, default=str, ensure_ascii=False)
        digest = hashlib.sha256(payload_text.encode('utf-8')).hexdigest()
        qpath = self._hmg_sync_queue_path()
        queue = []
        if os.path.exists(qpath):
            with open(qpath, 'r', encoding='utf-8') as f:
                queue = json.load(f)
        if queue and queue[-1].get('digest') == digest:
            return
        queue.append({
            'queued_at': datetime.now().isoformat(),
            'digest': digest,
            'patients': patients,
        })
        # Keep only the latest few states; the latest state contains all current
        # patients, so older snapshots are redundant.
        queue = queue[-5:]
        self._save_json(qpath, queue)
    except Exception as e:
        print(f'[HMG SYNC] queue write: {e}')


def _hmg_sync_patients_to_server(self, endpoint=None, token=None, timeout=30, instance=None):
    """Upload patients to an HTTP endpoint; failures remain queued offline.

    Expected server contract: POST JSON containing {patients, synced_at}.
    Authentication, when supplied, is sent as Authorization: Bearer <token>.
    Returns (success, message). The endpoint can also be stored in
    HMG_Reports/sync_config.json as {"endpoint":"...","token":"..."}.
    """
    cfg = self._hmg_load_sync_config()
    endpoint = (endpoint or cfg.get('endpoint', '')).strip()
    token = token if token is not None else cfg.get('token', '')
    self._queue_patient_sync()
    if not endpoint:
        return False, 'No sync endpoint configured. Patients remain safely queued offline.'

    qpath = self._hmg_sync_queue_path()
    try:
        with open(qpath, 'r', encoding='utf-8') as f:
            queue = json.load(f)
    except Exception:
        queue = []
    if not queue:
        return True, 'Nothing to synchronize.'

    headers = {'Content-Type': 'application/json'}
    if token:
        headers['Authorization'] = f'Bearer {token}'

    # requests is already used by the application's AI layer. Use it when
    # available; otherwise fail safely and retain the queue.
    if not REQUESTS_AVAILABLE:
        cfg['last_error'] = 'HTTP client unavailable'
        self._hmg_save_sync_config(cfg)
        return False, 'HTTP client unavailable; data remains queued.'

    last_error = ''
    # Send oldest -> newest. On a failure, stop and retain the unsent queue.
    for i, item in enumerate(list(queue)):
        try:
            payload = {
                'patients': item.get('patients', []),
                'synced_at': datetime.now().isoformat(),
                'client': 'HMG Hospital EMR',
                'digest': item.get('digest', ''),
            }
            r = requests.post(endpoint, headers=headers, json=payload, timeout=timeout)
            if 200 <= r.status_code < 300:
                continue
            last_error = f'HTTP {r.status_code}: {getattr(r, "text", "")[:300]}'
            queue = queue[i:]
            break
        except Exception as e:
            last_error = str(e)
            queue = queue[i:]
            break
    else:
        queue = []

    try:
        self._save_json(qpath, queue)
    except Exception as e:
        print(f'[HMG SYNC] queue update: {e}')

    if last_error:
        cfg['last_error'] = last_error
        self._hmg_save_sync_config(cfg)
        return False, f'Sync failed; retained offline queue. {last_error}'

    cfg['last_synced'] = datetime.now().isoformat()
    cfg['last_error'] = ''
    cfg['endpoint'] = endpoint
    if token is not None:
        cfg['token'] = token
    self._hmg_save_sync_config(cfg)
    try:
        self.audit_log('PATIENT_SYNC', f'Patients synchronized to {endpoint}')
    except Exception:
        pass
    return True, 'Patient data synchronized successfully.'


def _hmg_retry_sync_queue(self, *args, **kwargs):
    """Retry pending synchronization without disrupting the EMR UI."""
    try:
        ok, msg = self._sync_patients_to_server(*args, **kwargs)
        print(f'[HMG SYNC] retry: {msg}')
        return ok, msg
    except Exception as e:
        print(f'[HMG SYNC] retry error: {e}')
        return False, str(e)


def _hmg_sync_server_configure(self, endpoint, token=''):
    cfg = self._hmg_load_sync_config()
    cfg['endpoint'] = str(endpoint or '').strip()
    cfg['token'] = str(token or '').strip()
    self._hmg_save_sync_config(cfg)
    return cfg

HMGBillingApp._sync_patients_to_server = _hmg_sync_patients_to_server
HMGBillingApp._retry_sync_queue = _hmg_retry_sync_queue
HMGBillingApp._configure_patient_sync = _hmg_sync_server_configure
HMGBillingApp._queue_patient_sync = _hmg_queue_patient_sync
HMGBillingApp._hmg_sync_config_path = _hmg_sync_config_path
HMGBillingApp._hmg_sync_queue_path = _hmg_sync_queue_path
HMGBillingApp._hmg_load_sync_config = _hmg_load_sync_config
HMGBillingApp._hmg_save_sync_config = _hmg_save_sync_config


def _hmg_start_sync_retry(self):
    """Retry queued data periodically; no endpoint means no network activity."""
    try:
        if getattr(self, '_hmg_sync_event', None):
            self._hmg_sync_event.cancel()
    except Exception:
        pass
    def _retry(_dt):
        try:
            # Do not touch the sync queue while the login screen is active;
            # the clinical data collections are created in _build_main_app().
            if not hasattr(self, 'patients'):
                return
            cfg = self._hmg_load_sync_config()
            if cfg.get('endpoint'):
                self._retry_sync_queue(endpoint=cfg.get('endpoint'), token=cfg.get('token'))
        except Exception as e:
            print(f'[HMG SYNC] scheduled retry: {e}')
    self._hmg_sync_event = Clock.schedule_interval(_retry, 300)  # every 5 min

HMGBillingApp._hmg_start_sync_retry = _hmg_start_sync_retry


# ---------------------------- Dashboard upload UI ----------------------------
def _hmg_upload_patients_menu_v2(self, instance=None):
    content = BoxLayout(orientation='vertical', spacing=dp(10), padding=dp(12))
    content.add_widget(Label(
        text=(f'Patients stored: {len(getattr(self, "patients", []))}\n'
              f'Persistent folder:\n{self._get_reports_dir()}'),
        font_size=12, size_hint_y=None, height=dp(62)))
    pp = Popup(title='Upload / Export Patients', content=content,
               size_hint=(0.94, 0.68))

    def close(*_):
        pp.dismiss()

    def csv_share(*_):
        try:
            pp.dismiss()
            self._export_csv(None)
            # Current _export_csv writes cwd. Locate the newest CSV and copy it
            # into the persistent/public HMG folder before sharing.
            latest = max((os.path.join(os.getcwd(), f)
                          for f in os.listdir(os.getcwd())
                          if f.startswith('patients_') and f.endswith('.csv')),
                         key=os.path.getmtime, default=None)
            if latest:
                dst = self._hmg_data_path(os.path.basename(latest))
                shutil.copy2(latest, dst)
                self._save_to_public_downloads(dst)
                self._share_file(dst)
        except Exception as e:
            self._popup('Export Error', str(e))

    def backup_share(*_):
        try:
            pp.dismiss()
            self._backup_data(None)
            bdir = os.path.join(self._get_reports_dir(), 'backups')
            if os.path.isdir(bdir):
                newest = max((os.path.join(bdir, f) for f in os.listdir(bdir)
                              if os.path.isfile(os.path.join(bdir, f))),
                             key=os.path.getmtime, default=None)
                if newest:
                    self._save_to_public_downloads(newest)
                    self._share_file(newest)
        except Exception as e:
            self._popup('Backup Error', str(e))

    def json_share(*_):
        pp.dismiss()
        src = self._hmg_data_path('patients.json')
        if os.path.exists(src):
            self._save_to_public_downloads(src)
            self._share_file(src)
        else:
            self._popup('Patients', 'patients.json has not been created yet.')

    def sync_now(*_):
        pp.dismiss()
        ok, msg = self._sync_patients_to_server()
        self._popup('Patient Sync', msg)

    for txt, cb in [
        ('EXPORT CSV → SHARE', csv_share),
        ('BACKUP EVERYTHING (JSON) → SHARE', backup_share),
        ('SHARE patients.json', json_share),
        ('SYNC TO SERVER / RETRY QUEUE', sync_now),
        ('CLOSE', close),
    ]:
        b = HMGButton(text=txt, size_hint_y=None, height=dp(48),
                      background_normal='',
                      background_color=get_color_from_hex('#3F51B5'))
        b.bind(on_press=cb)
        content.add_widget(b)
    pp.open()

HMGBillingApp._upload_patients_menu = _hmg_upload_patients_menu_v2

# Ensure the dashboard gets an upload action after its 3-column grid exists.
def _hmg_install_upload_button_v2(self, _attempt=0):
    # Build is asynchronous on Android; retry until the TabbedPanel/dashboard
    # actually exists instead of assuming a fixed startup delay.
    if getattr(self, '_upload_btn_done', False):
        return
    tp = getattr(self, 'tp', None)
    if tp is None or not getattr(tp, 'tab_list', None):
        if _attempt < 40:
            Clock.schedule_once(
                lambda dt: self._install_upload_button(_attempt + 1), 0.25)
        else:
            print('[HMG] upload button: gave up waiting for tp')
        return
    try:
        for tab in getattr(tp, 'tab_list', []):
            if getattr(tab, 'text', '') != 'Dashboard':
                continue
            def walk(w):
                try:
                    from kivy.uix.gridlayout import GridLayout
                    if isinstance(w, GridLayout) and getattr(w, 'cols', 0) == 3:
                        # Avoid duplicate installation.
                        if any(getattr(c, 'text', '') == '⬆  UPLOAD PATIENTS'
                               for c in getattr(w, 'children', [])):
                            return True
                        b = HMGButton(text='⬆  UPLOAD PATIENTS',
                                      font_size=11, bold=True,
                                      size_hint_y=None, height=dp(58),
                                      background_normal='',
                                      background_color=get_color_from_hex('#27ae60'))
                        b.bind(on_press=self._upload_patients_menu)
                        w.add_widget(b)
                        self._upload_btn_done = True
                        print('[HMG] upload button installed')
                        return True
                except Exception:
                    pass
                for c in getattr(w, 'children', []):
                    if walk(c):
                        return True
                return False
            if walk(tab):
                return
        if _attempt < 40:
            Clock.schedule_once(
                lambda dt: self._install_upload_button(_attempt + 1), 0.25)
    except Exception as e:
        print(f'[HMG] upload button install: {e}')
        if _attempt < 40:
            Clock.schedule_once(
                lambda dt: self._install_upload_button(_attempt + 1), 0.25)

HMGBillingApp._install_upload_button = _hmg_install_upload_button_v2

if not getattr(HMGBillingApp, '_hmg_upload_build_patched', False):
    _hmg_build_before_upload = HMGBillingApp.build
    def _hmg_build_with_upload_and_sync(self, *a, **kw):
        root = _hmg_build_before_upload(self, *a, **kw)
        Clock.schedule_once(lambda dt: self._install_upload_button(0), 0.25)
        Clock.schedule_once(lambda dt: self._hmg_start_sync_retry(), 2.0)
        return root
    HMGBillingApp.build = _hmg_build_with_upload_and_sync
    HMGBillingApp._hmg_upload_build_patched = True

# Diagnostic helper for Android/Pydroid logs.
