_wrapped = 0
for _name in _HMG_HANDLERS:
    _fn = getattr(HMGBillingApp, _name, None)
    if _fn is None or not callable(_fn) or getattr(_fn, '_hmg_arity_safe', False):
        continue
    try:
        _sig = _hmg_inspect.signature(_fn)
        _params = list(_sig.parameters)
    except (TypeError, ValueError):
        continue
    if len(_params) < 2 or _params[1] != 'instance':
        continue
    @_hmg_functools.wraps(_fn)
    def _safe(self, instance=None, *args, _fn=_fn, **kwargs):
        try:
            return _fn(self, instance, *args, **kwargs)
        except TypeError as e:
            print(f'[HMG] handler {_fn.__name__}: {e}')
            return None
    _safe._hmg_arity_safe = True
    setattr(HMGBillingApp, _name, _safe)
    _wrapped += 1

print(f'[HMG ARITY GUARD] wrapped {_wrapped} handlers')

