def _hmg_persist_logo_signature(self):
    """Restore facility logo/signature paths from persistent FacilityConfig."""
    try:
        facility = getattr(self, 'facility', None)
        if facility is None:
            return
        logo = facility.get('logo_path', '') or ''
        sig = facility.get('signature_path', '') or ''
        self.rpt_logo_path = logo if logo and os.path.exists(logo) else None
        self.rpt_signature_path = sig if sig and os.path.exists(sig) else None
        if hasattr(self, 'rpt_logo_label'):
            self.rpt_logo_label.text = os.path.basename(self.rpt_logo_path) if self.rpt_logo_path else '(none attached)'
        if hasattr(self, 'rpt_sig_label'):
            self.rpt_sig_label.text = os.path.basename(self.rpt_signature_path) if self.rpt_signature_path else '(none attached)'
        print(f"[HMG] restored logo={bool(self.rpt_logo_path)} signature={bool(self.rpt_signature_path)}")
    except Exception as e:
        print(f"[HMG] persist logo/sig: {e}")


def _hmg_set_report_image_persistent(self, target, path):
    if path and not os.path.exists(path):
        self._popup('Error', f'File not found: {path}')
        return
    try:
        if target == 'logo':
            self.rpt_logo_path = path
            if hasattr(self, 'rpt_logo_label'):
                self.rpt_logo_label.text = os.path.basename(path) if path else '(none attached)'
            self.facility.set('logo_path', path or '')
        else:
            self.rpt_signature_path = path
            if hasattr(self, 'rpt_sig_label'):
                self.rpt_sig_label.text = os.path.basename(path) if path else '(none attached)'
            self.facility.set('signature_path', path or '')
        self.facility.FILE = os.path.join(self._get_reports_dir(), FacilityConfig.FILE)
        self.facility.save()
        if hasattr(self, 'log_activity'):
            self.log_activity(f"Report {target} {'attached' if path else 'cleared'}: {path or ''}")
    except Exception as e:
        print(f"[HMG] facility save on image attach: {e}")

HMGBillingApp._set_report_image = _hmg_set_report_image_persistent

