def _mature_dashboard(self):
    from kivy.uix.scrollview import ScrollView
    from kivy.uix.gridlayout import GridLayout
    from kivy.uix.tabbedpanel import TabbedPanelItem
    surface = get_color_from_hex(M3Tokens.get('surface'))
    surface_low = get_color_from_hex(M3Tokens.get('surface_container_low'))
    surface_high = get_color_from_hex(M3Tokens.get('surface_container_high'))
    surface_highest = get_color_from_hex(M3Tokens.get('surface_container_highest'))
    on_surface = get_color_from_hex(M3Tokens.get('on_surface'))
    on_surface_v = get_color_from_hex(M3Tokens.get('on_surface_variant'))
    outline = get_color_from_hex(M3Tokens.get('outline_variant'))
    primary = get_color_from_hex(M3Tokens.get('primary'))
    stat_accent = {
        'Patients': primary, 'Today': get_color_from_hex('#3A5A40'),
        'Pending': get_color_from_hex('#8C4A3C'), 'Stock': get_color_from_hex('#6E5A2A'),
        'LIS': get_color_from_hex('#2E5266'), 'Tasks': get_color_from_hex('#5B3A52')}
    tab = TabbedPanelItem(text='Dashboard')
    scroll = ScrollView(bar_width=dp(4))
    root = BoxLayout(orientation='vertical', padding=(dp(12),dp(12),dp(12),dp(20)), spacing=dp(14), size_hint_y=None)
    root.bind(minimum_height=root.setter('height'))
    def section_label(txt):
        return Label(text=txt, font_size=12, bold=True, size_hint_y=None, height=dp(22), color=on_surface_v, halign='left', valign='middle')
    root.add_widget(section_label('OVERVIEW'))
    grid = GridLayout(cols=3, size_hint_y=None, spacing=dp(8)); grid.bind(minimum_height=grid.setter('height'))
    self.stats = {}
    for title in ('Patients','Today','Pending','Stock','LIS','Tasks'):
        card=BoxLayout(orientation='vertical',size_hint_y=None,height=dp(84),padding=dp(10),spacing=dp(2))
        with card.canvas.before:
            Color(*surface_low); bg=RoundedRectangle(pos=card.pos,size=card.size,radius=[dp(14)])
            Color(*outline); ol=Line(rounded_rectangle=(card.x,card.y,card.width,card.height,dp(14)),width=1)
        def _u(*_,c=card,b=bg,o=ol): b.pos,b.size=c.pos,c.size; o.rounded_rectangle=(c.x,c.y,c.width,c.height,dp(14))
        card.bind(pos=_u,size=_u)
        val=Label(text='0',font_size=22,bold=True,color=stat_accent[title],size_hint_y=None,height=dp(34),halign='center',valign='middle')
        cap=Label(text=title.upper(),font_size=10,bold=True,color=on_surface_v,size_hint_y=None,height=dp(18),halign='center',valign='middle')
        card.add_widget(val); card.add_widget(cap); self.stats[title]=val; grid.add_widget(card)
    root.add_widget(grid)
    root.add_widget(section_label('WORKSPACE'))
    actions=[('Registration','Registration'),('EMR','EMR'),('Clinical AI','Clinical AI'),('Clinical Summary','Clinical Summary'),('Vitals Timeline','Vitals Timeline'),('Daily Notes','Daily Notes'),('Admissions','Admissions'),('Transfer','Transfer'),('Appointments','Appointments'),('Nursing Notes','Nursing Notes'),('Tasks','Tasks'),('Procedures','Procedures'),('Liver Span','Liver Span'),('ECG Analysis','ECG Analysis'),('Laboratory','Laboratory'),('Enhanced Lab','Enhanced Lab'),('LIS Connections','LIS Connections'),('Pathology AI','Pathology AI'),('Radiology','Radiology'),('Upload/Results','Upload/Results'),('Billing','Billing'),('Payments','Payments'),('Pharmacy','Pharmacy'),('Pharmacy Dispense','Pharmacy Dispense'),('Upload Patients','Upload Patients'),('Settings','Settings')]
    agrid=GridLayout(cols=3,size_hint_y=None,spacing=dp(8)); agrid.bind(minimum_height=agrid.setter('height'))
    for label,target in actions:
        b=_PlainKivyButton(text=label,font_size=12,bold=False,size_hint_y=None,height=dp(62),background_normal='',background_down='',background_color=surface_high,color=on_surface,halign='center',valign='middle')
        b.bind(state=lambda w,s: setattr(w,'background_color',surface_highest if s=='down' else surface_high))
        if target=='Upload Patients': b.bind(on_press=lambda *_: self._upload_patients_menu())
        else: b.bind(on_press=lambda _b,t=target: self._switch(t))
        agrid.add_widget(b)
    root.add_widget(agrid)
    root.add_widget(section_label('ACTIVITY'))
    self.act_log=TextInput(multiline=True,readonly=True,font_size=12,size_hint_y=None,height=dp(190),background_normal='',background_active='',background_color=surface_low,foreground_color=on_surface,cursor_color=primary)
    root.add_widget(self.act_log); scroll.add_widget(root); tab.add_widget(scroll); self.tp.add_widget(tab)
HMGBillingApp._dashboard = _mature_dashboard
