# ============================================================================
# HMG CLINICAL / DATA INTEGRITY HARDENING V1
# Purpose: strengthen the current single-file production build without
# replacing its working clinical UI.  This is an incremental safety layer.
# ============================================================================
try:
    import sqlite3 as _hmg_sqlite3
    from uuid import uuid4 as _hmg_uuid4
    import math as _hmg_math
except Exception as _hmg_core_import_error:
    print(f"[HMG HARDEN] core import: {_hmg_core_import_error}")

_HMG_SCHEMA_VERSION = 2
_HMG_DB_NAME = "HMG_EMR.sqlite3"

class HMGTransactionalStore:
    """SQLite snapshot store.

    The existing JSON files remain as a compatibility/export layer, but a
    complete application snapshot is also committed in one SQLite transaction.
    This prevents the app from having to treat 24 independently-written JSON
    files as if they were one transaction.
    """
    COLLECTIONS = (
        "patients", "emr_records", "lab_tests", "radiology", "prescriptions",
        "bills", "drugs", "investigations", "ecg_reports", "pathology_data",
        "followups", "patient_summaries", "consent_forms", "referral_notes",
        "daily_notes", "patient_snapshots", "procedures_db", "lab_results",
        "tasks", "admissions", "saved_lab_reports", "appointments",
        "nursing_notes", "transfers"
    )
    def __init__(self, app):
        self.app = app
        self.path = os.path.join(app._get_reports_dir(), _HMG_DB_NAME)
        self._init_db()

    def _connect(self):
        c = _hmg_sqlite3.connect(self.path, timeout=15)
        c.execute("PRAGMA journal_mode=WAL")
        c.execute("PRAGMA synchronous=FULL")
        c.execute("PRAGMA foreign_keys=ON")
        return c

    def _init_db(self):
        os.makedirs(os.path.dirname(self.path), exist_ok=True)
        with self._connect() as c:
            c.execute("CREATE TABLE IF NOT EXISTS meta (key TEXT PRIMARY KEY, value TEXT NOT NULL)")
            c.execute("CREATE TABLE IF NOT EXISTS snapshots (name TEXT PRIMARY KEY, payload TEXT NOT NULL, schema_version INTEGER NOT NULL)")
            c.execute("CREATE TABLE IF NOT EXISTS audit_snapshots (snapshot_id TEXT PRIMARY KEY, created_at TEXT NOT NULL, schema_version INTEGER NOT NULL, item_count INTEGER NOT NULL)")

    @staticmethod
    def _json(value):
        return json.dumps(value, ensure_ascii=False, separators=(",", ":"), default=str)

    def save_snapshot(self):
        snapshot_id = str(_hmg_uuid4())
        now = datetime.now().strftime("%Y-%m-%d %H:%M:%S")
        rows = []
        for name in self.COLLECTIONS:
            rows.append((name, self._json(getattr(self.app, name, [])), _HMG_SCHEMA_VERSION))
        with self._connect() as c:
            c.execute("BEGIN IMMEDIATE")
            c.executemany("INSERT OR REPLACE INTO snapshots(name,payload,schema_version) VALUES(?,?,?)", rows)
            total = sum(len(getattr(self.app, n, {}) or {}) if isinstance(getattr(self.app, n, {}), dict) else len(getattr(self.app, n, []) or []) for n in self.COLLECTIONS)
            c.execute("INSERT INTO audit_snapshots(snapshot_id,created_at,schema_version,item_count) VALUES(?,?,?,?)", (snapshot_id, now, _HMG_SCHEMA_VERSION, total))
            c.execute("INSERT OR REPLACE INTO meta(key,value) VALUES('last_snapshot_id',?)", (snapshot_id,))
            c.execute("INSERT OR REPLACE INTO meta(key,value) VALUES('last_snapshot_at',?)", (now,))
            c.execute("INSERT OR REPLACE INTO meta(key,value) VALUES('schema_version',?)", (str(_HMG_SCHEMA_VERSION),))
            c.execute("COMMIT")
        return snapshot_id

    def load_snapshot(self):
        with self._connect() as c:
            ver = c.execute("SELECT value FROM meta WHERE key='schema_version'").fetchone()
            if not ver or int(ver[0]) > _HMG_SCHEMA_VERSION:
                raise RuntimeError(f"Database schema {ver[0] if ver else '?'} is newer than app schema {_HMG_SCHEMA_VERSION}")
            rows = c.execute("SELECT name,payload,schema_version FROM snapshots").fetchall()
        if not rows:
            return False
        loaded = 0
        for name, payload, schema_version in rows:
            if name not in self.COLLECTIONS:
                continue
            setattr(self.app, name, json.loads(payload))
            loaded += 1
        if "tasks" in self.COLLECTIONS:
            try:
                self.app.tasks = self.app.task_manager.tasks = getattr(self.app, "tasks", [])
            except Exception:
                pass
        print(f"[HMG STORE] restored {loaded}/{len(self.COLLECTIONS)} collections from SQLite snapshot")
        return loaded == len(self.COLLECTIONS)


def _hmg_json_envelope(data):
    return {"__schema_version__": _HMG_SCHEMA_VERSION,
            "__saved_at__": datetime.now().strftime("%Y-%m-%d %H:%M:%S"),
            "data": data}

# Add a schema manifest without changing the shape of existing JSON files.
# This preserves compatibility with the current loaders and external exports.
_HMG_ORIG_SAVE_JSON = getattr(HMGBillingApp, "_save_json", None)
if callable(_HMG_ORIG_SAVE_JSON):
    def _hmg_save_json_versioned(self, filename, data, max_backups=3):
        result = _HMG_ORIG_SAVE_JSON(self, filename, data, max_backups)
        try:
            manifest_path = os.path.join(self._get_reports_dir(), "schema_manifest.json")
            existing = {}
            if os.path.exists(manifest_path):
                with open(manifest_path, "r", encoding="utf-8") as mf:
                    _loaded_manifest = json.load(mf)
                    existing = _loaded_manifest if isinstance(_loaded_manifest, dict) else {}
        except Exception:
            existing = {}
        try:
            existing[str(os.path.basename(filename))] = {
                "schema_version": _HMG_SCHEMA_VERSION,
                "saved_at": datetime.now().strftime("%Y-%m-%d %H:%M:%S")
            }
            tmp = manifest_path + ".tmp"
            with open(tmp, "w", encoding="utf-8") as mf:
                json.dump(existing, mf, indent=2, ensure_ascii=False)
            os.replace(tmp, manifest_path)
        except Exception as e:
            print(f"[HMG SCHEMA] manifest update: {e}")
        return result
    HMGBillingApp._save_json = _hmg_save_json_versioned

_HMG_ORIG_LOAD_ALL = getattr(HMGBillingApp, "load_all", None)
if callable(_HMG_ORIG_LOAD_ALL):
    def _hmg_load_all_hardened(self):
        # Prefer the transactionally committed SQLite snapshot when present.
        try:
            self._hmg_store = HMGTransactionalStore(self)
            if self._hmg_store.load_snapshot():
                return
        except Exception as e:
            print(f"[HMG STORE] snapshot restore skipped: {e}")
        _HMG_ORIG_LOAD_ALL(self)
    HMGBillingApp.load_all = _hmg_load_all_hardened

_HMG_ORIG_SAVE_ALL = getattr(HMGBillingApp, "save_all", None)
if callable(_HMG_ORIG_SAVE_ALL):
    def _hmg_save_all_transactional(self):
        try:
            if not hasattr(self, "_hmg_store"):
                self._hmg_store = HMGTransactionalStore(self)
            snapshot_id = self._hmg_store.save_snapshot()
            self._hmg_last_snapshot_id = snapshot_id
        except Exception as e:
            print(f"[HMG STORE] SQLite transaction failed: {e}")
        return _HMG_ORIG_SAVE_ALL(self)
    HMGBillingApp.save_all = _hmg_save_all_transactional

# ----------------------------- Identity discipline --------------------------
def _hmg_new_patient_id(existing=None):
    existing = set(existing or [])
    for _ in range(5):
        pid = "PT-" + datetime.now().strftime("%Y%m%d") + "-" + _hmg_uuid4().hex[:10].upper()
        if pid not in existing:
            return pid
    return "PT-" + _hmg_uuid4().hex.upper()

_HMG_ORIG_REG = getattr(HMGBillingApp, "_reg_pt", None)
if callable(_HMG_ORIG_REG):
    def _hmg_reg_unique(self, instance):
        try:
            if hasattr(self, "rw") and "id" in self.rw:
                old = self.rw["id"].text.strip()
                ids = [str(x.get("id", "")) for x in getattr(self, "patients", [])]
                if not old or old in ids or len(old) < 8:
                    self.rw["id"].text = _hmg_new_patient_id(ids)
                # Duplicate identity warning, without silently merging records.
                nm = self.rw.get("name").text.strip().lower() if self.rw.get("name") else ""
                phone = self.rw.get("phone").text.strip() if self.rw.get("phone") else ""
                dob = self.rw.get("dob").text.strip() if self.rw.get("dob") else ""
                possible = [p for p in self.patients if nm and p.get("name", "").strip().lower() == nm and
                            (not phone or str(p.get("phone", "")).strip() == phone) and
                            (not dob or str(p.get("dob", "")).strip() == dob)]
                if possible:
                    self._popup("Possible duplicate patient",
                                "A patient with the same name, DOB and phone already exists.\n\n"
                                "Review the existing record before registering a new patient.")
                    return
        except Exception as e:
            print(f"[HMG ID] registration guard: {e}")
        return _HMG_ORIG_REG(self, instance)
    HMGBillingApp._reg_pt = _hmg_reg_unique
    # Compatibility alias: some existing registration buttons were bound to
    # the guard method name directly. Kivy WeakMethod resolves the method
    # name at touch time, so the alias must remain on HMGBillingApp.
    HMGBillingApp._hmg_reg_unique = _hmg_reg_unique

# ---------------------------- Patient problem list --------------------------
def _hmg_problem_tokens(dx):
    if not dx:
        return []
    textv = str(dx).replace(";", ",").replace("\n", ",")
    return [x.strip() for x in textv.split(",") if x.strip()]

_HMG_ORIG_SAVE_EMR = getattr(HMGBillingApp, "_save_emr", None)
if callable(_HMG_ORIG_SAVE_EMR):
    def _hmg_save_emr_with_problems(self, instance):
        # Validate entered vitals before persistence; never convert bad input to 0.
        ok, msg = _hmg_validate_vitals(self)
        if not ok:
            self._popup("Check vital signs", msg)
            return
        result = _HMG_ORIG_SAVE_EMR(self, instance)
        try:
            pid = self.cp.get("id") if getattr(self, "cp", None) else None
            patient = next((p for p in self.patients if p.get("id") == pid), None)
            if patient is not None:
                patient.setdefault("problems", [])
                dx_widget = self.ew.get("dx") if hasattr(self, "ew") else None
                for problem in _hmg_problem_tokens(getattr(dx_widget, "text", "")):
                    if problem.lower() not in {str(x).lower() for x in patient["problems"]}:
                        patient["problems"].append(problem)
                patient["problems_updated_at"] = datetime.now().strftime("%Y-%m-%d %H:%M:%S")
                self.save_all()
        except Exception as e:
            print(f"[HMG PROBLEM LIST] {e}")
        return result
    HMGBillingApp._save_emr = _hmg_save_emr_with_problems

# ------------------------------ Typed vital guard ---------------------------
def _hmg_validate_vitals(self):
    try:
        ew = getattr(self, "ew", {})
        def val(k):
            w = ew.get(k)
            return str(getattr(w, "text", "")).strip() if w else ""
        bp, temp, pulse, spo2, rr, wt = map(val, ("bp", "temp", "pulse", "spo2", "rr", "wt"))
        if bp:
            m = re.fullmatch(r"\s*(\d{2,3})\s*/\s*(\d{2,3})\s*", bp)
            if not m:
                return False, "BP must be entered as systolic/diastolic, e.g. 120/80."
            sbp, dbp = int(m.group(1)), int(m.group(2))
            if not (50 <= sbp <= 260 and 25 <= dbp <= 150 and dbp < sbp):
                return False, "BP values are outside the accepted safety range."
        for k, label, lo, hi in (("temp","Temperature",25,45),("pulse","Pulse",20,250),
                                  ("spo2","SpO₂",50,100),("rr","Respiratory rate",4,80),
                                  ("wt","Weight",0.5,500)):
            raw = val(k)
            if raw:
                try: num = float(raw)
                except Exception: return False, f"{label} must be numeric."
                if not (lo <= num <= hi): return False, f"{label} is outside the accepted safety range."
        return True, ""
    except Exception as e:
        return False, f"Vital-sign validation error: {e}"

HMGBillingApp._validate_vitals = _hmg_validate_vitals

# -------------------------- Renal / medication safety ----------------------
def _hmg_normalize(s):
    return re.sub(r"[^a-z0-9]+", " ", str(s or "").lower()).strip()

_HMG_ALLERGY_GROUPS = {
    "penicillin": ("amoxicillin", "ampicillin", "penicillin", "piperacillin", "amoxicillin clavulanate", "flucloxacillin"),
    "cephalosporin": ("cephalexin", "cefuroxime", "ceftriaxone", "ceftazidime", "cefixime", "cefepime", "cefotaxime"),
    "sulfonamide": ("cotrimoxazole", "trimethoprim sulfamethoxazole", "sulfamethoxazole"),
    "macrolide": ("erythromycin", "clarithromycin", "azithromycin"),
    "nsaid": ("ibuprofen", "diclofenac", "naproxen", "ketoprofen", "indomethacin", "piroxicam", "ketorolac"),
}
_HMG_INTERACTIONS = {
    frozenset(("warfarin", "ibuprofen")), frozenset(("warfarin", "diclofenac")),
    frozenset(("warfarin", "naproxen")), frozenset(("warfarin", "aspirin")),
    frozenset(("warfarin", "clarithromycin")), frozenset(("warfarin", "erythromycin")),
    frozenset(("ace inhibitor", "spironolactone")), frozenset(("lisinopril", "spironolactone")),
    frozenset(("enalapril", "spironolactone")), frozenset(("ramipril", "spironolactone")),
    frozenset(("simvastatin", "clarithromycin")), frozenset(("atorvastatin", "clarithromycin")),
    frozenset(("methotrexate", "ibuprofen")), frozenset(("methotrexate", "naproxen")),
}
_HMG_RENAL_CAUTION = ("metformin", "ibuprofen", "diclofenac", "naproxen", "ketorolac", "spironolactone", "gentamicin", "amikacin")

def _hmg_patient_allergies(self):
    pt = getattr(self, "cp", None) or {}
    return str(pt.get("allergies", pt.get("all", "")) or "")

def _hmg_patient_drugs(self):
    out = []
    for d in getattr(self, "emr_drug_list", []) or []:
        if isinstance(d, dict): out.append(str(d.get("name", "")))
    # Include currently active prescriptions for this patient.
    pid = (getattr(self, "cp", None) or {}).get("id")
    for r in getattr(self, "prescriptions", []) or []:
        if r.get("patient_id") == pid and r.get("dispensed", False): out.append(str(r.get("drug", "")))
    return out

def _hmg_allergy_hits(allergy_text, drug):
    a = _hmg_normalize(allergy_text); d = _hmg_normalize(drug)
    hits = []
    if not a or not d: return hits
    for group, members in _HMG_ALLERGY_GROUPS.items():
        if group in a or any(m in a for m in members):
            if any(m in d for m in members): hits.append(group)
    # Direct textual overlap catches explicitly recorded drug names.
    for token in re.findall(r"[a-z][a-z0-9-]{3,}", a):
        if token in d: hits.append(token)
    return sorted(set(hits))

def _hmg_interaction_hits(drugs):
    norm = [_hmg_normalize(x) for x in drugs if x]
    hits=[]
    for i in range(len(norm)):
        for j in range(i+1,len(norm)):
            a,b=norm[i],norm[j]
            for pair in _HMG_INTERACTIONS:
                if all(any(part in drug for part in pair) for drug in (a,b)):
                    hits.append((drugs[i],drugs[j]))
    return hits

def _hmg_latest_egfr(self):
    pid = (getattr(self, "cp", None) or {}).get("id")
    if not pid: return None
    vals=[]
    for x in getattr(self, "lab_results", []) or []:
        if x.get("patient_id") != pid: continue
        if "egfr" in _hmg_normalize(x.get("test_name",x.get("component",""))):
            try: vals.append(float(str(x.get("result","")).split()[0]))
            except Exception: pass
    if vals: return vals[-1]
    # CKD-EPI 2021 creatinine equation for adults, without race coefficient.
    creat=None
    for x in reversed(getattr(self,"lab_results",[]) or []):
        if x.get("patient_id") != pid: continue
        if "creatinine" in _hmg_normalize(x.get("test_name",x.get("component",""))):
            try:
                creat=float(str(x.get("result","")).split()[0]); break
            except Exception: pass
    pt=getattr(self,"cp",None) or {}
    try: age=float(pt.get("age",0)); sex=str(pt.get("gender","")).lower()
    except Exception: return None
    if creat is None or age <= 0: return None
    unit=_hmg_normalize(next((x.get("unit","") for x in reversed(getattr(self,"lab_results",[]) or []) if x.get("patient_id")==pid and "creatinine" in _hmg_normalize(x.get("test_name",x.get("component","")))), ""))
    if "umol" in unit or "µmol" in unit: creat /= 88.4
    if "mg dl" not in unit and "umol" not in unit and "µmol" not in unit:
        # Default to the common EMR creatinine convention only if unit is absent.
        pass
    female = sex.startswith("f")
    k = 0.7 if female else 0.9
    a = -0.241 if female else -0.302
    return 142 * min(creat/k,1)**a * max(creat/k,1)**-1.200 * (0.9938**age) * (1.012 if female else 1.0)

def _hmg_medication_guard(self, drug_name, override=False):
    if override: return True
    warnings=[]
    allergy=_hmg_allergy_hits(_hmg_patient_allergies(self), drug_name)
    if allergy:
        warnings.append("ALLERGY: recorded allergy may match " + ", ".join(allergy))
    current=_hmg_patient_drugs(self)
    interactions=_hmg_interaction_hits(current + [drug_name])
    if interactions:
        warnings.append("INTERACTION: " + "; ".join(f"{a} + {b}" for a,b in interactions))
    egfr=_hmg_latest_egfr(self)
    nd=_hmg_normalize(drug_name)
    if egfr is not None and egfr < 60 and any(x in nd for x in _HMG_RENAL_CAUTION):
        warnings.append(f"RENAL CAUTION: latest estimated eGFR ≈ {egfr:.0f} mL/min/1.73m²; verify indication and dose.")
    if not warnings: return True
    content=BoxLayout(orientation='vertical', spacing=8, padding=10)
    content.add_widget(Label(text="\n".join(warnings), font_size=13))
    content.add_widget(Label(text="Review the patient record and drug choice. Continue only if clinically justified.", font_size=12))
    buttons=BoxLayout(size_hint_y=None,height=48,spacing=8)
    pop=Popup(title="Medication Safety Check",content=content,size_hint=(0.9,0.55),auto_dismiss=False)
    cancel=Button(text="CANCEL",size_hint_y=None,height=48)
    cont=Button(text="CONTINUE / OVERRIDE",size_hint_y=None,height=48)
    cancel.bind(on_press=lambda *_: pop.dismiss())
    def _go(*_):
        pop.dismiss(); self._hmg_prescription_override_once=True; self._add_drug_to_emr(None)
    cont.bind(on_press=_go)
    buttons.add_widget(cancel); buttons.add_widget(cont); content.add_widget(buttons)
    pop.open()
    return False

_HMG_ORIG_ADD_DRUG = getattr(HMGBillingApp, "_add_drug_to_emr", None)
if callable(_HMG_ORIG_ADD_DRUG):
    def _hmg_add_drug_guard(self, instance):
        override = bool(getattr(self, "_hmg_prescription_override_once", False))
        self._hmg_prescription_override_once = False
        drug_name = getattr(getattr(self, "emr_drug_spinner", None), "text", "")
        if not override and drug_name not in ("", "Select", "No match"):
            if not _hmg_medication_guard(self, drug_name, False): return
        return _HMG_ORIG_ADD_DRUG(self, instance)
    HMGBillingApp._add_drug_to_emr = _hmg_add_drug_guard

