# ============================================================================
# HMG EMR ENGINEERING PHASE 2
# Relational clinical core + audit/outbox + structured observations + migration
# This layer is intentionally additive: the legacy UI/data structures remain
# usable while authoritative clinical events are progressively normalized.
# ============================================================================
_HMG_ENGINE_SCHEMA = 3
_HMG_ENGINE_DB = "HMG_EMR_ENGINE.sqlite3"

class HMGClinicalEngine:
    """Small relational core for patient-safety and operational events.

    SQLite is the authoritative event store for new Phase-2 data. Existing JSON
    collections remain available for backward compatibility during migration.
    Every mutating operation is transactional and produces an audit record.
    """
    def __init__(self, app):
        self.app = app
        self.path = os.path.join(app._get_reports_dir(), _HMG_ENGINE_DB)
        os.makedirs(os.path.dirname(self.path), exist_ok=True)
        self._init()

    def db(self):
        c = _hmg_sqlite3.connect(self.path, timeout=20)
        c.row_factory = _hmg_sqlite3.Row
        c.execute("PRAGMA journal_mode=WAL")
        c.execute("PRAGMA synchronous=FULL")
        c.execute("PRAGMA foreign_keys=ON")
        return c

    def _init(self):
        with self.db() as c:
            c.executescript("""
            CREATE TABLE IF NOT EXISTS engine_meta(
                key TEXT PRIMARY KEY, value TEXT NOT NULL
            );
            CREATE TABLE IF NOT EXISTS patients_core(
                patient_id TEXT PRIMARY KEY,
                name TEXT NOT NULL,
                dob TEXT, sex TEXT, phone TEXT,
                created_at TEXT NOT NULL, updated_at TEXT NOT NULL
            );
            CREATE TABLE IF NOT EXISTS problems(
                id TEXT PRIMARY KEY, patient_id TEXT NOT NULL,
                problem TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'active',
                onset_date TEXT, recorded_at TEXT NOT NULL,
                recorded_by TEXT, source TEXT,
                FOREIGN KEY(patient_id) REFERENCES patients_core(patient_id)
            );
            CREATE INDEX IF NOT EXISTS idx_problems_patient ON problems(patient_id);
            CREATE TABLE IF NOT EXISTS observations(
                id TEXT PRIMARY KEY, patient_id TEXT NOT NULL,
                encounter_id TEXT, observed_at TEXT NOT NULL,
                sbp REAL, dbp REAL, temperature REAL, pulse REAL,
                spo2 REAL, respiratory_rate REAL, weight_kg REAL,
                source TEXT, recorded_by TEXT,
                FOREIGN KEY(patient_id) REFERENCES patients_core(patient_id)
            );
            CREATE INDEX IF NOT EXISTS idx_obs_patient_time
                ON observations(patient_id, observed_at);
            CREATE TABLE IF NOT EXISTS medication_events(
                id TEXT PRIMARY KEY, patient_id TEXT NOT NULL,
                drug TEXT NOT NULL, action TEXT NOT NULL,
                dose TEXT, route TEXT, frequency TEXT,
                override_reason TEXT, safety_status TEXT NOT NULL,
                created_at TEXT NOT NULL, created_by TEXT,
                FOREIGN KEY(patient_id) REFERENCES patients_core(patient_id)
            );
            CREATE TABLE IF NOT EXISTS surgical_checklists(
                id TEXT PRIMARY KEY, patient_id TEXT NOT NULL,
                procedure TEXT NOT NULL, status TEXT NOT NULL,
                payload TEXT NOT NULL, updated_at TEXT NOT NULL,
                FOREIGN KEY(patient_id) REFERENCES patients_core(patient_id)
            );
            CREATE TABLE IF NOT EXISTS audit_log(
                id TEXT PRIMARY KEY, actor TEXT, role TEXT,
                action TEXT NOT NULL, entity TEXT, entity_id TEXT,
                occurred_at TEXT NOT NULL, device TEXT, details TEXT
            );
            CREATE INDEX IF NOT EXISTS idx_audit_time ON audit_log(occurred_at);
            CREATE TABLE IF NOT EXISTS sync_outbox(
                id TEXT PRIMARY KEY, event_type TEXT NOT NULL,
                entity_id TEXT NOT NULL, payload TEXT NOT NULL,
                status TEXT NOT NULL DEFAULT 'pending', attempts INTEGER NOT NULL DEFAULT 0,
                next_attempt_at TEXT, last_error TEXT,
                created_at TEXT NOT NULL, sent_at TEXT
            );
            CREATE INDEX IF NOT EXISTS idx_outbox_status
                ON sync_outbox(status, next_attempt_at);
            CREATE TABLE IF NOT EXISTS schema_migrations(
                version INTEGER PRIMARY KEY, applied_at TEXT NOT NULL
            );
            """)
            row = c.execute("SELECT MAX(version) AS v FROM schema_migrations").fetchone()
            current = int(row["v"] or 0)
            if current < 3:
                c.execute("INSERT OR IGNORE INTO schema_migrations(version,applied_at) VALUES(?,?)",
                          (3, datetime.now().isoformat(timespec="seconds")))
            c.execute("INSERT OR REPLACE INTO engine_meta(key,value) VALUES('schema_version',?)",
                      (str(_HMG_ENGINE_SCHEMA),))

    @staticmethod
    def _now():
        return datetime.now().isoformat(timespec="seconds")

    @staticmethod
    def _json(v):
        return json.dumps(v, ensure_ascii=False, separators=(",", ":"), default=str)

    def actor(self):
        u = getattr(self.app, "current_user", {}) or {}
        return str(u.get("username", u.get("name", "system")))

    def role(self):
        return str((getattr(self.app, "current_user", {}) or {}).get("role", ""))

    def audit(self, c, action, entity=None, entity_id=None, details=None):
        c.execute("""INSERT INTO audit_log
            (id,actor,role,action,entity,entity_id,occurred_at,device,details)
            VALUES(?,?,?,?,?,?,?,?,?)""",
            (str(_hmg_uuid4()), self.actor(), self.role(), action,
             entity, entity_id, self._now(), "android", self._json(details or {})))

    def upsert_patient(self, p):
        pid = str(p.get("id") or _hmg_new_patient_id())
        now = self._now()
        with self.db() as c:
            c.execute("""INSERT INTO patients_core
                (patient_id,name,dob,sex,phone,created_at,updated_at)
                VALUES(?,?,?,?,?,?,?)
                ON CONFLICT(patient_id) DO UPDATE SET
                name=excluded.name,dob=excluded.dob,sex=excluded.sex,
                phone=excluded.phone,updated_at=excluded.updated_at""",
                (pid,str(p.get("name", "")).strip(),p.get("dob"),
                 p.get("gender",p.get("sex")),p.get("phone"),now,now))
            self.audit(c,"patient_upsert","patient",pid,{"name":p.get("name")})
        return pid

    def add_problem(self, patient_id, problem, source="EMR"):
        problem = str(problem or "").strip()
        if not patient_id or not problem: return None
        with self.db() as c:
            row = c.execute("SELECT id FROM problems WHERE patient_id=? AND lower(problem)=lower(?) AND status='active'",
                            (patient_id,problem)).fetchone()
            if row: return row["id"]
            ident=str(_hmg_uuid4())
            c.execute("""INSERT INTO problems
                (id,patient_id,problem,recorded_at,recorded_by,source)
                VALUES(?,?,?,?,?,?)""",
                (ident,patient_id,problem,self._now(),self.actor(),source))
            self.audit(c,"problem_added","problem",ident,{"patient_id":patient_id,"problem":problem})
            return ident

    def add_observation(self, patient_id, values, encounter_id=None):
        if not patient_id: return None
        ident=str(_hmg_uuid4())
        keys=("sbp","dbp","temperature","pulse","spo2","respiratory_rate","weight_kg")
        nums={k: values.get(k) for k in keys}
        with self.db() as c:
            c.execute("""INSERT INTO observations
                (id,patient_id,encounter_id,observed_at,sbp,dbp,temperature,pulse,spo2,respiratory_rate,weight_kg,source,recorded_by)
                VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?)""",
                (ident,patient_id,encounter_id,self._now(),*[nums[k] for k in keys],"EMR",self.actor()))
            self.audit(c,"vitals_recorded","observation",ident,{"patient_id":patient_id})
        return ident

    def enqueue(self,event_type,entity_id,payload):
        ident=str(_hmg_uuid4()); now=self._now()
        with self.db() as c:
            c.execute("""INSERT INTO sync_outbox
                (id,event_type,entity_id,payload,status,attempts,next_attempt_at,created_at)
                VALUES(?,?,?,?,?,?,?,?)""",
                (ident,event_type,str(entity_id),self._json(payload),"pending",0,now,now))
            self.audit(c,"sync_queued",event_type,str(entity_id),{})
        return ident

    def pending_sync(self, limit=50):
        with self.db() as c:
            rows=c.execute("""SELECT * FROM sync_outbox
                WHERE status='pending' AND (next_attempt_at IS NULL OR next_attempt_at<=?)
                ORDER BY created_at LIMIT ?""",(self._now(),int(limit))).fetchall()
            return [dict(r) for r in rows]

    def mark_sync(self, ident, success, error=None):
        with self.db() as c:
            if success:
                c.execute("UPDATE sync_outbox SET status='sent',sent_at=?,last_error=NULL WHERE id=?",
                          (self._now(),ident))
            else:
                row=c.execute("SELECT attempts FROM sync_outbox WHERE id=?",(ident,)).fetchone()
                attempts=int(row["attempts"] if row else 0)+1
                delay=min(3600,2**min(attempts,10))
                retry=(datetime.now()+__import__('datetime').timedelta(seconds=delay)).isoformat(timespec="seconds")
                c.execute("UPDATE sync_outbox SET attempts=?,next_attempt_at=?,last_error=? WHERE id=?",
                          (attempts,retry,str(error or "unknown error"),ident))


def _hmg_get_engine(self):
    eng=getattr(self,"_hmg_engine",None)
    if eng is None:
        eng=HMGClinicalEngine(self); self._hmg_engine=eng
    return eng

HMGBillingApp._hmg_get_engine=_hmg_get_engine

# --- Synchronize the legacy patient collection into the relational core. ---
_HMG_P2_ORIG_BUILD=getattr(HMGBillingApp,"build",None)
if callable(_HMG_P2_ORIG_BUILD) and not getattr(_HMG_P2_ORIG_BUILD,"_hmg_phase2",False):
    def _hmg_phase2_build(self,*a,**kw):
        result=_HMG_P2_ORIG_BUILD(self,*a,**kw)
        try:
            eng=self._hmg_get_engine()
            for p in (getattr(self,"patients",[]) or []):
                if isinstance(p,dict) and p.get("id"):
                    eng.upsert_patient(p)
        except Exception as e:
            print("[HMG P2] patient core sync:",e)
        return result
    _hmg_phase2_build._hmg_phase2=True
    HMGBillingApp.build=_hmg_phase2_build

# --- Structured vitals capture alongside the legacy EMR fields. ---
_HMG_P2_ORIG_SAVE_EMR=getattr(HMGBillingApp,"_save_emr",None)
if callable(_HMG_P2_ORIG_SAVE_EMR) and not getattr(_HMG_P2_ORIG_SAVE_EMR,"_hmg_phase2",False):
    def _hmg_phase2_save_emr(self,instance,*a,**kw):
        result=_HMG_P2_ORIG_SAVE_EMR(self,instance,*a,**kw)
        try:
            pid=(getattr(self,"cp",{}) or {}).get("id")
            if pid:
                eng=self._hmg_get_engine()
                vals={}
                ew=getattr(self,"ew",{}) or {}
                for key, dest in (("bp",None),("temp","temperature"),("pulse","pulse"),("spo2","spo2"),("rr","respiratory_rate"),("wt","weight_kg")):
                    w=ew.get(key); raw=str(getattr(w,"text","")).strip() if w else ""
                    if not raw: continue
                    if key=="bp":
                        m=re.fullmatch(r"\s*(\d{2,3})\s*/\s*(\d{2,3})\s*",raw)
                        if m: vals["sbp"]=float(m.group(1)); vals["dbp"]=float(m.group(2))
                    else: vals[dest]=float(raw)
                if vals: eng.add_observation(pid,vals)
                for problem in _hmg_problem_tokens(getattr(ew.get("dx"),"text","") if ew.get("dx") else ""):
                    eng.add_problem(pid,problem,"EMR")
                eng.enqueue("clinical_update",pid,{"patient_id":pid,"type":"EMR_SAVE"})
        except Exception as e:
            print("[HMG P2] structured EMR event:",e)
        return result
    _hmg_phase2_save_emr._hmg_phase2=True
    HMGBillingApp._save_emr=_hmg_phase2_save_emr

# --- Role/record visibility primitives for subsequent UI enforcement. ---
def _hmg_can_view_record(self, record, required_role=None):
    record=record or {}
    role=str((getattr(self,"current_user",{}) or {}).get("role","")).lower()
    owner=str(record.get("created_by",record.get("recorded_by","")))
    visibility=str(record.get("visibility","clinical")).lower()
    if required_role and role!=str(required_role).lower(): return False
    if visibility=="restricted" and role not in {"doctor","medical director","administrator","admin"}: return False
    if visibility=="owner" and owner and owner!=str((getattr(self,"current_user",{}) or {}).get("username","")):
        return role in {"doctor","medical director","administrator","admin"}
    return True
HMGBillingApp._hmg_can_view_record=_hmg_can_view_record

# --- Surgical completion gate: checklist must be complete before status moves to Completed. ---
def _hmg_surgical_gate(self, checklist):
    if not isinstance(checklist,dict): return False,"No surgical safety checklist exists."
    required=(checklist.get("sign_in",{}),checklist.get("time_out",{}),checklist.get("sign_out",{}))
    missing=[k for section in required for k,v in section.items() if not v]
    if missing:
        return False,"Surgical checklist incomplete: " + ", ".join(missing)
    return True,"OK"
HMGBillingApp._hmg_surgical_gate=_hmg_surgical_gate

print("[HMG P2] relational clinical core, structured observations, audit/outbox, visibility primitives and surgical completion gate loaded")

# ============================================================================
# HMG REGISTRATION — unique ID generator + missing-method safety net
# ============================================================================

import secrets

def _hmg_reg_unique(self, *args, **kwargs):
    """Generate a unique patient ID, avoiding collisions with existing IDs.

    Format: <PREFIX><YYMMDD>-<NNNN>, e.g. HMG260929-0001.
    Falls back to a random suffix if 9999 sequential IDs in a single day
    are exhausted.
    """
    try:
        existing = {str(p.get("id", "")).strip()
                    for p in getattr(self, "patients", [])}
        try:
            pending = str(self.rw["id"].text).strip()
            if pending:
                existing.add(pending)
        except Exception:
            pass
        prefix = "HMG"
        try:
            prefix = self.facility.get("report_prefix", "HMG") or "HMG"
        except Exception:
            pass
        base = datetime.now().strftime(f"{prefix}%y%m%d")
        for i in range(1, 10000):
            candidate = f"{base}-{i:04d}"
            if candidate not in existing:
                return candidate
        return f"{base}-{secrets.token_hex(3).upper()}"
    except Exception as e:
        print(f"[HMG] reg_unique: {e}")
        return f"PT{datetime.now().strftime('%Y%m%d%H%M%S')}"


def _hmg_reg_new_id(self, *args, **kwargs):
    """Handler for the NEW ID button."""
    try:
        new_id = self._hmg_reg_unique()
        if hasattr(self, "rw") and "id" in self.rw:
            self.rw["id"].text = new_id
        try:
            self.log_activity(f"Generated registration ID: {new_id}")
        except Exception:
            pass
        return new_id
    except Exception as e:
        print(f"[HMG] reg_new_id: {e}")
        return None


HMGBillingApp._hmg_reg_unique = _hmg_reg_unique
HMGBillingApp._hmg_reg_new_id = _hmg_reg_new_id
HMGBillingApp._reg_unique = _hmg_reg_unique
HMGBillingApp._reg_new_id = _hmg_reg_new_id


# ---------------------------------------------------------------------------
# Safety net: missing _hmg_* methods resolve to a logged no-op rather than
# crashing the application during a touch callback.
# ---------------------------------------------------------------------------
_hmg_missing_registry = set()

def _hmg_class_getattr(self, name):
    if not name.startswith("_hmg_"):
        raise AttributeError(
            f"'{type(self).__name__}' object has no attribute '{name}'")
    if name not in _hmg_missing_registry:
        _hmg_missing_registry.add(name)
        print(f"[HMG-GUARD] missing method '{name}' called — "
              f"returning no-op. Add a real implementation to "
              f"HMGBillingApp if this is a bug.")
    def _noop(*args, **kwargs):
        return None
    return _noop

if not getattr(HMGBillingApp, "_hmg_getattr_installed", False):
    HMGBillingApp.__getattr__ = _hmg_class_getattr
    HMGBillingApp._hmg_getattr_installed = True


# ---------------------------------------------------------------------------
# Registration tab: use HMG-format IDs and ensure NEW ID is available.
# ---------------------------------------------------------------------------
_hmg_orig_register = getattr(HMGBillingApp, "_register", None)
if callable(_hmg_orig_register) and not getattr(_hmg_orig_register, "_hmg_unique_wrapped", False):
    def _register_with_unique(self, *a, **kw):
        result = _hmg_orig_register(self, *a, **kw)
        try:
            if hasattr(self, "rw") and "id" in self.rw:
                self.rw["id"].text = self._hmg_reg_unique()

            def _add_new_id_button(w):
                from kivy.uix.boxlayout import BoxLayout as _BL
                from kivy.uix.button import Button as _Btn
                found = False
                for c in getattr(w, "children", []):
                    if isinstance(c, _BL):
                        for cc in getattr(c, "children", []):
                            if isinstance(cc, _Btn) and "NEW ID" in str(getattr(cc, "text", "")).upper():
                                found = True
                                break
                    if found:
                        break
                    if _add_new_id_button(c):
                        found = True
                        break
                if (not found and isinstance(w, _BL) and
                        any(isinstance(c, _Btn) for c in getattr(w, "children", []))):
                    nb = _Btn(text="NEW ID", font_size=13,
                              background_normal="",
                              background_color=get_color_from_hex("#16a085"))
                    nb.bind(on_press=self._hmg_reg_new_id)
                    w.add_widget(nb)
                    return True
                return found

            tp = getattr(self, "tp", None)
            for tab in (getattr(tp, "tab_list", []) if tp is not None else []):
                if getattr(tab, "text", "") == "Registration":
                    _add_new_id_button(tab)
                    break
        except Exception as e:
            print(f"[HMG] register wiring: {e}")
        return result

    _register_with_unique._hmg_unique_wrapped = True
    HMGBillingApp._register = _register_with_unique

print("[HMG] registration unique-ID fix installed")


# ============================================================================
# HMG SAVE PERFORMANCE FIX
#   1. Backup rotation runs at most once per 10 minutes per file.
#   2. save_all() is debounced to a single write per 0.6s of quiet.
#   3. JSON + SQLite snapshot I/O runs on a worker thread.
#   4. force=True is retained for logout/on_stop/critical registration.
# ============================================================================
import time as _hmg_time
import threading as _hmg_threading
import tempfile as _hmg_tempfile
import shutil as _hmg_shutil

_hmg_last_backup = {}
_HMG_BACKUP_INTERVAL = 600.0

if not getattr(HMGBillingApp, "_hmg_save_json_throttled", False):
    _hmg_orig_save_json_perf = HMGBillingApp._save_json

    def _save_json_throttled(self, filename, data, max_backups=3):
        try:
            now = _hmg_time.monotonic()
            last = _hmg_last_backup.get(filename, 0.0)
            do_rotate = (now - last) >= _HMG_BACKUP_INTERVAL
            if do_rotate:
                _hmg_last_backup[filename] = now
                if os.path.exists(filename):
                    for i in range(max_backups - 1, 0, -1):
                        src = f"{filename}.bak{i - 1}" if i > 1 else filename
                        dst = f"{filename}.bak{i}"
                        if os.path.exists(src):
                            try:
                                _hmg_shutil.copy2(src, dst)
                            except Exception:
                                pass
                    try:
                        _hmg_shutil.copy2(filename, f"{filename}.bak0")
                    except Exception:
                        pass

            parent = os.path.dirname(filename) or "."
            os.makedirs(parent, exist_ok=True)
            fd, tmp = _hmg_tempfile.mkstemp(
                dir=parent, prefix=".hmg_tmp_", suffix=".json")
            try:
                with os.fdopen(fd, "w", encoding="utf-8") as f:
                    json.dump(data, f, indent=None, default=str, ensure_ascii=False)
                os.replace(tmp, filename)
            finally:
                if os.path.exists(tmp):
                    try:
                        os.remove(tmp)
                    except Exception:
                        pass
        except Exception as e:
            print(f"[HMG] fast save_json {filename}: {e}")
            try:
                _hmg_orig_save_json_perf(self, filename, data, max_backups)
            except Exception as e2:
                print(f"[HMG] fallback save_json {filename}: {e2}")

    HMGBillingApp._save_json = _save_json_throttled
    HMGBillingApp._hmg_save_json_throttled = True


# ---------------------------------------------------------------------------
# Snapshot + worker helpers.  The worker also commits the SQLite snapshot so
# the transactional store does not become stale while JSON is being written.
# ---------------------------------------------------------------------------
def _hmg_snapshot_app_state(self):
    keys = [
        "patients", "emr_records", "lab_tests", "radiology",
        "prescriptions", "bills", "drugs", "investigations",
        "ecg_reports", "pathology_data", "followups", "patient_summaries",
        "consent_forms", "referral_notes", "daily_notes", "patient_snapshots",
        "procedures_db", "lab_results", "tasks", "admissions",
        "saved_lab_reports", "appointments", "nursing_notes", "transfers",
        "_vitals_records", "_surgical_cases", "_wards", "_beds",
    ]
    snap = {}
    for k in keys:
        v = getattr(self, k, [])
        try:
            if isinstance(v, list):
                snap[k] = list(v)
            elif isinstance(v, dict):
                snap[k] = dict(v)
            else:
                snap[k] = v
        except Exception:
            snap[k] = v
    return snap


def _hmg_write_sqlite_snapshot_from_snap(self, snap):
    """Commit the same Phase-1 transactional SQLite snapshot from the UI
    snapshot, without touching Kivy widgets from the worker thread."""
    try:
        class _SnapshotProxy:
            def __init__(proxy, app, state):
                proxy._app = app
                for name in HMGTransactionalStore.COLLECTIONS:
                    setattr(proxy, name, state.get(name, []))
            def _get_reports_dir(proxy):
                return proxy._app._get_reports_dir()

        proxy = _SnapshotProxy(self, snap)
        store = HMGTransactionalStore(proxy)
        snapshot_id = store.save_snapshot()
        return snapshot_id
    except Exception as e:
        print(f"[HMG STORE] async SQLite snapshot failed: {e}")
        return None


def _hmg_write_snapshot(self, snap, generation=None):
    """Worker-thread writer. No Kivy widgets are created or modified here."""
    io_lock = getattr(self, "_hmg_save_io_lock", None)
    if io_lock is None:
        return
    with io_lock:
        try:
            # A forced save may have superseded this pending snapshot.
            if generation is not None and generation != getattr(self, "_hmg_save_generation", 0):
                return

            base = self._get_reports_dir()
            files = {
                "patients.json": snap.get("patients", []),
                "emr.json": snap.get("emr_records", []),
                "lab.json": snap.get("lab_tests", []),
                "rad.json": snap.get("radiology", []),
                "rx.json": snap.get("prescriptions", []),
                "bills.json": snap.get("bills", []),
                "drugs.json": snap.get("drugs", []),
                "invs.json": snap.get("investigations", []),
                "ecg.json": snap.get("ecg_reports", []),
                "pathology.json": snap.get("pathology_data", []),
                "followups.json": snap.get("followups", []),
                "summaries.json": snap.get("patient_summaries", {}),
                "consent_forms.json": snap.get("consent_forms", []),
                "referral_notes.json": snap.get("referral_notes", []),
                "daily_notes.json": snap.get("daily_notes", []),
                "snapshots.json": snap.get("patient_snapshots", []),
                "procedures_db.json": snap.get("procedures_db", []),
                "lab_results.json": snap.get("lab_results", []),
                "tasks.json": snap.get("tasks", []),
                "admissions.json": snap.get("admissions", []),
                "saved_lab_reports.json": snap.get("saved_lab_reports", []),
                "appointments.json": snap.get("appointments", []),
                "nursing_notes.json": snap.get("nursing_notes", []),
                "transfers.json": snap.get("transfers", []),
                "vitals.json": snap.get("_vitals_records", []),
                "surgical_cases.json": snap.get("_surgical_cases", []),
                "beds.json": {"wards": snap.get("_wards", []),
                               "beds": snap.get("_beds", [])},
            }
            for fn, data in files.items():
                try:
                    self._save_json(os.path.join(base, fn), data)
                except Exception as e:
                    print(f"[HMG] async write {fn}: {e}")

            sid = _hmg_write_sqlite_snapshot_from_snap(self, snap)
            if sid:
                self._hmg_last_snapshot_id = sid
        except Exception as e:
            print(f"[HMG] async snapshot writer: {e}")


if not getattr(HMGBillingApp, "_hmg_save_all_async", False):
    _hmg_orig_save_all_perf = HMGBillingApp.save_all
    _hmg_save_lock = _hmg_threading.Lock()

    def _save_all_async(self, *a, **kw):
        force = bool(kw.pop("force", False))
        if a and isinstance(a[0], bool):
            force = a[0]

        if not hasattr(self, "_hmg_save_io_lock"):
            self._hmg_save_io_lock = _hmg_threading.RLock()
            self._hmg_save_generation = 0

        if force:
            with _hmg_save_lock:
                self._hmg_save_generation = getattr(self, "_hmg_save_generation", 0) + 1
                self._hmg_save_state = getattr(self, "_hmg_save_state", {})
                self._hmg_save_state.update({"pending": False, "dirty": False})
            with self._hmg_save_io_lock:
                try:
                    return _hmg_orig_save_all_perf(self)
                except Exception as e:
                    print(f"[HMG] forced save: {e}")
                    return None

        with _hmg_save_lock:
            state = getattr(self, "_hmg_save_state", None)
            if state is None:
                state = {"pending": False, "dirty": False}
                self._hmg_save_state = state
            state["dirty"] = True
            if state["pending"]:
                return None
            state["pending"] = True
            generation = getattr(self, "_hmg_save_generation", 0)

        def _run(dt):
            with _hmg_save_lock:
                state = getattr(self, "_hmg_save_state", {})
                if not state.get("dirty"):
                    state["pending"] = False
                    return
                state["dirty"] = False
                state["pending"] = False
            try:
                snapshot = _hmg_snapshot_app_state(self)
            except Exception as e:
                print(f"[HMG] snapshot: {e}")
                return
            _hmg_threading.Thread(
                target=_hmg_write_snapshot,
                args=(self, snapshot, generation),
                daemon=True,
            ).start()

        Clock.schedule_once(_run, 0.6)
        return None

    HMGBillingApp.save_all = _save_all_async
    HMGBillingApp._hmg_save_all_async = True


# ---------------------------------------------------------------------------
# Critical durability hooks
# ---------------------------------------------------------------------------
_hmg_orig_logout_perf = getattr(HMGBillingApp, "_logout", None)
if callable(_hmg_orig_logout_perf) and not getattr(_hmg_orig_logout_perf, "_hmg_force_save_wrapped", False):
    def _logout_force_save(self, *a, **kw):
        try:
            self.save_all(force=True)
        except Exception as e:
            print(f"[HMG] logout save: {e}")
        return _hmg_orig_logout_perf(self, *a, **kw)
    _logout_force_save._hmg_force_save_wrapped = True
    HMGBillingApp._logout = _logout_force_save

_hmg_orig_on_stop_perf = getattr(HMGBillingApp, "on_stop", None)
if callable(_hmg_orig_on_stop_perf) and not getattr(_hmg_orig_on_stop_perf, "_hmg_force_save_wrapped", False):
    def _on_stop_force_save(self, *a, **kw):
        try:
            self.save_all(force=True)
        except Exception as e:
            print(f"[HMG] on_stop save: {e}")
        return _hmg_orig_on_stop_perf(self, *a, **kw)
    _on_stop_force_save._hmg_force_save_wrapped = True
    HMGBillingApp.on_stop = _on_stop_force_save


# Registration remains explicitly durable after the actual patient append.
_hmg_orig_reg_pt_perf = getattr(HMGBillingApp, "_reg_pt", None)
if callable(_hmg_orig_reg_pt_perf) and not getattr(_hmg_orig_reg_pt_perf, "_hmg_perf_wrapped", False):
    def _reg_pt_fast(self, instance=None, *args, **kwargs):
        result = _hmg_orig_reg_pt_perf(self, instance, *args, **kwargs)
        try:
            self.save_all(force=True)
        except Exception as e:
            print(f"[HMG] post-register save: {e}")
        return result
    _reg_pt_fast._hmg_perf_wrapped = True
    HMGBillingApp._reg_pt = _reg_pt_fast


# ---------------------------------------------------------------------------
# Defer the expensive patient-selection refresh cascade by one frame.
# ---------------------------------------------------------------------------
_hmg_orig_sel_by_id_perf = getattr(HMGBillingApp, "_sel_by_id", None)
if callable(_hmg_orig_sel_by_id_perf) and not getattr(_hmg_orig_sel_by_id_perf, "_hmg_perf_wrapped", False):
    def _sel_by_id_deferred(self, pid):
        try:
            patient = next((p for p in self.patients if p.get("id") == pid), None)
            if patient:
                self.cp = patient
                if hasattr(self, "pt_lbl"):
                    self.pt_lbl.text = (f"{patient.get('name','')} "
                                        f"({patient.get('id','')}) "
                                        f"| {patient.get('age','')}yr")
                    self.pt_lbl.color = get_color_from_hex('#2c3e50')
        except Exception:
            pass
        def _go(dt):
            try:
                _hmg_orig_sel_by_id_perf(self, pid)
            except Exception as e:
                print(f"[HMG] select deferred: {e}")
        Clock.schedule_once(_go, 0)
    _sel_by_id_deferred._hmg_perf_wrapped = True
    HMGBillingApp._sel_by_id = _sel_by_id_deferred

print("[HMG] save performance fix installed (debounced, async, SQLite-aware, backup-throttled)")


# ============================================================================
# HMG CALLBACK RESILIENCE v2
#  1. Define _reg_pt_fast as a real class method (Kivy string/WeakMethod
#     resolution can look it up by literal name at press time).
#  2. Widen __getattr__ for missing private callback/helper names only.
#     Public/data attributes continue to raise normally.
#  3. Reconcile legacy _reg_pt wrappers without recursive/double invocation.
#  4. Provide explicit compatibility hooks expected by the HARDEN/Phase-2
#     layers.
# ============================================================================

# ---- 1. Real _reg_pt_fast on the class ------------------------------------
# Preserve the currently working _reg_pt implementation before rebinding it.
_HMG_REG_PT_BEFORE_RESILIENCE = getattr(HMGBillingApp, "_reg_pt", None)


def _reg_pt_fast(self, instance=None, *args, **kwargs):
    """Named registration callback with an explicit post-registration save.

    Kivy may resolve callback names through the instance/class at press time,
    so this must exist literally as HMGBillingApp._reg_pt_fast rather than
    only as a closure captured by another wrapper.
    """
    result = None

    # Call the pre-existing implementation exactly once. Avoid recursion if
    # a previous repair already rebound _reg_pt to this same named callback.
    current = getattr(type(self), "_reg_pt", None)
    target = _HMG_REG_PT_BEFORE_RESILIENCE
    if callable(target) and target is not _reg_pt_fast and target is not current:
        try:
            result = target(self, instance, *args, **kwargs)
        except TypeError:
            try:
                result = target(self, instance)
            except TypeError:
                result = target(self)
    elif callable(current) and current is not _reg_pt_fast:
        # If _reg_pt changed after installation, call that implementation,
        # but never call this method through itself.
        try:
            result = current(self, instance, *args, **kwargs)
        except TypeError:
            try:
                result = current(self, instance)
            except TypeError:
                result = current(self)

    # Registration is a critical durability point. Flush the debounced save.
    try:
        self.save_all(force=True)
    except Exception as e:
        print(f"[HMG] post-register force-save: {e}")
    return result


HMGBillingApp._reg_pt_fast = _reg_pt_fast


# ---- 2. Widened __getattr__ ----------------------------------------------
_hmg_missing_registry = set()


def _hmg_class_getattr_v2(self, name):
    # Dunder lookups must behave normally (copy/pickle/repr/introspection).
    if name.startswith("__") and name.endswith("__"):
        raise AttributeError(
            f"'{type(self).__name__}' object has no attribute '{name}'")

    # Public/data names remain strict so genuine data-path defects surface.
    if not name.startswith("_"):
        raise AttributeError(
            f"'{type(self).__name__}' object has no attribute '{name}'")

    # Private names are the callback/helper namespace. A missing handler
    # should not kill the UI during a touch; log once and return a callable.
    if name not in _hmg_missing_registry:
        _hmg_missing_registry.add(name)
        print(
            f"[HMG-GUARD] missing private method '{name}' — returning "
            f"no-op. Add a real implementation if this is not intentional."
        )

    def _noop(*args, **kwargs):
        return None
    _noop.__name__ = name
    return _noop


HMGBillingApp.__getattr__ = _hmg_class_getattr_v2
HMGBillingApp._hmg_getattr_v2_installed = True


# ---- 3. Register-button reconciliation -----------------------------------
# Do not replace a working _reg_pt merely because an earlier wrapper exists.
# If a previous patch explicitly redirected _reg_pt to a named fast callback,
# make the literal _reg_pt_fast lookup authoritative and avoid double-saving.
try:
    current = getattr(HMGBillingApp, "_reg_pt", None)
    current_name = getattr(current, "__name__", "") if callable(current) else ""
    if current is None or not callable(current):
        HMGBillingApp._reg_pt = _reg_pt_fast
    elif current is _reg_pt_fast:
        pass
    elif current_name == "_reg_pt_fast" and getattr(current, "_hmg_perf_wrapped", False):
        # Legacy performance wrapper already owns _reg_pt. Leave it intact;
        # _reg_pt_fast is now independently resolvable by Kivy.
        pass
    else:
        # Keep the actual working _reg_pt. The named callback exists separately.
        pass
except Exception as e:
    print(f"[HMG] reg_pt reconcile: {e}")


# ---- 4. Compatibility hooks expected by HARDEN / Phase-2 -----------------
def _hmg_engine(self, *args, **kwargs):
    """Compatibility engine accessor for older HARDEN call sites."""
    try:
        getter = getattr(type(self), "_hmg_get_engine", None)
        if callable(getter) and getter is not _hmg_engine:
            return getter(self, *args, **kwargs)
    except Exception:
        pass
    try:
        return self._safety()
    except Exception:
        return None


HMGBillingApp._hmg_engine = _hmg_engine


def _hmg_sync_event(self, *args, **kwargs):
    """Compatibility sync hook; safe on a single-device/offline install."""
    try:
        event = getattr(self, "_hmg_sync_event", None)
        # Do not recursively invoke ourselves. A Kivy ClockEvent has cancel().
        if event is not _hmg_sync_event and hasattr(event, "cancel"):
            return event
    except Exception:
        pass
    try:
        audit = getattr(self, "audit", None)
        if audit is not None and hasattr(audit, "log"):
            return audit.log(
                username=self._current_username(),
                action="SYNC_EVENT",
                details=str(args[0]) if args else "",
            )
    except Exception:
        pass
    return None


HMGBillingApp._hmg_sync_event = _hmg_sync_event


# ---- 5. ECG saved-button flag --------------------------------------------
if not hasattr(HMGBillingApp, "_hmg_saved_ecg_button_added"):
    HMGBillingApp._hmg_saved_ecg_button_added = False


print("[HMG] callback resilience v2 installed")



# ============================================================================
# HMG SAVE ENGINE v2 — SQLITE-FIRST, NON-BLOCKING, SINGLE-WRITER
# ============================================================================
# The previous performance layer still had a critical architectural problem:
# `force=True` called the old transactional save synchronously. That old path
# serialised 24 collections, opened/wrote many JSON files, updated the schema
# manifest, and could hold the UI thread for seconds. Debouncing did not fix
# that because registration/logout explicitly bypassed the debounce.
#
# v2 changes the rule:
#   * SQLite is the authoritative durable save for normal/critical saves.
#   * The UI thread ONLY takes a shallow application snapshot and queues it.
#   * Exactly ONE background writer drains the latest snapshot.
#   * JSON is a compatibility/export layer, not part of the interactive save.
#   * `force=True` means QUEUE IMMEDIATELY, not BLOCK THE UI.
#   * `_wait=True` is reserved for app shutdown/logout when a durable flush is
#     actually required before the process disappears.
#   * Older save wrappers are deliberately bypassed here to prevent recursion.
# ============================================================================

_HMG_SAVEV2_JSON_INTERVAL = 30.0
_HMG_SAVEV2_WAIT_TIMEOUT = 12.0

try:
    _hmg_savev2_state = getattr(HMGBillingApp, "_hmg_savev2_state", None)
    if _hmg_savev2_state is None:
        _hmg_savev2_state = {}
        HMGBillingApp._hmg_savev2_state = _hmg_savev2_state

    def _hmg_savev2_init(self):
        if getattr(self, "_hmg_savev2_initialized", False):
            return
        self._hmg_savev2_initialized = True
        self._hmg_savev2_lock = _hmg_threading.RLock()
        self._hmg_savev2_job = None
        self._hmg_savev2_worker = None
        self._hmg_savev2_seq = 0
        self._hmg_savev2_last_json = 0.0
        self._hmg_savev2_last_ok = False
        self._hmg_savev2_last_error = ""
        self._hmg_savev2_last_snapshot = None
        self._hmg_savev2_done = _hmg_threading.Event()
        self._hmg_savev2_done.set()

    def _hmg_savev2_export_json(self, snap):
        """Compatibility export only; SQLite has already become durable."""
        base = self._get_reports_dir()
        files = {
            "patients.json": snap.get("patients", []),
            "emr.json": snap.get("emr_records", []),
            "lab.json": snap.get("lab_tests", []),
            "rad.json": snap.get("radiology", []),
            "rx.json": snap.get("prescriptions", []),
            "bills.json": snap.get("bills", []),
            "drugs.json": snap.get("drugs", []),
            "invs.json": snap.get("investigations", []),
            "ecg.json": snap.get("ecg_reports", []),
            "pathology.json": snap.get("pathology_data", []),
            "followups.json": snap.get("followups", []),
            "summaries.json": snap.get("patient_summaries", {}),
            "consent_forms.json": snap.get("consent_forms", []),
            "referral_notes.json": snap.get("referral_notes", []),
            "daily_notes.json": snap.get("daily_notes", []),
            "snapshots.json": snap.get("patient_snapshots", []),
            "procedures_db.json": snap.get("procedures_db", []),
            "lab_results.json": snap.get("lab_results", []),
            "tasks.json": snap.get("tasks", []),
            "admissions.json": snap.get("admissions", []),
            "saved_lab_reports.json": snap.get("saved_lab_reports", []),
            "appointments.json": snap.get("appointments", []),
            "nursing_notes.json": snap.get("nursing_notes", []),
            "transfers.json": snap.get("transfers", []),
            "vitals.json": snap.get("_vitals_records", []),
            "surgical_cases.json": snap.get("_surgical_cases", []),
            "beds.json": {
                "wards": snap.get("_wards", []),
                "beds": snap.get("_beds", []),
            },
        }
        for fn, data in files.items():
            try:
                # Use the already-throttled atomic writer. This is deliberately
                # outside the interactive/UI thread.
                self._save_json(os.path.join(base, fn), data)
            except Exception as e:
                print(f"[HMG SAVE V2] JSON export {fn}: {e}")
        self._hmg_savev2_last_json = _hmg_time.monotonic()

    def _hmg_savev2_worker_loop(self):
        while True:
            with self._hmg_savev2_lock:
                job = self._hmg_savev2_job
                self._hmg_savev2_job = None
                if job is None:
                    self._hmg_savev2_worker = None
                    self._hmg_savev2_done.set()
                    return
                snap, seq, force_json = job
                self._hmg_savev2_done.clear()

            try:
                # IMPORTANT: bypass every older save_all wrapper. The old
                # wrappers are exactly what caused the UI-thread stalls.
                sid = _hmg_write_sqlite_snapshot_from_snap(self, snap)
                if not sid:
                    raise RuntimeError("SQLite snapshot returned no snapshot id")

                self._hmg_savev2_last_snapshot = sid
                self._hmg_savev2_last_ok = True
                self._hmg_savev2_last_error = ""
                print(f"[HMG SAVE V2] SQLite committed seq={seq} id={sid}")

                # JSON is compatibility output. Force saves request it;
                # ordinary saves export at most once every 30 seconds.
                now = _hmg_time.monotonic()
                if force_json or (now - self._hmg_savev2_last_json >= _HMG_SAVEV2_JSON_INTERVAL):
                    self._hmg_savev2_export_json(snap)
                    print(f"[HMG SAVE V2] JSON compatibility export complete seq={seq}")
            except Exception as e:
                self._hmg_savev2_last_ok = False
                self._hmg_savev2_last_error = str(e)
                print(f"[HMG SAVE V2] FAILED seq={seq}: {e}")

            # If another save arrived while this snapshot was being written,
            # the loop immediately takes the newest snapshot. Older snapshots
            # are intentionally discarded because the latest state supersedes
            # them.

    def _hmg_savev2_queue(self, force=False):
        _hmg_savev2_init(self)
        try:
            snap = _hmg_snapshot_app_state(self)
        except Exception as e:
            print(f"[HMG SAVE V2] snapshot failed: {e}")
            return False

        with self._hmg_savev2_lock:
            self._hmg_savev2_seq += 1
            seq = self._hmg_savev2_seq
            # Latest snapshot wins. Do not build a backlog of full clinical
            # application snapshots.
            self._hmg_savev2_job = (snap, seq, bool(force))
            self._hmg_savev2_done.clear()
            worker = self._hmg_savev2_worker
            if worker is None or not worker.is_alive():
                worker = _hmg_threading.Thread(
                    target=self._hmg_savev2_worker_loop,
                    name="HMG-SaveWorker",
                    daemon=True,
                )
                self._hmg_savev2_worker = worker
                worker.start()

        print(f"[HMG SAVE V2] queued seq={seq} force={bool(force)}")
        return True

    def _save_all_savev2(self, *args, **kwargs):
        force = bool(kwargs.pop("force", False))
        wait = bool(kwargs.pop("_wait", False))
        if args and isinstance(args[0], bool):
            force = bool(args[0])
        queued = _hmg_savev2_queue(self, force=force)
        if wait and queued:
            # Shutdown-only path. Normal buttons/registration NEVER wait.
            self._hmg_savev2_done.wait(_HMG_SAVEV2_WAIT_TIMEOUT)
            if not self._hmg_savev2_done.is_set():
                print("[HMG SAVE V2] shutdown wait timed out; SQLite worker remains daemonized")
        return queued

    HMGBillingApp.save_all = _save_all_savev2
    HMGBillingApp._hmg_savev2_queue = _hmg_savev2_queue
    HMGBillingApp._hmg_savev2_worker_loop = _hmg_savev2_worker_loop
    HMGBillingApp._hmg_savev2_export_json = _hmg_savev2_export_json
    HMGBillingApp._hmg_savev2_init = _hmg_savev2_init
    HMGBillingApp._hmg_savev2_active = True

    # Replace the earlier blocking critical hooks. Registration queues the
    # durable save and returns immediately; shutdown/logout explicitly waits.
    _HMG_SAVEV2_ORIG_REG = getattr(HMGBillingApp, "_reg_pt", None)
    if callable(_HMG_SAVEV2_ORIG_REG) and not getattr(_HMG_SAVEV2_ORIG_REG, "_hmg_savev2_reg", False):
        def _hmg_savev2_reg(self, instance=None, *a, **kw):
            result = _HMG_SAVEV2_ORIG_REG(self, instance, *a, **kw)
            try:
                self.save_all(force=True)
            except Exception as e:
                print(f"[HMG SAVE V2] post-register queue: {e}")
            return result
        _hmg_savev2_reg._hmg_savev2_reg = True
        HMGBillingApp._reg_pt = _hmg_savev2_reg

    _HMG_SAVEV2_ORIG_LOGOUT = getattr(HMGBillingApp, "_logout", None)
    if callable(_HMG_SAVEV2_ORIG_LOGOUT) and not getattr(_HMG_SAVEV2_ORIG_LOGOUT, "_hmg_savev2_logout", False):
        def _hmg_savev2_logout(self, *a, **kw):
            try:
                self.save_all(force=True, _wait=True)
            except Exception as e:
                print(f"[HMG SAVE V2] logout flush: {e}")
            return _HMG_SAVEV2_ORIG_LOGOUT(self, *a, **kw)
        _hmg_savev2_logout._hmg_savev2_logout = True
        HMGBillingApp._logout = _hmg_savev2_logout

    _HMG_SAVEV2_ORIG_STOP = getattr(HMGBillingApp, "on_stop", None)
    if callable(_HMG_SAVEV2_ORIG_STOP) and not getattr(_HMG_SAVEV2_ORIG_STOP, "_hmg_savev2_stop", False):
        def _hmg_savev2_stop(self, *a, **kw):
            try:
                self.save_all(force=True, _wait=True)
            except Exception as e:
                print(f"[HMG SAVE V2] on_stop flush: {e}")
            return _HMG_SAVEV2_ORIG_STOP(self, *a, **kw)
        _hmg_savev2_stop._hmg_savev2_stop = True
        HMGBillingApp.on_stop = _hmg_savev2_stop

    print("[HMG] SAVE ENGINE v2 installed — SQLite-first, non-blocking, single-writer")
except Exception as _hmg_savev2_error:
    print(f"[HMG SAVE V2] INSTALL FAILED: {_hmg_savev2_error}")
    raise
    
# ============================================================================
# HMG FINAL UI + PERSISTENCE REPAIR
# ----------------------------------------------------------------------------
#   • Dashboard crowded cards replaced by expandable CollapsibleSection groups.
#   • All interactive fonts raised to a minimum of 16 pt, bold.
#   • Consistent M3 surfaces (no rainbow of stat colours, no overlapping).
#   • Robust load: SQLite snapshot + JSON are merged, whichever has more data
#     per collection wins.  Force saves also flush the four critical JSON
#     files synchronously so a mid-flight app kill cannot lose a registration.
# ============================================================================

# ---------- 1. Robust load (SQLite + JSON, keep larger collection) ---------
def _hmg_robust_load_all(self):
    """Load core clinical data from SQLite snapshot AND JSON files, keeping
    whichever store has more records per collection.  This protects against
    a stale SQLite snapshot overwriting a newer JSON file (and vice versa),
    which is what caused saved patients to appear 'removed' after login."""
    sqlite_snapshot = {}
    try:
        store = HMGTransactionalStore(self)
        with store._connect() as c:
            rows = c.execute(
                "SELECT name, payload FROM snapshots").fetchall()
        for name, payload in rows:
            if name in HMGTransactionalStore.COLLECTIONS:
                try:
                    sqlite_snapshot[name] = json.loads(payload)
                except Exception as e:
                    print(f"[HMG LOAD] SQLite decode {name}: {e}")
    except Exception as e:
        print(f"[HMG LOAD] SQLite unavailable: {e}")

    json_snapshot = {}
    for fn, attr in _HMG_PERSIST_FILES.items():
        for candidate in (self._hmg_data_path(fn),
                          os.path.join(os.getcwd(), fn)):
            if not os.path.exists(candidate):
                continue
            try:
                with open(candidate, "r", encoding="utf-8") as f:
                    json_snapshot[attr] = json.load(f)
                break
            except Exception as e:
                print(f"[HMG LOAD] {candidate}: {e}")

    def _size(value):
        if isinstance(value, list):
            return len(value)
        if isinstance(value, dict):
            return len(value)
        return 0

    for attr in set(sqlite_snapshot) | set(json_snapshot):
        a = sqlite_snapshot.get(attr)
        b = json_snapshot.get(attr)
        chosen = a if _size(a) >= _size(b) else b
        # Preserve the original loader's normalization rules.
        try:
            if attr == "drugs" and isinstance(chosen, list):
                chosen = [{
                    "name": d.get("name", ""), "price": d.get("price", 0),
                    "qty": d.get("qty", d.get("quantity", 0)),
                    "min": d.get("min", d.get("min_stock", 20)),
                    "cat": d.get("cat", d.get("category", "")),
                    "mfr": d.get("mfr", d.get("manufacturer", "")),
                    "exp": d.get("exp", ""), "batch": d.get("batch", ""),
                } for d in chosen if isinstance(d, dict)]
            elif attr == "investigations" and isinstance(chosen, list):
                chosen = [{
                    "name": inv.get("name", ""), "price": inv.get("price", 0),
                    "dept": inv.get("dept", inv.get("department", "")),
                    "cat": inv.get("cat", inv.get("category", "")),
                    "tat": inv.get("tat", ""),
                    "specimen": inv.get("specimen", ""),
                    "ref": inv.get("ref", ""), "unit": inv.get("unit", ""),
                    "desc": inv.get("desc", ""),
                    "result_type": inv.get("result_type", "text"),
                    "allowed_units": inv.get("allowed_units", []),
                    "default_unit": inv.get("default_unit", ""),
                    "qualitative_options": inv.get("qualitative_options", []),
                    "reference": inv.get("reference", ""),
                } for inv in chosen if isinstance(inv, dict)]
        except Exception as e:
            print(f"[HMG LOAD] normalize {attr}: {e}")
        setattr(self, attr, chosen)

    # Keep the task manager and Phase-2 engine in sync with the loaded list.
    try:
        if hasattr(self, "task_manager"):
            self.task_manager.tasks = getattr(self, "tasks", [])
    except Exception:
        pass

    # Re-inject panel tests that only live in PANEL_DEFINITIONS.
    try:
        self._ensure_panel_tests_in_catalog()
    except Exception as e:
        print(f"[HMG LOAD] panel catalog: {e}")

    loaded = len(getattr(self, "patients", []) or [])
    print(f"[HMG LOAD] patients loaded: {loaded} "
          f"(SQLite={_size(sqlite_snapshot.get('patients'))}, "
          f"JSON={_size(json_snapshot.get('patients'))})")


# Replace the current load_all with the robust merge.
HMGBillingApp._hmg_robust_load_all = _hmg_robust_load_all
HMGBillingApp.load_all = _hmg_robust_load_all


# ---------- 2. Synchronous flush of critical files on force save ----------
def _hmg_savev2_sync_critical(self):
    """Write the four small, most-critical JSON files synchronously from the
    UI thread before returning.  SQLite continues to be the authoritative
    store; this is a belt-and-braces guarantee that a just-registered patient
    survives an abrupt process kill even while the async worker is running."""
    base = self._get_reports_dir()
    for fn, attr in (("patients.json", "patients"),
                     ("tasks.json", "tasks"),
                     ("bills.json", "bills"),
                     ("rx.json", "prescriptions")):
        try:
            self._save_json(os.path.join(base, fn),
                            getattr(self, attr, []))
        except Exception as e:
            print(f"[HMG SAVE V2] sync {fn}: {e}")

HMGBillingApp._hmg_savev2_sync_critical = _hmg_savev2_sync_critical

# Wrap the existing savev2 wrapper so force saves also flush critical files.
_HMG_SAVEV2_PREV = getattr(HMGBillingApp, "save_all", None)
if callable(_HMG_SAVEV2_PREV) and not getattr(_HMG_SAVEV2_PREV, "_hmg_sync_critical_wrapped", False):
    def _save_all_with_sync(self, *args, **kwargs):
        force = bool(kwargs.get("force", False))
        if args and isinstance(args[0], bool):
            force = bool(args[0])
        result = _HMG_SAVEV2_PREV(self, *args, **kwargs)
        if force:
            try:
                self._hmg_savev2_sync_critical()
            except Exception as e:
                print(f"[HMG SAVE V2] sync critical wrapper: {e}")
        return result
    _save_all_with_sync._hmg_sync_critical_wrapped = True
    HMGBillingApp.save_all = _save_all_with_sync


