_HMG_LOGIN_BEFORE_DIAG = getattr(HMGBillingApp, "_on_login_success", None)
if callable(_HMG_LOGIN_BEFORE_DIAG) and not getattr(
        _HMG_LOGIN_BEFORE_DIAG, "_hmg_patient_diag", False):
    def _login_patient_diag(self, user, *a, **kw):
        result = _HMG_LOGIN_BEFORE_DIAG(self, user, *a, **kw)
        try:
            def _check(dt):
                try:
                    n = len(getattr(self, "patients", []) or [])
                    if n == 0:
                        print("[HMG DIAG] patients collection is empty "
                              "after login. Check HMG_Reports folder.")
                    else:
                        print(f"[HMG DIAG] {n} patient record(s) loaded.")
                except Exception as e:
                    print(f"[HMG DIAG] {e}")
            Clock.schedule_once(_check, 1.5)
        except Exception:
            pass
        return result
    _login_patient_diag._hmg_patient_diag = True
    HMGBillingApp._on_login_success = _login_patient_diag


