# ============================================================================
# HMG UI UNIFICATION v3 — safe handlers, reliable icons, responsive layout,
# Clinical AI + all other tabs reorganised into CollapsibleSections.
# ============================================================================
from kivy.core.window import Window as _HMG_Window
import functools as _hmg_ft
import traceback as _hmg_tb

# ---------------------------------------------------------------------------
# A.  SAFE HANDLER SYSTEM  —  handles all invalid instances properly
# ---------------------------------------------------------------------------
# Capture the *unwrapped* popup so the wrapper can always show a message,
# even when _popup itself was wrapped.
_HMG_ORIGINAL_POPUP = getattr(HMGBillingApp, "_popup", None)


def _hmg_safe(fn):
    """Wrap a callback so a bad state cannot crash the UI."""
    @_hmg_ft.wraps(fn)
    def _wrapped(self, *args, **kwargs):
        try:
            return fn(self, *args, **kwargs)
        except Exception as e:
            tb = _hmg_tb.format_exc()
            print(f"[HMG SAFE] {fn.__name__}: {e}\n{tb}")
            try:
                if (_HMG_ORIGINAL_POPUP is not None
                        and fn is not _HMG_ORIGINAL_POPUP
                        and not getattr(fn, "_hmg_is_popup", False)):
                    _HMG_ORIGINAL_POPUP(
                        self, "Action could not complete",
                        f"{fn.__name__} failed.\n{type(e).__name__}: {e}")
            except Exception:
                pass
            return None
    _wrapped._hmg_safe = True
    return _wrapped


# Mark the popup pair so they are not wrapped (prevents recursion).
if callable(_HMG_ORIGINAL_POPUP):
    _HMG_ORIGINAL_POPUP._hmg_is_popup = True
_HMG_ORIGINAL_TEXTPOPUP = getattr(HMGBillingApp, "_text_popup", None)
if callable(_HMG_ORIGINAL_TEXTPOPUP):
    _HMG_ORIGINAL_TEXTPOPUP._hmg_is_popup = True


def _hmg_require_patient(self, message="Please select a patient first."):
    """Guard helper — returns True when a patient is selected."""
    if getattr(self, "cp", None):
        return True
    try:
        _HMG_ORIGINAL_POPUP(self, "No patient selected", message)
    except Exception:
        pass
    return False


def _hmg_safe_list(value):
    return value if isinstance(value, list) else (list(value) if value else [])


def _hmg_safe_dict(value):
    return value if isinstance(value, dict) else {}


HMGBillingApp._hmg_require_patient = _hmg_require_patient
HMGBillingApp._hmg_safe_list = staticmethod(_hmg_safe_list)
HMGBillingApp._hmg_safe_dict = staticmethod(_hmg_safe_dict)


# Wrap every private method that acts as a user callback.  Special lifecycle
# methods (build, on_stop, apply_m3_theme, load_all, save_all) are preserved.
_HMG_UNSAFE_SKIP = {
    "build", "on_stop", "on_start", "on_pause", "on_resume",
    "_apply_m3_theme", "_build_main_app", "load_all", "save_all",
    "_popup", "_text_popup", "_hmg_safe", "_hmg_require_patient",
    "_dashboard", "_clinical_ai_tab", "_analytics_tab", "_emr",
}

_HMG_SAFE_COUNT = 0
for _name in list(dir(HMGBillingApp)):
    if not _name.startswith("_") or _name.startswith("__"):
        continue
    if _name in _HMG_UNSAFE_SKIP:
        continue
    try:
        _fn = getattr(HMGBillingApp, _name)
    except Exception:
        continue
    if not callable(_fn):
        continue
    if getattr(_fn, "_hmg_safe", False) or getattr(_fn, "_hmg_is_popup", False):
        continue
    try:
        # Only wrap things that look like bound callbacks (accept `self`).
        import inspect as _hmg_insp
        _params = list(_hmg_insp.signature(_fn).parameters)
        if not _params or _params[0] != "self":
            continue
    except Exception:
        continue
    try:
        setattr(HMGBillingApp, _name, _hmg_safe(_fn))
        _HMG_SAFE_COUNT += 1
    except Exception:
        pass

print(f"[HMG SAFE] wrapped {_HMG_SAFE_COUNT} callbacks with invalid-instance protection")


