def _hmg_nav_button(self, label, target, icon_key=None):
    """Standard module / navigation button — neutral M3 surface, bold 16 pt."""
    theme = _m3_theme(self)
    base = _m3("surface_container_high", theme)
    down = _m3("surface_container_highest", theme)
    text_colour = _m3("on_surface", theme)
    icon = HMG_ICONS.get(icon_key or "", "") if icon_key else ""
    text = f"{icon}  {label}" if icon else label
    btn = _PlainKivyButton(
        text=text, font_size=16, bold=True,
        size_hint_y=None, height=_hmg_btn_height(),
        background_normal="", background_down="",
        background_color=base, color=text_colour,
        halign="center", valign="middle")
    btn.bind(state=lambda w, s, b=base, d=down:
             setattr(w, "background_color", d if s == "down" else b))
    if target:
        btn.bind(on_press=lambda _b, t=target: self._switch(t))
    return btn


def _hmg_primary_button(self, label, on_press, height=None):
    """Solid primary button used for the main action of a screen."""
    theme = _m3_theme(self)
    btn = _PlainKivyButton(
        text=label, font_size=17, bold=True,
        size_hint_y=None, height=height or _hmg_btn_height(),
        background_normal="", background_down="",
        background_color=_m3("primary", theme),
        color=_m3("on_primary", theme))
    if callable(on_press):
        btn.bind(on_press=on_press)
    return btn


def _hmg_action_button(self, label, on_press, icon_key=None):
    """Tonal action inside a CollapsibleSection body."""
    theme = _m3_theme(self)
    icon = HMG_ICONS.get(icon_key or "", "") if icon_key else ""
    text = f"{icon}  {label}" if icon else label
    btn = _PlainKivyButton(
        text=text, font_size=16, bold=True,
        size_hint_y=None, height=_hmg_btn_height(),
        background_normal="", background_down="",
        background_color=_m3("primary_container", theme),
        color=_m3("on_primary_container", theme))
    if callable(on_press):
        btn.bind(on_press=on_press)
    return btn


def _hmg_style_section(self, section):
    """Uniform primary-colour header, bold 18 pt."""
    theme = _m3_theme(self)
    try:
        section.header_btn.font_size = 18
        section.header_btn.bold = True
        section.header_btn.height = dp(58)
        section.header_btn.background_normal = ""
        section.header_btn.background_down = ""
        section.header_btn.background_color = _m3("primary", theme)
        section.header_btn.color = _m3("on_primary", theme)
    except Exception:
        pass


