# ---------------------------------------------------------------------------
# G.  GENERIC TAB REORGANIZER — same treatment for every other tab
# ---------------------------------------------------------------------------
def _hmg_split_sections(container):
    """Split a layout's children into [(title, [widgets])] based on bold
    section labels (>= 16pt). Visual order is preserved."""
    try:
        ordered = list(reversed(container.children))
    except Exception:
        return []
    sections = []
    cur_title = "General"
    cur = []
    for w in ordered:
        is_header = (
            isinstance(w, Label)
            and bool(getattr(w, "bold", False))
            and float(getattr(w, "font_size", 0) or 0) >= 16.0
            and str(w.text).strip())
        if is_header:
            if cur:
                sections.append((cur_title, cur))
            cur_title = str(w.text).strip()
            cur = []
        else:
            cur.append(w)
    if cur:
        sections.append((cur_title, cur))
    return sections


def _hmg_reorganize_tab(self, tab):
    """Wrap a tab's existing visual sections into CollapsibleSections.
    Every widget is preserved (same object), so all self.<widget> references
    remain valid after reorganisation."""
    try:
        # Locate the tab's ScrollView content root.
        sv = next((c for c in tab.children if isinstance(c, ScrollView)), None)
        if sv is None:
            return False
        inner = next((c for c in sv.children if isinstance(c, BoxLayout)), None)
        if inner is None:
            return False

        # Skip if this tab already has CollapsibleSections at the top level.
        for child in inner.children:
            if isinstance(child, CollapsibleSection):
                return False
            for sub in getattr(child, "children", []):
                if isinstance(sub, CollapsibleSection):
                    return False

        sections = _hmg_split_sections(inner)
        if len(sections) <= 1:
            return False

        theme = _m3_theme(self)
        new_root = BoxLayout(orientation="vertical",
                             padding=dp(8), spacing=dp(10),
                             size_hint_y=None)
        new_root.bind(minimum_height=new_root.setter("height"))

        for idx, (title, widgets) in enumerate(sections):
            short_title = title if len(title) <= 46 else title[:44] + "…"
            sec = CollapsibleSection(short_title, start_open=(idx == 0))
            _hmg_style_section(self, sec)
            for w in widgets:
                try:
                    if w.parent is not None:
                        w.parent.remove_widget(w)
                    sec.body.add_widget(w)
                except Exception as e:
                    print(f"[HMG REORG] {tab.text}/{title}: {e}")
            new_root.add_widget(sec)

        inner.clear_widgets()
        inner.add_widget(new_root)
        return True
    except Exception as e:
        print(f"[HMG REORG] {getattr(tab, 'text', '?')}: {e}")
        return False


def _hmg_reorganize_all_tabs(self, *args):
    """Apply the grouped layout to every remaining tab."""
    # Tabs already organised by their own builders.
    skip = {"Dashboard", "Clinical AI", "Analytics", "EMR"}
    count = 0
    for tab in list(getattr(self.tp, "tab_list", [])):
        if getattr(tab, "text", "") in skip:
            continue
        if self._hmg_reorganize_tab(tab):
            count += 1
    print(f"[HMG REORG] reorganised {count} additional tabs")


HMGBillingApp._hmg_reorganize_tab = _hmg_reorganize_tab
HMGBillingApp._hmg_reorganize_all_tabs = _hmg_reorganize_all_tabs


# ---------------------------------------------------------------------------
# H.  APPLY REORGANISATION AFTER LOGIN
# ---------------------------------------------------------------------------
_HMG_PREV_LOGIN = getattr(HMGBillingApp, "_on_login_success", None)
if callable(_HMG_PREV_LOGIN) and not getattr(_HMG_PREV_LOGIN, "_hmg_reorg_hook", False):
    def _login_reorg(self, user, *a, **kw):
        result = _HMG_PREV_LOGIN(self, user, *a, **kw)

        def _apply(_dt):
            try:
                self._hmg_reorganize_all_tabs()
            except Exception as e:
                print(f"[HMG REORG] after login: {e}")
        # Defer until the fast-load batch has finished constructing every tab.
        Clock.schedule_once(_apply, 6.0)
        return result
    _login_reorg._hmg_reorg_hook = True
    HMGBillingApp._on_login_success = _login_reorg


