def _hmg_rebuild_header(self, *_):
    try:
        root = getattr(self, "main_root", None)
        if root is None:
            return
        tp = getattr(self, "tp", None)
        to_remove = None
        for child in list(root.children):
            if child is tp:
                continue
            try:
                if (child.__class__.__name__ == "BoxLayout"
                        and getattr(child, "orientation", "") == "vertical"
                        and 80 <= float(getattr(child, "height", 0) or 0) <= 110):
                    to_remove = child
                    break
            except Exception:
                pass
        if to_remove is not None:
            try:
                root.remove_widget(to_remove)
            except Exception as e:
                print(f"[HMG HEADER] remove old: {e}")
        # For vertical BoxLayout, add header LAST so it sits at the top.
        root.add_widget(_hmg_build_header_v4(self))
        print("[HMG HEADER] rebuilt")
    except Exception as e:
        print(f"[HMG HEADER] rebuild: {e}")

HMGBillingApp._hmg_build_header_v4 = _hmg_build_header_v4
HMGBillingApp._hmg_rebuild_header = _hmg_rebuild_header


# ---- 6. Guarantee the EMR tab always appears ------------------------------
def _hmg_emr_builder_wrapper(self, *args, **kwargs):
    # Every EMR builder reads these; make sure they are the right type.
    self._hmg_ensure_runtime_defaults()

    # Chain of capable EMR builders, strongest first.
    candidates = [
        getattr(self, "_hmg_original_emr_builder", None),
        globals().get("_contrast_fixed_emr"),
        globals().get("_hmg_complex_emr"),
    ]
    for fn in candidates:
        if not callable(fn):
            continue
        try:
            result = fn(self, *args, **kwargs)
            # Confirm the tab was actually added; some builders swallow
            # their own errors.
            has_tab = any(getattr(t, "text", "") == "EMR"
                          for t in getattr(self.tp, "tab_list", []))
            if has_tab:
                return result
            print(f"[HMG EMR] {getattr(fn, '__name__', fn)} added no tab")
        except Exception as e:
            print(f"[HMG EMR] {getattr(fn, '__name__', fn)} failed: {e}")
            continue

    # Minimal fallback: always gives the user a working EMR entry point.
    try:
        theme = _m3_theme(self)
        tab = TabbedPanelItem(text="EMR")
        sv = ScrollView(bar_width=dp(4))
        root = BoxLayout(orientation="vertical", padding=dp(10),
                         spacing=dp(10), size_hint_y=None)
        root.bind(minimum_height=root.setter("height"))
        root.add_widget(Label(
            text="EMR is available. Select a patient, then open the "
                 "Registration or EMR tab to record clinical notes.",
            font_size=16, bold=True,
            color=_m3("on_surface", theme),
            size_hint_y=None, height=dp(80)))
        for label, target in (("Registration", "Registration"),
                              ("Clinical AI", "Clinical AI"),
                              ("Enhanced Lab", "Enhanced Lab"),
                              ("Billing", "Billing")):
            b = _PlainKivyButton(
                text=label, font_size=16, bold=True,
                size_hint_y=None, height=dp(56),
                background_normal="", background_down="",
                background_color=_m3("primary", theme),
                color=_m3("on_primary", theme))
            b.bind(on_press=lambda _b, t=target: self._switch(t))
            root.add_widget(b)
        sv.add_widget(root)
        tab.add_widget(sv)
        self.tp.add_widget(tab)
        print("[HMG EMR] fallback tab installed")
        return tab
    except Exception as e:
        print(f"[HMG EMR] fallback failed: {e}")
        return None

# Preserve whatever the current EMR implementation is under a private alias,
# then install the wrapper as the public `_emr`.
if not hasattr(HMGBillingApp, "_hmg_original_emr_builder") \
        or HMGBillingApp._hmg_original_emr_builder is None:
    HMGBillingApp._hmg_original_emr_builder = getattr(
        HMGBillingApp, "_emr", None)
HMGBillingApp._emr = _hmg_emr_builder_wrapper


# ---- 7. Share fallback that does not require FileProvider -----------------
def _hmg_share_file_v2(self, filepath):
    if not filepath or not os.path.exists(filepath):
        self._popup("Share Error", f"File not found:\n{filepath}")
        return

    if platform != "android":
        try:
            if sys.platform == "win32":
                subprocess.Popen(["explorer", "/select,", filepath])
            elif sys.platform == "darwin":
                subprocess.Popen(["open", "-R", filepath])
            else:
                subprocess.Popen(["xdg-open", os.path.dirname(filepath)])
        except Exception as e:
            self._popup("Share Error", str(e))
        return

    try:
        from jnius import autoclass
        PythonActivity = autoclass("org.kivy.android.PythonActivity")
        Intent = autoclass("android.content.Intent")
        File = autoclass("java.io.File")
        Uri = autoclass("android.net.Uri")

        activity = PythonActivity.mActivity
        if activity is None:
            self._popup("Share Error", "Android activity unavailable.")
            return

        mime, _ = mimetypes.guess_type(filepath)
        if not mime:
            low = filepath.lower()
            if low.endswith(".pdf"):
                mime = "application/pdf"
            elif low.endswith(".png"):
                mime = "image/png"
            elif low.endswith((".jpg", ".jpeg")):
                mime = "image/jpeg"
            else:
                mime = "*/*"

        # Copy into the app's private files directory. This sidesteps both
        # FileProvider (often missing under Pydroid) and the file:// exposure
        # restriction on Android 7+.
        try:
            dst = os.path.join(activity.getFilesDir().getAbsolutePath(),
                               os.path.basename(filepath))
            if os.path.abspath(dst) != os.path.abspath(filepath):
                shutil.copy2(filepath, dst)
        except Exception as e:
            print(f"[HMG SHARE] internal copy: {e}")
            dst = filepath

        try:
            uri = Uri.fromFile(File(dst))
        except Exception as e:
            self._popup("Share Error", f"Could not prepare file:\n{e}")
            return

        # Try ACTION_SEND first.
        try:
            intent = Intent(Intent.ACTION_SEND)
            intent.setType(mime)
            intent.putExtra(Intent.EXTRA_STREAM, uri)
            intent.putExtra(Intent.EXTRA_SUBJECT, os.path.basename(dst))
            intent.addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION)
            intent.addFlags(Intent.FLAG_ACTIVITY_NEW_TASK)
            chooser = Intent.createChooser(intent, "Share Report")
            chooser.addFlags(Intent.FLAG_ACTIVITY_NEW_TASK)
            activity.startActivity(chooser)
            return
        except Exception as e:
            print(f"[HMG SHARE] ACTION_SEND failed: {e}")

        # Fall back to ACTION_VIEW so the user can pick a share target
        # inside their viewer.
        try:
            view = Intent(Intent.ACTION_VIEW)
            view.setDataAndType(uri, mime)
            view.addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION)
            view.addFlags(Intent.FLAG_ACTIVITY_NEW_TASK)
            activity.startActivity(view)
        except Exception as e2:
            self._popup("Share Error", f"Could not share file:\n{e2}")
    except Exception as e:
        print(f"[HMG SHARE] outer: {e}")
        self._popup("Share Error", str(e))

HMGBillingApp._share_file = _hmg_share_file_v2


# ---- 8. Apply the repair after login and once FAST LOAD is done ----------
_HMG_PREV_LOGIN_V4 = getattr(HMGBillingApp, "_on_login_success", None)
if callable(_HMG_PREV_LOGIN_V4) and not getattr(_HMG_PREV_LOGIN_V4, "_hmg_v4", False):
    def _login_v4(self, user, *a, **kw):
        result = _HMG_PREV_LOGIN_V4(self, user, *a, **kw)
        self._hmg_ensure_runtime_defaults()

        def _after_batch(_dt):
            try:
                self._hmg_ensure_runtime_defaults()
                self._hmg_rebuild_header()
                have_emr = any(getattr(t, "text", "") == "EMR"
                               for t in getattr(self.tp, "tab_list", []))
                if not have_emr:
                    self._hmg_emr_builder_wrapper(self)
                # Re-run the analytics tab once now that defaults are stable.
                try:
                    self._analytics_render()
                except Exception as e:
                    print(f"[HMG ANALYTICS] post-login render: {e}")
            except Exception as e:
                print(f"[HMG POST-BATCH] {e}")
        # FAST LOAD completes in ≈0.1 s on a fast phone; retry after a wide
        # margin, then once more in case a slow device is still building.
        Clock.schedule_once(_after_batch, 5.0)
        Clock.schedule_once(_after_batch, 12.0)
        return result
    _login_v4._hmg_v4 = True
    HMGBillingApp._on_login_success = _login_v4


