# ============================================================================
# HMG EMERGENCY FIX v5
#   • _period_bounds is a proper @staticmethod again -> analytics stops
#     starving the Kivy event loop -> dashboard / Clinical AI / Analytics
#     buttons respond again.
#   • EMR builder wrapper now calls bound or unbound builders correctly and
#     always guarantees an EMR tab.
#   • drugs.json is merged with the built-in default catalogue.
# ============================================================================

import inspect as _hmg_inspect_v5

# ---- 1. FIX _period_bounds (staticmethod, 2 args) -------------------------

def _hmg_deterministic_period_bounds(period, anchor):
    """Deterministic period boundaries. Signature: (period, anchor)."""
    try:
        a = anchor.date() if isinstance(anchor, datetime) else anchor
        if not hasattr(a, "replace"):
            a = datetime.now().date()
    except Exception:
        a = datetime.now().date()

    if period == "daily":
        return a, a, a.strftime("%Y-%m-%d")

    if period == "weekly":
        start = a - timedelta(days=a.weekday())
        end = start + timedelta(days=6)
        return (start, end,
                f"{start.isocalendar().year}-W{start.isocalendar().week:02d}")

    if period == "monthly":
        start = a.replace(day=1)
        if start.month == 12:
            nxt = start.replace(year=start.year + 1, month=1, day=1)
        else:
            nxt = start.replace(month=start.month + 1, day=1)
        return start, nxt - timedelta(days=1), start.strftime("%Y-%m")

    start = a.replace(month=1, day=1)
    return (start,
            start.replace(year=start.year + 1) - timedelta(days=1),
            start.strftime("%Y"))


AnalyticsEngine._period_bounds = staticmethod(_hmg_deterministic_period_bounds)
print("[HMG v5] _period_bounds installed as a proper staticmethod")


# ---- 2. FIX the EMR builder wrapper (bound + unbound aware) ---------------

def _hmg_call_builder(fn, self, *args, **kwargs):
    """Call an EMR builder whether it's a bound method or a raw function."""
    is_bound = hasattr(fn, "__self__")
    try:
        sig = _hmg_inspect_v5.signature(fn)
        params = [p for p in sig.parameters.values()
                  if p.kind in (p.POSITIONAL_ONLY, p.POSITIONAL_OR_KEYWORD)]
    except Exception:
        params = []

    if is_bound:
        return fn(*args, **kwargs)
    if params and params[0].name == "self":
        return fn(self, *args, **kwargs)
    # Ambiguous — try no-arg first, then with self.
    try:
        return fn(*args, **kwargs)
    except TypeError:
        return fn(self, *args, **kwargs)


def _hmg_emr_builder_wrapper_v5(self, *args, **kwargs):
    try:
        self._hmg_ensure_runtime_defaults()
    except Exception as e:
        print(f"[HMG v5 EMR] defaults: {e}")

    candidates = []

    preserved = getattr(self, "_hmg_original_emr_builder", None)
    if callable(preserved):
        candidates.append(preserved)

    for name in ("_contrast_fixed_emr", "_hmg_complex_emr"):
        fn = globals().get(name)
        if callable(fn):
            candidates.append(fn)

    tried = []
    for fn in candidates:
        try:
            result = _hmg_call_builder(fn, self, *args, **kwargs)
        except Exception as e:
            tried.append(f"{getattr(fn, '__name__', fn)}: {e}")
            print(f"[HMG v5 EMR] {getattr(fn, '__name__', fn)} failed: {e}")
            continue

        try:
            has_tab = any(getattr(t, "text", "") == "EMR"
                          for t in getattr(self.tp, "tab_list", []))
        except Exception:
            has_tab = False

        if has_tab:
            print(f"[HMG v5 EMR] built via {getattr(fn, '__name__', fn)}")
            return result
        tried.append(f"{getattr(fn, '__name__', fn)}: no tab added")

    # ---- Fallback: a small, always-working EMR entry tab ----
    try:
        theme = _m3_theme(self)
        tab = TabbedPanelItem(text="EMR")
        sv = ScrollView(bar_width=dp(4))
        root = BoxLayout(orientation="vertical", padding=dp(12),
                         spacing=dp(10), size_hint_y=None)
        root.bind(minimum_height=root.setter("height"))
        root.add_widget(Label(
            text=("EMR — select a patient from the header, then use the "
                  "buttons below to record clinical notes."),
            font_size=16, bold=True,
            color=_m3("on_surface", theme),
            size_hint_y=None, height=dp(90)))
        for label, target in (("Registration", "Registration"),
                              ("Clinical AI", "Clinical AI"),
                              ("Enhanced Lab", "Enhanced Lab"),
                              ("Billing", "Billing")):
            b = _PlainKivyButton(
                text=label, font_size=16, bold=True,
                size_hint_y=None, height=dp(58),
                background_normal="", background_down="",
                background_color=_m3("primary", theme),
                color=_m3("on_primary", theme))
            b.bind(on_press=lambda _b, t=target: self._switch(t))
            root.add_widget(b)
        sv.add_widget(root)
        tab.add_widget(sv)
        self.tp.add_widget(tab)
        print(f"[HMG v5 EMR] fallback installed (tried: {tried})")
        return tab
    except Exception as e:
        print(f"[HMG v5 EMR] fallback failed: {e}")
        return None


_hmg_emr_builder_wrapper_v5._hmg_v5_emr = True
HMGBillingApp._emr = _hmg_emr_builder_wrapper_v5


# ---- 3. Merge loaded drugs with the built-in default catalogue -----------

_HMG_PREV_ROBUST_LOAD = getattr(HMGBillingApp, "_hmg_robust_load_all", None)
if callable(_HMG_PREV_ROBUST_LOAD) and not getattr(
        _HMG_PREV_ROBUST_LOAD, "_hmg_drug_merge", False):

    def _hmg_robust_load_with_drug_merge(self, *args, **kwargs):
        result = _HMG_PREV_ROBUST_LOAD(self, *args, **kwargs)

        try:
            default_drugs = []
            if hasattr(self, "_init_drugs"):
                try:
                    default_drugs = self._init_drugs() or []
                except Exception as e:
                    print(f"[HMG v5 DRUGS] defaults: {e}")

            current = getattr(self, "drugs", None)
            if not isinstance(current, list):
                current = []

            existing_names = set()
            for d in current:
                if isinstance(d, dict):
                    existing_names.add(
                        str(d.get("name", "")).strip().lower())

            merged = list(current)
            added = []
            for d in default_drugs:
                if not isinstance(d, dict):
                    continue
                nm = str(d.get("name", "")).strip().lower()
                if nm and nm not in existing_names:
                    merged.append(d)
                    existing_names.add(nm)
                    added.append(d.get("name", ""))

            if added:
                self.drugs = merged
                print(f"[HMG v5 DRUGS] merged {len(added)} defaults: "
                      f"{added}")
                # Refresh visible lists / spinners immediately.
                try:
                    fn = getattr(self, "_refresh_drug_list", None)
                    if callable(fn):
                        fn()
                except Exception as e:
                    print(f"[HMG v5 DRUGS] refresh list: {e}")
                try:
                    names = [str(d.get("name", "")) for d in merged
                             if isinstance(d, dict)]
                    for attr in ("emr_drug_spinner", "dispense_drug",
                                 "pharm_drug"):
                        w = getattr(self, attr, None)
                        if w is not None and hasattr(w, "values"):
                            w.values = names
                except Exception as e:
                    print(f"[HMG v5 DRUGS] spinners: {e}")
            else:
                print(f"[HMG v5 DRUGS] catalogue already complete "
                      f"({len(current)} entries)")
        except Exception as e:
            print(f"[HMG v5 DRUGS] merge error: {e}")

        return result

    _hmg_robust_load_with_drug_merge._hmg_drug_merge = True
    HMGBillingApp._hmg_robust_load_all = _hmg_robust_load_with_drug_merge
    HMGBillingApp.load_all = _hmg_robust_load_with_drug_merge


# ---- 4. Silence residual analytics-render exceptions --------------------

