# ---------- 1. Reliable collapsible section -------------------------------
class HMGReliableSection(BoxLayout):
    """Explicit-height, always-responsive collapsible section.

    Never depends on minimum_height propagation.  Body height is computed
    directly from the explicit heights of the children it contains.
    Header uses a plain Kivy Button so nothing can suppress its touch.
    """
    HEADER_H = dp(58)

    def __init__(self, title="", start_open=False, on_height_change=None, **kwargs):
        kwargs.setdefault("orientation", "vertical")
        kwargs.setdefault("size_hint_y", None)
        kwargs.setdefault("spacing", 0)
        super().__init__(**kwargs)
        self._is_open = bool(start_open)
        self._title = str(title or "Section")
        self._on_height_change = on_height_change

        self.header_btn = _PlainKivyButton(
            text=self._header_label(),
            size_hint_y=None, height=self.HEADER_H,
            font_size=18, bold=True,
            background_normal="", background_down="",
            background_color=get_color_from_hex("#6750A4"),
            color=(1, 1, 1, 1),
            halign="left", valign="middle")
        self.header_btn.bind(on_release=self._on_header_release)
        super().add_widget(self.header_btn)

        self.body = BoxLayout(
            orientation="vertical", size_hint_y=None, height=0,
            spacing=dp(6), padding=(dp(8), dp(6), dp(8), dp(6)))
        super().add_widget(self.body)

        self.height = self.HEADER_H
        Clock.schedule_once(lambda dt: self._recompute(), 0)

    def _header_label(self):
        return f"{'▾' if self._is_open else '▸'}   {self._title}"

    def _on_header_release(self, *_):
        self._is_open = not self._is_open
        try:
            self.header_btn.text = self._header_label()
        except Exception:
            pass
        print(f"[HMG SECTION] '{self._title}' -> "
              f"{'open' if self._is_open else 'closed'}")
        self._recompute()

    def _child_height(self, c):
        # Prefer explicit height; fall back to a layout's minimum_height.
        try:
            h = float(getattr(c, "height", 0) or 0)
        except Exception:
            h = 0.0
        if h > 1:
            return h
        try:
            mh = float(getattr(c, "minimum_height", 0) or 0)
        except Exception:
            mh = 0.0
        return mh if mh > 1 else 0.0

    def _recompute(self, *_):
        try:
            if self._is_open:
                self.body.opacity = 1
                self.body.disabled = False
                total = 0.0
                n = 0
                for c in self.body.children:
                    ch = self._child_height(c)
                    if ch > 0:
                        total += ch
                        n += 1
                if n > 1:
                    total += self.body.spacing * (n - 1)
                try:
                    total += self.body.padding[1] + self.body.padding[3]
                except Exception:
                    pass
                self.body.height = max(total, dp(24))
            else:
                self.body.opacity = 0
                self.body.disabled = True
                self.body.height = 0
            self.height = self.HEADER_H + self.body.height
            if callable(self._on_height_change):
                try:
                    self._on_height_change()
                except Exception:
                    pass
            # Bump parents so their own minimum_height bindings refresh.
            p = getattr(self, "parent", None)
            depth = 0
            while p is not None and depth < 6:
                try:
                    if hasattr(p, "do_layout"):
                        p.do_layout()
                except Exception:
                    pass
                p = getattr(p, "parent", None)
                depth += 1
        except Exception as e:
            print(f"[HMG SECTION] recompute: {e}")

    def add_widget(self, w, *args, **kwargs):
        # External callers use self.body.add_widget(...) directly.  If someone
        # calls section.add_widget(w) instead, route the widget into body.
        if w is getattr(self, "header_btn", None) or w is getattr(self, "body", None):
            return super().add_widget(w, *args, **kwargs)
        self.body.add_widget(w, *args, **kwargs)
        Clock.schedule_once(lambda dt: self._recompute(), 0)
        return w

    def toggle(self):
        self._on_header_release()

    def open(self):
        if not self._is_open:
            self._on_header_release()

    def close(self):
        if self._is_open:
            self._on_header_release()


# Replace both the module global and the class attribute so every existing
# builder that references CollapsibleSection picks up the reliable version.
CollapsibleSection = HMGReliableSection
print("[HMG FIX v5] CollapsibleSection replaced with HMGReliableSection")


# ---------- 2. Strict header rebuild --------------------------------------
def _hmg_rebuild_header_strict(self, *_):
    """Remove every sibling of the tab panel, then install one header."""
    try:
        root = getattr(self, "main_root", None)
        tp = getattr(self, "tp", None)
        if root is None or tp is None:
            return
        removed = 0
        for child in list(root.children):
            if child is tp:
                continue
            try:
                root.remove_widget(child)
                removed += 1
            except Exception as e:
                print(f"[HMG HEADER] remove child: {e}")
        # In a vertical BoxLayout, the last added child sits at the top.
        root.add_widget(_hmg_build_header_v4(self))
        print(f"[HMG HEADER] strict rebuild — removed {removed}, added 1")
    except Exception as e:
        print(f"[HMG HEADER] strict rebuild: {e}")

HMGBillingApp._hmg_rebuild_header = _hmg_rebuild_header_strict


# ---------- 3. Drug list integrity ----------------------------------------
def _hmg_ensure_drug_list(self, *_):
    """Make sure every loaded drug is inside a scrollable, fully visible list."""
    try:
        drugs = getattr(self, "drugs", []) or []
        print(f"[HMG DRUGS] ensuring {len(drugs)} item(s) are displayed")

        dl = getattr(self, "drug_list", None)
        if dl is None:
            # The Manage Drugs tab hasn't been built yet; retry shortly.
            Clock.schedule_once(lambda dt: self._hmg_ensure_drug_list(), 1.0)
            return

        # Make sure the drug list itself scrolls.  If it is not already inside
        # a ScrollView, wrap it — this fixes the "only a few drugs visible" bug.
        parent = getattr(dl, "parent", None)
        already_scrollable = False
        p = parent
        depth = 0
        while p is not None and depth < 4:
            if p.__class__.__name__ == "ScrollView":
                already_scrollable = True
                break
            p = getattr(p, "parent", None)
            depth += 1

        if not already_scrollable and parent is not None:
            try:
                parent.remove_widget(dl)
            except Exception:
                pass
            sv = ScrollView(size_hint_y=None, height=dp(340), bar_width=dp(8))
            dl.size_hint_y = None
            dl.bind(minimum_height=dl.setter("height"))
            sv.add_widget(dl)
            try:
                parent.add_widget(sv)
            except Exception:
                pass

        # Force a refresh so every drug is rendered.
        try:
            self._refresh_drug_list()
        except Exception as e:
            print(f"[HMG DRUGS] refresh: {e}")

        # Log what was actually rendered.
        try:
            rendered = len(getattr(dl, "children", []))
            print(f"[HMG DRUGS] rows rendered: {rendered}")
        except Exception:
            pass
    except Exception as e:
        print(f"[HMG DRUGS] ensure: {e}")

HMGBillingApp._hmg_ensure_drug_list = _hmg_ensure_drug_list


