# ---------- 5. Guarantee EMR tab is added, with a real fallback -----------
def _hmg_emr_safe_builder(self, *a, **kw):
    self._hmg_ensure_runtime_defaults()

    # First try every existing EMR implementation.
    try:
        original = getattr(HMGBillingApp, "_hmg_original_emr_builder", None)
        if callable(original):
            try:
                original(self, *a, **kw)
                if any(getattr(t, "text", "") == "EMR"
                       for t in getattr(self.tp, "tab_list", [])):
                    print("[HMG EMR] built by original implementation")
                    return
            except Exception as e:
                print(f"[HMG EMR] original failed: {e}")
    except Exception as e:
        print(f"[HMG EMR] original wrapper: {e}")

    # Fallback: build a working EMR tab directly.
    theme = _m3_theme(self)
    tab = TabbedPanelItem(text="EMR")
    sv = ScrollView(bar_width=dp(4))
    root = BoxLayout(orientation="vertical", padding=dp(12),
                     spacing=dp(10), size_hint_y=None)
    root.bind(minimum_height=root.setter("height"))

    root.add_widget(Label(
        text="ELECTRONIC MEDICAL RECORD",
        font_size=22, bold=True, color=_m3("on_surface", theme),
        size_hint_y=None, height=dp(36), halign="left"))

    pt_card = BoxLayout(orientation="vertical", size_hint_y=None,
                        height=dp(80), padding=dp(10), spacing=dp(2))
    with pt_card.canvas.before:
        Color(*_m3("surface_container_low", theme))
        pc_bg = RoundedRectangle(pos=pt_card.pos, size=pt_card.size,
                                  radius=[dp(14)])
    pt_card.bind(pos=lambda w, *_: setattr(pc_bg, "pos", w.pos),
                 size=lambda w, *_: setattr(pc_bg, "size", w.size))
    try:
        pt_line = (f"{self.cp.get('name','')} ({self.cp.get('id','')})"
                   if getattr(self, "cp", None) else "No patient selected")
    except Exception:
        pt_line = "No patient selected"
    pt_card.add_widget(Label(text="PATIENT", font_size=14, bold=True,
                              color=_m3("on_surface_variant", theme),
                              size_hint_y=None, height=dp(22), halign="left"))
    pt_card.add_widget(Label(text=pt_line, font_size=16,
                              color=_m3("on_surface", theme),
                              size_hint_y=None, height=dp(30), halign="left"))
    root.add_widget(pt_card)

    def _go_emr(*_):
        # Delegate to the full EMR implementation when available.
        try:
            fn = globals().get("_HMG_ORIGINAL_EMR_BUILDER")
            if callable(fn):
                # Remove this fallback tab first.
                try:
                    self.tp.remove_widget(tab)
                except Exception:
                    pass
                fn(self)
                return
        except Exception as e:
            print(f"[HMG EMR] delegate: {e}")
        self._popup("EMR", "Full EMR is not available on this build.")

    root.add_widget(_hmg_primary_button(
        self, "OPEN FULL EMR", _go_emr, height=dp(60)))
    for label, target in (("Select Patient", None),
                          ("Registration", "Registration"),
                          ("Clinical AI", "Clinical AI"),
                          ("Laboratory", "Laboratory"),
                          ("Billing", "Billing")):
        if target is None:
            b = _hmg_nav_button(self, label, None, "patients")
            b.bind(on_press=lambda *_: self._sel_pt_popup())
        else:
            b = _hmg_nav_button(self, label, target, None)
        root.add_widget(b)

    sv.add_widget(root)
    tab.add_widget(sv)
    self.tp.add_widget(tab)
    print("[HMG EMR] fallback tab installed")

HMGBillingApp._emr = _hmg_emr_safe_builder


# ---------- 6. Post-login hook — rebuild header, sections, drug list ------
_HMG_PREV_LOGIN_V5 = getattr(HMGBillingApp, "_on_login_success", None)
if callable(_HMG_PREV_LOGIN_V5) and not getattr(_HMG_PREV_LOGIN_V5, "_hmg_v5", False):
    def _login_v5(self, user, *a, **kw):
        result = _HMG_PREV_LOGIN_V5(self, user, *a, **kw)

        def _after(_dt):
            try:
                self._hmg_ensure_runtime_defaults()
            except Exception as e:
                print(f"[HMG v5] defaults: {e}")
            try:
                self._hmg_rebuild_header()
            except Exception as e:
                print(f"[HMG v5] header: {e}")
            try:
                self._hmg_ensure_drug_list()
            except Exception as e:
                print(f"[HMG v5] drugs: {e}")
            try:
                tabs = [getattr(t, "text", "?")
                        for t in getattr(self.tp, "tab_list", [])]
                print(f"[HMG v5] tabs: {tabs}")
                print(f"[HMG v5] drugs in memory: "
                      f"{len(getattr(self, 'drugs', []) or [])}")
            except Exception:
                pass
        # Run twice — once after the fast-load batch settles and once more
        # in case a slow device is still building tabs.
        Clock.schedule_once(_after, 6.0)
        Clock.schedule_once(_after, 12.0)
        return result
    _login_v5._hmg_v5 = True
    HMGBillingApp._on_login_success = _login_v5


