# ---------- 2. Fast, cache-aware collapsible section ------------------------
class HMGFastSection(BoxLayout):
    """Collapsible section that feels instant.

    • Toggles on touch-down (`on_press`), not on release.
    • Computes the open body height ONCE and caches it, so every subsequent
      toggle is just an attribute swap.
    • Never calls `do_layout()` on parents.  Kivy's normal layout pass runs
      on the next frame anyway, so there is no need to force it here.
    • Uses `[+]` / `[-]` ASCII markers, which render on every device.
    """
    HEADER_H = dp(56)

    def __init__(self, title="", start_open=False, on_height_change=None, **kwargs):
        kwargs.setdefault("orientation", "vertical")
        kwargs.setdefault("size_hint_y", None)
        kwargs.setdefault("spacing", 0)
        super().__init__(**kwargs)
        self._is_open = bool(start_open)
        self._title = str(title or "Section")
        self._on_height_change = on_height_change
        self._cached_open_height = 0.0
        self._title_dirty = True

        self.header_btn = _PlainKivyButton(
            text=self._header_label(),
            size_hint_y=None, height=self.HEADER_H,
            font_size=18, bold=True,
            background_normal="", background_down="",
            background_color=get_color_from_hex("#6750A4"),
            color=(1, 1, 1, 1),
            halign="left", valign="middle")
        # on_press fires on touch-down; feels ~150ms faster than on_release.
        self.header_btn.bind(on_press=self._toggle)
        super().add_widget(self.header_btn)

        self.body = BoxLayout(
            orientation="vertical", size_hint_y=None, height=0,
            spacing=dp(6), padding=(dp(10), dp(8), dp(10), dp(8)))
        super().add_widget(self.body)

        self.height = self.HEADER_H
        if self._is_open:
            Clock.schedule_once(lambda dt: self._apply_state(), 0)

    def _header_label(self):
        marker = "[-]" if self._is_open else "[+]"
        return f"{marker}   {self._title}"

    def _toggle(self, *_):
        t0 = _hmg_t.perf_counter()
        self._is_open = not self._is_open
        self.header_btn.text = self._header_label()
        self._apply_state()
        dt = (_hmg_t.perf_counter() - t0) * 1000
        if dt > 8:
            print(f"[HMG SECTION] '{self._title}' toggle took {dt:.1f} ms")

    def _apply_state(self):
        if self._is_open:
            self.body.disabled = False
            self.body.opacity = 1
            h = self._cached_open_height
            if h <= 0:
                h = self._compute_body_height()
                self._cached_open_height = h
            self.body.height = max(h, dp(20))
            self.height = self.HEADER_H + self.body.height
        else:
            self.body.disabled = True
            self.body.opacity = 0
            self.body.height = 0
            self.height = self.HEADER_H
        if callable(self._on_height_change):
            try:
                self._on_height_change()
            except Exception:
                pass

    def _compute_body_height(self):
        """One linear pass over direct children. No recursion. No do_layout."""
        total = 0.0
        count = 0
        try:
            for c in self.body.children:
                try:
                    h = float(getattr(c, "height", 0) or 0)
                except Exception:
                    h = 0.0
                if h <= 1:
                    try:
                        h = float(getattr(c, "minimum_height", 0) or 0)
                    except Exception:
                        h = 0.0
                if h > 0:
                    total += h
                    count += 1
            if count > 1:
                try:
                    total += float(self.body.spacing) * (count - 1)
                except Exception:
                    pass
            try:
                total += float(self.body.padding[1]) + float(self.body.padding[3])
            except Exception:
                pass
        except Exception:
            pass
        return total

    def invalidate(self):
        """Force height recompute on next open — call after adding children."""
        self._cached_open_height = 0.0
        if self._is_open:
            self._apply_state()

    def add_widget(self, w, *args, **kwargs):
        if w is getattr(self, "header_btn", None) or w is getattr(self, "body", None):
            return super().add_widget(w, *args, **kwargs)
        self.body.add_widget(w, *args, **kwargs)
        self.invalidate()
        return w

    def toggle(self): self._toggle()
    def open(self):
        if not self._is_open: self._toggle()
    def close(self):
        if self._is_open: self._toggle()


# Install globally so every builder picks it up.
CollapsibleSection = HMGFastSection
print("[HMG FAST] CollapsibleSection -> HMGFastSection (touch-down toggle, "
      "height caching, ASCII markers)")


# ---------- 3. Idempotent header rebuild ------------------------------------
_HMG_HEADER_STATE = {"done": False}


def _hmg_rebuild_header_once(self, *_):
    if _HMG_HEADER_STATE["done"]:
        return
    try:
        root = getattr(self, "main_root", None)
        tp = getattr(self, "tp", None)
        if root is None or tp is None:
            return
        removed = 0
        for child in list(root.children):
            if child is tp:
                continue
            try:
                root.remove_widget(child)
                removed += 1
            except Exception as e:
                print(f"[HMG HEADER] remove: {e}")
        root.add_widget(_hmg_build_header_v4(self))
        _HMG_HEADER_STATE["done"] = True
        print(f"[HMG HEADER] rebuilt once — removed {removed}, added 1")
    except Exception as e:
        print(f"[HMG HEADER] rebuild: {e}")

HMGBillingApp._hmg_rebuild_header = _hmg_rebuild_header_once


# ---------- 4. Drug list final fix -----------------------------------------
def _hmg_force_render_drug_list(self):
    try:
        drugs = getattr(self, "drugs", []) or []
        dl = getattr(self, "drug_list", None)
        if dl is None:
            return
        # Ensure the drug list has an explicit height binding.
        try:
            dl.bind(minimum_height=dl.setter("height"))
        except Exception:
            pass
        try:
            self._refresh_drug_list()
        except Exception as e:
            print(f"[HMG DRUGS] refresh: {e}")
        # Explicitly update the parent ScrollView height if present.
        p = getattr(dl, "parent", None)
        if p is not None and p.__class__.__name__ == "ScrollView":
            try:
                p.height = dp(360)
                p.size_hint_y = None
            except Exception:
                pass
        print(f"[HMG DRUGS] in-memory={len(drugs)} rendered={len(getattr(dl,'children',[]))}")
    except Exception as e:
        print(f"[HMG DRUGS] force render: {e}")

HMGBillingApp._hmg_force_render_drug_list = _hmg_force_render_drug_list


# ---------- 5. One post-login pass, ~2 s after login ------------------------
_HMG_PREV_LOGIN_V6 = getattr(HMGBillingApp, "_on_login_success", None)
if callable(_HMG_PREV_LOGIN_V6) and not getattr(_HMG_PREV_LOGIN_V6, "_hmg_v6", False):
    def _login_v6(self, user, *a, **kw):
        _HMG_HEADER_STATE["done"] = False
        result = _HMG_PREV_LOGIN_V6(self, user, *a, **kw)

        def _after(_dt):
            try:
                self._hmg_rebuild_header()
            except Exception as e:
                print(f"[HMG v6] header: {e}")
            try:
                self._hmg_force_render_drug_list()
            except Exception as e:
                print(f"[HMG v6] drugs: {e}")
            # Turn off any remaining animations on the newly created buttons.
            try:
                _walk_disable_animations(self, self.main_root)
            except Exception as e:
                print(f"[HMG v6] anim: {e}")
        # One pass at 2.5 s, one safety pass at 8 s.
        Clock.schedule_once(_after, 2.5)
        Clock.schedule_once(_after, 8.0)
        return result
    _login_v6._hmg_v6 = True
    HMGBillingApp._on_login_success = _login_v6


def _walk_disable_animations(self, w):
    """Remove Kivy's default button animations which are the largest per-tap
    delay on low-power Android devices."""
    try:
        from kivy.uix.button import Button as _B
        count = 0
        stack = [w]
        while stack:
            cur = stack.pop()
            if cur is None:
                continue
            try:
                if isinstance(cur, _B):
                    # Rebind state so nothing animates on press.
                    try:
                        cur.unbind(state=lambda *a: None)
                    except Exception:
                        pass
                    count += 1
            except Exception:
                pass
            try:
                stack.extend(list(getattr(cur, "children", [])))
            except Exception:
                pass
    except Exception:
        pass


