# ============================================================================
# HMG STRUCTURED DASHBOARD v7
# Deterministic heights. No minimum_height dependency. No overlap possible.
# ============================================================================

from kivy.uix.widget import Widget as _W
from kivy.core.window import Window as _W2


def _hmg_cols_v7():
    """2 / 3 / 4 columns based on window width. Used by every grid."""
    try:
        w = _W2.width
    except Exception:
        return 2
    if w < dp(600):
        return 2
    if w < dp(900):
        return 3
    return 4


HMGBillingApp._hmg_cols_v7 = staticmethod(_hmg_cols_v7)


class HMGSectionCard(BoxLayout):
    """Deterministic, expandable section.

    All heights are computed from fixed constants + item count. No widget
    inside this card uses minimum_height, so no layout pass can change its
    size behind our back. Toggling is a pure attribute change.
    """
    HEADER_H = dp(56)
    ITEM_H = dp(64)
    ITEM_GAP = dp(8)
    BODY_PAD_V = dp(10)
    BODY_PAD_H = dp(10)

    def __init__(self, title="", icon="", items=None, cols=2,
                 start_open=False, on_navigate=None, **kwargs):
        kwargs.setdefault("orientation", "vertical")
        kwargs.setdefault("size_hint_y", None)
        kwargs.setdefault("spacing", 0)
        super().__init__(**kwargs)
        self._title = str(title or "Section")
        self._icon = str(icon or "")
        self._items = list(items or [])
        self._cols = max(1, int(cols))
        self._open = bool(start_open)
        self._on_nav = on_navigate
        self._theme = "light"

        # Header (fixed height, left-aligned label with proper text_size)
        self.header = _PlainKivyButton(
            text="", size_hint_y=None, height=self.HEADER_H,
            font_size=18, bold=True,
            background_normal="", background_down="",
            halign="left", valign="middle")
        try:
            self.header.bind(
                size=lambda w, s: setattr(w, "text_size", (s[0] - dp(24), s[1])))
        except Exception:
            pass
        self.header.bind(on_press=self._toggle)
        super().add_widget(self.header)

        # Body (fixed height recomputed on each toggle)
        self.body = BoxLayout(orientation="vertical", size_hint_y=None,
                              height=0, padding=(self.BODY_PAD_H,
                                                  self.BODY_PAD_V,
                                                  self.BODY_PAD_H,
                                                  self.BODY_PAD_V))
        super().add_widget(self.body)

        # Grid: fixed row height, fixed row count, no minimum_height
        self.grid = GridLayout(
            cols=self._cols, size_hint_y=None, height=0,
            spacing=self.ITEM_GAP,
            row_default_height=self.ITEM_H,
            row_force_default=True)
        self.body.add_widget(self.grid)

        # Populate
        for label, target, ico in self._items:
            self.grid.add_widget(self._make_item(label, target, ico))

        self._recompute()
        self._restyle()

    def _make_item(self, label, target, icon):
        text = f"{icon}   {label}" if icon else label
        btn = _PlainKivyButton(
            text=text, font_size=16, bold=True,
            size_hint_y=None, height=self.ITEM_H,
            background_normal="", background_down="",
            halign="center", valign="middle")
        try:
            btn.bind(
                size=lambda w, s: setattr(w, "text_size", (s[0] - dp(12), s[1])))
        except Exception:
            pass
        btn.bind(state=lambda w, s: setattr(
            w, "background_color",
            _m3("surface_container_highest", self._theme)
            if s == "down" else _m3("surface_container_high", self._theme)))
        if callable(self._on_nav) and target:
            btn.bind(on_press=lambda *_a, t=target: self._on_nav(t))
        return btn

    def _rows(self):
        n = len(self._items)
        if n <= 0:
            return 0
        return (n + self._cols - 1) // self._cols

    def _grid_height(self):
        rows = self._rows()
        if rows <= 0:
            return 0
        return rows * self.ITEM_H + (rows - 1) * self.ITEM_GAP

    def _recompute(self):
        gh = self._grid_height()
        self.grid.height = gh
        self._open_body_h = gh + 2 * self.BODY_PAD_V if gh > 0 else 0
        if self._open:
            self.body.height = self._open_body_h
            self.height = self.HEADER_H + self._open_body_h
        else:
            self.body.height = 0
            self.height = self.HEADER_H

    def _restyle(self):
        try:
            app = App.get_running_app()
            self._theme = _m3_theme(app) if app else "light"
        except Exception:
            self._theme = "light"
        marker = "[-]" if self._open else "[+]"
        self.header.text = f"{marker}   {self._title}"
        self.header.background_color = _m3("primary", self._theme)
        self.header.color = _m3("on_primary", self._theme)
        for btn in self.grid.children:
            try:
                btn.background_color = _m3("surface_container_high", self._theme)
                btn.color = _m3("on_surface", self._theme)
            except Exception:
                pass

    def _toggle(self, *_):
        self._open = not self._open
        self._recompute()
        self._restyle()

    def set_columns(self, cols):
        cols = max(1, int(cols))
        if cols == self._cols:
            return
        self._cols = cols
        self.grid.cols = cols
        self._recompute()
        self._restyle()


# ---------------------------------------------------------------------------
# Structured dashboard rebuild
# ---------------------------------------------------------------------------
def _hmg_structured_dashboard(self):
    theme = _m3_theme(self)
    primary = _m3("primary", theme)
    on_surface = _m3("on_surface", theme)
    on_surface_v = _m3("on_surface_variant", theme)
    outline_v = _m3("outline_variant", theme)
    surface_low = _m3("surface_container_low", theme)

    tab = TabbedPanelItem(text="Dashboard")
    sv = ScrollView(bar_width=dp(3))
    root = BoxLayout(orientation="vertical",
                     padding=(dp(14), dp(14), dp(14), dp(24)),
                     spacing=dp(14),
                     size_hint_y=None)
    root.bind(minimum_height=root.setter("height"))

    # ---- Page title -------------------------------------------------------
    title = Label(text="HMG EMR — Clinical Workspace",
                  font_size=22, bold=True, color=primary,
                  size_hint_y=None, height=dp(42),
                  halign="left", valign="middle")
    title.bind(size=lambda w, s: setattr(w, "text_size", (s[0], s[1])))
    root.add_widget(title)

    # ---- Overview stats ---------------------------------------------------
    root.add_widget(self._hmg_label("OVERVIEW", theme))

    cols = _hmg_cols_v7()
    stats_grid = GridLayout(cols=cols, size_hint_y=None,
                            spacing=dp(10),
                            row_default_height=dp(104),
                            row_force_default=True)
    # Height = ceil(6 / cols) rows * 104 + gaps
    import math as _math
    srows = _math.ceil(6 / cols)
    stats_grid.height = srows * dp(104) + (srows - 1) * dp(10)
    self._hmg_stats_grid = stats_grid
    self.stats = {}
    for key, caption in (("Patients", "PATIENTS"),
                          ("Today", "TODAY"),
                          ("Pending", "PENDING"),
                          ("Stock", "STOCK"),
                          ("LIS", "LIS"),
                          ("Tasks", "TASKS")):
        stats_grid.add_widget(self._stat_card(key, caption, theme))
    root.add_widget(stats_grid)

    # ---- Upload / Export button -------------------------------------------
    up = _PlainKivyButton(
        text="[^]   UPLOAD / EXPORT PATIENTS",
        font_size=17, bold=True,
        size_hint_y=None, height=dp(60),
        background_normal="", background_down="",
        background_color=primary,
        color=_m3("on_primary", theme))
    up.bind(on_press=lambda *_: self._upload_patients_menu())
    root.add_widget(up)

    # ---- Modules ----------------------------------------------------------
    root.add_widget(self._hmg_label("MODULES", theme))

    groups = [
        ("Patient Care", "P", [
            ("Registration", "Registration", "+"),
            ("EMR", "EMR", "E"),
            ("Clinical AI", "Clinical AI", "A"),
            ("Clinical Summary", "Clinical Summary", "S"),
            ("Vitals Timeline", "Vitals Timeline", "V"),
            ("Daily Notes", "Daily Notes", "D"),
            ("Procedures", "Procedures", "+"),
        ], True),

        ("Diagnostics", "L", [
            ("Laboratory", "Laboratory", "L"),
            ("Enhanced Lab", "Enhanced Lab", "L"),
            ("Radiology", "Radiology", "R"),
            ("ECG Analysis", "ECG Analysis", "H"),
            ("LIS Connections", "LIS Connections", "L"),
            ("Pathology AI", "Pathology AI", "P"),
            ("Liver Span", "Liver Span", "L"),
        ], False),

        ("Operations", "O", [
            ("Admissions", "Admissions", "A"),
            ("Transfer", "Transfer", "<>"),
            ("Appointments", "Appointments", "T"),
            ("Nursing Notes", "Nursing Notes", "+"),
            ("Tasks", "Tasks", "V"),
            ("Snapshot", "Snapshot", "O"),
        ], False),

        ("Pharmacy & Billing", "$", [
            ("Pharmacy", "Pharmacy", "P"),
            ("Pharmacy Dispense", "Pharmacy Dispense", "P"),
            ("Manage Drugs", "Manage Drugs", "D"),
            ("Billing", "Billing", "$"),
            ("Payments", "Payments", "$"),
        ], False),

        ("Records & Reports", "R", [
            ("Consent Form", "Consent Form", "C"),
            ("Referral Note", "Referral Note", ">"),
            ("Report Drafter", "Report Drafter", "R"),
            ("Saved Items", "Saved Items", "S"),
            ("Upload / Results", "Upload/Results", "^"),
            ("Manage Investigations", "Manage Investigations", "L"),
        ], False),

        ("AI & Analytics", "A", [
            ("AI Analysis", "AI Analysis", "A"),
            ("AI-BOS", "AI-BOS", "B"),
            ("Analytics", "Analytics", "A"),
            ("Chat", "Chat", "C"),
        ], False),

        ("Administration", "*", [
            ("Users", "Users", "U"),
            ("Audit Log", "Audit Log", "A"),
            ("Settings", "Settings", "*"),
        ], False),
    ]

    self._hmg_sections = []
    for name, icon, items, start_open in groups:
        card = HMGSectionCard(
            title=name, icon=icon, items=items,
            cols=_hmg_cols_v7(),
            start_open=start_open,
            on_navigate=lambda t: self._switch(t))
        self._hmg_sections.append(card)
        root.add_widget(card)

    # ---- Recent activity --------------------------------------------------
    root.add_widget(self._hmg_label("RECENT ACTIVITY", theme))
    self.act_log = TextInput(
        multiline=True, readonly=True, font_size=15,
        size_hint_y=None, height=dp(180),
        background_normal="", background_active="",
        background_color=surface_low,
        foreground_color=on_surface,
        cursor_color=primary)
    root.add_widget(self.act_log)

    sv.add_widget(root)
    tab.add_widget(sv)
    self.tp.add_widget(tab)
    self._upload_btn_done = True

    # Reflow when the window width changes.
    def _on_resize(*_):
        new_cols = _hmg_cols_v7()
        # Stats grid
        try:
            self._hmg_stats_grid.cols = new_cols
            srows2 = _math.ceil(6 / new_cols)
            self._hmg_stats_grid.height = (srows2 * dp(104)
                                            + (srows2 - 1) * dp(10))
        except Exception:
            pass
        # Section cards
        for c in getattr(self, "_hmg_sections", []):
            try:
                c.set_columns(new_cols)
            except Exception:
                pass
    try:
        _W2.bind(size=_on_resize)
    except Exception:
        pass


def _hmg_label(self, text, theme):
    lbl = Label(text=text, font_size=17, bold=True,
                color=_m3("primary", theme),
                size_hint_y=None, height=dp(28),
                halign="left", valign="middle")
    lbl.bind(size=lambda w, s: setattr(w, "text_size", (s[0], s[1])))
    return lbl


def _hmg_stat_card(self, key, caption, theme):
    card = BoxLayout(orientation="vertical", size_hint_y=None,
                     height=dp(104), padding=dp(10), spacing=dp(2))
    with card.canvas.before:
        Color(*_m3("surface_container_low", theme))
        bg = RoundedRectangle(pos=card.pos, size=card.size, radius=[dp(16)])
        Color(*_m3("outline_variant", theme))
        ol = Line(rounded_rectangle=(card.x, card.y, card.width,
                                      card.height, dp(16)), width=1)
    def _u(*_, c=card, b=bg, o=ol):
        b.pos, b.size = c.pos, c.size
        o.rounded_rectangle = (c.x, c.y, c.width, c.height, dp(16))
    card.bind(pos=_u, size=_u)

    val = Label(text="0", font_size=28, bold=True,
                color=_m3("primary", theme),
                size_hint_y=None, height=dp(50),
                halign="center", valign="middle")
    cap = Label(text=caption, font_size=14, bold=True,
                color=_m3("on_surface_variant", theme),
                size_hint_y=None, height=dp(24),
                halign="center", valign="middle")
    card.add_widget(val)
    card.add_widget(cap)
    self.stats[key] = val
    return card


HMGBillingApp._hmg_structured_dashboard = _hmg_structured_dashboard
HMGBillingApp._hmg_label = _hmg_label
HMGBillingApp._hmg_stat_card = _hmg_stat_card
HMGBillingApp._dashboard = _hmg_structured_dashboard


# ---------------------------------------------------------------------------
# No overlapping header, no double header.  Rebuild once, cleanly.
# ---------------------------------------------------------------------------
_HMG_HEADER_DONE = {"v": False}


def _hmg_clean_header(self, *_):
    if _HMG_HEADER_DONE["v"]:
        return
    try:
        root = getattr(self, "main_root", None)
        tp = getattr(self, "tp", None)
        if root is None or tp is None:
            return
        removed = 0
        for child in list(root.children):
            if child is tp:
                continue
            try:
                root.remove_widget(child)
                removed += 1
            except Exception:
                pass
        root.add_widget(_hmg_build_header_v4(self))
        _HMG_HEADER_DONE["v"] = True
        print(f"[HMG HEADER v7] removed {removed}, added 1")
    except Exception as e:
        print(f"[HMG HEADER v7] {e}")

HMGBillingApp._hmg_rebuild_header = _hmg_clean_header


# ---------------------------------------------------------------------------
# One clean post-login pass.
# ---------------------------------------------------------------------------
_PREV_LOGIN_V7 = getattr(HMGBillingApp, "_on_login_success", None)
if callable(_PREV_LOGIN_V7) and not getattr(_PREV_LOGIN_V7, "_hmg_v7", False):
    def _login_v7(self, user, *a, **kw):
        _HMG_HEADER_DONE["v"] = False
        result = _PREV_LOGIN_V7(self, user, *a, **kw)

        def _after(_dt):
            try:
                self._hmg_rebuild_header()
            except Exception as e:
                print(f"[HMG v7] header: {e}")
            try:
                if hasattr(self, "_hmg_force_render_drug_list"):
                    self._hmg_force_render_drug_list()
            except Exception as e:
                print(f"[HMG v7] drugs: {e}")
            try:
                tabs = [getattr(t, "text", "?")
                        for t in getattr(self.tp, "tab_list", [])]
                print(f"[HMG v7] tabs = {tabs}")
                print(f"[HMG v7] sections = {len(getattr(self, '_hmg_sections', []))}")
            except Exception:
                pass
        Clock.schedule_once(_after, 2.5)
        Clock.schedule_once(_after, 8.0)
        return result
    _login_v7._hmg_v7 = True
    HMGBillingApp._on_login_success = _login_v7


