# ============================================================================
# HMG v8.1 DASHBOARD BUILDER FIX
# ----------------------------------------------------------------------------
# 1. Bind every module helper under the name the dashboard actually calls.
# 2. Rebuild the Dashboard tab cleanly so a half-failed build cannot remain.
# ============================================================================

# ---- 1. Bind every alias the v7 dashboard references ----------------------
for _alias, _impl in (
    ("_stat_card",  _hmg_stat_card),
    ("_hmg_stat",   _hmg_stat_card),
    ("_section_label", _hmg_label),
    ("_hmg_section_label", _hmg_label),
):
    try:
        setattr(HMGBillingApp, _alias, _impl)
    except Exception as _e:
        print(f"[HMG v8.1] bind {_alias}: {_e}")

# Bind them into globals too, in case a caller resolves by name.
globals()["_stat_card"] = _hmg_stat_card


# ---- 2. Rebuild the Dashboard tab cleanly ---------------------------------
def _hmg_rebuild_dashboard_tab(self, *_):
    """Remove a half-built Dashboard tab and rebuild it with the v7 builder.
    Safe to call repeatedly — does nothing when the dashboard is intact."""
    try:
        tp = getattr(self, "tp", None)
        if tp is None:
            return False

        # Detect whether the previous build completed. A healthy dashboard
        # always ends up with at least the 6 stat labels in self.stats.
        stats = getattr(self, "stats", None) or {}
        sections = getattr(self, "_hmg_sections", None) or []
        healthy = (len(stats) >= 6 and len(sections) >= 3)

        if healthy:
            print("[HMG v8.1] dashboard already healthy — no rebuild")
            return True

        # Remove any existing Dashboard tab so it cannot duplicate.
        for tab in list(getattr(tp, "tab_list", [])):
            if getattr(tab, "text", "") == "Dashboard":
                try:
                    tp.remove_widget(tab)
                except Exception as e:
                    print(f"[HMG v8.1] remove old dashboard: {e}")

        # Make sure any stale references are cleared before rebuild.
        try:
            self.stats = {}
            self._hmg_sections = []
            self._hmg_responsive_grids = []
        except Exception:
            pass

        # Rebuild using the v7 builder.
        _hmg_structured_dashboard(self)
        print(f"[HMG v8.1] dashboard rebuilt — stats="
              f"{len(getattr(self, 'stats', {}))} "
              f"sections={len(getattr(self, '_hmg_sections', []))}")
        return True
    except Exception as e:
        import traceback
        traceback.print_exc()
        print(f"[HMG v8.1] dashboard rebuild failed: {e}")
        return False


HMGBillingApp._hmg_rebuild_dashboard_tab = _hmg_rebuild_dashboard_tab


# ---- 3. Make sure the login handler triggers the rebuild ------------------
_HMG_PREV_LOGIN_V8 = getattr(HMGBillingApp, "_on_login_success", None)
if callable(_HMG_PREV_LOGIN_V8) and not getattr(_HMG_PREV_LOGIN_V8, "_hmg_v8_1", False):
    def _login_v8_1(self, user, *a, **kw):
        result = _HMG_PREV_LOGIN_V8(self, user, *a, **kw)

        def _after(_dt):
            try:
                self._hmg_rebuild_dashboard_tab()
            except Exception as e:
                print(f"[HMG v8.1] post-login dashboard: {e}")
        # Run twice: once as soon as the fast-load batch settles, once as a
        # safety net in case the first pass raced with tab construction.
        Clock.schedule_once(_after, 2.5)
        Clock.schedule_once(_after, 8.0)
        return result
    _login_v8_1._hmg_v8_1 = True
    HMGBillingApp._on_login_success = _login_v8_1


# ---- 4. If we are already logged in, rebuild now --------------------------
def _hmg_kick_dashboard_fix(_dt=0):
    try:
        app = App.get_running_app()
        if app is None:
            Clock.schedule_once(_hmg_kick_dashboard_fix, 0.5)
            return
        if not getattr(app, "main_root", None):
            Clock.schedule_once(_hmg_kick_dashboard_fix, 0.5)
            return
        if not getattr(app, "current_user", None):
            return  # Will rebuild on next login.
        app._hmg_rebuild_dashboard_tab()
    except Exception as e:
        print(f"[HMG v8.1] kick: {e}")

try:
    Clock.schedule_once(_hmg_kick_dashboard_fix, 0.3)
except Exception:
    pass


print("[HMG] v8.1 dashboard builder fix installed — _stat_card alias bound, "
      "dashboard rebuild triggered")
      
