# ---- 1. Fix: collapsed sections must hide body (height + opacity + disabled)
def _hmg_fix_closed_section(section):
    try:
        if not hasattr(section, "body") or not hasattr(section, "_is_open"):
            return
        if section._is_open:
            section.body.opacity = 1
            section.body.disabled = False
        else:
            section.body.height = 0
            section.body.opacity = 0
            section.body.disabled = True
    except Exception:
        pass


def _hmg_install_closed_fix(cls):
    if cls is None or getattr(cls, "_hmg_closed_fixed", False):
        return
    orig_init = cls.__init__
    def _patched_init(self, *a, **kw):
        orig_init(self, *a, **kw)
        _hmg_fix_closed_section(self)
    try:
        cls.__init__ = _patched_init
        cls._hmg_closed_fixed = True
        print(f"[HMG v10] closed-state fix installed on {cls.__name__}")
    except Exception as e:
        print(f"[HMG v10] closed fix {getattr(cls,'__name__',cls)}: {e}")

for _cname in ("HMGFastSection", "HMGReliableSection", "CollapsibleSection"):
    _hmg_install_closed_fix(globals().get(_cname))


