def _v12_theme():
    try:
        return "dark" if str(
            _v12_App.get_running_app().facility.get("theme", "light")
        ).lower() == "dark" else "light"
    except Exception:
        return "light"


def _v12_c(role, fallback="#6750A4"):
    try:
        return _m3(role, _v12_theme())
    except Exception:
        return get_color_from_hex(fallback)


