_WIDAL_SEROTYPES = [
    ("Salmonella typhi",     "S. typhi O",         "S. typhi H"),
    ("S. paratyphi A",       "S. paratyphi A O",   "S. paratyphi A H"),
    ("S. paratyphi B",       "S. paratyphi B O",   "S. paratyphi B H"),
    ("S. paratyphi C",       "S. paratyphi C O",   "S. paratyphi C H"),
]


def _v12_register_widal():
    try:
        if not isinstance(PANEL_DEFINITIONS, dict):
            print("[HMG v12] PANEL_DEFINITIONS missing")
            return
        rows = []
        for _label, o_name, h_name in _WIDAL_SEROTYPES:
            rows.append((o_name, "titre", ["titre"], "< 1:80"))
            rows.append((h_name, "titre", ["titre"], "< 1:80"))
        PANEL_DEFINITIONS["Widal Test"] = rows
        print(f"[HMG v12] Widal Test registered "
              f"({len(rows)} antigen rows)")
    except Exception as e:
        print(f"[HMG v12] Widal register: {e}")

_v12_register_widal()


def _v12_ensure_widal_investigation(self):
    """Make sure 'Widal Test' is in the investigation catalog and spinner."""
    try:
        invs = getattr(self, "investigations", None)
        if not isinstance(invs, list):
            invs = []
            self.investigations = invs
        names = {str(i.get("name", "")).strip().lower()
                 for i in invs if isinstance(i, dict)}
        if "widal test" not in names:
            invs.append({
                "name": "Widal Test", "price": 2500,
                "dept": "Laboratory", "cat": "Microbiology",
                "result_type": "panel",
                "allowed_units": ["titre"],
                "default_unit": "titre",
                "qualitative_options": [],
                "reference": "< 1:80",
            })
        spin = getattr(self, "elab_test", None)
        if spin is not None:
            spin.values = [str(i.get("name", "")) for i in invs
                           if isinstance(i, dict) and i.get("name")]
        return True
    except Exception as e:
        print(f"[HMG v12] Widal ensure: {e}")
        return False


