# ============================================================================
# 2. TOUCH-CONSUMING HEADER  — solves the ScrollView-touch-grab problem
# ============================================================================
class _V12Header(_v12_Bt):
    """A button whose on_touch_down is a METHOD override (returns True),
    so the enclosing ScrollView cannot steal the touch first."""

    def __init__(self, section, **kw):
        super().__init__(**kw)
        self._section = section
        self._started_here = False

    def on_touch_down(self, touch):
        # collide_point must use *this* widget, not the section
        if self.collide_point(*touch.pos):
            self._started_here = True
            # Toggle on touch-down for instant response
            try:
                self._section._do_toggle()
            except Exception as e:
                print(f"[HMG v12] header toggle: {e}")
            return True  # consume — ScrollView won't see this touch
        return super().on_touch_down(touch)

    def on_touch_move(self, touch):
        # We consumed the down; keep consuming while the finger stays on us.
        if self._started_here:
            return True
        return super().on_touch_move(touch)

    def on_touch_up(self, touch):
        self._started_here = False
        return super().on_touch_up(touch)


class V12Section(_v12_BL):
    """Section that toggles reliably and has pre-computed heights.

    Children passed in must have explicit size_hint_y=None and an explicit
    height; the section uses those heights to size its open body once.
    """

    HEADER_H = dp(58)
    PAD = dp(10)
    GAP = dp(8)

    def __init__(self, title, children, start_open=False, **kw):
        kw.setdefault("orientation", "vertical")
        kw.setdefault("size_hint_y", None)
        kw.setdefault("spacing", 0)
        super().__init__(**kw)

        self._title = str(title)
        self._open = bool(start_open)

        # Measure body height ONCE
        heights = []
        for w in children:
            try:
                w.size_hint_y = None
                h = float(getattr(w, "height", 0) or 0)
            except Exception:
                h = 0.0
            if h <= 1:
                try:
                    h = float(getattr(w, "minimum_height", 0) or 0)
                except Exception:
                    h = 0.0
            if h <= 1:
                h = dp(58)
            heights.append(h)
        body_h = sum(heights)
        if len(children) > 1:
            body_h += self.GAP * (len(children) - 1)
        body_h += 2 * self.PAD
        self._body_h = body_h

        # ---- Header ----
        self._header = _V12Header(
            self,
            text="",
            size_hint_y=None, height=self.HEADER_H,
            font_size=18, bold=True,
            background_normal="", background_down="",
            background_color=_v12_c("primary", "#6750A4"),
            color=_v12_c("on_primary", "#FFFFFF"),
            halign="left", valign="middle")
        try:
            self._header.bind(size=lambda w, s:
                              setattr(w, "text_size", (s[0] - dp(24), s[1])))
        except Exception:
            pass
        super().add_widget(self._header)

        # ---- Body ----
        self._body = _v12_BL(orientation="vertical", size_hint_y=None,
                              height=0, spacing=self.GAP,
                              padding=(self.PAD, self.PAD,
                                       self.PAD, self.PAD))
        for w in children:
            self._body.add_widget(w)
        super().add_widget(self._body)

        self._apply()

    def _do_toggle(self):
        self._open = not self._open
        print(f"[HMG SECTION v12] '{self._title}' -> "
              f"{'OPEN' if self._open else 'CLOSED'}")
        self._apply()

    def _apply(self):
        try:
            if self._open:
                self._header.text = f"[-]   {self._title}"
                self._body.height = self._body_h
                self._body.opacity = 1
                self._body.disabled = False
                self.height = self.HEADER_H + self._body_h
            else:
                self._header.text = f"[+]   {self._title}"
                self._body.height = 0
                self._body.opacity = 0
                self._body.disabled = True
                self.height = self.HEADER_H
        except Exception as e:
            print(f"[HMG v12] apply: {e}")


