# 4. Refresh Widal when Enhanced Lab opens
# ============================================================================
_v12_prev_switch = getattr(HMGBillingApp, "_switch", None)
if callable(_v12_prev_switch) and not getattr(_v12_prev_switch, "_v12_hook", False):
    def _v12_switch(self, tab_text, *a, **kw):
        result = _v12_prev_switch(self, tab_text, *a, **kw)
        if str(tab_text) in ("Enhanced Lab", "Laboratory"):
            Clock.schedule_once(
                lambda dt: _v12_ensure_widal_investigation(self), 0)
        return result
    _v12_switch._v12_hook = True
    HMGBillingApp._switch = _v12_switch


# ============================================================================
# 5. Post-login: rebuild Clinical AI, ensure Widal
# ============================================================================
_v12_prev_login = getattr(HMGBillingApp, "_on_login_success", None)
if callable(_v12_prev_login) and not getattr(_v12_prev_login, "_v12_hook", False):
    def _v12_login(self, user, *a, **kw):
        result = _v12_prev_login(self, user, *a, **kw)

        def _after(_dt):
            # Remove every duplicate Clinical AI tab first.
            try:
                tp = getattr(self, "tp", None)
                if tp is not None:
                    for tab in list(getattr(tp, "tab_list", [])):
                        if getattr(tab, "text", "") == "Clinical AI":
                            try:
                                tp.remove_widget(tab)
                            except Exception:
                                pass
                self._clinical_ai_tab()
            except Exception as e:
                print(f"[HMG v12] rebuild Clinical AI: {e}")
            try:
                _v12_ensure_widal_investigation(self)
            except Exception as e:
                print(f"[HMG v12] ensure Widal: {e}")

        Clock.schedule_once(_after, 2.0)
        Clock.schedule_once(_after, 7.0)
        return result
    _v12_login._v12_hook = True
    HMGBillingApp._on_login_success = _v12_login


# ============================================================================
# 6. If already logged in, apply right now
# ============================================================================
def _v12_kick(_dt=0):
    try:
        app = _v12_App.get_running_app()
        if app is None or not getattr(app, "main_root", None):
            Clock.schedule_once(_v12_kick, 0.5)
            return
        if not getattr(app, "current_user", None):
            return
        try:
            tp = getattr(app, "tp", None)
            if tp is not None:
                for tab in list(getattr(tp, "tab_list", [])):
                    if getattr(tab, "text", "") == "Clinical AI":
                        try:
                            tp.remove_widget(tab)
                        except Exception:
                            pass
            app._clinical_ai_tab()
        except Exception as e:
            print(f"[HMG v12] kick Clinical AI: {e}")
        try:
            _v12_ensure_widal_investigation(app)
        except Exception as e:
            print(f"[HMG v12] kick Widal: {e}")
    except Exception as e:
        print(f"[HMG v12] kick outer: {e}")

try:
    Clock.schedule_once(_v12_kick, 0.4)
except Exception:
    pass


print("[HMG] v12 installed — touch-consuming sections, Widal test guaranteed")

