# HMG v13 — modal-popup pattern. Fast, reliable, no layout math.
# ============================================================================
from kivy.core.window import Window as _v13_win
from kivy.uix.boxlayout import BoxLayout as _v13_BL
from kivy.uix.scrollview import ScrollView as _v13_SV
from kivy.uix.label import Label as _v13_Lb
from kivy.uix.button import Button as _v13_Bt
from kivy.uix.textinput import TextInput as _v13_TI
