from kivy.uix.tabbedpanel import TabbedPanelItem as _v13_Tab
from kivy.clock import Clock as _v13_Clock
from kivy.app import App as _v13_App


def _v13_theme():
    try:
        return "dark" if str(
            _v13_App.get_running_app().facility.get("theme", "light")
        ).lower() == "dark" else "light"
    except Exception:
        return "light"


def _v13_c(role, fallback="#6750A4"):
    try:
        return _m3(role, _v13_theme())
    except Exception:
        return get_color_from_hex(fallback)


# ---------------------------------------------------------------------------
# 1. Modal popup helper — this is the whole trick
# ---------------------------------------------------------------------------
def _v13_modal(self, title, content_widget, height_hint=0.75):
    """Show a modal popup. Guaranteed instant; no ScrollView in the way."""
    theme = _v13_theme()
    wrap = _v13_BL(orientation="vertical", spacing=dp(10), padding=dp(12))
    wrap.add_widget(content_widget)

    close = _v13_Bt(text="CLOSE", font_size=16, bold=True,
                    size_hint_y=None, height=dp(52),
                    background_normal="", background_down="",
                    background_color=_v13_c("primary", "#6750A4"),
                    color=_v13_c("on_primary", "#FFFFFF"))
    wrap.add_widget(close)

    pop = _v13_Pop(title=title, content=wrap,
                   size_hint=(0.94, height_hint),
                   auto_dismiss=True,
                   title_color=_v13_c("on_surface", "#1D1B20"),
                   separator_color=_v13_c("primary", "#6750A4"))
    close.bind(on_press=lambda *_: pop.dismiss())
    pop.open()
    return pop


def _v13_action_button(self, label, cb):
    b = _v13_Bt(text=label, font_size=16, bold=True,
                size_hint_y=None, height=dp(60),
                background_normal="", background_down="",
                background_color=_v13_c("primary_container", "#EADDFF"),
                color=_v13_c("on_primary_container", "#21005D"))
    if callable(cb):
        b.bind(on_press=cb)
    return b


def _v13_header_button(self, label):
    """A big header that opens a modal when tapped."""
    b = _v13_Bt(text=label, font_size=18, bold=True,
                size_hint_y=None, height=dp(58),
                background_normal="", background_down="",
                background_color=_v13_c("primary", "#6750A4"),
                color=_v13_c("on_primary", "#FFFFFF"),
                halign="left", valign="middle",
                padding=(dp(16), 0, dp(16), 0))
    try:
        b.bind(size=lambda w, s: setattr(w, "text_size", (s[0] - dp(24), s[1])))
    except Exception:
        pass
    return b


