# ---------------------------------------------------------------------------
# 3. Widal — dedicated button on the Enhanced Lab tab, opens a modal
# ---------------------------------------------------------------------------
_WIDAL_ROWS = [
    ("Salmonella typhi",   "S. typhi O",       "S. typhi H"),
    ("S. paratyphi A",     "S. paratyphi A O", "S. paratyphi A H"),
    ("S. paratyphi B",     "S. paratyphi B O", "S. paratyphi B H"),
    ("S. paratyphi C",     "S. paratyphi C O", "S. paratyphi C H"),
]


def _v13_open_widal(self, *_a, **_k):
    """Modal Widal table. Serotype | O titre | H titre."""
    theme = _v13_theme()

    outer = _v13_BL(orientation="vertical", spacing=dp(8), padding=dp(6))
    outer.add_widget(_v13_Lb(
        text="Enter the titre for each antigen (e.g. 1:80).",
        font_size=14,
        color=_v13_c("on_surface_variant", "#49454F"),
        size_hint_y=None, height=dp(28),
        halign="left", valign="middle"))

    # Column header
    hdr = _v13_BL(size_hint_y=None, height=dp(34), spacing=dp(6))
    for txt, sx in (("Serotype", 0.40),
                    ("O antigen", 0.30),
                    ("H antigen", 0.30)):
        hdr.add_widget(_v13_Lb(
            text=txt, size_hint_x=sx, font_size=13, bold=True,
            color=_v13_c("on_surface_variant", "#49454F"),
            halign="center", valign="middle"))
    outer.add_widget(hdr)

    # Rows
    fields = []
    for label, o_name, h_name in _WIDAL_ROWS:
        row = _v13_BL(size_hint_y=None, height=dp(56), spacing=dp(6))
        lbl = _v13_Lb(text=label, size_hint_x=0.40, font_size=14, bold=True,
                      color=_v13_c("on_surface", "#1D1B20"),
                      halign="left", valign="middle")
        lbl.bind(size=lambda w, s: setattr(w, "text_size", (s[0] - dp(8), s[1])))
        row.add_widget(lbl)
        o_in = _v13_TI(multiline=False, font_size=14,
                       size_hint_x=0.30, size_hint_y=None, height=dp(48),
                       hint_text="1:80",
                       background_color=_v13_c("surface_container_lowest", "#FFFFFF"),
                       foreground_color=_v13_c("on_surface", "#1D1B20"))
        row.add_widget(o_in)
        h_in = _v13_TI(multiline=False, font_size=14,
                       size_hint_x=0.30, size_hint_y=None, height=dp(48),
                       hint_text="1:80",
                       background_color=_v13_c("surface_container_lowest", "#FFFFFF"),
                       foreground_color=_v13_c("on_surface", "#1D1B20"))
        row.add_widget(h_in)
        outer.add_widget(row)
        fields.append((o_name, o_in, h_name, h_in))

    # Save button
    def save_all(*_a, **_k):
        try:
            pid = ""
            try:
                pid = (getattr(self, "cp", None) or {}).get("id", "")
            except Exception:
                pid = ""
            if not pid:
                pid = (getattr(self, "elab_pid", None) and self.elab_pid.text) or ""
            pname = (getattr(self, "elab_name", None) and self.elab_name.text) or ""

            saved = []
            for o_name, o_in, h_name, h_in in fields:
                for name, wid in ((o_name, o_in), (h_name, h_in)):
                    val = str(wid.text or "").strip()
                    if not val:
                        continue
                    entry = {
                        "id": f"WIDAL{datetime.now().strftime('%Y%m%d%H%M%S%f')}",
                        "patient_id": pid,
                        "patient_name": pname,
                        "test_name": name,
                        "result": val,
                        "unit": "titre",
                        "reference": "< 1:80",
                        "date": datetime.now().strftime("%Y-%m-%d %H:%M:%S"),
                        "status": "Completed",
                        "panel": "Widal Test",
                        "component": name,
                    }
                    self.lab_results.append(entry)
                    saved.append(f"{name}: {val}")
            if not saved:
                self._popup("Widal Test", "Enter at least one titre.")
                return
            self.save_all()
            try:
                self._refresh_elab()
            except Exception:
                pass
            _v13_dismiss_all()
            self._popup("Widal Test Saved", "\n".join(saved))
        except Exception as e:
            print(f"[HMG v13] Widal save: {e}")
            self._popup("Widal Test", f"Save failed: {e}")

    outer.add_widget(_v13_Bt(
        text="SAVE WIDAL RESULT", font_size=16, bold=True,
        size_hint_y=None, height=dp(54),
        background_normal="", background_down="",
        background_color=_v13_c("primary", "#6750A4"),
        color=_v13_c("on_primary", "#FFFFFF"),
        on_press=save_all))

    _v13_modal(self, "Widal Test", outer, height_hint=0.85)


def _v13_add_widal_button_to_enhanced_lab(self):
    """Insert a WIDAL TEST button at the top of the Enhanced Lab tab."""
    try:
        tp = getattr(self, "tp", None)
        if tp is None:
            return
        for tab in getattr(tp, "tab_list", []):
            if getattr(tab, "text", "") != "Enhanced Lab":
                continue
            # Skip if already added.
            if getattr(tab, "_v13_widal_added", False):
                return
            tab._v13_widal_added = True

            # Find the outermost vertical BoxLayout inside the ScrollView.
            def find_scroll(w):
                from kivy.uix.scrollview import ScrollView as _S
                if isinstance(w, _S):
                    return w
                for c in getattr(w, "children", []):
                    r = find_scroll(c)
                    if r is not None:
                        return r
                return None

            sv = find_scroll(tab)
            if sv is None:
                print("[HMG v13] Widal button: no ScrollView found")
                return
            inner = next((c for c in sv.children
                          if isinstance(c, _v13_BL)), None)
            if inner is None:
                print("[HMG v13] Widal button: no inner BoxLayout")
                return

            btn = _v13_Bt(
                text="[+]   WIDAL TEST — enter O & H antigens",
                font_size=17, bold=True,
                size_hint_y=None, height=dp(60),
                background_normal="", background_down="",
                background_color=_v13_c("primary", "#6750A4"),
                color=_v13_c("on_primary", "#FFFFFF"))
            btn.bind(on_press=lambda *_a, **_k: _v13_open_widal(self))
            # Add at the top of the inner layout.
            inner.add_widget(btn, index=len(inner.children))
            print("[HMG v13] Widal button added to Enhanced Lab")
            return
    except Exception as e:
        print(f"[HMG v13] add Widal button: {e}")


# ---------------------------------------------------------------------------
# 4. Post-login: rebuild Clinical AI, add Widal button, tidy header
# ---------------------------------------------------------------------------
_v13_prev_login = getattr(HMGBillingApp, "_on_login_success", None)
if callable(_v13_prev_login) and not getattr(_v13_prev_login, "_v13_hook", False):
    def _v13_login(self, user, *a, **kw):
        result = _v13_prev_login(self, user, *a, **kw)

        def _after(_dt):
            # Rebuild Clinical AI with the popup pattern.
            try:
                tp = getattr(self, "tp", None)
                if tp is not None:
                    for tab in list(getattr(tp, "tab_list", [])):
                        if getattr(tab, "text", "") == "Clinical AI":
                            try:
                                tp.remove_widget(tab)
                            except Exception:
                                pass
                self._clinical_ai_tab()
            except Exception as e:
                print(f"[HMG v13] rebuild Clinical AI: {e}")
            # Add the Widal button.
            try:
                _v13_add_widal_button_to_enhanced_lab(self)
            except Exception as e:
                print(f"[HMG v13] add Widal: {e}")

        _v13_Clock.schedule_once(_after, 2.0)
        _v13_Clock.schedule_once(_after, 7.0)
        return result
    _v13_login._v13_hook = True
    HMGBillingApp._on_login_success = _v13_login


# ---------------------------------------------------------------------------
# 5. If already logged in, apply right now
# ---------------------------------------------------------------------------
def _v13_kick(_dt=0):
    try:
        app = _v13_App.get_running_app()
        if app is None or not getattr(app, "main_root", None):
            _v13_Clock.schedule_once(_v13_kick, 0.5)
            return
        if not getattr(app, "current_user", None):
            return
        try:
            tp = getattr(app, "tp", None)
            if tp is not None:
                for tab in list(getattr(tp, "tab_list", [])):
                    if getattr(tab, "text", "") == "Clinical AI":
                        try:
                            tp.remove_widget(tab)
                        except Exception:
                            pass
            app._clinical_ai_tab()
        except Exception as e:
            print(f"[HMG v13] kick Clinical AI: {e}")
        try:
            _v13_add_widal_button_to_enhanced_lab(app)
        except Exception as e:
            print(f"[HMG v13] kick Widal: {e}")
    except Exception as e:
        print(f"[HMG v13] kick outer: {e}")

try:
    _v13_Clock.schedule_once(_v13_kick, 0.4)
except Exception:
    pass


print("[HMG] v13 installed — modal popup sections + Widal test button")

