# ---------------------------------------------------------------------------
# Font constants — every text element uses these or larger
# ---------------------------------------------------------------------------
_F_HEADER = 20
_F_TITLE  = 24
_F_SECT   = 19
_F_BTN    = 17
_F_LABEL  = 16
_F_SMALL  = 16


def _v14_theme():
    try:
        return "dark" if str(
            _v14_App.get_running_app().facility.get("theme", "light")
        ).lower() == "dark" else "light"
    except Exception:
        return "light"


def _v14_c(role, fallback="#6750A4"):
    try:
        return _m3(role, _v14_theme())
    except Exception:
        return get_color_from_hex(fallback)


# ---------------------------------------------------------------------------
# Reusable widgets
# ---------------------------------------------------------------------------
def _v14_section_button(self, label, on_press):
    """A big purple section header. Tap opens a modal."""
    b = _v14_Bt(
        text=label, font_size=_F_SECT, bold=True,
        size_hint_y=None, height=dp(66),
        background_normal="", background_down="",
        background_color=_v14_c("primary", "#6750A4"),
        color=_v14_c("on_primary", "#FFFFFF"),
        halign="left", valign="middle",
        padding=(dp(18), 0, dp(18), 0))
    try:
        b.bind(size=lambda w, s: setattr(w, "text_size",
                                          (s[0] - dp(28), s[1])))
    except Exception:
        pass
    b.bind(on_press=on_press)
    return b


def _v14_action_button(self, label, cb, primary=False):
    theme = _v14_theme()
    role_bg = "primary" if primary else "primary_container"
    role_fg = "on_primary" if primary else "on_primary_container"
    b = _v14_Bt(
        text=label, font_size=_F_BTN, bold=True,
        size_hint_y=None, height=dp(64),
        background_normal="", background_down="",
        background_color=_v14_c(role_bg, "#6750A4"),
        color=_v14_c(role_fg, "#FFFFFF"))
    if callable(cb):
        b.bind(on_press=cb)
    return b


def _v14_modal(self, title, content, height_hint=0.75):
    theme = _v14_theme()
    wrap = _v14_BL(orientation="vertical", spacing=dp(10), padding=dp(12))
    wrap.add_widget(content)

    close = _v14_Bt(text="CLOSE", font_size=_F_BTN, bold=True,
                    size_hint_y=None, height=dp(56),
                    background_normal="", background_down="",
                    background_color=_v14_c("primary", "#6750A4"),
                    color=_v14_c("on_primary", "#FFFFFF"))
    wrap.add_widget(close)

    pop = _v14_Pop(title=title, content=wrap,
                   size_hint=(0.94, height_hint),
                   title_color=_v14_c("on_surface", "#1D1B20"),
                   title_size=str(_F_HEADER) + "sp",
                   separator_color=_v14_c("primary", "#6750A4"))
    close.bind(on_press=lambda *_: pop.dismiss())
    pop.open()
    return pop


def _v14_close_all():
    try:
        for w in list(_v14_win.children):
            if isinstance(w, _v14_Pop):
                w.dismiss()
    except Exception:
        pass


# ---------------------------------------------------------------------------
# Camera — general purpose capture + gallery
# ---------------------------------------------------------------------------
def _v14_camera_dir(self):
    try:
        base = self._get_reports_dir()
    except Exception:
        base = os.path.join(os.path.expanduser("~"), "HMG_Reports")
    d = os.path.join(base, "Camera")
    try:
        os.makedirs(d, exist_ok=True)
    except Exception:
        pass
    return d


def _v14_camera_open(self, mode="photo"):
    """Open a camera popup. mode='photo' or 'doc' (both save to Camera/)."""
    try:
        from kivy.uix.camera import Camera as _Cam
    except Exception as e:
        self._popup("Camera", f"Camera module unavailable: {e}")
        return

    if not CameraHelper.available():
        self._popup("Camera", "No camera available on this device.")
        return

    try:
        cam = _Cam(play=True, resolution=(1280, 960))
    except Exception as e:
        self._popup("Camera", f"Could not start camera: {e}")
        return

    box = _v14_BL(orientation="vertical", spacing=dp(8), padding=dp(8))
    box.add_widget(cam)

    def capture(*_a, **_k):
        try:
            if not cam.texture:
                self._popup("Camera", "Camera not ready yet. Try again.")
                return
            target_dir = self._v14_camera_dir()
            name = f"HMG_{mode}_{datetime.now().strftime('%Y%m%d_%H%M%S')}.png"
            path = os.path.join(target_dir, name)
            cam.texture.save(path)
            try:
                cam.play = False
            except Exception:
                pass
            _v14_close_all()
            self._popup("Photo Saved",
                        f"Saved to:\n{path}")
            self._audit_log_safe("CAMERA_CAPTURE", path)
        except Exception as e:
            print(f"[HMG v14] camera capture: {e}")

    def cancel(*_a, **_k):
        try:
            cam.play = False
        except Exception:
            pass
        _v14_close_all()

    row = _v14_BL(size_hint_y=None, height=dp(60), spacing=dp(8))
    row.add_widget(_v14_Bt(
        text="CAPTURE", font_size=_F_BTN, bold=True,
        size_hint_x=0.6,
        background_normal="", background_down="",
        background_color=_v14_c("primary", "#6750A4"),
        color=_v14_c("on_primary", "#FFFFFF"),
        on_press=capture))
    row.add_widget(_v14_Bt(
        text="CANCEL", font_size=_F_BTN, bold=True,
        size_hint_x=0.4,
        background_normal="", background_down="",
        background_color=_v14_c("surface_container_high", "#ECE6F0"),
        color=_v14_c("on_surface", "#1D1B20"),
        on_press=cancel))
    box.add_widget(row)

    _v14_modal(self, "Camera — Capture Photo", box, height_hint=0.85)


def _v14_camera_gallery(self, *_a, **_k):
    """Show all photos captured through the camera."""
    d = self._v14_camera_dir()
    files = []
    try:
        for f in sorted(os.listdir(d), reverse=True):
            full = os.path.join(d, f)
            if os.path.isfile(full) and f.lower().endswith(
                    (".png", ".jpg", ".jpeg")):
                files.append(full)
    except Exception:
        pass

    box = _v14_BL(orientation="vertical", spacing=dp(8),
                  padding=dp(6), size_hint_y=None)
    box.bind(minimum_height=box.setter("height"))

    box.add_widget(_v14_Lb(
        text=f"Camera folder:\n{d}\n\n"
             f"{len(files)} photo(s)",
        font_size=_F_LABEL,
        color=_v14_c("on_surface_variant", "#49454F"),
        size_hint_y=None, height=dp(80),
        halign="left", valign="middle"))

    if not files:
        box.add_widget(_v14_Lb(
            text="No photos yet. Tap CAMERA to capture one.",
            font_size=_F_LABEL,
            color=_v14_c("on_surface_variant", "#49454F"),
            size_hint_y=None, height=dp(40),
            halign="center", valign="middle"))
    else:
        sv = _v14_SV(bar_width=dp(6))
        inner = _v14_BL(orientation="vertical", spacing=dp(6),
                        size_hint_y=None)
        inner.bind(minimum_height=inner.setter("height"))
        for path in files[:200]:
            row = _v14_BL(size_hint_y=None, height=dp(56), spacing=dp(6))
            row.add_widget(_v14_Lb(
                text=os.path.basename(path), font_size=_F_LABEL,
                size_hint_x=0.7,
                color=_v14_c("on_surface", "#1D1B20"),
                halign="left", valign="middle"))
            b_view = _v14_Bt(
                text="VIEW", font_size=_F_LABEL, bold=True,
                size_hint_x=0.15,
                background_normal="", background_down="",
                background_color=_v14_c("primary_container", "#EADDFF"),
                color=_v14_c("on_primary_container", "#21005D"))
            b_view.bind(on_press=lambda *_a, p=path:
                        self._open_file_with_fallback(p))
            row.add_widget(b_view)
            b_share = _v14_Bt(
                text="SHARE", font_size=_F_LABEL, bold=True,
                size_hint_x=0.15,
                background_normal="", background_down="",
                background_color=_v14_c("surface_container_high", "#ECE6F0"),
                color=_v14_c("on_surface", "#1D1B20"))
            b_share.bind(on_press=lambda *_a, p=path: self._share_file(p))
            row.add_widget(b_share)
            inner.add_widget(row)
        sv.add_widget(inner)
        box.add_widget(sv)

    _v14_modal(self, "Camera — Gallery", box, height_hint=0.85)


