def _v14_view_saved_bills(self, instance=None):
    try:
        pid = None
        try:
            if getattr(self, "cp", None):
                pid = self.cp.get("id")
        except Exception:
            pass
        if not pid and hasattr(self, "bill_pid"):
            pid = self.bill_pid.text.strip()
        if not pid:
            self._popup("Saved Bills", "Select a patient first.")
            return

        bills = [b for b in getattr(self, "bills", [])
                 if (b.get("patient") or {}).get("id") == pid]
        if not bills:
            self._popup("Saved Bills",
                        f"No bills for this patient yet.\n"
                        f"(Patient ID: {pid})")
            return

        theme = _v14_theme()
        sv = _v14_SV(bar_width=dp(6))
        inner = _v14_BL(orientation="vertical", spacing=dp(12),
                        padding=dp(6), size_hint_y=None)
        inner.bind(minimum_height=inner.setter("height"))

        for b in bills:
            bill_id = b.get("bill_id", "?")
            total = b.get("total", 0)
            status = b.get("status", "Pending")
            when = b.get("ts", "")

            header = _v14_BL(orientation="vertical",
                             size_hint_y=None, height=dp(88),
                             padding=dp(10), spacing=dp(2))
            with header.canvas.before:
                Color(*_v14_c("surface_container_low", "#F7F2FA"))
                hb = RoundedRectangle(pos=header.pos, size=header.size,
                                      radius=[dp(12)])
            def _hh(w, *_a, _hb=hb):
                _hb.pos = w.pos
                _hb.size = w.size
            header.bind(pos=_hh, size=_hh)
            header.add_widget(_v14_Lb(
                text=f"Bill {bill_id}   |   {status}",
                font_size=_F_LABEL, bold=True,
                color=_v14_c("on_surface", "#1D1B20"),
                size_hint_y=None, height=dp(26),
                halign="left", valign="middle"))
            header.add_widget(_v14_Lb(
                text=f"{when}",
                font_size=_F_LABEL,
                color=_v14_c("on_surface_variant", "#49454F"),
                size_hint_y=None, height=dp(24),
                halign="left", valign="middle"))
            header.add_widget(_v14_Lb(
                text=f"TOTAL: ₦{total:,.2f}",
                font_size=_F_LABEL, bold=True,
                color=_v14_c("primary", "#6750A4"),
                size_hint_y=None, height=dp(26),
                halign="left", valign="middle"))
            inner.add_widget(header)

            # Line items
            items = b.get("items", []) or []
            if items:
                for i, it in enumerate(items, 1):
                    row = _v14_BL(size_hint_y=None, height=dp(38),
                                  spacing=dp(4))
                    row.add_widget(_v14_Lb(
                        text=f"{i:>2}.  {str(it.get('name',''))[:34]}",
                        font_size=_F_LABEL,
                        color=_v14_c("on_surface", "#1D1B20"),
                        size_hint_x=0.5, halign="left", valign="middle"))
                    row.add_widget(_v14_Lb(
                        text=f"x{it.get('qty', 1)}",
                        font_size=_F_LABEL,
                        color=_v14_c("on_surface_variant", "#49454F"),
                        size_hint_x=0.12, halign="center",
                        valign="middle"))
                    row.add_widget(_v14_Lb(
                        text=f"₦{float(it.get('price',0)):,.0f}",
                        font_size=_F_LABEL,
                        color=_v14_c("on_surface_variant", "#49454F"),
                        size_hint_x=0.18, halign="right",
                        valign="middle"))
                    row.add_widget(_v14_Lb(
                        text=f"₦{float(it.get('total',0)):,.0f}",
                        font_size=_F_LABEL, bold=True,
                        color=_v14_c("on_surface", "#1D1B20"),
                        size_hint_x=0.20, halign="right",
                        valign="middle"))
                    inner.add_widget(row)
            else:
                inner.add_widget(_v14_Lb(
                    text="(no line items in this bill)",
                    font_size=_F_SMALL,
                    color=_v14_c("on_surface_variant", "#49454F"),
                    size_hint_y=None, height=dp(28),
                    halign="left", valign="middle"))

            inner.add_widget(_v14_Lb(
                text="─" * 40, font_size=_F_SMALL,
                color=_v14_c("outline_variant", "#CAC4D0"),
                size_hint_y=None, height=dp(20),
                halign="center", valign="middle"))

        sv.add_widget(inner)
        _v14_modal(self, f"Saved Bills — {len(bills)}", sv,
                   height_hint=0.85)
    except Exception as e:
        print(f"[HMG v14] view saved bills: {e}")
        self._popup("Saved Bills", f"Error: {e}")


