# ---------------------------------------------------------------------------
# New Dashboard
# ---------------------------------------------------------------------------
def _v14_dashboard(self):
    theme = _v14_theme()
    primary = _v14_c("primary", "#6750A4")
    on_surface = _v14_c("on_surface", "#1D1B20")
    on_surface_v = _v14_c("on_surface_variant", "#49454F")

    tab = _v14_Tab(text="Dashboard")
    sv = _v14_SV(bar_width=dp(4))
    root = _v14_BL(orientation="vertical",
                   padding=(dp(14), dp(14), dp(14), dp(24)),
                   spacing=dp(14), size_hint_y=None)
    root.bind(minimum_height=root.setter("height"))

    # Big page title
    title = _v14_Lb(
        text="HMG EMR — Clinical Workspace",
        font_size=_F_TITLE, bold=True,
        color=primary,
        size_hint_y=None, height=dp(44),
        halign="left", valign="middle")
    title.bind(size=lambda w, s: setattr(w, "text_size", (s[0], s[1])))
    root.add_widget(title)

    # -------- Overview stats --------
    root.add_widget(_v14_Lb(
        text="OVERVIEW", font_size=_F_SECT, bold=True, color=primary,
        size_hint_y=None, height=dp(32),
        halign="left", valign="middle"))

    try:
        cols = 2 if _v14_win.width < dp(600) else (
            3 if _v14_win.width < dp(900) else 4)
    except Exception:
        cols = 2

    stats_grid = _v14_GL(cols=cols, size_hint_y=None, spacing=dp(10),
                         row_default_height=dp(110),
                         row_force_default=True)
    import math as _v14_math
    srows = _v14_math.ceil(6 / cols)
    stats_grid.height = srows * dp(110) + (srows - 1) * dp(10)
    self._v14_stats_grid = stats_grid
    self.stats = {}

    for key, caption in (
            ("Patients", "PATIENTS"),
            ("Today", "TODAY"),
            ("Pending", "PENDING"),
            ("Stock", "STOCK"),
            ("LIS", "LIS"),
            ("Tasks", "TASKS")):
        card = _v14_BL(orientation="vertical", size_hint_y=None,
                       height=dp(110), padding=dp(10), spacing=dp(2))
        with card.canvas.before:
            Color(*_v14_c("surface_container_low", "#F7F2FA"))
            bg = RoundedRectangle(pos=card.pos, size=card.size,
                                  radius=[dp(16)])
            Color(*_v14_c("outline_variant", "#CAC4D0"))
            ol = Line(rounded_rectangle=(card.x, card.y, card.width,
                                          card.height, dp(16)),
                      width=1)
        def _u(*_, c=card, b=bg, o=ol):
            b.pos, b.size = c.pos, c.size
            o.rounded_rectangle = (c.x, c.y, c.width, c.height, dp(16))
        card.bind(pos=_u, size=_u)
        val = _v14_Lb(text="0", font_size=30, bold=True,
                      color=primary,
                      size_hint_y=None, height=dp(52),
                      halign="center", valign="middle")
        cap = _v14_Lb(text=caption, font_size=_F_LABEL, bold=True,
                      color=on_surface_v,
                      size_hint_y=None, height=dp(28),
                      halign="center", valign="middle")
        card.add_widget(val)
        card.add_widget(cap)
        self.stats[key] = val
        stats_grid.add_widget(card)
    root.add_widget(stats_grid)

    # -------- Upload / Export --------
    up = _v14_Bt(
        text="UPLOAD / EXPORT PATIENTS",
        font_size=_F_BTN, bold=True,
        size_hint_y=None, height=dp(66),
        background_normal="", background_down="",
        background_color=primary, color=_v14_c("on_primary", "#FFFFFF"))
    up.bind(on_press=lambda *_: self._upload_patients_menu())
    root.add_widget(up)

    # -------- Sections (each opens a modal) --------
    root.add_widget(_v14_Lb(
        text="CLINICAL MODULES", font_size=_F_SECT, bold=True,
        color=primary,
        size_hint_y=None, height=dp(32),
        halign="left", valign="middle"))

    sections = [
        ("[+]   Patient Care",           _v14_open_patient_care),
        ("[+]   Diagnostics",            _v14_open_diagnostics),
        ("[+]   Billing",                _v14_open_billing_section),
        ("[+]   Payments",               _v14_open_payments_section),
        ("[+]   Pharmacy & Inventory",   _v14_open_pharmacy),
        ("[+]   Records & Reports",      _v14_open_records),
        ("[+]   Operations",             _v14_open_operations),
        ("[+]   AI & Analytics",         _v14_open_ai),
        ("[+]   Camera",                 _v14_open_camera_section),
        ("[+]   Administration",         _v14_open_admin),
    ]

    for label, cb in sections:
        root.add_widget(_v14_section_button(
            self, label,
            lambda *_a, _cb=cb, **_k: _cb(self)))

    # -------- Recent activity --------
    root.add_widget(_v14_Lb(
        text="RECENT ACTIVITY", font_size=_F_SECT, bold=True,
        color=primary,
        size_hint_y=None, height=dp(32),
        halign="left", valign="middle"))
    self.act_log = _v14_TI(
        multiline=True, readonly=True, font_size=_F_LABEL,
        size_hint_y=None, height=dp(180),
        background_normal="", background_active="",
        background_color=_v14_c("surface_container_low", "#F7F2FA"),
        foreground_color=on_surface,
        cursor_color=primary)
    root.add_widget(self.act_log)

    sv.add_widget(root)
    tab.add_widget(sv)
    self.tp.add_widget(tab)
    self._upload_btn_done = True

    # Reflow on resize
    def _on_resize(*_a, **_k):
        try:
            nc = 2 if _v14_win.width < dp(600) else (
                3 if _v14_win.width < dp(900) else 4)
            self._v14_stats_grid.cols = nc
            r2 = _v14_math.ceil(6 / nc)
            self._v14_stats_grid.height = (r2 * dp(110)
                                            + (r2 - 1) * dp(10))
        except Exception:
            pass
    try:
        _v14_win.bind(size=_on_resize)
    except Exception:
        pass

    print("[HMG v14] dashboard rebuilt with Billing / Payments / Camera")


HMGBillingApp._dashboard = _v14_dashboard


# ---------------------------------------------------------------------------
# Post-login: rebuild dashboard once
# ---------------------------------------------------------------------------
_v14_prev_login = getattr(HMGBillingApp, "_on_login_success", None)
if callable(_v14_prev_login) and not getattr(_v14_prev_login, "_v14_hook", False):
    def _v14_login(self, user, *a, **kw):
        result = _v14_prev_login(self, user, *a, **kw)

        def _after(_dt):
            try:
                tp = getattr(self, "tp", None)
                if tp is not None:
                    for tab in list(getattr(tp, "tab_list", [])):
                        if getattr(tab, "text", "") == "Dashboard":
                            try:
                                tp.remove_widget(tab)
                            except Exception:
                                pass
                            break
                self._dashboard()
                print("[HMG v14] dashboard rebuilt after login")
            except Exception as e:
                print(f"[HMG v14] post-login dashboard: {e}")
        _v14_Clock.schedule_once(_after, 2.0)
        _v14_Clock.schedule_once(_after, 7.0)
        return result
    _v14_login._v14_hook = True
    HMGBillingApp._on_login_success = _v14_login


def _v14_kick(_dt=0):
    try:
        app = _v14_App.get_running_app()
        if app is None or not getattr(app, "main_root", None):
            _v14_Clock.schedule_once(_v14_kick, 0.5)
            return
        if not getattr(app, "current_user", None):
            return
        tp = getattr(app, "tp", None)
        if tp is not None:
            for tab in list(getattr(tp, "tab_list", [])):
                if getattr(tab, "text", "") == "Dashboard":
                    try:
                        tp.remove_widget(tab)
                    except Exception:
                        pass
                    break
        app._dashboard()
        print("[HMG v14] dashboard rebuilt immediately")
    except Exception as e:
        print(f"[HMG v14] kick: {e}")

try:
    _v14_Clock.schedule_once(_v14_kick, 0.4)
except Exception:
    pass


print("[HMG] v14 installed — Dashboard sections (Billing, Payments, Camera), "
      "enhanced bill viewer with line items, larger fonts")
      
# ============================================================================
# HMG v15 — force Dashboard to be the first tab, always.
# ============================================================================
from kivy.clock import Clock as _v15_Clock
from kivy.app import App as _v15_App


def _v15_put_dashboard_first(self, *_a, **_k):
    """Reorder the tab strip so Dashboard is first and is the current tab."""
    try:
        tp = getattr(self, "tp", None)
        if tp is None:
            return

        # Find the Dashboard tab and, if it exists, the currently selected tab.
        dash = None
        current = None
        try:
            current = tp.current_tab
        except Exception:
            pass

        for tab in list(getattr(tp, "tab_list", [])):
            if getattr(tab, "text", "") == "Dashboard":
                dash = tab
                break

        if dash is None:
            return

        # Kivy keeps `tab_list` in visual order.  The `content` area holds
        # the actual widgets. To reorder, we remove every tab and re-add
        # them with Dashboard first.
        tab_list = list(getattr(tp, "tab_list", []))
        if not tab_list or tab_list[0] is dash:
            # Already first — just make sure it's selected.
            if current is not dash:
                try:
                    tp.switch_to(dash)
                except Exception:
                    pass
            return

        # Detach every tab, then re-add with Dashboard at the front.
        ordered = [dash] + [t for t in tab_list if t is not dash]
        for t in ordered:
            try:
                tp.remove_widget(t)
            except Exception:
                pass
        for t in ordered:
            try:
                tp.add_widget(t)
            except Exception:
                pass

        # Select the Dashboard tab.
        try:
            tp.switch_to(dash)
        except Exception:
            pass

        print("[HMG v15] Dashboard forced to first tab position")
    except Exception as e:
        print(f"[HMG v15] reorder: {e}")


HMGBillingApp._v15_put_dashboard_first = _v15_put_dashboard_first


# ---------------------------------------------------------------------------
# Hook the dashboard builders so a rebuild is immediately followed by a
# reorder. Covers every earlier dashboard implementation, whichever one
# currently lives on the class.
# ---------------------------------------------------------------------------
_prev_dashboard_v15 = getattr(HMGBillingApp, "_dashboard", None)
if callable(_prev_dashboard_v15) and not getattr(
        _prev_dashboard_v15, "_v15_wrapped", False):
    def _v15_dashboard(self, *a, **kw):
        result = _prev_dashboard_v15(self, *a, **kw)
        # Reorder on the next frame so the newly added tab is in tab_list.
        _v15_Clock.schedule_once(
            lambda dt: self._v15_put_dashboard_first(), 0)
        return result
    _v15_dashboard._v15_wrapped = True
    HMGBillingApp._dashboard = _v15_dashboard


# ---------------------------------------------------------------------------
# Hook tab-switch so that even if the user lands on another tab from a
# dashboard button, the strip order remains unchanged.
# ---------------------------------------------------------------------------
_prev_switch_v15 = getattr(HMGBillingApp, "_switch", None)
if callable(_prev_switch_v15) and not getattr(_prev_switch_v15,
                                               "_v15_hook", False):
    def _v15_switch(self, tab_text, *a, **kw):
        result = _prev_switch_v15(self, tab_text, *a, **kw)
        # If we ever land on Dashboard through a button, keep it at index 0.
        if str(tab_text) == "Dashboard":
            _v15_Clock.schedule_once(
                lambda dt: self._v15_put_dashboard_first(), 0)
        return result
    _v15_switch._v15_hook = True
    HMGBillingApp._switch = _v15_switch


# ---------------------------------------------------------------------------
# Also enforce ordering after login (belt and braces).
# ---------------------------------------------------------------------------
_prev_login_v15 = getattr(HMGBillingApp, "_on_login_success", None)
if callable(_prev_login_v15) and not getattr(_prev_login_v15,
                                              "_v15_hook", False):
    def _v15_login(self, user, *a, **kw):
        result = _prev_login_v15(self, user, *a, **kw)

        def _reorder(_dt=0):
            try:
                self._v15_put_dashboard_first()
            except Exception as e:
                print(f"[HMG v15] post-login reorder: {e}")

        # Run several times because later hooks rebuild the dashboard.
        for delay in (0.5, 2.5, 4.0, 7.5, 10.0):
            _v15_Clock.schedule_once(_reorder, delay)
        return result
    _v15_login._v15_hook = True
    HMGBillingApp._on_login_success = _v15_login


# ---------------------------------------------------------------------------
# If we are already logged in, reorder right now.
# ---------------------------------------------------------------------------
def _v15_kick(_dt=0):
    try:
        app = _v15_App.get_running_app()
        if app is None or not getattr(app, "main_root", None):
            _v15_Clock.schedule_once(_v15_kick, 0.5)
            return
        if not getattr(app, "current_user", None):
            return
        app._v15_put_dashboard_first()
    except Exception as e:
        print(f"[HMG v15] kick: {e}")

try:
    for _delay in (0.4, 1.5, 4.0, 9.0):
        _v15_Clock.schedule_once(_v15_kick, _delay)
except Exception:
    pass


print("[HMG] v15 installed — Dashboard forced to first tab position")

# ============================================================================
# HMG v16 — fix _update_ca (missing ca_diag/ca_emr) and the Clear button.
# Self-contained; assumes the v13 Clinical AI tab + v14 dashboard are present.
# ============================================================================
from kivy.clock import Clock as _v16_Clock
from kivy.app import App as _v16_App
from kivy.uix.textinput import TextInput as _v16_TI


# ---------------------------------------------------------------------------
# 1. Eagerly create ca_diag and ca_emr so _update_ca always finds them.
#    They live off-screen; the modals in v13 create their own local copies
#    for on-screen display.
# ---------------------------------------------------------------------------
def _v16_ensure_ca_widgets(self):
    """Create self.ca_diag and self.ca_emr if they don't exist. These are
    backing stores that _update_ca writes to; the modals render them."""
    made = []
    for name, height in (("ca_diag", 400), ("ca_emr", 400)):
        cur = getattr(self, name, None)
        # A missing attribute is None; a no-op callable can leak in from
        # earlier __getattr__ patches.
        if cur is None or callable(cur):
            try:
                w = _v16_TI(
                    multiline=True, readonly=True, font_size=15,
                    size_hint=(None, None),
                    size=(dp(10), dp(10)),   # tiny, off-screen
                    opacity=0, disabled=True,
                    background_color=(0, 0, 0, 0),
                    foreground_color=(0, 0, 0, 0))
                setattr(self, name, w)
                made.append(name)
            except Exception as e:
                print(f"[HMG v16] create {name}: {e}")
    if made:
        print(f"[HMG v16] created backing widgets: {made}")


HMGBillingApp._v16_ensure_ca_widgets = _v16_ensure_ca_widgets


# ---------------------------------------------------------------------------
# 2. Wrap _update_ca so it never crashes on a missing widget.
# ---------------------------------------------------------------------------
_prev_update_ca_v16 = getattr(HMGBillingApp, "_update_ca", None)
if callable(_prev_update_ca_v16) and not getattr(_prev_update_ca_v16,
                                                  "_v16_wrapped", False):
    def _v16_update_ca(self, response, expected_pid=None):
        self._v16_ensure_ca_widgets()
        try:
            return _prev_update_ca_v16(self, response, expected_pid)
        except AttributeError as e:
            # Belt and braces: even with the backing widgets present, an
            # earlier patch may still try to touch a widget we don't have.
            print(f"[HMG v16] _update_ca recovered from AttributeError: {e}")
            # Fall back to just appending the response to the chat.
            try:
                cur = getattr(self, "ca_chat", None)
                if cur is not None and hasattr(cur, "text"):
                    cur.text = (cur.text or "") + \
                        f"\nAssistant: {response}\n"
            except Exception:
                pass
            return None
        except Exception as e:
            print(f"[HMG v16] _update_ca recovered: {e}")
            return None

    _v16_update_ca._v16_wrapped = True
    HMGBillingApp._update_ca = _v16_update_ca


# ---------------------------------------------------------------------------
# 3. Wrap _send_ca so that any missing ca_* widget is created before use.
# ---------------------------------------------------------------------------
_prev_send_ca_v16 = getattr(HMGBillingApp, "_send_ca", None)
if callable(_prev_send_ca_v16) and not getattr(_prev_send_ca_v16,
                                                "_v16_wrapped", False):
    def _v16_send_ca(self, instance=None, *a, **kw):
        self._v16_ensure_ca_widgets()
        try:
            return _prev_send_ca_v16(self, instance, *a, **kw)
        except Exception as e:
            print(f"[HMG v16] _send_ca recovered: {e}")
            return None

    _v16_send_ca._v16_wrapped = True
    HMGBillingApp._send_ca = _v16_send_ca


# ---------------------------------------------------------------------------
# 4. Guaranteed Clear handler — module-level function called by name.
#    The header button uses this via a direct reference, so it cannot be
#    affected by any wrapper that removed _hmg_do_clear_patient.
# ---------------------------------------------------------------------------
def _v16_clear_patient(app):
    """Clear the active patient. Never raises."""
    try:
        app.cp = None
        lbl = getattr(app, "pt_lbl", None)
        if lbl is not None and hasattr(lbl, "text"):
            try:
                lbl.text = "No Patient"
                lbl.color = get_color_from_hex("#7f8c8d")
            except Exception:
                pass

        # Blank every field that might reference the patient.
        for attr in (
                "emr_pid", "emr_name", "bill_pid", "bill_name",
                "pay_pid", "pay_name", "pharm_pid", "pharm_name",
                "lab_pid", "lab_name", "rad_pid", "rad_name",
                "up_pid", "up_name", "consent_pid", "consent_name",
                "referral_pid", "referral_name", "snapshot_pid",
                "snapshot_name", "elab_pid", "elab_name",
                "proc_pid", "proc_name_display",
                "dispense_pid", "dispense_name",
                "task_pid", "task_patient_name",
                "daily_pid", "daily_name", "adm_pid", "adm_name",
                "appt_pid", "appt_name", "nurse_pid", "nurse_name",
                "transfer_pid", "transfer_name"):
            w = getattr(app, attr, None)
            if w is not None and hasattr(w, "text"):
                try:
                    w.text = ""
                except Exception:
                    pass

        # Best-effort refresh of dependent panels. Never raises.
        for name in (
                "_refresh_timeline", "_refresh_uploaded_results",
                "_refresh_vitals_timeline", "_refresh_daily_notes",
                "_refresh_snapshots", "_refresh_saved_items",
                "_refresh_elab", "_refresh_tasks",
                "_refresh_pharmacy_dispense",
                "_refresh_admissions_list",
                "_refresh_saved_reports_list",
                "_refresh_appointments",
                "_refresh_nursing_notes",
                "_refresh_transfer_list"):
            fn = getattr(app, name, None)
            if callable(fn):
                try:
                    fn()
                except Exception:
                    pass
        print("[HMG v16] patient cleared")
    except Exception as e:
        print(f"[HMG v16] clear failed: {e}")


def _v16_logout(app):
    """Logout that never blocks on save/audit errors."""
    try:
        user = getattr(app, "current_user", None)
        if user:
            try:
                app.audit.log(username=user.get("username"),
                              action="LOGOUT")
            except Exception:
                pass
    except Exception:
        pass
    try:
        app.save_all(force=True)
    except Exception as e:
        print(f"[HMG v16 LOGOUT] save: {e}")
    try:
        rc = getattr(app, "root_container", None)
        if rc is not None:
            rc.clear_widgets()
    except Exception:
        pass
    try:
        app.cp = None
        app.bill_items = []
        app.emr_drug_list = []
    except Exception:
        pass
    try:
        app.clinical_ai = ModularAIClinicalAssistant(app.ai)
    except Exception:
        pass
    try:
        ls = LoginScreen(app.user_manager, on_login=app._on_login_success)
        rc = getattr(app, "root_container", None)
        if rc is not None:
            rc.add_widget(ls)
        app.login_screen = ls
    except Exception as e:
        print(f"[HMG v16 LOGOUT] login screen: {e}")
    try:
        app.current_user = None
    except Exception:
        pass
    print("[HMG v16 LOGOUT] complete")


def _v16_select(app):
    """Patient picker — reuses v8's if present, else a safe fallback."""
    fn = globals().get("_hmg_show_patient_picker")
    if callable(fn):
        try:
            return fn(app)
        except Exception as e:
            print(f"[HMG v16 SELECT] v8 picker: {e}")
    # Minimal fallback
    try:
        from kivy.uix.popup import Popup as _P
        from kivy.uix.boxlayout import BoxLayout as _B
        from kivy.uix.scrollview import ScrollView as _S
        from kivy.uix.button import Button as _Bt
        from kivy.uix.label import Label as _L
        from kivy.uix.tabbedpanel import TabbedPanelItem  # noqa: F401

        theme = "light"
        try:
            theme = "dark" if str(
                app.facility.get("theme", "light")).lower() == "dark" else "light"
        except Exception:
            pass

        patients = [p for p in (getattr(app, "patients", []) or [])
                    if isinstance(p, dict)]
        root = _B(orientation="vertical", spacing=dp(6), padding=dp(8))
        status = _L(text=f"{len(patients)} patient(s)",
                    font_size=16, bold=True,
                    color=_m3("on_surface_variant", theme),
                    size_hint_y=None, height=dp(24))
        root.add_widget(status)
        sv = _S()
        inner = _B(orientation="vertical", spacing=dp(4),
                    size_hint_y=None)
        inner.bind(minimum_height=inner.setter("height"))
        sv.add_widget(inner)
        root.add_widget(sv)
        close = _Bt(text="CLOSE", font_size=16, bold=True,
                     size_hint_y=None, height=dp(48),
                     background_normal="", background_down="",
                     background_color=_m3("surface_container_high", theme),
                     color=_m3("on_surface", theme))
        root.add_widget(close)
        pop = _P(title="Select Patient", content=root,
                 size_hint=(0.94, 0.85))
        close.bind(on_press=lambda *_: pop.dismiss())

        def select_one(p):
            app.cp = p
            lbl = getattr(app, "pt_lbl", None)
            if lbl is not None:
                try:
                    lbl.text = (f"{p.get('name','')} "
                                f"({p.get('id','')}) "
                                f"| {p.get('age','')}yr")
                except Exception:
                    pass
            # Try the app's loader first.
            fn2 = getattr(app, "_load_patient_data", None)
            if callable(fn2):
                try:
                    fn2()
                except Exception:
                    pass
            pop.dismiss()
            print(f"[HMG v16 SELECT] {p.get('name','')}")

        if not patients:
            inner.add_widget(_L(
                text="No patients registered yet.",
                font_size=16,
                color=_m3("on_surface_variant", theme),
                size_hint_y=None, height=dp(48),
                halign="center", valign="middle"))
        else:
            for p in patients:
                b = _Bt(
                    text=(f"{p.get('name','')}  |  {p.get('id','')}  |  "
                          f"{p.get('age','')}y  |  {p.get('gender','')}"),
                    font_size=16, bold=True,
                    size_hint_y=None, height=dp(58),
                    background_normal="", background_down="",
                    background_color=_m3("surface_container_high", theme),
                    color=_m3("on_surface", theme),
                    halign="left", valign="middle")
                b.bind(on_press=lambda *_a, _p=p: select_one(_p))
                inner.add_widget(b)
        pop.open()
    except Exception as e:
        print(f"[HMG v16 SELECT] {e}")


# ---------------------------------------------------------------------------
# 5. Rebuild the header with direct references to the v16 module functions.
# ---------------------------------------------------------------------------
def _v16_header(self):
    from kivy.uix.boxlayout import BoxLayout as _B
    from kivy.uix.label import Label as _L
    theme = "light"
    try:
        theme = "dark" if str(
            self.facility.get("theme", "light")).lower() == "dark" else "light"
    except Exception:
        pass

    primary = _m3("primary", theme)
    on_primary = _m3("on_primary", theme)
    surface_high = _m3("surface_container_high", theme)
    on_surface = _m3("on_surface", theme)
    on_surface_v = _m3("on_surface_variant", theme)
    error = _m3("error", theme)
    on_error = _m3("on_error", theme)

    outer = _B(orientation="vertical", size_hint_y=None,
               height=dp(100), padding=dp(4), spacing=dp(4))

    # Row 1
    row1 = _B(size_hint_y=None, height=dp(46), spacing=dp(4))
    row1.add_widget(_L(text="HMG EMR", font_size=17, bold=True,
                        color=primary, size_hint_x=0.28,
                        halign="left", valign="middle"))
    try:
        running = sum(1 for s in self.lis_manager.servers.values()
                      if s.get("running"))
    except Exception:
        running = 0
    self.lis_lbl = _L(text=f"LIS:{running}", font_size=14, bold=True,
                       color=on_surface_v, size_hint_x=0.13)
    row1.add_widget(self.lis_lbl)
    self.ai_lbl = _L(
        text=f"AI:{'ON' if getattr(self.ai, 'enabled', False) else 'OFF'}",
        font_size=14, bold=True, color=on_surface_v, size_hint_x=0.13)
    row1.add_widget(self.ai_lbl)

    try:
        uname = (self.current_user or {}).get("username", "")
    except Exception:
        uname = ""
    self.user_lbl = _L(text=f"@{uname}" if uname else "@ Guest",
                        font_size=14, bold=True, color=on_surface,
                        size_hint_x=0.21, shorten=True,
                        shorten_from="right")
    row1.add_widget(self.user_lbl)

    logout_btn = _PlainKivyButton(
        text="LOGOUT", font_size=15, bold=True,
        size_hint_x=0.25, size_hint_y=None, height=dp(46),
        background_normal="", background_down="",
        background_color=error, color=on_error)
    logout_btn.bind(on_press=lambda *_a, **_k: _v16_logout(self))
    row1.add_widget(logout_btn)
    outer.add_widget(row1)

    # Row 2
    row2 = _B(size_hint_y=None, height=dp(48), spacing=dp(4))
    try:
        pt_text = (f"{self.cp.get('name','')} ({self.cp.get('id','')})"
                   if getattr(self, "cp", None) else "No Patient")
    except Exception:
        pt_text = "No Patient"
    self.pt_lbl = _L(
        text=pt_text, font_size=16, bold=True,
        color=on_surface if getattr(self, "cp", None) else on_surface_v,
        size_hint_x=0.5, shorten=True, shorten_from="right",
        halign="left", valign="middle")
    row2.add_widget(self.pt_lbl)

    select_btn = _PlainKivyButton(
        text="SELECT PATIENT", font_size=15, bold=True,
        size_hint_x=0.28, size_hint_y=None, height=dp(46),
        background_normal="", background_down="",
        background_color=primary, color=on_primary)
    select_btn.bind(on_press=lambda *_a, **_k: _v16_select(self))
    row2.add_widget(select_btn)

    clear_btn = _PlainKivyButton(
        text="CLEAR", font_size=15, bold=True,
        size_hint_x=0.22, size_hint_y=None, height=dp(46),
        background_normal="", background_down="",
        background_color=surface_high, color=on_surface)
    clear_btn.bind(on_press=lambda *_a, **_k: _v16_clear_patient(self))
    row2.add_widget(clear_btn)
    outer.add_widget(row2)
    return outer


HMGBillingApp._v16_header = _v16_header


def _v16_rebuild_header(self, *_):
    try:
        root = getattr(self, "main_root", None)
        tp = getattr(self, "tp", None)
        if root is None or tp is None:
            return
        removed = 0
        for child in list(root.children):
            if child is tp:
                continue
            try:
                root.remove_widget(child)
                removed += 1
            except Exception:
                pass
        root.add_widget(self._v16_header())
        print(f"[HMG v16] header rebuilt — removed {removed}, added 1")
    except Exception as e:
        print(f"[HMG v16] header: {e}")


HMGBillingApp._v16_rebuild_header = _v16_rebuild_header


# ---------------------------------------------------------------------------
# 6. Post-login: create backing widgets, rebuild header.
# ---------------------------------------------------------------------------
_prev_login_v16 = getattr(HMGBillingApp, "_on_login_success", None)
if callable(_prev_login_v16) and not getattr(_prev_login_v16,
                                              "_v16_hook", False):
    def _v16_login(self, user, *a, **kw):
        result = _prev_login_v16(self, user, *a, **kw)

        def _after(_dt):
            try:
                self._v16_ensure_ca_widgets()
            except Exception as e:
                print(f"[HMG v16] ensure ca: {e}")
            try:
                self._v16_rebuild_header()
            except Exception as e:
                print(f"[HMG v16] post-login header: {e}")

        for delay in (0.8, 2.5, 6.0):
            _v16_Clock.schedule_once(_after, delay)
        return result
    _v16_login._v16_hook = True
    HMGBillingApp._on_login_success = _v16_login


# ---------------------------------------------------------------------------
# 7. If already logged in, apply now.
# ---------------------------------------------------------------------------
def _v16_kick(_dt=0):
    try:
        app = _v16_App.get_running_app()
        if app is None or not getattr(app, "main_root", None):
            _v16_Clock.schedule_once(_v16_kick, 0.5)
            return
        if not getattr(app, "current_user", None):
            return
        app._v16_ensure_ca_widgets()
        app._v16_rebuild_header()
    except Exception as e:
        print(f"[HMG v16] kick: {e}")

try:
    for _delay in (0.4, 1.5):
        _v16_Clock.schedule_once(_v16_kick, _delay)
except Exception:
    pass


print("[HMG] v16 installed — ca_diag/ca_emr backing widgets, "
      "guaranteed Clear/Logout/Select handlers, header rebuilt")
      
# ============================================================================
# HMG v16.1 — Kivy WeakMethod resolver fix
# Kivy stores the wrapper's internal __name__ and later does
# getattr(app, that_name). Alias every self-taking wrapper onto the class so
# the lookup always succeeds.
# ============================================================================
import inspect as _v161_insp

_aliased = []
for _name, _obj in list(globals().items()):
    if not callable(_obj):
        continue
    # Only touch our own wrappers.
    if not (_name.startswith("_v") or _name.startswith("_hmg_")):
        continue
    try:
        _params = list(_v161_insp.signature(_obj).parameters)
    except Exception:
        continue
    if not _params or _params[0] != "self":
        continue
    try:
        if not hasattr(HMGBillingApp, _name):
            setattr(HMGBillingApp, _name, _obj)
            _aliased.append(_name)
    except Exception:
        pass

print(f"[HMG v16.1] aliased {len(_aliased)} wrapper names on HMGBillingApp")
if _aliased:
    for _n in _aliased[:20]:
        print(f"[HMG v16.1]   + {_n}")


# Also fix the canonical __name__ on the main wrappers so any *new* bindings
# resolve to the class attribute they are assigned to, not to the wrapper
# name. This prevents the same class of bug in future rebuilds.
def _v161_fix_names():
    pairs = (
        ("_v16_send_ca",   "_send_ca"),
        ("_v16_update_ca", "_update_ca"),
    )
    for src, dst in pairs:
        fn = globals().get(src)
        if callable(fn):
            try:
                fn.__name__ = dst
            except Exception:
                pass

_v161_fix_names()


# Explicit belt-and-braces aliases for the specific names the traceback
# pointed at. This guarantees the resolver works even if the loop above
# somehow missed one.
for _pair in (
        ("_v16_send_ca",    _v16_send_ca    if "_v16_send_ca" in globals()    else None),
        ("_v16_update_ca",  _v16_update_ca  if "_v16_update_ca" in globals()  else None),
        ("_v13_clinical_ai_tab", _v13_clinical_ai_tab if "_v13_clinical_ai_tab" in globals() else None),
        ("_v14_dashboard",  _v14_dashboard  if "_v14_dashboard" in globals()  else None),
        ("_v16_header",     _v16_header     if "_v16_header" in globals()     else None),
        ("_v16_rebuild_header", _v16_rebuild_header if "_v16_rebuild_header" in globals() else None),
        ("_v16_ensure_ca_widgets", _v16_ensure_ca_widgets if "_v16_ensure_ca_widgets" in globals() else None),
):
    _alias, _fn = _pair
    if callable(_fn) and not hasattr(HMGBillingApp, _alias):
        try:
            setattr(HMGBillingApp, _alias, _fn)
            print(f"[HMG v16.1] forced alias: {_alias}")
        except Exception as e:
            print(f"[HMG v16.1] alias {_alias}: {e}")


print("[HMG] v16.1 installed — WeakMethod resolver fix")
      
# ============================================================================
# HMG v17 — COMPREHENSIVE CLINICAL ASSESSMENT
#   • SOAP-format assessment output
#   • Keyword-based clinical reasoning (differentials, red flags, workup)
