def _v17_match_syndromes(text):
    """Return the list of KB entries whose pattern matches the given text."""
    if not text:
        return []
    low = str(text).lower()
    hits = []
    for entry in _HMG_KB:
        try:
            if re.search(entry["pattern"], low):
                hits.append(entry)
        except Exception:
            continue
    return hits


# ---------------------------------------------------------------------------
# 2. Build a comprehensive assessment from the current EMR dict
# ---------------------------------------------------------------------------
def _v17_build_comprehensive(self, emr=None):
    """Return a formatted multi-section assessment string. Works with any
    EMR dict — AI-produced or fallback."""
    if emr is None:
        try:
            emr = self.clinical_ai.get_emr() if hasattr(self, "clinical_ai") else None
        except Exception:
            emr = None
    if not isinstance(emr, dict):
        emr = {}

    def field(k, default="Not documented"):
        v = emr.get(k, "")
        if v is None or str(v).strip() == "":
            return default
        return str(v).strip()

    # Patient identity
    pt_name = pt_id = pt_age = pt_sex = ""
    try:
        cp = getattr(self, "cp", None) or {}
        pt_name = cp.get("name", "")
        pt_id = cp.get("id", "")
        pt_age = str(cp.get("age", ""))
        pt_sex = cp.get("gender", "")
    except Exception:
        pass

    # Combined narrative for syndrome matching
    text_blob = " ".join([
        field("cc", ""), field("hpi", ""), field("pmh", ""),
        field("sh", ""), field("ros", ""),
    ])
    syndromes = _v17_match_syndromes(text_blob)

    # Aggregate differentials, red flags, workup from matched syndromes
    differentials = []
    red_flags = []
    extra_workup = []
    treatment_hints = []
    for s in syndromes:
        for d in s.get("differentials", []):
            if d not in differentials:
                differentials.append(d)
        for f in s.get("red_flags", []):
            if f not in red_flags:
                red_flags.append(f)
        for w in s.get("workup", []):
            if w not in extra_workup:
                extra_workup.append(w)
        for t in s.get("treatment_hints", []):
            if t not in treatment_hints:
                treatment_hints.append(t)

    # What was actually recorded as ordered
    ordered_labs = []
    ol = emr.get("lab_orders", [])
    if isinstance(ol, str):
        ordered_labs = [x.strip() for x in ol.split("\n") if x.strip()]
    elif isinstance(ol, list):
        ordered_labs = [str(x).strip() for x in ol if str(x).strip()]
    ordered_rad = []
    orr = emr.get("radiology_orders", [])
    if isinstance(orr, str):
        ordered_rad = [x.strip() for x in orr.split("\n") if x.strip()]
    elif isinstance(orr, list):
        ordered_rad = [str(x).strip() for x in orr if str(x).strip()]

    # AI / user-typed diagnosis
    working_dx = field("dx", "")
    if working_dx in ("", "Further evaluation needed"):
        working_dx = "(pending clinician review)"

    # ---- Compose the output ----
    out = []
    bar = "═" * 60
    thin = "─" * 60

    out.append("COMPREHENSIVE CLINICAL ASSESSMENT")
    out.append(bar)
    out.append("")

    # PATIENT
    if pt_name or pt_id:
        out.append("PATIENT")
        out.append(thin)
        out.append(f"  Name: {pt_name or 'N/A'}")
        out.append(f"  ID:   {pt_id or 'N/A'}")
        out.append(f"  Age:  {pt_age or 'N/A'} y    "
                   f"Sex: {pt_sex or 'N/A'}")
        out.append("")

    # SUBJECTIVE
    out.append("SUBJECTIVE")
    out.append(thin)
    out.append(f"  Chief Complaint:  {field('cc')}")
    out.append(f"  HPI:              {field('hpi')}")
    out.append(f"  Past Medical:     {field('pmh')}")
    out.append(f"  Past Surgical:    {field('psh')}")
    out.append(f"  Drug History:     {field('dh')}")
    out.append(f"  Allergies:        {field('all')}")
    out.append(f"  Family History:   {field('fh')}")
    out.append(f"  Social History:   {field('sh')}")
    out.append(f"  Review of Systems:{field('ros')}")
    out.append("")

    # OBJECTIVE
    out.append("OBJECTIVE")
    out.append(thin)
    bp = field("bp", "")
    pulse = field("pulse", "")
    rr = field("rr", "")
    spo2 = field("spo2", "")
    temp = field("temp", "")
    wt = field("wt", "")
    ht = field("ht", "")
    bmi = field("bmi", "")
    avpu = field("avpu", "Alert")

    vitals = []
    vitals.append(f"BP: {bp if bp else 'not documented'}")
    vitals.append(f"Pulse: {pulse if pulse else 'not documented'} bpm")
    vitals.append(f"RR: {rr if rr else 'not documented'} /min")
    vitals.append(f"SpO2: {spo2 if spo2 else 'not documented'} %")
    vitals.append(f"Temp: {temp if temp else 'not documented'} °C")
    vitals.append(f"AVPU: {avpu}")
    out.append("  Vital Signs:")
    out.append("    " + "  |  ".join(vitals))
    if wt or ht or bmi:
        meas = []
        if wt:
            meas.append(f"Weight: {wt} kg")
        if ht:
            meas.append(f"Height: {ht} cm")
        if bmi:
            meas.append(f"BMI: {bmi}")
        out.append("    " + "  |  ".join(meas))
    out.append("")
    out.append("  Examination:")
    out.append(f"    General:      {field('gen')}")
    out.append(f"    CVS:          {field('cvs')}")
    out.append(f"    Respiratory:  {field('resp')}")
    out.append(f"    Abdomen:      {field('abd')}")
    out.append(f"    CNS:          {field('cns')}")
    out.append("")

    # ASSESSMENT
    out.append("ASSESSMENT")
    out.append(thin)
    out.append(f"  Working Diagnosis: {working_dx}")

    if differentials:
        out.append("")
        out.append("  Differential Diagnoses:")
        for i, d in enumerate(differentials, 1):
            out.append(f"    {i:>2}. {d}")
    else:
        out.append("")
        out.append("  Differential Diagnoses: (no matching syndrome in "
                   "knowledge base; suggest clinician review)")

    if red_flags:
        out.append("")
        out.append("  Red Flags to Confirm / Exclude:")
        for rf in red_flags:
            out.append(f"    • {rf}")

    if syndromes:
        out.append("")
        out.append("  Clinical Reasoning:")
        for s in syndromes:
            label = s["id"].replace("_", " ").title()
            out.append(f"    - Matched syndrome: {label}")

    urgency = field("urgency", "Routine")
    out.append("")
    out.append(f"  Urgency: {urgency}")
    out.append("")

    # PLAN
    out.append("PLAN")
    out.append(thin)

    if ordered_labs:
        out.append("  Investigations Ordered:")
        for w in ordered_labs:
            out.append(f"    • {w}")

    if ordered_rad:
        out.append("  Imaging Ordered:")
        for w in ordered_rad:
            out.append(f"    • {w}")

    # Suggested additional workup not yet ordered
    already = {x.lower() for x in (ordered_labs + ordered_rad)}
    suggested = [w for w in extra_workup if w.lower() not in already]
    if suggested:
        out.append("  Suggested Additional Workup:")
        for w in suggested[:10]:
            out.append(f"    • {w}")

    tx = field("tx", "")
    if tx and tx not in ("Clinical management pending assessment",
                          "Symptomatic management; review after investigation"):
        out.append("")
        out.append(f"  Treatment: {tx}")

    if treatment_hints:
        out.append("  Treatment Considerations:")
        for t in treatment_hints[:6]:
            out.append(f"    • {t}")

    no = emr.get("nursing_orders", [])
    if isinstance(no, str):
        no_list = [x.strip() for x in no.split("\n") if x.strip()]
    elif isinstance(no, list):
        no_list = [str(x).strip() for x in no if str(x).strip()]
    else:
        no_list = []
    if no_list:
        out.append("")
        out.append("  Nursing Care:")
        for n in no_list:
            out.append(f"    • {n}")

    fu = field("fu", "") or field("follow_up", "")
    out.append("")
    out.append(f"  Follow-up: {fu}")

    out.append("")
    out.append(bar)
    out.append("⚠  This assessment is decision-support only.")
    out.append("   Final diagnosis and treatment require clinician review.")

    return "\n".join(out)


# ---------------------------------------------------------------------------
# 3. Override _show_assessment so it uses the comprehensive builder
# ---------------------------------------------------------------------------
def _v17_show_assessment(self, instance=None, *a, **kw):
    try:
        emr = None
        try:
            if hasattr(self, "clinical_ai") and self.clinical_ai is not None:
                emr = self.clinical_ai.get_emr()
        except Exception:
            emr = None

        # If nothing in memory, try the most recent saved EMR for this patient.
        if not emr:
            try:
                pid = (getattr(self, "cp", None) or {}).get("id")
                recs = [r for r in getattr(self, "emr_records", [])
                        if r.get("patient_id") == pid]
                if recs:
                    emr = recs[-1]
            except Exception:
                pass

        if not emr:
            self._popup(
                "Clinical Assessment",
                "No clinical data yet.\n\n"
                "1. Tap START INTERVIEW in Session Controls.\n"
                "2. Answer the AI's questions.\n"
                "3. Tap SHOW / GENERATE ASSESSMENT again.")
            return

        text = _v17_build_comprehensive(self, emr)
        self._text_popup("Comprehensive Clinical Assessment", text)
        print("[HMG v17] comprehensive assessment shown")
    except Exception as e:
        import traceback
        traceback.print_exc()
        try:
            self._popup("Assessment Error", str(e))
        except Exception:
            pass


HMGBillingApp._show_assessment = _v17_show_assessment


# ---------------------------------------------------------------------------
# 4. Override the fallback summary so the chat window also shows the
#    comprehensive text (not the tiny default).
# ---------------------------------------------------------------------------
def _v17_non_ai_sum(self):
    # Build a rough clerking dict from whatever the conversation captured.
    users = [str(m.get("content", "")).strip()
             for m in getattr(self, "conv", []) if m.get("role") == "user"]
    users = [u for u in users if u]
    emr = {
        "cc": users[0] if len(users) >= 1 else "Not documented",
        "hpi": users[1] if len(users) >= 2 else "Not documented",
        "pmh": users[5] if len(users) >= 6 else "Not documented",
        "psh": users[6] if len(users) >= 7 else "Not documented",
        "dh":  users[7] if len(users) >= 8 else "Not documented",
        "all": users[8] if len(users) >= 9 else "Not documented",
        "fh":  users[9] if len(users) >= 10 else "Not documented",
        "sh":  users[10] if len(users) >= 11 else "Not documented",
        "ros": " ".join(users[11:]) if len(users) >= 12 else "Not documented",
        "gen": "Not documented", "cvs": "Not documented",
        "resp": "Not documented", "abd": "Not documented",
        "cns": "Not documented",
        "bp": "", "temp": "", "pulse": "", "spo2": "", "rr": "",
        "wt": "", "ht": "", "bmi": "", "avpu": "Alert",
        "dx": "Further evaluation needed",
        "tx": "Clinical management pending assessment",
        "fu": "Clinical review as indicated",
        "lab_orders": [], "radiology_orders": [],
        "prescribed_drugs": [], "nursing_orders": [],
        "follow_up": "Clinical review as indicated",
        "urgency": "Routine",
        "_text": "[DIAGNOSIS_READY]\nComprehensive clerking summary "
                 "prepared from available information.\n"
                 "AI was not used; clinical findings and decisions require "
                 "clinician verification.",
    }
    # Try to pull vitals from the conversation
    try:
        blob = " ".join(users)
        for k, pat in (
                ("bp", r"\bbp\s*[:=]?\s*(\d{2,3}\s*/\s*\d{2,3})"),
                ("pulse", r"\b(?:pulse|hr)\s*[:=]?\s*(\d{2,3})"),
                ("rr", r"\b(?:rr|resp)\s*[:=]?\s*(\d{1,2})"),
                ("spo2", r"\b(?:spo2|sat)\s*[:=]?\s*(\d{2,3})"),
                ("temp", r"\btemp\s*[:=]?\s*(\d{2}(?:\.\d)?)")):
            m = re.search(pat, blob, re.I)
            if m:
                emr[k] = m.group(1)
    except Exception:
        pass

    # Return dict-compatible shape for _extract
    return emr


# Replace the AI assistant's fallback
try:
    ModularAIClinicalAssistant._sum = _v17_non_ai_sum
    print("[HMG v17] fallback summary replaced with richer version")
except Exception as e:
    print(f"[HMG v17] fallback replace: {e}")


