# ============================================================================
# HMG v17.1 — SILENCE THE REBUILD STORM
# ----------------------------------------------------------------------------
# Cancels every pending rebuild timer scheduled by v4-v16 and installs a
# clean login handler that rebuilds each critical tab exactly once.
# Keeps: v14 dashboard, v13 Clinical AI, v16 header, v17 assessment.
# ============================================================================
from kivy.clock import Clock as _v171_Clock
from kivy.app import App as _v171_App


# --- 1. Cancel every pending rebuild kick ----------------------------------
_KICK_NAMES = (
    "_v10_kick", "_v11_kick", "_v12_kick",
    "_v13_kick", "_v14_kick", "_v15_kick", "_v16_kick",
    "_hmg_kick_dashboard_fix",
    "_schedule_header_rebuild",
)
_unscheduled = []
for _name in _KICK_NAMES:
    _fn = globals().get(_name)
    if callable(_fn):
        try:
            # all=True removes every occurrence in the queue
            _v171_Clock.unschedule(_fn)
            _unscheduled.append(_name)
        except Exception:
            pass
print(f"[HMG v17.1] unscheduled {len(_unscheduled)} pending kicks: "
      f"{_unscheduled}")


# --- 2. Snapshot the clean builders we want to keep ------------------------
# Everything below is looked up from module globals so we can bypass any
# class-level wrappers added by earlier patches.
_KEEP = {}
for _k, _gname in (
        ("_dashboard",         "_v14_dashboard"),
        ("_clinical_ai_tab",   "_v13_clinical_ai_tab"),
        ("_show_assessment",   "_v17_show_assessment"),
        ("_v16_rebuild_header","_v16_rebuild_header"),
        ("_v16_ensure_ca_widgets", "_v16_ensure_ca_widgets"),
        ("_v15_put_dashboard_first", "_v15_put_dashboard_first")):
    _fn = globals().get(_gname)
    if callable(_fn):
        _KEEP[_k] = _fn

# EMR: keep whatever is currently on the class (the last builder wins)
_emr_current = getattr(HMGBillingApp, "_emr", None)
if callable(_emr_current):
    _KEEP["_emr"] = _emr_current

print(f"[HMG v17.1] kept clean builders: {sorted(_KEEP.keys())}")

for _k, _fn in _KEEP.items():
    try:
        setattr(HMGBillingApp, _k, _fn)
    except Exception as e:
        print(f"[HMG v17.1] install {_k}: {e}")


# --- 3. Clean login handler ------------------------------------------------
def _v171_clean_login(self, user, *a, **kw):
    """Runs the login steps once, then a single tidy-up. No cascade."""
    print("[HMG v17.1] clean login starting")
    try:
        self.current_user = user
    except Exception:
        pass
    try:
        if hasattr(self, "audit"):
            self.audit.log(username=user.get("username"),
                            action="LOGIN",
                            details=f"Role: {user.get('role')}")
    except Exception as e:
        print(f"[HMG v17.1] audit: {e}")
    try:
        self.root_container.clear_widgets()
    except Exception:
        pass
    try:
        self._build_main_app()
    except Exception as e:
        import traceback
        traceback.print_exc()
        print(f"[HMG v17.1] build_main_app: {e}")

    # Default-password warning (single schedule, once)
    try:
        if user.get("must_change_password"):
            _v171_Clock.schedule_once(
                lambda dt: self._popup(
                    "Security Warning",
                    "You are using a default or reset password.\n\n"
                    "Go to Settings → SECURITY → CHANGE MY PASSWORD."),
                0.5)
    except Exception:
        pass

    # One tidy-up frame. Nothing rebuilds twice.
    def _finish(_dt=0):
        try:
            self._v16_ensure_ca_widgets()
        except Exception as e:
            print(f"[HMG v17.1] ca widgets: {e}")
        try:
            self._v16_rebuild_header()
        except Exception as e:
            print(f"[HMG v17.1] header: {e}")
        try:
            self._v15_put_dashboard_first()
        except Exception as e:
            print(f"[HMG v17.1] dashboard-first: {e}")
        print("[HMG v17.1] clean login complete")

    _v171_Clock.schedule_once(_finish, 1.5)


HMGBillingApp._on_login_success = _v171_clean_login


# --- 4. If you are already logged in, clean up now -------------------------
def _v171_kick(_dt=0):
    try:
        app = _v171_App.get_running_app()
        if app is None or not getattr(app, "main_root", None):
            _v171_Clock.schedule_once(_v171_kick, 0.4)
            return
        if not getattr(app, "current_user", None):
            return
        print("[HMG v17.1] cleaning running app")
        try:
            app._v16_ensure_ca_widgets()
        except Exception:
            pass
        try:
            app._v16_rebuild_header()
        except Exception:
            pass
        try:
            app._v15_put_dashboard_first()
        except Exception:
            pass
        print("[HMG v17.1] running app cleaned")
    except Exception as e:
        print(f"[HMG v17.1] kick: {e}")

try:
    _v171_Clock.schedule_once(_v171_kick, 0.4)
except Exception:
    pass


print("[HMG] v17.1 installed — rebuild storm silenced, single-shot login")

    
