# ---------------------------------------------------------------------------
# Inject the new syndromes into the KB
# ---------------------------------------------------------------------------
try:
    # Guard against double-injection if the module is reloaded.
    _existing_ids = {entry.get("id") for entry in _HMG_KB}
    _added = 0
    for entry in _EXTRA_SYNDROMES:
        if entry.get("id") not in _existing_ids:
            _HMG_KB.append(entry)
            _added += 1
    print(f"[HMG v17.2] added {_added} syndromes to knowledge base "
          f"(total now {len(_HMG_KB)})")
    print(f"[HMG v17.2] syndrome IDs: "
          f"{sorted([e['id'] for e in _HMG_KB])}")
except Exception as e:
    print(f"[HMG v17.2] KB injection: {e}")


# ---------------------------------------------------------------------------
# Re-bind the assessment so it uses the expanded KB immediately.
# _v17_show_assessment and _v17_build_comprehensive both reference the module
# global _HMG_KB, so no rebinding is strictly needed — but we reinstall them
# to be certain the class attribute points to the correct function.
# ---------------------------------------------------------------------------
try:
    if callable(globals().get("_v17_show_assessment")):
        HMGBillingApp._show_assessment = globals()["_v17_show_assessment"]
    if callable(globals().get("_v17_build_comprehensive")):
        HMGBillingApp._v17_build_comprehensive = globals()["_v17_build_comprehensive"]
    print("[HMG v17.2] assessment rebinding OK")
except Exception as e:
    print(f"[HMG v17.2] rebind: {e}")


print("[HMG] v17.2 installed — 15 additional clinical syndromes active")    

if __name__ == "__main__":
    HMGBillingApp().run()
